type IcuDailyFluidRow = {
  time: string;
  iv1: string;
  iv2: string;
  bloodProducts: string;
  ngFj: string;
  oral: string;
  totalInput: number;
  urine: string;
  ngOutput: string;
  drain: string;
  vomitStool: string;
  uf: string;
  totalOutput: number;
  balance: number;
  cumulative: number;
};

const ICU_DAILY_FLOW_HOURS = ["08:00", "09:00", "10:00", "11:00", "12:00", "13:00", "14:00", "15:00", "16:00", "17:00", "18:00", "19:00", "20:00", "21:00", "22:00", "23:00", "00:00", "01:00", "02:00", "03:00", "04:00", "05:00", "06:00", "07:00"];

function buildIcuDailyFluidRows(rows: typeof intakeOutputRows, infusions: typeof infusionRows): IcuDailyFluidRow[] {
  const rowsByHour = new Map<string, IcuIntakeOutput[]>();
  rows.forEach((row) => {
    const hour = icuDailyHourSlot(row.time);
    if (!rowsByHour.has(hour)) rowsByHour.set(hour, []);
    rowsByHour.get(hour)?.push(row);
  });

  const infusionsByHour = new Map<string, typeof infusionRows>();
  infusions.forEach((row) => {
    const hour = icuDailyHourSlot(row.startTime);
    if (!infusionsByHour.has(hour)) infusionsByHour.set(hour, []);
    infusionsByHour.get(hour)?.push(row);
  });

  let cumulative = 0;
  return ICU_DAILY_FLOW_HOURS.map((time) => {
    const entries = rowsByHour.get(time) ?? [];
    const intakeEntries = entries.filter((row) => row.kind === "Intake");
    const outputEntries = entries.filter((row) => row.kind === "Output");
    const pumpEntries = infusionsByHour.get(time) ?? [];

    const bloodEntries = intakeEntries.filter(icuDailyIsBloodProduct);
    const ngFjEntries = intakeEntries.filter(icuDailyIsNgFjIntake);
    const oralEntries = intakeEntries.filter(icuDailyIsOralIntake);
    const ivEntries = intakeEntries.filter((row) => !icuDailyIsBloodProduct(row) && !icuDailyIsNgFjIntake(row) && !icuDailyIsOralIntake(row));
    const ivCells = [
      ...ivEntries.map(icuDailyInputCell),
      ...pumpEntries.map((row) => `${row.fluidName} ${icuDailyMl(row.infusedVolumeMl)} (${row.rate})`),
    ];

    const totalInput = intakeEntries.reduce((sum, row) => sum + row.intakeMl, 0);
    const totalOutput = outputEntries.reduce((sum, row) => sum + row.outputMl, 0);
    const balance = totalInput - totalOutput;
    cumulative += balance;

    return {
      time,
      iv1: ivCells[0] ?? "-",
      iv2: ivCells[1] ?? "-",
      bloodProducts: icuDailyJoinCells(bloodEntries.map(icuDailyInputCell)),
      ngFj: icuDailyJoinCells(ngFjEntries.map(icuDailyInputCell)),
      oral: icuDailyJoinCells(oralEntries.map(icuDailyInputCell)),
      totalInput,
      urine: icuDailyOutputCell(outputEntries, /urine|foley|catheter/i),
      ngOutput: icuDailyOutputCell(outputEntries, /ng|gastric/i),
      drain: icuDailyOutputCell(outputEntries, /drain|pleural|mediastinum|line removal|dressing/i),
      vomitStool: icuDailyOutputCell(outputEntries, /vomit|stool|emesis|regurg/i),
      uf: icuDailyOutputCell(outputEntries, /\buf\b|dialysis/i),
      totalOutput,
      balance,
      cumulative,
    };
  });
}

function buildIcuDailyLineDeviceRows(rows: typeof intakeOutputRows, infusions: typeof infusionRows) {
  const allText = rows.map((row) => `${row.category} ${row.component} ${row.route} ${row.outputType} ${row.intakeType}`).join(" ");
  const pendingReviewCount = rows.filter((row) => row.status === "Pending review").length;
  const correctedCount = rows.filter((row) => row.status === "Corrected").length;
  const hasIvLine = infusions.length > 0 || /iv|infusion/i.test(allText);
  const hasFoley = /foley|urinary catheter/i.test(allText);
  const hasNg = /\bng\b|ng tube|gastric/i.test(allText);
  const hasCvpPicc = /central line|cvp|picc|vasopressor|noradrenaline/i.test(allText + " " + infusions.map((row) => `${row.fluidName} ${row.alert}`).join(" "));

  return [{
    ivLine: hasIvLine ? `${Math.max(infusions.length, 1)} active / size not recorded` : "Not recorded",
    etTube: "Not recorded",
    foley: hasFoley ? "Present / size not recorded" : "Not recorded",
    cvpPicc: hasCvpPicc ? "Present / size not recorded" : "Not recorded",
    arterialLine: "Not recorded",
    ngTube: hasNg ? "Present / size not recorded" : "Not recorded",
    status: pendingReviewCount || correctedCount ? `${pendingReviewCount} pending review, ${correctedCount} corrected` : "Signed / auto synced",
  }];
}

function icuDailyHourSlot(value: string) {
  const match = value.match(/^(\d{1,2})/);
  if (!match) return "00:00";
  return `${match[1].padStart(2, "0")}:00`;
}

function icuDailyMl(value: number) {
  return value ? `${value} ml` : "-";
}

function icuDailySignedMl(value: number) {
  if (!value) return "-";
  return `${value > 0 ? "+" : ""}${value} ml`;
}

function icuDailyInputCell(row: IcuIntakeOutput) {
  return `${row.component} ${icuDailyMl(row.quantityMl)}`;
}

function icuDailyJoinCells(values: string[]) {
  return values.length ? values.join(" | ") : "-";
}

function icuDailyOutputCell(rows: IcuIntakeOutput[], pattern: RegExp) {
  const matched = rows.filter((row) => pattern.test(`${row.category} ${row.component} ${row.route} ${row.outputType} ${row.source}`));
  return icuDailyJoinCells(matched.map((row) => `${row.component} ${icuDailyMl(row.outputMl || row.quantityMl)}`));
}

function icuDailyIsBloodProduct(row: IcuIntakeOutput) {
  return /blood|prbc|rbc|ffp|plasma|platelet|cryo/i.test(`${row.category} ${row.component} ${row.route} ${row.intakeType} ${row.source}`);
}

function icuDailyIsNgFjIntake(row: IcuIntakeOutput) {
  return /\bng\b|fj|enteral|feed/i.test(`${row.category} ${row.component} ${row.route} ${row.intakeType}`);
}

function icuDailyIsOralIntake(row: IcuIntakeOutput) {
  return /oral|p\.o|po\b|sip|water/i.test(`${row.category} ${row.component} ${row.route} ${row.intakeType}`);
}

function IcuDailyTransfusionTable({ rows }: { rows: typeof transfusionRows }) {
  const chartDate = rows.map((row) => row.startTime).length ? "Today" : "-";

  return (
    <div className="max-h-[44vh] max-w-full overflow-auto rounded-md border border-border">
      <table className="w-full min-w-[1220px] border-collapse text-sm">
        <thead className="sticky top-0 z-10 bg-surface-muted text-xs uppercase text-muted-foreground">
          <tr>
            {["Date", "Start time", "Bag no", "Component", "Bag group", "Rh", "Checked by", "Started by", "Given qty", "Stop time", "Reaction", "Status"].map((header) => (
              <th className="border-b border-r border-border px-3 py-2 text-left last:border-r-0" key={header}>{header}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.length ? rows.map((row) => (
            <tr className="border-b border-border last:border-0" key={row.id}>
              <td className="border-r border-border px-3 py-2">{chartDate}</td>
              <td className="border-r border-border px-3 py-2">{row.startTime}</td>
              <td className="border-r border-border px-3 py-2 font-bold text-foreground">{row.unitNumber}</td>
              <td className="border-r border-border px-3 py-2 font-bold text-foreground">{row.componentType}</td>
              <td className="border-r border-border px-3 py-2">{icuDailyBloodGroupBase(row.bloodGroup)}</td>
              <td className="border-r border-border px-3 py-2">{icuDailyRh(row.bloodGroup)}</td>
              <td className="border-r border-border px-3 py-2">{row.nurse}</td>
              <td className="border-r border-border px-3 py-2">{row.doctor}</td>
              <td className="border-r border-border px-3 py-2">{icuDailyTransfusionQty(row.componentType)}</td>
              <td className="border-r border-border px-3 py-2">{row.status === "Completed" ? "Completed" : "-"}</td>
              <td className="border-r border-border px-3 py-2">{row.reactionObserved}</td>
              <td className="px-3 py-2"><StatusPill tone={toneForStatus(row.status)}>{row.status}</StatusPill></td>
            </tr>
          )) : (
            <tr><td className="px-3 py-6 text-center text-sm text-muted-foreground" colSpan={12}>No transfusion row for this patient.</td></tr>
          )}
        </tbody>
      </table>
    </div>
  );
}

function icuDailyBloodGroupBase(group: string) {
  return group.replace(/[+-]/g, "") || "-";
}

function icuDailyRh(group: string) {
  if (group.includes("-")) return "Negative";
  if (group.includes("+")) return "Positive";
  return "-";
}

function icuDailyTransfusionQty(componentType: string) {
  if (/platelet|sdp|rdp/i.test(componentType)) return "1 unit platelet";
  if (/ffp|plasma/i.test(componentType)) return "1 unit FFP";
  if (/cryo/i.test(componentType)) return "1 pool";
  return "1 unit";
}

function IcuDailyKeyValueRows({ rows }: { rows: Array<[string, React.ReactNode, DashboardCellTone?]> }) {
  return (
    <div className="space-y-2">
      {rows.map(([label, value, tone = "info"]) => (
        <div className={cn("rounded-md border px-3 py-2 text-sm", dashboardToneSurfaceClass(tone))} key={label}>
          <div className="text-[11px] font-black uppercase">{label}</div>
          <div className="mt-1 font-semibold">{value}</div>
        </div>
      ))}
    </div>
  );
}

