function buildNotificationCommandRows(statusOverrides: Record<string, string>): NotificationCommandRow[] {
  const patientById = new Map(icuPatients.map((patient) => [patient.id, patient]));
  const rows: NotificationCommandRow[] = [
    ...icuAlerts
      .filter((alert) => alert.status !== "Resolved")
      .map((alert) => {
        const patient = patientById.get(alert.patientId);
        const priority = notificationPriorityFromAlert(alert.severity);
        return {
          id: `alert-${alert.id}`,
          source: "Clinical alert" as NotificationCommandSource,
          type: alert.type,
          title: alert.message,
          patientId: alert.patientId,
          patient: patient ? `${patient.bedNo} - ${patient.patientName}` : alert.bedNo,
          unit: patient?.unit ?? notificationUnitForPatient(alert.patientId),
          owner: alert.owner,
          routeTo: alert.owner.includes("Doctor") ? "Duty doctor" : alert.owner,
          priority,
          status: statusOverrides[`alert-${alert.id}`] ?? alert.status,
          waitingMinutes: notificationMinutesFromLabel(alert.createdAt),
          slaMinutes: priority === "Critical" ? 5 : priority === "High" ? 15 : 30,
          dueLabel: alert.createdAt,
          createdAt: alert.createdAt,
          tone: notificationPriorityTone(priority),
          details: alert.source,
        };
      }),
    ...icuTasks
      .filter((task) => task.status !== "Completed")
      .map((task) => {
        const patient = patientById.get(task.patientId);
        const priority = notificationPriorityFromTask(task.priority);
        return {
          id: `task-${task.id}`,
          source: "Nurse task" as NotificationCommandSource,
          type: task.taskType,
          title: task.title,
          patientId: task.patientId,
          patient: `${task.bedNo} - ${task.patientName}`,
          unit: patient?.unit ?? notificationUnitForPatient(task.patientId),
          owner: task.assignedTo,
          routeTo: task.createdBy,
          priority,
          status: statusOverrides[`task-${task.id}`] ?? task.status,
          waitingMinutes: notificationMinutesFromLabel(task.dueTime),
          slaMinutes: priority === "Critical" ? 5 : priority === "High" ? 20 : 60,
          dueLabel: task.dueTime,
          createdAt: task.dueTime,
          tone: notificationPriorityTone(priority),
          details: task.remarks,
        };
      }),
    ...doctorInstructions
      .filter((instruction) => instruction.status !== "Completed")
      .map((instruction) => {
        const patient = patientById.get(instruction.patientId);
        const priority = notificationPriorityFromTask(instruction.priority);
        return {
          id: `instruction-${instruction.id}`,
          source: "Doctor instruction" as NotificationCommandSource,
          type: instruction.instructionType,
          title: instruction.instruction,
          patientId: instruction.patientId,
          patient: patient ? `${patient.bedNo} - ${patient.patientName}` : instruction.bedNo,
          unit: patient?.unit ?? notificationUnitForPatient(instruction.patientId),
          owner: instruction.assignedNurse,
          routeTo: instruction.doctor,
          priority,
          status: statusOverrides[`instruction-${instruction.id}`] ?? instruction.status,
          waitingMinutes: notificationMinutesFromLabel(instruction.dueTime),
          slaMinutes: priority === "Critical" ? 5 : priority === "High" ? 20 : 90,
          dueLabel: instruction.dueTime,
          createdAt: instruction.dueTime,
          tone: notificationPriorityTone(priority),
          details: instruction.remarks,
        };
      }),
    ...medicationRows
      .filter((medication) => ["Due", "Late"].includes(medication.status))
      .map((medication) => {
        const patient = patientById.get(medication.patientId);
        const priority = medication.status === "Late" || medication.doubleVerification === "Required" ? "High" : "Medium";
        return {
          id: `med-${medication.id}`,
          source: "Medication" as NotificationCommandSource,
          type: medication.status,
          title: `${medication.medication} ${medication.dose} ${medication.route}`,
          patientId: medication.patientId,
          patient: patient ? `${patient.bedNo} - ${patient.patientName}` : medication.bedNo,
          unit: patient?.unit ?? notificationUnitForPatient(medication.patientId),
          owner: medication.administeredBy === "-" ? "Ward Nurse" : medication.administeredBy,
          routeTo: medication.doubleVerification === "Required" ? "Doctor + pharmacy" : "Ward nurse",
          priority: priority as NotificationCommandRow["priority"],
          status: statusOverrides[`med-${medication.id}`] ?? medication.status,
          waitingMinutes: notificationMinutesFromLabel(medication.scheduledTime),
          slaMinutes: medication.status === "Late" ? 10 : 30,
          dueLabel: medication.scheduledTime,
          createdAt: medication.scheduledTime,
          tone: (medication.status === "Late" ? "danger" : "warning") as DashboardCellTone,
          details: medication.reason,
        };
      }),
    ...getCommandDeviceRows()
      .filter((device) => device.connectivity !== "Online" || device.signal !== "Good" || device.issue !== "No issue")
      .map((device) => {
        const patient = icuPatients.find((item) => item.bedNo === device.bedNo);
        const priority: NotificationCommandRow["priority"] = device.connectivity !== "Online" ? "High" : "Medium";
        return {
          id: `device-${device.id}`,
          source: "Device" as NotificationCommandSource,
          type: device.connectivity !== "Online" ? "Connectivity" : "Signal",
          title: `${device.bedNo}: ${device.issue}`,
          patientId: patient?.id,
          patient: patient ? `${patient.bedNo} - ${patient.patientName}` : `${device.bedNo} - Unassigned`,
          unit: patient?.unit ?? deviceOpsUnitFromBed(device.bedNo),
          owner: device.owner,
          routeTo: "Biomedical",
          priority,
          status: statusOverrides[`device-${device.id}`] ?? "Open",
          waitingMinutes: notificationMinutesFromLabel(device.lastData),
          slaMinutes: device.connectivity !== "Online" ? 10 : 30,
          dueLabel: device.lastData,
          createdAt: device.lastData,
          tone: (device.connectivity !== "Online" ? "danger" : "warning") as DashboardCellTone,
          details: `${device.monitor}, ${device.ventilator}, ${device.gateway}`,
        };
      }),
  ];

  return rows;
}

function notificationMetrics(rows: NotificationCommandRow[]): Array<{ label: string; value: React.ReactNode; tone: DashboardCellTone }> {
  const critical = rows.filter((row) => row.priority === "Critical").length;
  const breached = rows.filter(notificationSlaBreached).length;
  const escalated = rows.filter((row) => row.status === "Escalated").length;
  return [
    { label: "Visible", value: rows.length, tone: "info" },
    { label: "Critical", value: critical, tone: critical ? "critical" : "success" },
    { label: "SLA breach", value: breached, tone: breached ? "danger" : "success" },
    { label: "Escalated", value: escalated, tone: escalated ? "warning" : "success" },
    { label: "Medication", value: rows.filter((row) => row.source === "Medication").length, tone: "purple" },
    { label: "Device", value: rows.filter((row) => row.source === "Device").length, tone: "warning" },
  ];
}

function notificationSort(left: NotificationCommandRow, right: NotificationCommandRow) {
  const priorityRank: Record<NotificationCommandRow["priority"], number> = { Critical: 4, High: 3, Medium: 2, Routine: 1 };
  const leftScore = priorityRank[left.priority] * 1000 + (notificationSlaBreached(left) ? 500 : 0) + left.waitingMinutes;
  const rightScore = priorityRank[right.priority] * 1000 + (notificationSlaBreached(right) ? 500 : 0) + right.waitingMinutes;
  return rightScore - leftScore;
}

function notificationSlaBreached(row: NotificationCommandRow) {
  return row.waitingMinutes >= row.slaMinutes && row.status !== "Resolved";
}

function notificationSlaLabel(row: NotificationCommandRow) {
  if (row.status === "Resolved") return "Resolved";
  const remaining = row.slaMinutes - row.waitingMinutes;
  if (remaining <= 0) return `${Math.abs(remaining)}m breach`;
  return `${remaining}m left`;
}

function notificationSlaTone(row: NotificationCommandRow): DashboardCellTone {
  if (row.status === "Resolved") return "success";
  if (notificationSlaBreached(row)) return "danger";
  if (row.slaMinutes - row.waitingMinutes <= 5) return "warning";
  return "success";
}

function notificationStatusTone(status: string): DashboardCellTone {
  if (status === "Resolved" || status === "Completed") return "success";
  if (status === "Escalated" || status === "Late" || status === "Overdue") return "danger";
  if (status === "Acknowledged" || status === "Assigned" || status === "In progress") return "info";
  if (status === "Due" || status === "Open" || status === "Pending") return "warning";
  return "muted";
}

function notificationPriorityTone(priority: NotificationCommandRow["priority"]): DashboardCellTone {
  if (priority === "Critical") return "critical";
  if (priority === "High") return "danger";
  if (priority === "Medium") return "warning";
  return "info";
}

function notificationSourceTone(source: NotificationCommandSource): DashboardCellTone {
  if (source === "Clinical alert") return "danger";
  if (source === "Medication") return "purple";
  if (source === "Device") return "warning";
  if (source === "Doctor instruction") return "info";
  return "success";
}

function notificationSourceIcon(source: NotificationCommandSource) {
  if (source === "Clinical alert") return AlertTriangle;
  if (source === "Medication") return Pill;
  if (source === "Device") return Activity;
  if (source === "Doctor instruction") return Stethoscope;
  return ListChecks;
}

function notificationStatusAfterAction(kind: NotificationActionKind) {
  const statusMap: Record<NotificationActionKind, string> = {
    open: "Open",
    acknowledge: "Acknowledged",
    assign: "Assigned",
    start: "In progress",
    resolve: "Resolved",
    escalate: "Escalated",
  };
  return statusMap[kind];
}

function notificationActionLabel(kind: NotificationActionKind) {
  const labels: Record<NotificationActionKind, string> = {
    open: "Queue review",
    acknowledge: "Acknowledgement",
    assign: "Assignment",
    start: "Work started",
    resolve: "Resolution",
    escalate: "Escalation",
  };
  return labels[kind];
}

function notificationActionCopy(action: NotificationWorkflowAction): {
  title: string;
  tone: DashboardCellTone;
  defaultAction: string;
  defaultReview: string;
  note: string;
  checklistTitle: string;
  actionOptions: string[];
  ownerOptions: string[];
  reviewOptions: string[];
  checklist: string[];
} {
  const ownerOptions = Array.from(new Set([
    action.row.owner,
    action.row.routeTo,
    "Ward Nurse Kavita",
    "Ward Nurse Arjun",
    "Unit Nurse Priya",
    "Unit Nurse Meera",
    "Duty Doctor",
    "Pharmacy",
    "Biomedical",
  ])).filter(Boolean);
  const reviewOptions = ["Now", "Next 5 min", "Next 15 min", "Next round", "End of shift"];
  const actionOptions = action.row.source === "Medication"
    ? ["Acknowledge medicine due", "Administer and document", "Notify pharmacy", "Escalate medication delay", "Resolve after administration"]
    : action.row.source === "Device"
      ? ["Acknowledge device issue", "Assign biomedical", "Switch clinical fallback", "Escalate device downtime", "Resolve after signal check"]
      : action.row.source === "Doctor instruction"
        ? ["Acknowledge doctor instruction", "Start instruction task", "Request clarification", "Escalate delayed instruction", "Resolve after documentation"]
        : action.row.source === "Clinical alert"
          ? ["Acknowledge alert", "Start clinical review", "Notify duty doctor", "Escalate critical alert", "Resolve after review"]
          : ["Acknowledge task", "Start task", "Reassign task", "Escalate task", "Resolve task"];
  const defaultAction = action.kind === "escalate"
    ? actionOptions.find((option) => option.includes("Escalate")) ?? actionOptions[0]
    : action.kind === "resolve"
      ? actionOptions.find((option) => option.includes("Resolve")) ?? actionOptions[0]
      : action.kind === "start"
        ? actionOptions.find((option) => option.includes("Start") || option.includes("Administer")) ?? actionOptions[0]
        : action.kind === "assign"
          ? actionOptions.find((option) => option.includes("Assign") || option.includes("Reassign")) ?? actionOptions[0]
          : actionOptions[0];
  return {
    title: `${notificationActionLabel(action.kind)} - ${action.row.source}`,
    tone: action.kind === "escalate" ? "danger" : action.kind === "resolve" ? "success" : action.row.tone,
    defaultAction,
    defaultReview: action.kind === "escalate" || notificationSlaBreached(action.row) ? "Next 5 min" : "Next 15 min",
    note: `${action.row.title}. Owner: ${action.row.owner}.`,
    checklistTitle: "Action safety checklist",
    actionOptions,
    ownerOptions,
    reviewOptions,
    checklist: [
      "Patient identity and context verified",
      "Owner and route-to person confirmed",
      "Patient impact reviewed",
      "Next review time documented",
      "Handover/escalation note updated if needed",
    ],
  };
}

function notificationPriorityFromAlert(severity: string): NotificationCommandRow["priority"] {
  if (severity === "Critical") return "Critical";
  if (severity === "High") return "High";
  if (severity === "Medium") return "Medium";
  return "Routine";
}

function notificationPriorityFromTask(priority: string): NotificationCommandRow["priority"] {
  if (priority === "Critical") return "Critical";
  if (priority === "High") return "High";
  if (priority === "Medium") return "Medium";
  return "Routine";
}

function notificationUnitForPatient(patientId: string) {
  return icuPatients.find((patient) => patient.id === patientId)?.unit ?? "ICU";
}

function notificationMinutesFromLabel(label: string) {
  const normalized = label.toLowerCase();
  if (normalized.includes("now") || normalized.includes("running")) return 0;
  const match = normalized.match(/(\d+)/);
  if (!match) return normalized.includes("hr") || normalized.includes("hour") ? 60 : 15;
  const value = Number(match[1]);
  if (normalized.includes("hr") || normalized.includes("hour")) return value * 60;
  if (normalized.includes("min")) return value;
  if (normalized.includes(":")) return Math.max(5, value);
  return value;
}

function PatientSearchCommand({ patients }: { patients: IcuPatient[] }) {
  const [query, setQuery] = React.useState("");
  const [risk, setRisk] = React.useState("All risk");
  const [ventilator, setVentilator] = React.useState("All ventilator");
  const rows = patients.filter((patient) => {
    const searchable = `${patient.patientName} ${patient.mrn} ${patient.bedNo} ${patient.diagnosis} ${patient.admittingDoctor} ${patient.assignedWardNurse}`.toLowerCase();
    const matchesQuery = searchable.includes(query.toLowerCase());
    const matchesRisk = risk === "All risk" || patient.currentStatus === risk || (risk === "Critical score" && patient.criticalityScore >= 8);
    const matchesVentilator = ventilator === "All ventilator" || (ventilator === "On support" && patient.ventilatorStatus !== "Room air") || patient.ventilatorStatus === ventilator;
    return matchesQuery && matchesRisk && matchesVentilator;
  });
  const pagination = useIcuCommandPagination(rows);

  return (
    <div className="space-y-4">
      <CollapsibleCommandPanel
        summary={`${query.trim() || "All patients"} | ${risk} | ${ventilator} | ${rows.length} result(s)`}
        title="Patient search filters"
      >
        <div className="grid gap-3 p-4 md:grid-cols-[minmax(240px,1fr)_220px_220px_auto] md:items-end">
          <label className="space-y-1 text-sm">
            <span className="font-medium text-foreground">Search MRN / patient / bed / doctor</span>
            <Input placeholder="Search ICU patient..." value={query} onChange={(event) => setQuery(event.target.value)} />
          </label>
          <NativeSelect label="Risk" value={risk} onChange={setRisk} options={["All risk", "Critical score", "Critical", "Ventilated", "Stable ICU care", "Ready for transfer"]} />
          <NativeSelect label="Ventilator" value={ventilator} onChange={setVentilator} options={["All ventilator", "On support", "Room air", "NIV support", "Invasive ventilation", "Oxygen mask"]} />
          <Button variant="outline" onClick={() => {
            setQuery("");
            setRisk("All risk");
            setVentilator("All ventilator");
          }}>Reset</Button>
        </div>
      </CollapsibleCommandPanel>

      <div className="overflow-hidden rounded-md border border-slate-200 bg-white shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full min-w-[1100px] border-collapse text-sm">
            <thead className="border-b border-slate-200 bg-white text-[11px] uppercase text-sky-700">
              <tr>
                <th className="px-3 py-3 text-left">Patient</th>
                <th className="px-3 py-3 text-left">Bed / Unit</th>
                <th className="px-3 py-3 text-left">Ventilation</th>
                <th className="px-3 py-3 text-left">Doctor</th>
                <th className="px-3 py-3 text-left">Nurse</th>
                <th className="px-3 py-3 text-right">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200">
              {pagination.pageRows.map((patient) => (
                <tr className="align-middle hover:bg-sky-50/40" key={patient.id}>
                  <td className="px-3 py-3">
                    <Link className={cn("font-bold hover:underline", dashboardToneTextClass(patientDashboardTone(patient)))} href={icuPatientDetailHref(patient.id, "overview")}>
                      {patient.patientName}
                    </Link>
                    <p className="mt-1 text-xs font-semibold text-slate-500">{patient.mrn} | {patient.ageGender}</p>
                  </td>
                  <td className="px-3 py-3">
                    <p className="font-semibold text-slate-800">{patient.bedNo}</p>
                    <p className="mt-1 text-xs font-semibold text-slate-500">{patient.unit}</p>
                  </td>
                  <td className="px-3 py-3 font-semibold text-slate-700">{patient.ventilatorStatus}</td>
                  <td className="px-3 py-3 font-semibold text-slate-700">{patient.admittingDoctor}</td>
                  <td className="px-3 py-3 font-semibold text-slate-700">{patient.assignedWardNurse}</td>
                  <td className="px-3 py-3 text-right">
                    <Button size="sm" asChild>
                      <Link href={icuPatientDetailHref(patient.id, "overview")}>Open patient</Link>
                    </Button>
                  </td>
                </tr>
              ))}
              {!pagination.pageRows.length ? (
                <tr>
                  <td className="px-3 py-10 text-center text-sm font-semibold text-slate-500" colSpan={6}>No ICU patient matched the selected filters.</td>
                </tr>
              ) : null}
            </tbody>
          </table>
        </div>
      </div>
      <IcuCommandPaginationControls {...pagination} />
    </div>
  );
}

function PatientTimelineCommand() {
  const [patientId, setPatientId] = React.useState(icuPatients[0]?.id ?? "");
  const patient = icuPatients.find((item) => item.id === patientId) ?? icuPatients[0];
  const timeline = [
    { type: "Admission", title: `${patient?.admissionSource} to ${patient?.bedNo}`, detail: patient?.admissionTime ?? "Today", time: "08:10", tone: "info" as StatusTone },
    ...icuVitals.filter((row) => row.patientId === patientId).map((row) => ({ type: "Vitals", title: `${row.bp}, SpO2 ${row.spo2}%`, detail: row.note, time: row.time, tone: row.abnormal ? "danger" as StatusTone : "success" as StatusTone })),
    ...medicationRows.filter((row) => row.patientId === patientId).map((row) => ({ type: "Medication", title: `${row.medication} ${row.status}`, detail: row.reason, time: row.scheduledTime, tone: toneForStatus(row.status) })),
    ...icuAlerts.filter((row) => row.patientId === patientId).map((row) => ({ type: "Alert", title: row.type, detail: row.message, time: row.createdAt, tone: toneForStatus(row.severity) })),
    ...doctorInstructions.filter((row) => row.patientId === patientId).map((row) => ({ type: "Doctor", title: row.instructionType, detail: row.instruction, time: row.dueTime, tone: toneForPriority(row.priority) })),
  ];

  return (
    <div className="grid gap-4 xl:grid-cols-[320px_minmax(0,1fr)]">
      <CommandSection title="Select Patient" description="Timeline follows the selected ICU patient.">
        <PatientSelect label="Patient" value={patientId} onChange={setPatientId} patients={icuPatients} />
        {patient ? <PatientMiniCard patient={patient} /> : null}
      </CommandSection>
      <CommandSection title="Patient Timeline" description="Admission, vitals, medication, alerts, doctor instructions, and handover cues.">
        <div className="space-y-3">
          {timeline.map((item, index) => (
            <div className="grid gap-3 rounded-md border border-border bg-background p-3 md:grid-cols-[90px_120px_minmax(0,1fr)_100px]" key={`${item.type}-${index}`}>
              <Badge tone={item.tone}>{item.type}</Badge>
              <span className="text-sm font-semibold text-foreground">{item.time}</span>
              <div>
                <p className="text-sm font-semibold text-foreground">{item.title}</p>
                <p className="mt-1 text-xs text-muted-foreground">{item.detail}</p>
              </div>
              <Button size="sm" variant="outline">Open</Button>
            </div>
          ))}
        </div>
      </CommandSection>
    </div>
  );
}

type SmartBedStatus = "Occupied" | "Available" | "Reserved" | "Cleaning" | "Maintenance" | "Blocked";

type SmartBedInventoryRow = {
  id: string;
  bedNo: string;
  unit: string;
  status: SmartBedStatus;
  patient?: IcuPatient;
  capability: string;
  isolation: string;
  nurseStation: string;
  turnaround: string;
  reservation: string;
  latestVital?: IcuVital;
  device?: ReturnType<typeof getCommandDeviceRows>[number];
  alertCount: number;
  taskCount: number;
  dueMedicationCount: number;
  flowStatus: string;
};

const smartBedEmptyInventory: Array<Omit<SmartBedInventoryRow, "latestVital" | "device" | "alertCount" | "taskCount" | "dueMedicationCount">> = [
  { id: "bed-g02", bedNo: "ICU-G02", unit: "General ICU", status: "Available", capability: "Monitor + oxygen + suction", isolation: "Standard", nurseStation: "General ICU station", turnaround: "Ready now", reservation: "-", flowStatus: "Open for admission" },
  { id: "bed-m03", bedNo: "ICU-M03", unit: "Medical ICU", status: "Available", capability: "Ventilator + 3 pumps + dialysis-ready", isolation: "Standard", nurseStation: "Medical ICU station", turnaround: "Ready now", reservation: "-", flowStatus: "Open for emergency admission" },
  { id: "bed-c04", bedNo: "ICU-C04", unit: "Cardiothoracic ICU", status: "Reserved", capability: "Ventilator + invasive monitor + drains", isolation: "Standard", nurseStation: "CT ICU station", turnaround: "ETA 35 min", reservation: "Post CABG from OT", flowStatus: "Patient transfer expected" },
  { id: "bed-p08", bedNo: "ICU-P08", unit: "Pediatric ICU", status: "Cleaning", capability: "Pediatric monitor + NIV + suction", isolation: "Contact-ready", nurseStation: "Pediatric ICU station", turnaround: "18 min", reservation: "-", flowStatus: "Housekeeping in progress" },
  { id: "bed-n04", bedNo: "ICU-N04", unit: "Neuro ICU", status: "Available", capability: "Neuro monitor + oxygen + seizure watch", isolation: "Standard", nurseStation: "Neuro ICU station", turnaround: "Ready now", reservation: "-", flowStatus: "Open for stroke observation" },
  { id: "bed-t07", bedNo: "ICU-T07", unit: "Transplant ICU", status: "Available", capability: "Strict I/O + infusion pump + protective care", isolation: "Protective", nurseStation: "Transplant ICU station", turnaround: "Ready now", reservation: "-", flowStatus: "Open for transplant admission" },
  { id: "bed-t08", bedNo: "ICU-T08", unit: "Transplant ICU", status: "Blocked", capability: "Protective isolation + renal support", isolation: "Protective", nurseStation: "Transplant ICU station", turnaround: "Awaiting infection-control clearance", reservation: "-", flowStatus: "Environmental clearance pending" },
  { id: "bed-r08", bedNo: "ICU-R08", unit: "Respiratory ICU", status: "Available", capability: "NIV + oxygen + suction + ABG watch", isolation: "Droplet-ready", nurseStation: "Respiratory ICU station", turnaround: "Ready now", reservation: "-", flowStatus: "Open for respiratory admission" },
  { id: "bed-r09", bedNo: "ICU-R09", unit: "Respiratory ICU", status: "Maintenance", capability: "Ventilator + monitor + suction", isolation: "Standard", nurseStation: "Respiratory ICU station", turnaround: "Biomedical ETA 25 min", reservation: "-", flowStatus: "Gateway and ventilator check" },
  { id: "bed-g03", bedNo: "ICU-G03", unit: "General ICU", status: "Cleaning", capability: "Monitor + oxygen", isolation: "Standard", nurseStation: "General ICU station", turnaround: "12 min", reservation: "ER admission waiting", flowStatus: "Priority cleaning requested" },
];

const smartBedWaitingAdmissions = [
  "ER-260612-04 | Sana Sheikh | Septic shock | Critical",
  "OT-260612-02 | Mahesh Rao | Post CABG | High",
  "WARD-260612-07 | Farida Begum | Respiratory failure | High",
];

function smartBedCapability(patient: IcuPatient) {
  if (patient.unit === "Transplant ICU") return "Strict I/O + pumps + protective care";
  if (patient.unit === "Respiratory ICU") return "NIV/ventilator + suction + ABG watch";
  if (patient.unit === "Cardiothoracic ICU") return "Invasive monitor + ventilator + drains";
  if (patient.unit === "Pediatric ICU") return "Pediatric monitor + oxygen/NIV";
  if (patient.unit === "Neuro ICU") return "Neuro observation + oxygen support";
  return "Monitor + oxygen + infusion support";
}

function smartBedIsolation(patient: IcuPatient) {
  if (patient.unit === "Transplant ICU") return "Protective";
  if (patient.unit === "Respiratory ICU") return "Droplet watch";
  return "Standard";
}

function smartBedFlowStatus(patient: IcuPatient) {
  if (patient.currentStatus === "Ready for transfer") return "Transfer checklist pending";
  if (patient.currentStatus === "Discharge ordered") return "Discharge clearance in progress";
  if (patient.currentStatus === "Death workflow") return "Mortuary workflow active";
  return `${patient.admissionTime} | ICU care active`;
}

function buildSmartBedInventory(statusOverrides: Record<string, SmartBedStatus>): SmartBedInventoryRow[] {
  const devices = getCommandDeviceRows();
  const occupiedRows = icuPatients.map((patient) => ({
    id: `smart-${patient.id}`,
    bedNo: patient.bedNo,
    unit: patient.unit,
    status: statusOverrides[patient.bedNo] ?? "Occupied" as SmartBedStatus,
    patient,
    capability: smartBedCapability(patient),
    isolation: smartBedIsolation(patient),
    nurseStation: `${patient.unit} station`,
    turnaround: "-",
    reservation: "-",
    latestVital: [...icuVitals].reverse().find((row) => row.patientId === patient.id),
    device: devices.find((row) => row.bedNo === patient.bedNo),
    alertCount: icuAlerts.filter((row) => row.patientId === patient.id && row.status !== "Resolved").length,
    taskCount: icuTasks.filter((row) => row.patientId === patient.id && row.status !== "Completed").length,
    dueMedicationCount: medicationRows.filter((row) => row.patientId === patient.id && ["Due", "Late"].includes(row.status)).length,
    flowStatus: smartBedFlowStatus(patient),
  }));

  const emptyRows = smartBedEmptyInventory.map((bed) => ({
    ...bed,
    status: statusOverrides[bed.bedNo] ?? bed.status,
    device: devices.find((row) => row.bedNo === bed.bedNo),
    alertCount: bed.status === "Maintenance" || bed.status === "Blocked" ? 1 : 0,
    taskCount: bed.status === "Cleaning" || bed.status === "Maintenance" || bed.status === "Blocked" ? 1 : 0,
    dueMedicationCount: 0,
  }));

  return [...occupiedRows, ...emptyRows];
}

function smartBedStatusTone(status: SmartBedStatus): StatusTone {
  if (status === "Available") return "success";
  if (status === "Occupied") return "info";
  if (status === "Reserved" || status === "Cleaning") return "warning";
  if (status === "Maintenance") return "danger";
  return "critical";
}

function smartBedDeviceLabel(row: SmartBedInventoryRow) {
  if (!row.device) return row.status === "Available" ? "Ready, not mapped" : "Not mapped";
  if (row.device.connectivity !== "Online") return "Offline";
  if (row.device.signal !== "Good") return "Signal degraded";
  return "Online";
}

type SmartBedCellKind = "status" | "risk" | "monitoring" | "ventilation" | "device" | "work" | "team" | "flow";

function smartBedDashboardTone(row: SmartBedInventoryRow, kind: SmartBedCellKind): DashboardCellTone {
  if (kind === "status") {
    if (row.status === "Available") return "success";
    if (row.status === "Occupied") return "info";
    if (row.status === "Reserved" || row.status === "Cleaning") return "warning";
    return "danger";
  }
  if (kind === "risk") {
    const score = row.patient?.criticalityScore ?? 0;
    if (score >= 9) return "critical";
    if (score >= 8) return "danger";
    if (score >= 5) return "purple";
    return row.patient ? "success" : "muted";
  }
  if (kind === "monitoring") {
    if (!row.latestVital) return "muted";
    if (row.latestVital.spo2 < 92 || row.latestVital.abnormal) return "critical";
    if (row.latestVital.spo2 < 95) return "warning";
    return "success";
  }
  if (kind === "ventilation") {
    if (!row.patient) return row.status === "Available" ? "info" : "muted";
    if (row.patient.ventilatorStatus === "Room air") return "success";
    return "purple";
  }
  if (kind === "device") {
    const state = smartBedDeviceLabel(row);
    if (state === "Online" || state === "Ready, not mapped") return "success";
    if (state === "Signal degraded") return "warning";
    return "danger";
  }
  if (kind === "work") {
    if (row.alertCount) return "danger";
    if (row.taskCount || row.dueMedicationCount) return "warning";
    return "success";
  }
  if (kind === "team") return row.patient ? "info" : "muted";
  if (row.status === "Available") return "success";
  if (row.status === "Cleaning" || row.status === "Reserved") return "warning";
  if (row.status === "Maintenance" || row.status === "Blocked") return "danger";
  return row.patient?.currentStatus === "Ready for transfer" ? "info" : "success";
}

function smartBedStatusToneFromDashboard(tone: DashboardCellTone): StatusTone {
  if (tone === "critical" || tone === "danger") return "danger";
  if (tone === "warning" || tone === "purple") return "warning";
  if (tone === "success") return "success";
  return "info";
}

function smartBedPatientRoute(row: SmartBedInventoryRow, kind: SmartBedCellKind) {
  if (!row.patient) return undefined;
  if (kind === "status" || kind === "ventilation" || kind === "device" || kind === "work" || kind === "team" || kind === "flow") return undefined;
  if (kind === "monitoring") return icuPatientDetailHref(row.patient.id, "monitoring", "24h-chart");
  return icuPatientDetailHref(row.patient.id, "overview");
}

function smartBedAssignedToLabel(row: SmartBedInventoryRow) {
  if (!row.patient) {
    if (row.status === "Cleaning") return "Housekeeping";
    if (row.status === "Maintenance") return "Biomedical";
    if (row.status === "Blocked") return "Infection Control";
    return "Bed Coordinator";
  }
  if (row.alertCount > 0 || row.patient.criticalityScore >= 8) return row.patient.dutyDoctor;
  if (row.taskCount > 0 || row.dueMedicationCount > 0) return row.patient.assignedWardNurse;
  return row.patient.assignedUnitNurse;
}

function smartBedCell(row: SmartBedInventoryRow, kind: SmartBedCellKind): DashboardCell {
  if (kind === "status") {
    return {
      title: row.status,
      detail: row.status === "Occupied" ? row.unit : row.turnaround,
      tone: smartBedDashboardTone(row, kind),
      icon: BedDouble,
    };
  }
  if (kind === "risk") {
    return {
      title: row.patient ? `Score ${row.patient.criticalityScore}` : "No patient",
      detail: row.patient?.currentStatus ?? "Bed not allocated",
      tone: smartBedDashboardTone(row, kind),
      icon: ShieldAlert,
    };
  }
  if (kind === "monitoring") {
    return {
      title: row.latestVital ? `SpO2 ${row.latestVital.spo2}%` : "No data",
      detail: row.latestVital ? `${row.latestVital.bp} | P ${row.latestVital.pulse}` : "Awaiting patient",
      tone: smartBedDashboardTone(row, kind),
      icon: HeartPulse,
    };
  }
  if (kind === "ventilation") {
    const support = row.patient?.ventilatorStatus ?? "Support ready";
    const shortSupport = support === "Invasive ventilation" ? "Invasive"
      : support === "NIV support" ? "NIV support"
        : support === "Oxygen mask" ? "Oxygen mask"
          : support === "Room air" ? "Room air"
            : support;
    return {
      title: shortSupport,
      detail: row.device?.ventilator ?? row.capability,
      tone: smartBedDashboardTone(row, kind),
      icon: Activity,
    };
  }
  if (kind === "device") {
    return {
      title: smartBedDeviceLabel(row),
      detail: row.device
        ? row.device.issue !== "No issue" ? row.device.issue : `${row.device.monitor} | ${row.device.gateway}`
        : "Map after allocation",
      tone: smartBedDashboardTone(row, kind),
      icon: Activity,
    };
  }
  if (kind === "work") {
    const openCount = row.alertCount + row.taskCount + row.dueMedicationCount;
    return {
      title: openCount ? `${openCount} pending` : "No pending",
      detail: `${row.alertCount} alert | ${row.taskCount} task | ${row.dueMedicationCount} med`,
      tone: smartBedDashboardTone(row, kind),
      icon: AlertTriangle,
    };
  }
  if (kind === "team") {
    return {
      title: smartBedAssignedToLabel(row),
      detail: row.patient ? `${row.patient.assignedWardNurse} | ${row.patient.dutyDoctor}` : row.nurseStation,
      tone: smartBedDashboardTone(row, kind),
      icon: UserRound,
    };
  }
  const flowTitle = row.status === "Available"
    ? "Allocate"
    : row.status === "Cleaning"
      ? row.turnaround
      : row.status === "Reserved"
        ? "Incoming"
        : row.status === "Maintenance" || row.status === "Blocked"
          ? "Resolve"
          : row.patient?.currentStatus === "Ready for transfer"
            ? "Transfer"
            : "Active";
  return {
    title: flowTitle,
    detail: row.reservation !== "-" ? row.reservation : row.flowStatus,
    tone: smartBedDashboardTone(row, kind),
    icon: ArrowRightLeft,
  };
}

function SmartBedCommandCell({
  row,
  kind,
  onOpenBed,
}: {
  row: SmartBedInventoryRow;
  kind: SmartBedCellKind;
  onOpenBed: () => void;
}) {
  const cell = smartBedCell(row, kind);
  const route = smartBedPatientRoute(row, kind);
  const actionCell = ["device", "work", "team", "flow"].includes(kind);
  const content = actionCell
    ? <SmartBedActionCircleCell cell={cell} kind={kind} />
    : <span className="flex min-h-[72px] w-full items-center justify-center pt-8"><VitalTrafficPill cell={cell} icon={cell.icon} /></span>;

  if (route) {
    return (
      <Link className="inline-flex w-full justify-center" href={route} title={`${cell.title} - ${cell.detail}`}>
        {content}
      </Link>
    );
  }

  return (
    <button className="inline-flex w-full justify-center" type="button" onClick={onOpenBed} title={`${cell.title} - ${cell.detail}`}>
      {content}
    </button>
  );
}

function SmartBedActionCircleCell({ cell, kind }: { cell: DashboardCell; kind: SmartBedCellKind }) {
  const Icon = cell.icon;
  const hideDetail = ["device", "work", "team", "flow"].includes(kind);
  const actionClass = kind === "team"
    ? "bg-sky-600 hover:bg-sky-700"
    : kind === "flow" && cell.tone === "info"
      ? "bg-sky-600 hover:bg-sky-700"
      : cell.tone === "critical" || cell.tone === "danger"
        ? "bg-red-600 hover:bg-red-700"
        : cell.tone === "warning"
          ? "bg-amber-500 hover:bg-amber-600"
          : cell.tone === "success"
            ? "bg-emerald-600 hover:bg-emerald-700"
            : "bg-slate-700 hover:bg-slate-800";

  return (
    <span className="flex min-h-[72px] w-full min-w-28 flex-col items-center justify-center gap-1.5 py-1">
      <span className={cn("inline-flex h-10 w-10 items-center justify-center rounded-full text-white shadow-[0_3px_8px_rgba(0,0,0,0.28)] transition", actionClass)}>
        <Icon className="h-4 w-4" />
      </span>
      <span className="block w-full max-w-32 truncate whitespace-nowrap text-center text-xs font-bold leading-tight text-slate-800" title={cell.title}>{cell.title}</span>
      <span className={cn("block w-full max-w-32 truncate whitespace-nowrap text-center text-[11px] leading-tight text-slate-500", hideDetail && "hidden")} aria-hidden={hideDetail}>
        {cell.detail || "-"}
      </span>
    </span>
  );
}

function SmartBedViewCommand() {
  const [search, setSearch] = React.useState("");
  const [unit, setUnit] = React.useState("All ICU units");
  const [bedStatus, setBedStatus] = React.useState("All bed status");
  const [clinical, setClinical] = React.useState("All clinical priority");
  const [deviceStatus, setDeviceStatus] = React.useState("All device status");
  const [statusOverrides, setStatusOverrides] = React.useState<Record<string, SmartBedStatus>>({});
  const [activeBedAction, setActiveBedAction] = React.useState<{ id: string; kind: SmartBedCellKind } | null>(null);

  const inventory = React.useMemo(() => buildSmartBedInventory(statusOverrides), [statusOverrides]);
  const activeBed = inventory.find((row) => row.id === activeBedAction?.id) ?? null;
  const units = ["All ICU units", ...Array.from(new Set(inventory.map((row) => row.unit)))];
  const rows = inventory.filter((row) => {
    const text = `${row.bedNo} ${row.unit} ${row.status} ${row.patient?.patientName ?? ""} ${row.patient?.mrn ?? ""} ${row.capability} ${row.device?.monitor ?? ""} ${row.device?.ventilator ?? ""}`.toLowerCase();
    const clinicalMatch = clinical === "All clinical priority"
      || (clinical === "Critical" && Boolean(row.patient && row.patient.criticalityScore >= 9))
      || (clinical === "High risk" && Boolean(row.patient && row.patient.criticalityScore >= 7))
      || (clinical === "Stable" && Boolean(row.patient && row.patient.criticalityScore < 7))
      || (clinical === "No patient" && !row.patient);
    const deviceLabel = smartBedDeviceLabel(row);
    return text.includes(search.toLowerCase())
      && (unit === "All ICU units" || row.unit === unit)
      && (bedStatus === "All bed status" || row.status === bedStatus)
      && clinicalMatch
      && (deviceStatus === "All device status" || deviceLabel === deviceStatus);
  });
  const pagination = useIcuCommandPagination(rows);

  const occupied = inventory.filter((row) => row.status === "Occupied").length;
  const available = inventory.filter((row) => row.status === "Available").length;
  const critical = inventory.filter((row) => (row.patient?.criticalityScore ?? 0) >= 8).length;
  const ventilated = inventory.filter((row) => row.patient && row.patient.ventilatorStatus !== "Room air").length;
  const turnover = inventory.filter((row) => row.status === "Cleaning" || row.status === "Reserved").length;
  const deviceIssues = inventory.filter((row) => {
    if (row.device) return row.device.connectivity !== "Online" || row.device.signal !== "Good";
    return row.status === "Occupied" || row.status === "Reserved" || row.status === "Maintenance";
  }).length;

  return (
    <div className="min-w-0 max-w-full space-y-4 overflow-hidden">
      <CollapsibleCommandPanel
        summary={`${unit} | ${bedStatus} | ${clinical} | ${rows.length} bed(s)`}
        title="Smart bed metrics & filters"
      >
        <div className="grid grid-cols-2 gap-2 border-b border-slate-200 px-3 py-3 sm:flex sm:flex-wrap sm:items-center">
          <DashboardCommandMetric label="Total beds" value={inventory.length} tone="info" />
          <DashboardCommandMetric label="Occupied" value={occupied} tone="info" />
          <DashboardCommandMetric label="Available" value={available} tone="success" />
          <DashboardCommandMetric label="Critical / high" value={critical} tone="critical" />
          <DashboardCommandMetric label="Ventilated" value={ventilated} tone="purple" />
          <DashboardCommandMetric label="Turnover" value={turnover} tone="warning" />
          <DashboardCommandMetric label="Device issue" value={deviceIssues} tone={deviceIssues ? "danger" : "success"} />
          <DashboardCommandMetric label="Waiting" value={smartBedWaitingAdmissions.length} tone="warning" />
        </div>

        <div className="grid gap-2 p-3 md:grid-cols-2 xl:grid-cols-[minmax(260px,1.6fr)_repeat(4,minmax(150px,1fr))_auto]">
          <div className="relative">
            <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
            <Input className="h-10 pl-9" placeholder="Search bed, patient, MRN, device..." value={search} onChange={(event) => setSearch(event.target.value)} />
          </div>
          <select className="h-10 rounded-md border border-slate-300 bg-white px-3 text-sm" value={unit} onChange={(event) => setUnit(event.target.value)}>
            {units.map((option) => <option key={option}>{option}</option>)}
          </select>
          <select className="h-10 rounded-md border border-slate-300 bg-white px-3 text-sm" value={bedStatus} onChange={(event) => setBedStatus(event.target.value)}>
            {["All bed status", "Occupied", "Available", "Reserved", "Cleaning", "Maintenance", "Blocked"].map((option) => <option key={option}>{option}</option>)}
          </select>
          <select className="h-10 rounded-md border border-slate-300 bg-white px-3 text-sm" value={clinical} onChange={(event) => setClinical(event.target.value)}>
            {["All clinical priority", "Critical", "High risk", "Stable", "No patient"].map((option) => <option key={option}>{option}</option>)}
          </select>
          <select className="h-10 rounded-md border border-slate-300 bg-white px-3 text-sm" value={deviceStatus} onChange={(event) => setDeviceStatus(event.target.value)}>
            {["All device status", "Online", "Signal degraded", "Offline", "Ready, not mapped", "Not mapped"].map((option) => <option key={option}>{option}</option>)}
          </select>
          <Button variant="outline" onClick={() => {
            setSearch("");
            setUnit("All ICU units");
            setBedStatus("All bed status");
            setClinical("All clinical priority");
            setDeviceStatus("All device status");
          }}>Reset</Button>
        </div>
      </CollapsibleCommandPanel>

      <div className="overflow-hidden rounded-sm border border-slate-300 bg-white shadow-sm">
        <div className="flex flex-col gap-2 border-b border-slate-200 px-3 py-2 sm:flex-row sm:items-center sm:justify-end">
          <IcuLegend />
        </div>

        <div className="max-h-[650px] overflow-auto">
          <table className="w-full min-w-[1260px] border-collapse bg-white text-sm">
            <thead className="sticky top-0 z-20 bg-white">
              <tr className="border-b border-slate-300 text-[11px] uppercase text-sky-700">
                <th className="sticky left-0 z-40 w-[210px] min-w-[210px] bg-white px-3 py-3 text-left">Patient</th>
                <th className="w-[190px] min-w-[190px] px-3 py-3 text-left">Bed Readiness</th>
                <th className="min-w-[120px] px-2 py-3 text-center">Status</th>
                <th className="min-w-[120px] px-2 py-3 text-center">Risk</th>
                <th className="min-w-[130px] px-2 py-3 text-center">Monitoring</th>
                <th className="min-w-[130px] px-2 py-3 text-center">Ventilation</th>
                <th className="min-w-[120px] px-2 py-3 text-center">Device</th>
                <th className="min-w-[130px] px-2 py-3 text-center">Pending work</th>
                <th className="min-w-[130px] px-2 py-3 text-center">Assigned team</th>
                <th className="min-w-[130px] px-2 py-3 text-center">Bed flow</th>
              </tr>
            </thead>
            <tbody>
              {pagination.pageRows.map((row) => (
                <tr className="border-b border-slate-200 last:border-b-0 hover:bg-sky-50/40" key={row.id}>
                  <td className="sticky left-0 z-10 bg-white px-3 py-2 align-middle shadow-[8px_0_14px_-15px_rgba(15,23,42,0.45)]">
                    {row.patient ? (
                      <Link className="block max-w-[188px] rounded-md px-2 py-2 transition hover:bg-sky-50" href={icuPatientDetailHref(row.patient.id, "overview")}>
                        <p className={cn("truncate text-sm font-bold", dashboardToneTextClass(smartBedDashboardTone(row, "risk")))}>{row.patient.patientName}</p>
                        <p className="mt-1 truncate text-xs font-semibold text-slate-700">{row.bedNo} | {row.unit}</p>
                      </Link>
                    ) : (
                      <button className="block max-w-[188px] rounded-md px-2 py-2 text-left transition hover:bg-sky-50" type="button" onClick={() => setActiveBedAction({ id: row.id, kind: "status" })}>
                        <p className={cn("truncate text-sm font-bold", dashboardToneTextClass(smartBedDashboardTone(row, "status")))}>No patient assigned</p>
                        <p className="mt-1 truncate text-xs font-semibold text-slate-700">{row.bedNo} | {row.unit}</p>
                      </button>
                    )}
                  </td>
                  <td className="px-3 py-2 align-middle">
                    <div className="flex min-h-[72px] max-w-[170px] flex-col justify-center gap-1">
                      <p className="truncate whitespace-nowrap text-sm font-bold text-slate-950" title={`${row.status} | ${row.turnaround}`}>
                        {row.status === "Available" ? "Ready now" : row.turnaround}
                      </p>
                      <p className="truncate whitespace-nowrap text-xs font-semibold text-slate-700" title={`${row.capability} | ${row.isolation} | ${row.flowStatus}`}>
                        {row.capability}
                      </p>
                    </div>
                  </td>
                  {(["status", "risk", "monitoring", "ventilation", "device", "work", "team", "flow"] as SmartBedCellKind[]).map((kind) => (
                    <td className="px-2 py-2 text-center align-middle" key={`${row.id}-${kind}`}>
                      <SmartBedCommandCell kind={kind} onOpenBed={() => setActiveBedAction({ id: row.id, kind })} row={row} />
                    </td>
                  ))}
                </tr>
              ))}
              {!rows.length ? (
                <tr>
                  <td className="px-4 py-12 text-center text-sm text-slate-500" colSpan={10}>No smart bed matched the selected filters.</td>
                </tr>
              ) : null}
            </tbody>
          </table>
        </div>
        <IcuCommandPaginationControls {...pagination} />
      </div>
      <SmartBedActionDialog
        actionKind={activeBedAction?.kind ?? "status"}
        bed={activeBed}
        key={`${activeBed?.id ?? "closed-smart-bed-dialog"}-${activeBedAction?.kind ?? "status"}`}
        onOpenChange={(open) => {
          if (!open) setActiveBedAction(null);
        }}
        onUpdateStatus={(bedNo, nextStatus) => {
          setStatusOverrides((current) => ({ ...current, [bedNo]: nextStatus }));
          setActiveBedAction(null);
        }}
      />
    </div>
  );
}

function smartBedActionTitle(kind: SmartBedCellKind, bed: SmartBedInventoryRow) {
  if (kind === "ventilation") return [`${bed.bedNo} ventilation workflow`, "Respiratory support, ventilator mode, oxygen settings, ABG readiness, suction, and bundle review."] as const;
  if (kind === "device") return [`${bed.bedNo} device workflow`, "Monitor, ventilator, pump, gateway, signal, biomedical owner, and downtime action."] as const;
  if (kind === "work") return [`${bed.bedNo} pending work`, "Open alerts, due medicines, nursing tasks, acknowledgement status, and next escalation step."] as const;
  if (kind === "team") return [`${bed.bedNo} assigned team`, "Ward nurse, unit nurse, duty doctor, and support team responsible for this bed."] as const;
  if (kind === "flow") return [`${bed.bedNo} bed flow`, "Current bed movement: admission, active stay, transfer, cleaning, reservation, maintenance, or release."] as const;
  return [`${bed.bedNo} bed status`, "Bed availability, capability, isolation, owner, and operational readiness."] as const;
}

function smartBedDefaultOwner(bed: SmartBedInventoryRow, kind: SmartBedCellKind) {
  if (kind === "ventilation") return bed.patient?.dutyDoctor ?? "Duty Doctor";
  if (kind === "device" || bed.status === "Maintenance") return "Biomedical Raj";
  if (kind === "work") return bed.patient?.dutyDoctor ?? "Head Nurse Sana";
  if (kind === "team") return bed.patient?.assignedUnitNurse ?? "Head Nurse Sana";
  if (bed.status === "Cleaning") return "Housekeeping Team A";
  if (bed.status === "Blocked") return "Infection Control Team";
  return "ICU Bed Coordinator";
}

function smartBedPrimaryLabel(bed: SmartBedInventoryRow, kind: SmartBedCellKind) {
  if (kind === "ventilation") return "Save ventilation review";
  if (kind === "device") return smartBedDeviceLabel(bed) === "Online" ? "Mark checked" : "Assign biomedical";
  if (kind === "work") return bed.alertCount ? "Acknowledge pending work" : "Save work note";
  if (kind === "team") return "Notify team";
  if (kind === "flow" && bed.patient) return bed.patient.currentStatus === "Ready for transfer" ? "Start transfer" : "Save flow note";
  if (bed.status === "Available") return "Reserve bed";
  if (bed.status === "Cleaning") return "Mark ready";
  if (bed.status === "Maintenance") return "Send for cleaning";
  if (bed.status === "Blocked") return "Release block";
  if (bed.status === "Reserved") return "Confirm reservation";
  return "Save bed update";
}

function SmartBedActionDialog({
  actionKind,
  bed,
  onOpenChange,
  onUpdateStatus,
}: {
  actionKind: SmartBedCellKind;
  bed: SmartBedInventoryRow | null;
  onOpenChange: (open: boolean) => void;
  onUpdateStatus: (bedNo: string, status: SmartBedStatus) => void;
}) {
  const [request, setRequest] = React.useState(smartBedWaitingAdmissions[0]);
  const [owner, setOwner] = React.useState(bed ? smartBedDefaultOwner(bed, actionKind) : "ICU Bed Coordinator");
  const [note, setNote] = React.useState("");

  if (!bed) return null;

  const patientAlerts = bed.patient ? icuAlerts.filter((row) => row.patientId === bed.patient?.id && row.status !== "Resolved") : [];
  const patientTasks = bed.patient ? icuTasks.filter((row) => row.patientId === bed.patient?.id && row.status !== "Completed") : [];
  const patientMeds = bed.patient ? medicationRows.filter((row) => row.patientId === bed.patient?.id && ["Due", "Late"].includes(row.status)) : [];
  const patientInfusions = bed.patient ? infusionRows.filter((row) => row.patientId === bed.patient?.id) : [];
  const ventilationSupport = bed.patient?.ventilatorStatus ?? (bed.status === "Available" ? "Support ready" : "No patient support");
  const ventilationType = ventilationSupport === "Invasive ventilation"
    ? "Invasive mechanical ventilation"
    : ventilationSupport === "NIV support"
      ? "Non-invasive ventilation"
      : ventilationSupport === "Oxygen mask"
        ? "Oxygen therapy"
        : ventilationSupport === "Room air"
          ? "Room air observation"
          : "Respiratory support readiness";
  const ventilationMode = ventilationSupport === "Invasive ventilation"
    ? "AC/VC or SIMV as ordered"
    : ventilationSupport === "NIV support"
      ? "BiPAP / CPAP readiness"
      : ventilationSupport === "Oxygen mask"
        ? "Mask oxygen support"
        : ventilationSupport === "Room air"
          ? "No active ventilatory support"
          : "NIV / oxygen / suction ready";
  const oxygenDetail = bed.latestVital ? `${bed.latestVital.oxygenFlow} | FiO2 ${icuFio2Value(bed.latestVital.oxygenFlow)}%` : "No active oxygen chart";
  const [dialogTitle, dialogDescription] = smartBedActionTitle(actionKind, bed);
  const nextStatus: SmartBedStatus = bed.status === "Available"
    ? "Reserved"
    : bed.status === "Cleaning"
      ? "Available"
      : bed.status === "Maintenance" || bed.status === "Blocked"
        ? "Cleaning"
        : bed.status;
  const primaryLabel = smartBedPrimaryLabel(bed, actionKind);
  const shouldUpdateBedStatus = actionKind === "status" || (actionKind === "flow" && !bed.patient);
  const pendingWorkRows = bed.patient ? [
    ...patientAlerts.map((row) => ({
      category: "Alert",
      item: row.message,
      assignedTo: row.owner || bed.patient?.dutyDoctor || "Duty Doctor",
      status: row.status,
      tone: row.severity === "Critical" ? "danger" as StatusTone : "warning" as StatusTone,
    })),
    ...patientTasks.map((row) => ({
      category: "Task",
      item: `${row.dueTime}: ${row.title}`,
      assignedTo: row.assignedTo || bed.patient?.assignedWardNurse || "Ward Nurse",
      status: row.status,
      tone: row.status === "Overdue" ? "danger" as StatusTone : "info" as StatusTone,
    })),
    ...patientMeds.map((row) => ({
      category: "Medication",
      item: `${row.scheduledTime}: ${row.medication}`,
      assignedTo: row.administeredBy === "-" ? bed.patient?.assignedWardNurse || "Ward Nurse" : row.administeredBy,
      status: row.status,
      tone: row.status === "Late" ? "danger" as StatusTone : "warning" as StatusTone,
    })),
  ] : [
    {
      category: "Bed",
      item: bed.status === "Available" ? "Bed ready for allocation" : bed.flowStatus,
      assignedTo: smartBedAssignedToLabel(bed),
      status: bed.status,
      tone: smartBedStatusTone(bed.status),
    },
    ...(bed.status === "Cleaning" || bed.status === "Maintenance" || bed.status === "Blocked" ? [{
      category: "Operations",
      item: bed.turnaround,
      assignedTo: smartBedDefaultOwner(bed, actionKind),
      status: "Pending",
      tone: "warning" as StatusTone,
    }] : []),
  ];

  return (
    <Dialog.Root open={Boolean(bed)} onOpenChange={onOpenChange}>
      <Dialog.Portal>
        <Dialog.Overlay className="fixed inset-0 z-50 bg-black/40 backdrop-blur-[1px]" />
        <Dialog.Content className="fixed left-1/2 top-1/2 z-50 flex max-h-[90dvh] w-[min(760px,calc(100vw-24px))] -translate-x-1/2 -translate-y-1/2 flex-col overflow-hidden rounded-lg border border-slate-200 bg-white shadow-soft outline-none">
          <div className="flex items-start justify-between gap-3 border-b border-slate-200 bg-sky-700 px-4 py-3 text-white">
            <div>
              <Dialog.Title className="text-base font-bold">{dialogTitle}</Dialog.Title>
              <Dialog.Description className="mt-1 text-xs text-sky-100">{dialogDescription}</Dialog.Description>
            </div>
            <Dialog.Close asChild><Button className="text-white hover:bg-white/10" size="icon" variant="ghost"><X className="h-4 w-4" /></Button></Dialog.Close>
          </div>

          <div className="overflow-y-auto p-4">
            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
              <MiniMetric label="Bed status" value={bed.status} tone={smartBedStatusTone(bed.status)} />
              <MiniMetric label="Patient" value={bed.patient?.patientName ?? "Unassigned"} tone={bed.patient ? "info" : "success"} />
              <MiniMetric label={actionKind === "ventilation" ? "Support" : "Device"} value={actionKind === "ventilation" ? ventilationSupport : smartBedDeviceLabel(bed)} tone={actionKind === "ventilation" ? smartBedStatusToneFromDashboard(smartBedDashboardTone(bed, "ventilation")) : smartBedDeviceLabel(bed) === "Online" ? "success" : "warning"} />
              <MiniMetric label={actionKind === "work" ? "Pending work" : "Turnaround"} value={actionKind === "work" ? bed.alertCount + bed.taskCount + bed.dueMedicationCount : bed.turnaround} tone={actionKind === "work" && (bed.alertCount || bed.taskCount || bed.dueMedicationCount) ? "warning" : bed.status === "Available" ? "success" : "warning"} />
            </div>

            {actionKind === "ventilation" ? (
              <div className="mt-4 grid gap-3 md:grid-cols-2">
                <MiniList title="Ventilation setup" rows={[
                  `Support type: ${ventilationType}`,
                  `Mode / plan: ${ventilationMode}`,
                  `Ventilator / oxygen device: ${bed.device?.ventilator ?? "Not mapped"}`,
                  `Oxygen detail: ${oxygenDetail}`,
                ]} />
                <MiniList title="Latest respiratory status" rows={bed.latestVital ? [
                  `SpO2 ${bed.latestVital.spo2}%`,
                  `Respiratory rate ${bed.latestVital.respiratoryRate}/min`,
                  `GCS ${bed.latestVital.gcs}`,
                  `Last device data: ${bed.device?.lastData ?? bed.patient?.lastVitalsTime ?? "-"}`,
                ] : ["No active patient vitals available"]} />
                <MiniList title="Ventilator bundle / safety" rows={[
                  ventilationSupport === "Invasive ventilation" ? "VAP bundle: head-end elevation, oral care, sedation/weaning readiness" : "Oxygen/NIV mask fit, skin pressure area, humidification if required",
                  "Suction readiness and airway emergency trolley checked",
                  "ABG / repeat respiratory assessment due as per doctor order",
                  smartBedDeviceLabel(bed) === "Online" ? "Device connectivity live" : `Device issue: ${smartBedDeviceLabel(bed)}`,
                ]} />
                <MiniList title="Related respiratory orders" rows={patientTasks.filter((row) => /abg|vent|oxygen|resp|suction|niv/i.test(`${row.title} ${row.taskType} ${row.remarks}`)).map((row) => `${row.dueTime}: ${row.title}`).concat(
                  doctorInstructions.filter((row) => row.patientId === bed.patient?.id && /abg|vent|oxygen|resp|suction|niv/i.test(`${row.instructionType} ${row.instruction} ${row.remarks}`)).map((row) => `${row.dueTime}: ${row.instruction}`),
                )} empty="No respiratory order pending" />
              </div>
            ) : null}

            {actionKind === "device" ? (
              <div className="mt-4 grid gap-3 md:grid-cols-2">
                <MiniList title="Mapped devices" rows={[
                  `Monitor: ${bed.device?.monitor ?? "Not mapped"}`,
                  `Ventilator / oxygen: ${bed.device?.ventilator ?? "Not mapped"}`,
                  `Infusion pump: ${bed.device?.infusionPump ?? "Not mapped"}`,
                  `Gateway: ${bed.device?.gateway ?? "Not mapped"}`,
                ]} />
                <MiniList title="Signal / downtime" rows={[
                  `Connectivity: ${bed.device?.connectivity ?? smartBedDeviceLabel(bed)}`,
                  `Signal: ${bed.device?.signal ?? "Not mapped"}`,
                  `Last data: ${bed.device?.lastData ?? "No device feed"}`,
                  `Issue: ${bed.device?.issue ?? "Map devices after allocation"}`,
                ]} />
              </div>
            ) : null}

            {actionKind === "work" ? (
              <div className="mt-4 space-y-3">
                <div className="grid gap-2 sm:grid-cols-3">
                  <MiniMetric label="Alerts" value={patientAlerts.length} tone={patientAlerts.length ? "danger" : "success"} />
                  <MiniMetric label="Tasks" value={patientTasks.length} tone={patientTasks.length ? "warning" : "success"} />
                  <MiniMetric label="Medication due" value={patientMeds.length} tone={patientMeds.length ? "warning" : "success"} />
                </div>
                <div className="overflow-hidden rounded-md border border-slate-200">
                  <table className="w-full min-w-[620px] text-sm">
                    <thead className="bg-slate-50 text-left text-[11px] uppercase text-slate-500">
                      <tr>
                        <th className="px-3 py-2">Type</th>
                        <th className="px-3 py-2">Pending item</th>
                        <th className="px-3 py-2">Assigned to</th>
                        <th className="px-3 py-2">Status</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-200">
                      {pendingWorkRows.map((row, index) => (
                        <tr className="bg-white" key={`${row.category}-${row.item}-${index}`}>
                          <td className="px-3 py-2 font-semibold text-slate-700">{row.category}</td>
                          <td className="px-3 py-2 text-slate-950">{row.item}</td>
                          <td className="px-3 py-2 font-semibold text-slate-800">{row.assignedTo}</td>
                          <td className="px-3 py-2"><Badge tone={row.tone}>{row.status}</Badge></td>
                        </tr>
                      ))}
                      {!pendingWorkRows.length ? (
                        <tr>
                          <td className="px-3 py-6 text-center text-sm text-slate-500" colSpan={4}>No pending work for this bed.</td>
                        </tr>
                      ) : null}
                    </tbody>
                  </table>
                </div>
              </div>
            ) : null}

            {actionKind === "team" ? (
              <div className="mt-4 grid gap-3 md:grid-cols-2">
                <div className="space-y-2 rounded-md border border-slate-200 bg-slate-50 p-3">
                  <InfoLine label="Ward nurse" value={bed.patient?.assignedWardNurse ?? "Assign during allocation"} />
                  <InfoLine label="Unit nurse" value={bed.patient?.assignedUnitNurse ?? bed.nurseStation} />
                  <InfoLine label="Duty doctor" value={bed.patient?.dutyDoctor ?? "Assign after patient allocation"} />
                </div>
                <MiniList title="Team actions" rows={["Notify ward nurse", "Notify unit nurse", "Notify duty doctor", "Escalate to head nurse"]} />
              </div>
            ) : null}

            {actionKind === "flow" ? (
              <div className="mt-4 grid gap-3 md:grid-cols-2">
                <MiniList title="Bed flow context" rows={[
                  `Current: ${bed.flowStatus}`,
                  `Reservation: ${bed.reservation}`,
                  `Turnaround: ${bed.turnaround}`,
                  `Capability: ${bed.capability}`,
                ]} />
                <MiniList title="Related active items" rows={[
                  ...patientInfusions.slice(0, 2).map((row) => `${row.pumpNo}: ${row.fluidName} ${row.status}`),
                  ...patientTasks.slice(0, 2).map((row) => `${row.dueTime}: ${row.title}`),
                ]} empty="No patient flow blockers" />
              </div>
            ) : null}

            <div className="mt-4 grid gap-3 md:grid-cols-2">
              {(bed.status === "Available" || (actionKind === "flow" && !bed.patient)) ? (
                <label className="space-y-1 text-sm">
                  <span className="font-semibold text-slate-800">Waiting admission request</span>
                  <select className="h-10 w-full rounded-md border border-slate-300 bg-white px-3" value={request} onChange={(event) => setRequest(event.target.value)}>
                    {smartBedWaitingAdmissions.map((item) => <option key={item}>{item}</option>)}
                  </select>
                </label>
              ) : (
                <div className="rounded-md border border-slate-200 bg-slate-50 p-3 text-sm">
                  <p className="font-semibold text-slate-900">Current workflow</p>
                  <p className="mt-1 text-xs text-slate-600">{bed.flowStatus}</p>
                </div>
              )}
              <label className="space-y-1 text-sm">
                <span className="font-semibold text-slate-800">Assigned to</span>
                <select className="h-10 w-full rounded-md border border-slate-300 bg-white px-3" value={owner} onChange={(event) => setOwner(event.target.value)}>
                  {["ICU Bed Coordinator", "Head Nurse Sana", "Housekeeping Team A", "Biomedical Raj", "Infection Control Team"].map((item) => <option key={item}>{item}</option>)}
                </select>
              </label>
            </div>

            <div className="mt-4 grid gap-2 md:grid-cols-2">
              {[
                `Capability verified: ${bed.capability}`,
                `Isolation requirement: ${bed.isolation}`,
                `Device state: ${smartBedDeviceLabel(bed)}`,
                `Nurse station: ${bed.nurseStation}`,
              ].map((item) => (
                <div className="flex items-center gap-2 rounded-md border border-slate-200 border-l-sky-500 bg-white p-3 text-sm text-slate-800 shadow-sm" key={item}>
                  <CheckCircle2 className="h-4 w-4 shrink-0 text-sky-600" />
                  {item}
                </div>
              ))}
            </div>

            <label className="mt-4 block space-y-1 text-sm">
              <span className="font-semibold text-slate-800">Operational note</span>
              <textarea className="min-h-24 w-full rounded-md border border-slate-300 bg-white p-3 outline-none focus:ring-2 focus:ring-sky-200" placeholder="Document allocation, cleaning, maintenance, or escalation note..." value={note} onChange={(event) => setNote(event.target.value)} />
            </label>
          </div>

          <div className="flex flex-wrap items-center justify-between gap-3 border-t border-slate-200 bg-slate-50 px-4 py-3">
            <p className="text-xs text-slate-500">Assigned to: {owner}</p>
            <div className="flex gap-2">
              <Dialog.Close asChild><Button variant="outline">Cancel</Button></Dialog.Close>
              {bed.patient ? <Button variant="outline" asChild><Link href={icuPatientDetailHref(bed.patient.id, "overview")}>Open patient</Link></Button> : null}
              <Button onClick={() => {
                if (shouldUpdateBedStatus) {
                  onUpdateStatus(bed.bedNo, nextStatus);
                } else {
                  onOpenChange(false);
                }
                toast.success(`${bed.bedNo}: ${primaryLabel.toLowerCase()} completed`);
              }}>{primaryLabel}</Button>
            </div>
          </div>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

function IcuOperationsCommand() {
  const { queryFocus, queryUnit } = useCommandRouteContext();
  const [search, setSearch] = React.useState("");
  const [unit, setUnit] = React.useState(queryUnit || "All ICU units");
  const [shift, setShift] = React.useState("Current shift");
  const [bedStatus, setBedStatus] = React.useState("All bed status");
  const [owner, setOwner] = React.useState("All owners");
  const [activeAction, setActiveAction] = React.useState<IcuOperationActiveAction | null>(null);
  const [resolvedRows, setResolvedRows] = React.useState<Set<string>>(() => new Set());

  const inventory = React.useMemo(() => buildSmartBedInventory({}), []);
  const operationRows = React.useMemo(() => buildIcuOperationRows(inventory, resolvedRows), [inventory, resolvedRows]);
  const unitOptions = React.useMemo(() => ["All ICU units", ...Array.from(new Set(operationRows.map((row) => row.unit)))], [operationRows]);
  const ownerOptions = React.useMemo(() => ["All owners", ...Array.from(new Set(operationRows.map((row) => row.ownerGroup)))], [operationRows]);
  React.useEffect(() => {
    if (queryUnit) setUnit(queryUnit);
  }, [queryUnit]);
  const filteredRows = React.useMemo(() => {
    const query = search.trim().toLowerCase();
    return operationRows.filter((row) => {
      const searchMatch = !query
        || row.bedNo.toLowerCase().includes(query)
        || row.unit.toLowerCase().includes(query)
        || row.patientName.toLowerCase().includes(query)
        || row.mrn.toLowerCase().includes(query)
        || row.flowStatus.toLowerCase().includes(query)
        || row.blocker.toLowerCase().includes(query)
        || row.owner.toLowerCase().includes(query);
      const unitMatch = unit === "All ICU units" || row.unit === unit;
      const statusMatch = bedStatus === "All bed status" || row.bedStatus === bedStatus;
      const ownerMatch = owner === "All owners" || row.ownerGroup === owner;
      const shiftMatch = shift === "Current shift" || row.shift === shift || row.shift === "All shifts";
      return searchMatch && unitMatch && statusMatch && ownerMatch && shiftMatch;
    }).sort((left, right) => icuOperationsFocusRank(right, queryFocus) - icuOperationsFocusRank(left, queryFocus));
  }, [bedStatus, operationRows, owner, queryFocus, search, shift, unit]);
  const pagination = useIcuCommandPagination(filteredRows);

  const occupied = operationRows.filter((row) => row.bedStatus === "Occupied").length;
  const available = operationRows.filter((row) => row.bedStatus === "Available").length;
  const turnaround = operationRows.filter((row) => ["Cleaning", "Reserved", "Maintenance", "Blocked"].includes(row.bedStatus)).length;
  const pendingAdmissions = icuOperationAdmissionQueue.filter((row) => row.status !== "Allocated").length;
  const pendingMovements = operationRows.filter((row) => row.movementType !== "Active ICU care" && row.movementType !== "Closed").length;
  const staffingRisk = operationRows.filter((row) => row.staffTone === "warning" || row.staffTone === "danger").length;
  const criticalBlocks = operationRows.filter((row) => row.tone === "critical" || row.tone === "danger").length;

  return (
    <div className="min-w-0 max-w-full space-y-4 overflow-hidden">
      <CollapsibleCommandPanel
        summary={`${unit} | ${shift} | ${bedStatus} | ${filteredRows.length} bed(s)`}
        title="ICU operations metrics & filters"
      >
        <div className="grid grid-cols-2 gap-2 border-b border-slate-200 px-3 py-3 md:flex md:flex-wrap md:items-center">
          <DashboardCommandMetric label="Beds" value={operationRows.length} tone="info" />
          <DashboardCommandMetric label="Occupied" value={occupied} tone={occupied ? "info" : "muted"} />
          <DashboardCommandMetric label="Available" value={available} tone={available ? "success" : "warning"} />
          <DashboardCommandMetric label="Turnaround" value={turnaround} tone={turnaround ? "warning" : "success"} />
          <DashboardCommandMetric label="Admissions" value={pendingAdmissions} tone={pendingAdmissions ? "danger" : "success"} />
          <DashboardCommandMetric label="Movements" value={pendingMovements} tone={pendingMovements ? "warning" : "success"} />
          <DashboardCommandMetric label="Staff risk" value={staffingRisk} tone={staffingRisk ? "warning" : "success"} />
          <DashboardCommandMetric label="Critical blocks" value={criticalBlocks} tone={criticalBlocks ? "critical" : "success"} />
        </div>

        <div className="grid items-end gap-3 p-3 md:grid-cols-2 xl:grid-cols-[minmax(240px,1.35fr)_repeat(4,minmax(128px,1fr))_minmax(112px,0.7fr)] 2xl:grid-cols-[minmax(280px,1.65fr)_repeat(4,minmax(150px,1fr))_minmax(120px,0.7fr)]">
          <label className="space-y-1 text-sm">
            <span className="block text-xs font-semibold text-slate-700">Search bed / patient / blocker</span>
            <span className="relative block">
              <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
              <Input className="h-10 pl-9" placeholder="Search ICU bed, MRN, patient, owner..." value={search} onChange={(event) => setSearch(event.target.value)} />
            </span>
          </label>
          <IcuOperationsFilterSelect label="ICU unit" value={unit} onChange={setUnit} options={unitOptions} />
          <IcuOperationsFilterSelect label="Shift" value={shift} onChange={setShift} options={["Current shift", "Morning", "Evening", "Night"]} />
          <IcuOperationsFilterSelect label="Bed status" value={bedStatus} onChange={setBedStatus} options={["All bed status", "Occupied", "Available", "Reserved", "Cleaning", "Maintenance", "Blocked"]} />
          <IcuOperationsFilterSelect label="Owner" value={owner} onChange={setOwner} options={ownerOptions} />
          <div className="min-w-[112px] space-y-1">
            <span className="block text-xs font-semibold text-transparent">Reset</span>
            <Button
              className="h-10 w-full"
              variant="outline"
              onClick={() => {
                setSearch("");
                setUnit("All ICU units");
                setShift("Current shift");
                setBedStatus("All bed status");
                setOwner("All owners");
              }}
            >
              Reset
            </Button>
          </div>
        </div>
      </CollapsibleCommandPanel>

      <div className="overflow-hidden rounded-sm border border-slate-300 bg-white shadow-sm">
        <div className="flex justify-end border-b border-slate-200 bg-white px-3 py-2">
          <div className="flex flex-wrap items-center justify-end gap-2">
            <IcuLegend />
          </div>
        </div>

        <div className="max-h-[650px] overflow-auto">
          <table className="w-full min-w-[1460px] border-collapse bg-white text-sm">
            <thead className="sticky top-0 z-20 bg-white">
              <tr className="border-b border-slate-300 text-[11px] uppercase text-sky-700">
                <th className="sticky left-0 z-40 min-w-[190px] bg-white px-3 py-3 text-left">Bed / Unit</th>
                <th className="min-w-[250px] px-3 py-3 text-left">Patient</th>
                <th className="min-w-[150px] px-2 py-3 text-center">Admission / Discharge</th>
                <th className="min-w-[140px] px-2 py-3 text-center">Bed readiness</th>
                <th className="min-w-[140px] px-2 py-3 text-center">Staffing</th>
                <th className="min-w-[150px] px-2 py-3 text-center">Device / BioMed</th>
                <th className="min-w-[190px] px-2 py-3 text-center">Blocker / Owner</th>
                <th className="min-w-[120px] px-2 py-3 text-center">SLA</th>
                <th className="min-w-[130px] px-2 py-3 text-center">Action</th>
              </tr>
            </thead>
            <tbody>
              {pagination.pageRows.map((row) => (
                <tr className="border-b border-slate-200 last:border-b-0 hover:bg-sky-50/40" key={row.id}>
                  <td className="sticky left-0 z-10 bg-white px-3 py-2 align-middle shadow-[8px_0_14px_-15px_rgba(15,23,42,0.45)]">
                    <button className="block min-h-24 w-full rounded-md px-3 py-2 text-left transition hover:bg-sky-50" type="button" onClick={() => setActiveAction({ row, kind: "bed" })}>
                      <p className={cn("truncate whitespace-nowrap text-sm font-bold", dashboardToneTextClass(row.tone))}>{row.unit}</p>
                      <p className="mt-1 text-xs font-bold text-slate-700">{row.bedNo}</p>
                      <p className="mt-1 truncate whitespace-nowrap text-xs text-slate-500">{row.bedStatus} | {row.nurseStation}</p>
                    </button>
                  </td>
                  <td className="px-4 py-2 align-middle">
                    <div className="flex min-h-20 flex-col justify-center">
                      <p className="truncate whitespace-nowrap text-sm font-bold text-slate-950">{row.patientName}</p>
                      <p className="mt-1 truncate whitespace-nowrap text-xs text-slate-500">{row.mrn || row.capability}</p>
                    </div>
                  </td>
                  <td className="px-2 py-2 text-center align-middle">
                    <IcuOpsMatrixCell icon={ArrowRightLeft} title={row.movementType} detail={row.movementDetail} tone={row.movementTone} showDetail={false} onClick={() => setActiveAction({ row, kind: "movement" })} />
                  </td>
                  <td className="px-2 py-2 text-center align-middle">
                    <IcuOpsMatrixCell icon={BedDouble} title={row.bedReadiness} detail={row.turnaround} tone={row.bedTone} showDetail={false} onClick={() => setActiveAction({ row, kind: "bed-readiness" })} />
                  </td>
                  <td className="px-2 py-2 text-center align-middle">
                    <IcuOpsMatrixCell icon={UserRound} title={row.staffing} detail={row.staffDetail} tone={row.staffTone} showDetail={false} onClick={() => setActiveAction({ row, kind: "staffing" })} />
                  </td>
                  <td className="px-2 py-2 text-center align-middle">
                    <IcuOpsMatrixCell icon={Activity} title={row.deviceStatus} detail={row.deviceDetail} tone={row.deviceTone} showDetail={false} onClick={() => setActiveAction({ row, kind: "device" })} />
                  </td>
                  <td className="px-2 py-2 text-center align-middle">
                    <button className={cn("mx-auto flex min-h-20 w-full min-w-36 flex-col items-center justify-center rounded-md border p-2 transition hover:brightness-95", dashboardToneSurfaceClass(row.tone))} type="button" onClick={() => setActiveAction({ row, kind: "blocker" })}>
                      <span className={cn("rounded-full border px-2 py-0.5 text-[11px] font-bold", dashboardTonePillClass(row.tone))}>{row.ownerGroup}</span>
                      <span className="mt-1 block max-w-36 truncate whitespace-nowrap text-center text-xs font-bold text-slate-800">{row.blocker}</span>
                      <span aria-hidden className="invisible mt-0.5 block max-w-36 truncate whitespace-nowrap text-center text-[11px] text-slate-500">{row.owner}</span>
                    </button>
                  </td>
                  <td className="px-2 py-2 text-center align-middle">
                    <IcuOpsMatrixCell icon={Clock3} title={row.sla} detail={row.eta} tone={row.slaTone} showDetail={false} onClick={() => setActiveAction({ row, kind: "sla" })} />
                  </td>
                  <td className="px-2 py-2 text-center align-middle">
                    <button className="group flex w-full flex-col items-center justify-center" type="button" onClick={() => setActiveAction({ row, kind: "action" })}>
                      <span className={cn("inline-flex h-10 w-10 items-center justify-center rounded-full text-white shadow-[0_3px_8px_rgba(0,0,0,0.28)] transition group-hover:brightness-95", dashboardToneSolidClass(row.tone))}>
                        <ClipboardCheck className="h-4 w-4" />
                      </span>
                      <span className="mt-1 text-xs font-bold text-slate-800">{row.action}</span>
                    </button>
                  </td>
                </tr>
              ))}
              {!filteredRows.length ? (
                <tr>
                  <td className="px-4 py-12 text-center text-sm text-slate-500" colSpan={9}>No ICU operation matched the selected filters.</td>
                </tr>
              ) : null}
            </tbody>
          </table>
        </div>
        <IcuCommandPaginationControls {...pagination} />
      </div>

      <div className="grid gap-4 xl:grid-cols-3">
        <IcuOperationsQueuePanel
          title="Admission pressure queue"
          rows={icuOperationAdmissionQueue.map((row) => ({
            id: row.id,
            title: `${row.source} - ${row.patient}`,
            detail: `${row.need} | ${row.targetUnit}`,
            meta: `${row.eta} | ${row.owner}`,
            tone: row.tone,
          }))}
          onOpen={(id) => {
            const queueRow = icuOperationAdmissionQueue.find((item) => item.id === id);
            if (queueRow) setActiveAction({ row: operationRowFromAdmissionQueue(queueRow), kind: "admission-queue" });
          }}
        />
        <IcuOperationsQueuePanel
          title="Transfer / discharge queue"
          rows={operationRows.filter((row) => row.movementType !== "Active ICU care" && row.movementType !== "Closed").map((row) => ({
            id: row.id,
            title: `${row.bedNo} - ${row.patientName}`,
            detail: row.movementDetail,
            meta: `${row.ownerGroup} | ${row.sla}`,
            tone: row.movementTone,
          }))}
          onOpen={(id) => {
            const row = operationRows.find((item) => item.id === id);
            if (row) setActiveAction({ row, kind: "transfer-queue" });
          }}
        />
        <IcuOperationsQueuePanel
          title="Turnaround ownership"
          rows={operationRows.filter((row) => row.bedStatus !== "Occupied" && row.bedStatus !== "Available").map((row) => ({
            id: row.id,
            title: `${row.bedNo} - ${row.bedStatus}`,
            detail: row.blocker,
            meta: `${row.owner} | ${row.eta}`,
            tone: row.tone,
          }))}
          onOpen={(id) => {
            const row = operationRows.find((item) => item.id === id);
            if (row) setActiveAction({ row, kind: "turnaround-queue" });
          }}
        />
      </div>

      <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_360px]">
        <CommandSection title="Staff load by nurse">
          <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">
            {buildIcuStaffCoverageRows(operationRows).map((row) => (
              <button className={cn("rounded-md border p-3 text-left transition hover:-translate-y-0.5 hover:shadow-sm", dashboardToneSurfaceClass(row.tone))} key={row.nurse} type="button" onClick={() => toast.info(`${row.nurse}: ${row.patients} patients, ${row.tasks} tasks, ${row.alerts} alerts`)}>
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <p className="text-sm font-bold text-slate-950">{row.nurse}</p>
                    <p className="mt-1 text-xs text-slate-500">{row.role}</p>
                  </div>
                  <span className={cn("rounded-full border px-2 py-0.5 text-[11px] font-bold", dashboardTonePillClass(row.tone))}>{row.status}</span>
                </div>
                <div className="mt-3 grid grid-cols-3 gap-2 text-center text-xs">
                  <div className="rounded-md bg-white/70 p-2"><b>{row.patients}</b><br />patients</div>
                  <div className="rounded-md bg-white/70 p-2"><b>{row.tasks}</b><br />tasks</div>
                  <div className="rounded-md bg-white/70 p-2"><b>{row.alerts}</b><br />alerts</div>
                </div>
              </button>
            ))}
          </div>
        </CommandSection>
        <CommandSection title="Command ownership">
          <InfoLine label="ICU head" value="Dr. Aman Verma" />
          <InfoLine label="Head nurse" value="Head Nurse Sana" />
          <InfoLine label="Admission desk" value={`${pendingAdmissions} pending admission(s)`} />
          <InfoLine label="Housekeeping" value={`${operationRows.filter((row) => row.ownerGroup === "Housekeeping").length} active`} />
          <InfoLine label="Biomedical" value={`${operationRows.filter((row) => row.ownerGroup === "Biomedical").length} active`} />
          <InfoLine label="Escalation rule" value="Critical SLA immediately" />
        </CommandSection>
      </div>

      <IcuOperationsActionDialog
        action={activeAction}
        onOpenChange={(open) => !open && setActiveAction(null)}
        onComplete={(row, action) => {
          if (action === "Mark resolved") {
            setResolvedRows((current) => new Set([...current, row.id]));
          }
          toast.success(`${row.bedNo}: ${action.toLowerCase()} saved`);
          setActiveAction(null);
        }}
      />
    </div>
  );
}

function IcuOperationsFilterSelect({
  label,
  value,
  onChange,
  options,
}: {
  label: string;
  value: string;
  onChange: (value: string) => void;
  options: string[];
}) {
  return (
    <label className="space-y-1 text-sm">
      <span className="block text-xs font-semibold text-slate-700">{label}</span>
      <select
        className="h-10 w-full rounded-md border border-slate-300 bg-white px-3 text-sm text-slate-900 outline-none transition focus:border-primary focus:ring-2 focus:ring-ring/20"
        value={value}
        onChange={(event) => onChange(event.target.value)}
      >
        {options.map((option) => <option key={option}>{option}</option>)}
      </select>
    </label>
  );
}

type IcuOperationRow = {
  id: string;
  bedNo: string;
  unit: string;
  bedStatus: SmartBedStatus;
  patientId?: string;
  patientName: string;
  mrn: string;
  nurseStation: string;
  capability: string;
  flowStatus: string;
  movementType: string;
  movementDetail: string;
  movementTone: DashboardCellTone;
  bedReadiness: string;
  bedTone: DashboardCellTone;
  turnaround: string;
  staffing: string;
  staffDetail: string;
  staffTone: DashboardCellTone;
  deviceStatus: string;
  deviceDetail: string;
  deviceTone: DashboardCellTone;
  blocker: string;
  owner: string;
  ownerGroup: string;
  priority: string;
  tone: DashboardCellTone;
  sla: string;
  slaTone: DashboardCellTone;
  eta: string;
  action: string;
  shift: string;
  sourceSummary: string;
  decisionBasis: string;
};

type IcuOperationActionKind = "bed" | "movement" | "bed-readiness" | "staffing" | "device" | "blocker" | "sla" | "action" | "admission-queue" | "transfer-queue" | "turnaround-queue";

type IcuOperationActiveAction = {
  row: IcuOperationRow;
  kind: IcuOperationActionKind;
};

function icuOperationsFocusRank(row: IcuOperationRow, focus: string) {
  const toneRank = row.tone === "critical" ? 80 : row.tone === "danger" ? 70 : row.tone === "warning" ? 45 : row.tone === "info" ? 20 : 0;
  const movementRank = row.movementType === "Active ICU care" || row.movementType === "Closed" ? 0 : 40;
  const bedRank = row.bedStatus === "Blocked" || row.bedStatus === "Maintenance"
    ? 45
    : row.bedStatus === "Reserved" || row.bedStatus === "Cleaning"
      ? 35
      : row.bedStatus === "Occupied"
        ? 25
        : 5;
  if (focus === "occupancy" || focus === "unit") return toneRank + movementRank + bedRank;
  return toneRank + movementRank;
}

const icuOperationAdmissionQueue = [
  { id: "adm-er-sepsis", source: "Emergency", patient: "Sana Sheikh", need: "Septic shock, vasopressor watch", targetUnit: "Medical ICU", eta: "Now", owner: "Admission desk", status: "Waiting", tone: "critical" as DashboardCellTone },
  { id: "adm-ot-cabg", source: "OT", patient: "Mahesh Rao", need: "Post CABG ventilator bed", targetUnit: "Cardiothoracic ICU", eta: "35 min", owner: "OT coordinator", status: "Reserved", tone: "warning" as DashboardCellTone },
  { id: "adm-ward-resp", source: "Ward", patient: "Farida Begum", need: "Respiratory failure on NIV", targetUnit: "Respiratory ICU", eta: "20 min", owner: "Duty doctor", status: "Waiting", tone: "danger" as DashboardCellTone },
];

function buildIcuOperationRows(inventory: SmartBedInventoryRow[], resolvedRows: Set<string>): IcuOperationRow[] {
  return inventory.map((bed) => {
    const patient = bed.patient;
    const patientAlerts = patient ? icuAlerts.filter((alert) => alert.patientId === patient.id && alert.status !== "Resolved") : [];
    const patientTasks = patient ? icuTasks.filter((task) => task.patientId === patient.id && task.status !== "Completed") : [];
    const dueMeds = patient ? medicationRows.filter((medication) => medication.patientId === patient.id && ["Due", "Late"].includes(medication.status)) : [];
    const resolved = resolvedRows.has(`ops-${bed.bedNo}`);
    const movement = icuOperationMovement(patient, bed);
    const bedReadiness = icuOperationBedReadiness(bed, resolved);
    const staff = icuOperationStaffing(patient, patientTasks, patientAlerts);
    const device = icuOperationDevice(bed);
    const blocker = icuOperationBlocker(bed, patient, patientAlerts, patientTasks, dueMeds, resolved);
    const priority = icuOperationPriority(bed, patient, patientAlerts, patientTasks, dueMeds, resolved);
    const tone = icuOperationTone(priority, bed);
    const owner = icuOperationOwner(bed, patient, blocker);
    const sla = icuOperationSla(priority, bed);
    const sourceSummary = icuOperationSourceSummary(bed, patient, patientAlerts, patientTasks, dueMeds);
    const decisionBasis = icuOperationDecisionBasis(bed, patient, patientAlerts, patientTasks, dueMeds, priority);

    return {
      id: `ops-${bed.bedNo}`,
      bedNo: bed.bedNo,
      unit: bed.unit,
      bedStatus: bed.status,
      patientId: patient?.id,
      patientName: patient ? patient.patientName : "No patient assigned",
      mrn: patient?.mrn ?? "",
      nurseStation: bed.nurseStation,
      capability: bed.capability,
      flowStatus: resolved ? "Operational issue closed" : bed.flowStatus,
      movementType: resolved ? "Closed" : movement.title,
      movementDetail: resolved ? "No active movement blocker" : movement.detail,
      movementTone: resolved ? "success" : movement.tone,
      bedReadiness: bedReadiness.title,
      bedTone: bedReadiness.tone,
      turnaround: bedReadiness.detail,
      staffing: staff.title,
      staffDetail: staff.detail,
      staffTone: staff.tone,
      deviceStatus: device.title,
      deviceDetail: device.detail,
      deviceTone: device.tone,
      blocker: resolved ? "Resolved" : blocker.title,
      owner: resolved ? "Closed" : owner.name,
      ownerGroup: resolved ? "Closed" : owner.group,
      priority,
      tone,
      sla: resolved ? "Closed" : sla.title,
      slaTone: resolved ? "success" : sla.tone,
      eta: resolved ? "Completed" : sla.detail,
      action: resolved ? "Closed" : icuOperationAction(priority, bed),
      shift: icuOperationShift(patient, bed),
      sourceSummary: resolved ? "Command action log" : sourceSummary,
      decisionBasis: resolved ? "This row was manually closed by the command team." : decisionBasis,
    };
  });
}

function icuOperationSourceSummary(
  bed: SmartBedInventoryRow,
  patient: IcuPatient | undefined,
  alerts: typeof icuAlerts,
  tasks: typeof icuTasks,
  meds: typeof medicationRows,
) {
  const sources = ["Smart Bed inventory"];
  if (patient) sources.push("Patient record");
  if (alerts.length) sources.push(`${alerts.length} active alert${alerts.length > 1 ? "s" : ""}`);
  if (tasks.length) sources.push(`${tasks.length} open task${tasks.length > 1 ? "s" : ""}`);
  if (meds.length) sources.push(`${meds.length} due/late med${meds.length > 1 ? "s" : ""}`);
  if (bed.device) sources.push("Device feed");
  return sources.join(" + ");
}

function icuOperationDecisionBasis(
  bed: SmartBedInventoryRow,
  patient: IcuPatient | undefined,
  alerts: typeof icuAlerts,
  tasks: typeof icuTasks,
  meds: typeof medicationRows,
  priority: string,
) {
  if (alerts.some((alert) => alert.severity === "Critical")) return `Critical because unresolved critical alert exists for ${patient?.bedNo ?? bed.bedNo}.`;
  if (tasks.some((task) => task.priority === "Critical")) return "Critical because at least one critical nursing/clinical task is still open.";
  if (patient?.criticalityScore === 9) return "Critical because patient criticality score is 9.";
  if (bed.status === "Blocked") return "High risk because bed is blocked and cannot be allocated until clearance.";
  if (bed.status === "Maintenance") return "High risk because biomedical maintenance is active.";
  if (meds.some((medication) => medication.status === "Late")) return "High risk because medication administration is late.";
  if (bed.status === "Cleaning" || bed.status === "Reserved") return `Medium because bed status is ${bed.status.toLowerCase()} and turnaround is pending.`;
  if (patient?.currentStatus === "Ready for transfer") return "Medium because patient is transfer-ready and can release ICU capacity.";
  if (bed.status === "Available") return "Open because bed is available for allocation.";
  return `${priority} based on live bed status, patient status, active alerts, tasks, and medication queue.`;
}

function icuOperationMovement(patient: IcuPatient | undefined, bed: SmartBedInventoryRow): { title: string; detail: string; tone: DashboardCellTone } {
  if (!patient) {
    if (bed.status === "Reserved") return { title: "Admission expected", detail: bed.reservation || "Reserved for incoming patient", tone: "warning" };
    if (bed.status === "Available") return { title: "Open admission", detail: bed.flowStatus, tone: "success" };
    return { title: "No movement", detail: bed.flowStatus, tone: smartBedDashboardTone(bed, "status") };
  }
  if (patient.currentStatus === "Ready for transfer") return { title: "Transfer ready", detail: "Ward/HDU bed and handover clearance needed", tone: "info" };
  if (patient.currentStatus === "Discharge ordered") return { title: "Discharge ordered", detail: "Summary, pharmacy, billing, and family handover", tone: "warning" };
  if (patient.currentStatus === "Death workflow") return { title: "Death workflow", detail: "Declaration, family, mortuary, and bed release", tone: "critical" };
  return { title: "Active ICU care", detail: patient.currentStatus, tone: patient.criticalityScore >= 8 ? "danger" : "success" };
}

function icuOperationBedReadiness(bed: SmartBedInventoryRow, resolved: boolean): { title: string; detail: string; tone: DashboardCellTone } {
  if (resolved) return { title: "Ready", detail: "Issue closed", tone: "success" };
  if (bed.status === "Available") return { title: "Ready", detail: bed.turnaround, tone: "success" };
  if (bed.status === "Cleaning") return { title: "Cleaning", detail: bed.turnaround, tone: "warning" };
  if (bed.status === "Reserved") return { title: "Reserved", detail: bed.reservation, tone: "warning" };
  if (bed.status === "Maintenance") return { title: "Maintenance", detail: bed.turnaround, tone: "danger" };
  if (bed.status === "Blocked") return { title: "Blocked", detail: bed.turnaround, tone: "critical" };
  return { title: "Occupied", detail: "Clinical bed active", tone: "info" };
}

function icuOperationStaffing(patient: IcuPatient | undefined, tasks: typeof icuTasks, alerts: typeof icuAlerts): { title: string; detail: string; tone: DashboardCellTone } {
  if (!patient) return { title: "Standby", detail: "No nurse assigned", tone: "muted" };
  const risk = alerts.length + tasks.filter((task) => task.priority === "Critical" || task.status === "Overdue").length;
  if (risk >= 3) return { title: "Overloaded", detail: patient.assignedWardNurse, tone: "danger" };
  if (risk >= 1) return { title: "Watch", detail: patient.assignedWardNurse, tone: "warning" };
  return { title: "Covered", detail: patient.assignedWardNurse, tone: "success" };
}

function icuOperationDevice(bed: SmartBedInventoryRow): { title: string; detail: string; tone: DashboardCellTone } {
  const label = smartBedDeviceLabel(bed);
  if (label === "Online") return { title: "Online", detail: bed.device?.monitor ?? "Monitor ready", tone: "success" };
  if (label === "Signal degraded") return { title: "Signal risk", detail: bed.device?.signal ?? "Needs check", tone: "warning" };
  if (label === "Offline") return { title: "Offline", detail: bed.device?.gateway ?? "Biomedical review", tone: "danger" };
  if (bed.status === "Maintenance") return { title: "BioMed", detail: bed.turnaround, tone: "danger" };
  return { title: label, detail: bed.capability, tone: bed.status === "Available" ? "success" : "warning" };
}

function icuOperationBlocker(
  bed: SmartBedInventoryRow,
  patient: IcuPatient | undefined,
  alerts: typeof icuAlerts,
  tasks: typeof icuTasks,
  meds: typeof medicationRows,
  resolved: boolean,
): { title: string } {
  if (resolved) return { title: "Resolved" };
  if (bed.status === "Cleaning") return { title: "Cleaning turnover pending" };
  if (bed.status === "Maintenance") return { title: "Device / gateway maintenance" };
  if (bed.status === "Blocked") return { title: "Infection-control clearance" };
  if (bed.status === "Reserved") return { title: bed.reservation || "Reserved bed coordination" };
  if (meds.some((medication) => medication.status === "Late")) return { title: "Medication dispense delay" };
  const criticalAlert = alerts.find((alert) => alert.severity === "Critical" || alert.severity === "High");
  if (criticalAlert) return { title: criticalAlert.message };
  const overdueTask = tasks.find((task) => task.status === "Overdue" || task.priority === "Critical");
  if (overdueTask) return { title: overdueTask.title };
  if (patient?.currentStatus === "Ready for transfer") return { title: "Transfer checklist pending" };
  if (!patient && bed.status === "Available") return { title: "No blocker" };
  return { title: "Routine operational watch" };
}

function icuOperationOwner(bed: SmartBedInventoryRow, patient: IcuPatient | undefined, blocker: { title: string }): { name: string; group: string } {
  const lower = blocker.title.toLowerCase();
  if (lower.includes("cleaning")) return { name: "Housekeeping Team A", group: "Housekeeping" };
  if (lower.includes("device") || lower.includes("gateway") || lower.includes("biomed")) return { name: "Biomedical Raj", group: "Biomedical" };
  if (lower.includes("infection")) return { name: "Infection Control Team", group: "Infection Control" };
  if (lower.includes("medication") || lower.includes("dispense")) return { name: "Pharmacy", group: "Pharmacy" };
  if (lower.includes("transfer") || lower.includes("reserved")) return { name: patient?.assignedUnitNurse ?? "Admission Desk", group: "Admission / Transfer" };
  if (lower.includes("spo2") || lower.includes("bp") || lower.includes("abg")) return { name: patient?.dutyDoctor ?? "Duty Doctor", group: "Doctor" };
  if (bed.status === "Available") return { name: "Admission Desk", group: "Admission / Transfer" };
  return { name: patient?.assignedWardNurse ?? "Head Nurse Sana", group: "Nursing" };
}

function icuOperationPriority(
  bed: SmartBedInventoryRow,
  patient: IcuPatient | undefined,
  alerts: typeof icuAlerts,
  tasks: typeof icuTasks,
  meds: typeof medicationRows,
  resolved: boolean,
) {
  if (resolved) return "Resolved";
  if (alerts.some((alert) => alert.severity === "Critical") || tasks.some((task) => task.priority === "Critical") || patient?.criticalityScore === 9) return "Critical";
  if (bed.status === "Blocked" || bed.status === "Maintenance" || meds.some((medication) => medication.status === "Late")) return "High";
  if (bed.status === "Cleaning" || bed.status === "Reserved" || patient?.currentStatus === "Ready for transfer") return "Medium";
  if (bed.status === "Available") return "Open";
  return "Routine";
}

function icuOperationTone(priority: string, bed: SmartBedInventoryRow): DashboardCellTone {
  if (priority === "Critical") return "critical";
  if (priority === "High") return "danger";
  if (priority === "Medium") return "warning";
  if (priority === "Resolved" || priority === "Open" || bed.status === "Available") return "success";
  return "info";
}

function icuOperationSla(priority: string, bed: SmartBedInventoryRow): { title: string; detail: string; tone: DashboardCellTone } {
  if (priority === "Critical") return { title: "Now", detail: "Immediate escalation", tone: "critical" };
  if (priority === "High") return { title: "15 min", detail: "Owner follow-up", tone: "danger" };
  if (priority === "Medium") return { title: "30 min", detail: bed.turnaround, tone: "warning" };
  if (priority === "Open") return { title: "Ready", detail: "Can allocate", tone: "success" };
  if (priority === "Resolved") return { title: "Closed", detail: "Completed", tone: "success" };
  return { title: "Shift", detail: "Routine watch", tone: "info" };
}

function icuOperationAction(priority: string, bed: SmartBedInventoryRow) {
  if (priority === "Critical") return "Escalate";
  if (priority === "High") return "Assign";
  if (priority === "Medium") return bed.status === "Cleaning" ? "Track ETA" : "Follow up";
  if (priority === "Open") return "Allocate";
  if (priority === "Resolved") return "Closed";
  return "Review";
}

function icuOperationShift(patient: IcuPatient | undefined, bed: SmartBedInventoryRow) {
  if (patient?.assignedWardNurse.includes("Leena")) return "Night";
  if (bed.status === "Reserved" || bed.status === "Cleaning") return "Evening";
  return "Morning";
}

function operationRowFromAdmissionQueue(row: typeof icuOperationAdmissionQueue[number]): IcuOperationRow {
  return {
    id: `ops-${row.id}`,
    bedNo: "Pending bed",
    unit: row.targetUnit,
    bedStatus: "Reserved",
    patientName: row.patient,
    mrn: row.source,
    nurseStation: `${row.targetUnit} station`,
    capability: row.need,
    flowStatus: `${row.source} admission waiting for ICU allocation`,
    movementType: "Admission waiting",
    movementDetail: row.need,
    movementTone: row.tone,
    bedReadiness: row.status,
    bedTone: row.tone,
    turnaround: row.eta,
    staffing: "Pending",
    staffDetail: "Assign after bed confirmation",
    staffTone: "warning",
    deviceStatus: "Required",
    deviceDetail: row.targetUnit,
    deviceTone: row.tone,
    blocker: "ICU bed allocation pending",
    owner: row.owner,
    ownerGroup: "Admission / Transfer",
    priority: row.tone === "critical" ? "Critical" : "High",
    tone: row.tone,
    sla: row.eta,
    slaTone: row.tone,
    eta: row.eta,
    action: "Allocate",
    shift: "All shifts",
    sourceSummary: "Admission queue + source unit handover",
    decisionBasis: `${row.source} requested ${row.targetUnit}; status is ${row.status} and ETA is ${row.eta}.`,
  };
}

function buildIcuStaffCoverageRows(rows: IcuOperationRow[]) {
  const nurses = Array.from(new Set(icuPatients.flatMap((patient) => [patient.assignedWardNurse, patient.assignedUnitNurse])));
  return nurses.map((nurse) => {
    const assignedPatients = icuPatients.filter((patient) => patient.assignedWardNurse === nurse || patient.assignedUnitNurse === nurse);
    const assignedIds = new Set(assignedPatients.map((patient) => patient.id));
    const tasks = icuTasks.filter((task) => assignedIds.has(task.patientId) && task.status !== "Completed").length;
    const alerts = icuAlerts.filter((alert) => assignedIds.has(alert.patientId) && alert.status !== "Resolved").length;
    const critical = assignedPatients.filter((patient) => patient.criticalityScore >= 8).length;
    const tone: DashboardCellTone = critical >= 2 || tasks >= 5 ? "danger" : alerts || tasks >= 3 ? "warning" : "success";
    return {
      nurse,
      role: nurse.includes("Unit") ? "Unit nurse" : "Ward nurse",
      patients: assignedPatients.length,
      tasks,
      alerts,
      status: tone === "danger" ? "Overloaded" : tone === "warning" ? "Watch" : "Balanced",
      tone,
      rows,
    };
  });
}

