type IcuOperationsSpecificContent = {
  label: string;
  title: string;
  detail: string;
  badge: string;
  tone: DashboardCellTone;
  fields: Array<{ label: string; value: string }>;
  verifyTitle: string;
  verifyRows: string[];
  outputTitle: string;
  outputRows: string[];
};

function icuOperationsSpecificContent(row: IcuOperationRow, kind: IcuOperationActionKind, action: string, owner: string, due: string): IcuOperationsSpecificContent {
  if (kind === "bed") {
    return {
      label: "Bed / unit",
      title: `${row.bedNo} - ${row.unit}`,
      detail: "Bed identity, occupancy, ICU unit, capability, nurse station, and bed-level command status.",
      badge: row.bedStatus,
      tone: row.tone,
      fields: [
        { label: "Bed", value: row.bedNo },
        { label: "Unit", value: row.unit },
        { label: "Bed status", value: row.bedStatus },
        { label: "Nurse station", value: row.nurseStation },
        { label: "Capability", value: row.capability },
        { label: "Priority", value: row.priority },
      ],
      verifyTitle: "Bed checks",
      verifyRows: ["Correct patient is mapped to this bed", "Isolation/capability requirement reviewed", "Bed status matches physical bed", "Nurse station owner confirmed"],
      outputTitle: "Bed action outcome",
      outputRows: [`Action: ${action}`, `Owner: ${owner}`, `Due: ${due}`, "Updates bed/census command status"],
    };
  }

  if (kind === "movement" || kind === "admission-queue" || kind === "transfer-queue") {
    const admission = kind === "admission-queue" || row.movementType.toLowerCase().includes("admission");
    return {
      label: admission ? "Admission movement" : "Transfer / discharge",
      title: row.movementType,
      detail: admission ? "Incoming ICU admission allocation, source handover, target unit, ETA, and receiving ownership." : "ICU transfer/discharge movement, destination readiness, handover, transport, and bed release.",
      badge: admission ? "Admission" : "Movement",
      tone: row.movementTone,
      fields: [
        { label: admission ? "Admission need" : "Movement reason", value: row.movementDetail },
        { label: "Patient", value: row.patientName },
        { label: "Current / target unit", value: row.unit },
        { label: "Bed readiness", value: row.bedReadiness },
        { label: "Device readiness", value: row.deviceStatus },
        { label: "ETA / SLA", value: `${row.sla} - ${row.eta}` },
      ],
      verifyTitle: admission ? "Admission checks" : "Movement checks",
      verifyRows: admission ? ["Source location and clinical need verified", "Receiving ICU unit selected", "Bed/device/nurse readiness confirmed", "ER/OT/Ward ETA communicated"] : ["Destination bed/ward confirmed", "Doctor order and readiness reviewed", "Nurse handover owner assigned", "Transport, oxygen, and medication continuity checked"],
      outputTitle: "Movement outcome",
      outputRows: [`Action: ${action}`, `Coordinator: ${owner}`, `Next review: ${due}`, admission ? "Creates/updates ICU admission allocation" : "Updates transfer/discharge movement queue"],
    };
  }

  if (kind === "bed-readiness" || kind === "turnaround-queue") {
    return {
      label: "Bed readiness",
      title: row.bedReadiness,
      detail: "Cleaning, maintenance, reserved bed, blocked bed, infection clearance, and physical readiness.",
      badge: row.turnaround,
      tone: row.bedTone,
      fields: [
        { label: "Readiness", value: row.bedReadiness },
        { label: "Turnaround", value: row.turnaround },
        { label: "Bed status", value: row.bedStatus },
        { label: "Blocking service", value: row.ownerGroup },
        { label: "Owner", value: row.owner },
        { label: "SLA", value: `${row.sla} - ${row.eta}` },
      ],
      verifyTitle: "Readiness checks",
      verifyRows: ["Cleaning/maintenance status confirmed", "Oxygen, suction, monitor, bed and pump checked", "Infection-control clearance reviewed if needed", "Ready status after physical verification"],
      outputTitle: "Readiness outcome",
      outputRows: [`Action: ${action}`, `Responsible owner: ${owner}`, `Due: ${due}`, "Updates bed readiness, not patient clinical record"],
    };
  }

  if (kind === "staffing") {
    return {
      label: "Staffing",
      title: row.staffing,
      detail: "Nurse coverage, workload, pending task/alert pressure, backup nurse, and head nurse escalation.",
      badge: row.staffDetail,
      tone: row.staffTone,
      fields: [
        { label: "Coverage status", value: row.staffing },
        { label: "Primary nurse", value: row.staffDetail },
        { label: "Patient", value: row.patientName },
        { label: "Shift", value: row.shift },
        { label: "Priority", value: row.priority },
        { label: "Owner", value: row.owner },
      ],
      verifyTitle: "Staffing checks",
      verifyRows: ["Primary nurse and backup nurse identified", "Critical load reviewed", "Pending tasks and alerts considered", "Head nurse escalation documented if overloaded"],
      outputTitle: "Staffing outcome",
      outputRows: [`Action: ${action}`, `Head nurse/owner: ${owner}`, `Review: ${due}`, "Updates nurse coverage and workload visibility"],
    };
  }

  if (kind === "device") {
    return {
      label: "Device / BioMed",
      title: row.deviceStatus,
      detail: "Monitor, ventilator, pump, gateway, signal status, last-data confidence, biomedical owner, and manual fallback.",
      badge: row.deviceDetail,
      tone: row.deviceTone,
      fields: [
        { label: "Device status", value: row.deviceStatus },
        { label: "Device detail", value: row.deviceDetail },
        { label: "Bed capability", value: row.capability },
        { label: "Clinical fallback", value: row.deviceStatus === "Online" ? "Live feed usable" : "Manual bedside check needed" },
        { label: "BioMed owner", value: owner },
        { label: "SLA", value: due },
      ],
      verifyTitle: "Device checks",
      verifyRows: ["Monitor/ventilator/pump/gateway status reviewed", "Signal or offline reason checked", "Biomedical owner assigned", "Manual charting fallback documented if live feed is unreliable"],
      outputTitle: "Device outcome",
      outputRows: [`Action: ${action}`, `Responsible owner: ${owner}`, `Review: ${due}`, "Updates device readiness and biomedical queue"],
    };
  }

  if (kind === "blocker") {
    return {
      label: "Blocker / owner",
      title: row.blocker,
      detail: "Exact blocker stopping ICU flow, owner department, escalation route, and closure evidence.",
      badge: row.ownerGroup,
      tone: row.tone,
      fields: [
        { label: "Blocker", value: row.blocker },
        { label: "Owner group", value: row.ownerGroup },
        { label: "Named owner", value: row.owner },
        { label: "Impact", value: row.priority },
        { label: "SLA", value: `${row.sla} - ${row.eta}` },
        { label: "Patient/bed", value: `${row.bedNo} - ${row.patientName}` },
      ],
      verifyTitle: "Blocker checks",
      verifyRows: ["Blocker category is correct", "Named owner can act on it", "Patient safety impact reviewed", "Resolution evidence required before closure"],
      outputTitle: "Blocker outcome",
      outputRows: [`Action: ${action}`, `Owner: ${owner}`, `Due: ${due}`, "Updates blocker ownership and escalation status"],
    };
  }

  if (kind === "sla") {
    return {
      label: "SLA",
      title: row.sla,
      detail: "Due time, breach risk, next review, escalation trigger, and command follow-up.",
      badge: row.eta,
      tone: row.slaTone,
      fields: [
        { label: "Current SLA", value: row.sla },
        { label: "SLA detail", value: row.eta },
        { label: "Priority", value: row.priority },
        { label: "Owner", value: row.owner },
        { label: "Blocker", value: row.blocker },
        { label: "Next review", value: due },
      ],
      verifyTitle: "SLA checks",
      verifyRows: ["Due time matches risk", "Owner acknowledged", "Escalate if breached or near breach", "Next review time visible to command team"],
      outputTitle: "SLA outcome",
      outputRows: [`Action: ${action}`, `Owner: ${owner}`, `Next review: ${due}`, "Updates SLA and escalation timing"],
    };
  }

  return {
    label: "Command action",
    title: row.action,
    detail: "Final operational action: acknowledge, assign, escalate, resolve, and save command note.",
    badge: action,
    tone: row.tone,
    fields: [
      { label: "Action", value: row.action },
      { label: "Selected", value: action },
      { label: "Owner", value: owner },
      { label: "Due", value: due },
      { label: "Blocker", value: row.blocker },
      { label: "Priority", value: row.priority },
    ],
    verifyTitle: "Action checks",
    verifyRows: ["Action reason is clear", "Responsible owner selected", "ETA/SLA selected", "Outcome verified before closure"],
    outputTitle: "Action outcome",
    outputRows: [`Save ${action}`, `Owner: ${owner}`, `Review: ${due}`, "Writes command action note"],
  };
}

type IcuOperationsModalCopy = {
  title: string;
  description: string;
  kindLabel: string;
  focusLabel: string;
  focusValue: string;
  focusDetail: string;
  contextTitle: string;
  contextRows: string[];
  actionLabel: string;
  defaultAction: string;
  defaultOwner: string;
  defaultDue: string;
  actionOptions: string[];
  ownerOptions: string[];
  dueOptions: string[];
  checklistTitle: string;
  checklist: string[];
  note: string;
  tone: DashboardCellTone;
};

function icuOperationsModalCopy(row: IcuOperationRow, kind: IcuOperationActionKind): IcuOperationsModalCopy {
  const defaultAction = row.action === "Closed" ? "Mark resolved" : row.action === "Assign" ? "Assign owner" : row.action;
  const baseActions = uniqueTextValues([defaultAction, "Assign owner", "Acknowledge", "Escalate", "Mark resolved"]);
  const baseOwners = uniqueTextValues([row.owner, "Head Nurse Sana", "Admission Desk", "Housekeeping Team A", "Biomedical Raj", "Pharmacy", "Duty Doctor", "Infection Control Team"]);
  const baseDue = uniqueTextValues([row.sla, "Now", "15 min", "30 min", "Current shift", "Before transfer", "Closed"]);
  const baseNote = `${row.bedNo} ${row.unit}. Patient: ${row.patientName}. Blocker: ${row.blocker}. Owner: ${row.owner}. SLA: ${row.sla} (${row.eta}). Source: ${row.sourceSummary}. Basis: ${row.decisionBasis}`;
  const base = {
    description: `${row.unit} | ${row.patientName} | ${row.blocker}`,
    actionLabel: "Next action",
    defaultAction,
    defaultOwner: row.owner,
    defaultDue: row.sla,
    actionOptions: baseActions,
    ownerOptions: baseOwners,
    dueOptions: baseDue,
    note: baseNote,
    tone: row.tone,
  };

  if (kind === "bed") {
    return {
      ...base,
      title: `${row.bedNo} bed command`,
      kindLabel: "Bed",
      focusLabel: "Bed status",
      focusValue: row.bedStatus,
      focusDetail: "Use this to confirm bed occupancy, isolation need, capability, and command ownership.",
      contextTitle: "Bed context",
      contextRows: [row.nurseStation, row.capability, row.flowStatus, row.turnaround],
      actionOptions: uniqueTextValues([defaultAction, "Validate bed", "Assign owner", "Allocate", "Escalate", "Mark resolved"]),
      checklistTitle: "Bed command checklist",
      checklist: [
        "Bed status matches live ICU census",
        "Patient-bed mapping is correct",
        "Isolation, oxygen, monitor, and capability need reviewed",
        "Nurse station ownership confirmed",
        "Admission/transfer desk informed if bed can move",
        "Command center status updated",
      ],
      note: `${baseNote} Bed command review opened for ${row.bedStatus}.`,
      tone: row.tone,
    };
  }

  if (kind === "movement" || kind === "admission-queue" || kind === "transfer-queue") {
    const admission = kind === "admission-queue" || row.movementType.toLowerCase().includes("admission");
    return {
      ...base,
      title: admission ? `${row.unit} admission movement` : `${row.bedNo} transfer / discharge movement`,
      kindLabel: admission ? "Admission" : "Movement",
      focusLabel: "Movement status",
      focusValue: row.movementType,
      focusDetail: row.movementDetail,
      contextTitle: "Movement context",
      contextRows: [row.flowStatus, row.bedReadiness, row.staffing, row.deviceStatus],
      actionOptions: uniqueTextValues([defaultAction, admission ? "Allocate bed" : "Coordinate movement", "Acknowledge", "Escalate", "Mark resolved"]),
      ownerOptions: uniqueTextValues([row.owner, "Admission Desk", "Duty Doctor", "Head Nurse Sana", "Ward Coordinator", "Transport Team"]),
      checklistTitle: admission ? "Admission allocation checklist" : "Transfer / discharge checklist",
      checklist: admission ? [
        "Source location and clinical need verified",
        "Target ICU unit and bed capability confirmed",
        "Doctor acceptance and nurse receiving owner assigned",
        "Ventilator/device readiness checked",
        "ETA communicated to ER/OT/Ward",
        "Bed allocation updated in command center",
      ] : [
        "Destination bed or discharge destination confirmed",
        "Clinical readiness and doctor order reviewed",
        "Nurse handover and transport plan assigned",
        "Devices, oxygen, and medication continuity reviewed",
        "Family/billing/pharmacy blockers checked if discharge",
        "Movement completion time documented",
      ],
      note: `${baseNote} Movement workflow: ${row.movementType}. ${row.movementDetail}.`,
      tone: row.movementTone,
    };
  }

  if (kind === "bed-readiness" || kind === "turnaround-queue") {
    return {
      ...base,
      title: `${row.bedNo} bed readiness`,
      kindLabel: "Readiness",
      focusLabel: "Readiness",
      focusValue: row.bedReadiness,
      focusDetail: row.turnaround,
      contextTitle: "Readiness context",
      contextRows: [row.bedStatus, row.blocker, row.owner, row.eta],
      actionOptions: uniqueTextValues([defaultAction, "Track ETA", "Mark ready", "Assign housekeeping", "Escalate", "Mark resolved"]),
      ownerOptions: uniqueTextValues([row.owner, "Housekeeping Team A", "Biomedical Raj", "Infection Control Team", "Head Nurse Sana", "Admission Desk"]),
      checklistTitle: "Bed readiness checklist",
      checklist: [
        "Cleaning or maintenance status confirmed",
        "Oxygen, suction, monitor, bed, and pump readiness checked",
        "Infection-control clearance completed if needed",
        "Turnaround ETA visible to admission desk",
        "Responsible nonclinical owner assigned",
        "Bed marked ready only after physical verification",
      ],
      note: `${baseNote} Bed readiness review: ${row.bedReadiness} / ${row.turnaround}.`,
      tone: row.bedTone,
    };
  }

  if (kind === "staffing") {
    return {
      ...base,
      title: `${row.bedNo} staffing coverage`,
      kindLabel: "Staffing",
      focusLabel: "Coverage",
      focusValue: row.staffing,
      focusDetail: row.staffDetail,
      contextTitle: "Staffing context",
      contextRows: [row.patientName, row.priority, row.flowStatus, row.shift],
      actionOptions: uniqueTextValues([defaultAction, "Reassign nurse", "Add support nurse", "Notify head nurse", "Escalate", "Mark resolved"]),
      ownerOptions: uniqueTextValues([row.owner, "Head Nurse Sana", "Ward Nurse Kavita", "Ward Nurse Arjun", "Unit Nurse Priya", "Duty Doctor"]),
      checklistTitle: "Staffing safety checklist",
      checklist: [
        "Primary nurse and backup nurse identified",
        "Critical patient load reviewed",
        "Pending tasks and alerts considered",
        "Shift handover responsibility confirmed",
        "Escalation to head nurse documented if overloaded",
        "Coverage update reflected in command center",
      ],
      note: `${baseNote} Staffing coverage review: ${row.staffing}, ${row.staffDetail}.`,
      tone: row.staffTone,
    };
  }

  if (kind === "device") {
    return {
      ...base,
      title: `${row.bedNo} device / biomedical`,
      kindLabel: "Device",
      focusLabel: "Device status",
      focusValue: row.deviceStatus,
      focusDetail: row.deviceDetail,
      contextTitle: "Device context",
      contextRows: [row.capability, row.bedReadiness, row.blocker, row.sla],
      actionOptions: uniqueTextValues([defaultAction, "Validate device", "Troubleshoot device", "Request BioMed", "Escalate", "Mark resolved"]),
      ownerOptions: uniqueTextValues([row.owner, "Biomedical Raj", "Biomedical Nisha", "IT Network Team", "Head Nurse Sana", "Duty Doctor"]),
      checklistTitle: "Device readiness checklist",
      checklist: [
        "Monitor, ventilator, pump, oxygen, and suction readiness checked",
        "Gateway / live feed status reviewed",
        "Biomedical owner assigned for offline or degraded device",
        "Clinical fallback documented if device data is missing",
        "Device readiness communicated before admission or transfer",
        "Issue closed only after live data or physical check",
      ],
      note: `${baseNote} Device workflow: ${row.deviceStatus}, ${row.deviceDetail}.`,
      tone: row.deviceTone,
    };
  }

  if (kind === "blocker") {
    return {
      ...base,
      title: `${row.bedNo} blocker ownership`,
      kindLabel: "Blocker",
      focusLabel: "Blocker",
      focusValue: row.blocker,
      focusDetail: `Owner: ${row.owner} (${row.ownerGroup}).`,
      contextTitle: "Blocker context",
      contextRows: [row.flowStatus, row.movementDetail, row.turnaround, row.deviceDetail],
      actionOptions: uniqueTextValues([defaultAction, "Assign owner", "Acknowledge", "Escalate", "Mark resolved"]),
      checklistTitle: "Blocker closure checklist",
      checklist: [
        "Blocker category is correct",
        "Owner group and named owner confirmed",
        "Patient safety impact reviewed",
        "ETA/SLA communicated to command team",
        "Escalation route selected if SLA at risk",
        "Resolution evidence will be documented",
      ],
      note: `${baseNote} Blocker owner workflow opened.`,
      tone: row.tone,
    };
  }

  if (kind === "sla") {
    return {
      ...base,
      title: `${row.bedNo} SLA review`,
      kindLabel: "SLA",
      focusLabel: "Due",
      focusValue: row.sla,
      focusDetail: row.eta,
      contextTitle: "SLA context",
      contextRows: [row.priority, row.ownerGroup, row.blocker, row.action],
      actionOptions: uniqueTextValues([defaultAction, "Update SLA", "Acknowledge", "Escalate", "Mark resolved"]),
      checklistTitle: "SLA review checklist",
      checklist: [
        "Priority and due time match clinical/operational risk",
        "Owner has acknowledged the SLA",
        "Escalation required if SLA is breached",
        "Next review time is visible",
        "Command team informed for critical SLA",
        "Closure time documented",
      ],
      note: `${baseNote} SLA review opened for ${row.sla}.`,
      tone: row.slaTone,
    };
  }

  return {
    ...base,
    title: `${row.bedNo} command action`,
    kindLabel: "Action",
    focusLabel: "Action",
    focusValue: row.action,
    focusDetail: "Use this to acknowledge, assign, escalate, or close the selected ICU operations workflow.",
    contextTitle: "Action context",
    contextRows: [row.blocker, row.owner, row.sla, row.eta],
    actionOptions: uniqueTextValues([defaultAction, "Assign owner", "Acknowledge", "Escalate", "Mark resolved"]),
    checklistTitle: "Action completion checklist",
    checklist: [
      "Action reason is clear",
      "Responsible owner confirmed",
      "ETA/SLA is visible",
      "Patient safety impact reviewed",
      "Escalation path documented if needed",
      "Close only after outcome is verified",
    ],
    note: `${baseNote} Command action opened from matrix action column.`,
    tone: row.tone,
  };
}

function DiagnosticsHubCommand() {
  const labRows = icuAlerts.filter((alert) => alert.type.toLowerCase().includes("lab") || alert.source.toLowerCase().includes("lab"));
  const pendingSamples = icuTasks.filter((task) => task.taskType.toLowerCase().includes("lab") || task.title.toLowerCase().includes("sample"));
  const pharmacyPending = medicationRows.filter((row) => row.status === "Due" || row.status === "Late");

  return (
    <div className="space-y-4">
      <SummaryGrid>
        <StatCard label="Critical labs" value={labRows.length} change="Doctor review" context="Lab alerts" tone={labRows.length ? "critical" : "success"} icon={TestTube2} />
        <StatCard label="Pending samples" value={pendingSamples.length} change="Collection queue" context="Nursing action" tone="warning" icon={ClipboardCheck} />
        <StatCard label="Radiology pending" value={1} change="CT review" context="Neuro ICU" tone="warning" icon={BarChart3} />
        <StatCard label="Pharmacy pending" value={pharmacyPending.length} change="Dispense follow-up" context="Medication queue" tone={pharmacyPending.length ? "danger" : "success"} icon={Pill} />
      </SummaryGrid>
      <div className="grid gap-4 xl:grid-cols-3">
        <CommandSection title="Lab Queue" description="Critical and pending lab work.">
          <MiniList title="Critical values" rows={labRows.map((row) => `${row.bedNo} - ${row.message}`)} empty="No critical lab alert" />
          <MiniList title="Sample tasks" rows={pendingSamples.map((row) => `${row.bedNo} - ${row.title}`)} />
        </CommandSection>
        <CommandSection title="Radiology Queue" description="Report availability and doctor review.">
          {[
            ["ICU-B03", "CT brain", "Report pending"],
            ["ICU-A02", "Portable chest X-ray", "Reviewed"],
            ["ICU-A01", "USG abdomen", "Ordered"],
          ].map(([bed, test, status]) => <InfoLine label={`${bed} ${test}`} value={status} key={`${bed}-${test}`} />)}
        </CommandSection>
        <CommandSection title="Pharmacy Queue" description="Medicine dispense and shortage watch.">
          <MiniList title="Pending medicines" rows={pharmacyPending.map((row) => `${row.bedNo} - ${row.medication} ${row.status}`)} />
        </CommandSection>
      </div>
    </div>
  );
}

function OperationalAnalyticsCommand() {
  const occupancy = Math.round((icuPatients.length / 12) * 100);
  const medCompliance = Math.round((medicationRows.filter((row) => row.status === "Administered").length / Math.max(medicationRows.length, 1)) * 100);
  const alertClosure = Math.round((icuAlerts.filter((alert) => alert.status === "Resolved").length / Math.max(icuAlerts.length, 1)) * 100);
  const taskCompletion = Math.round((icuTasks.filter((task) => task.status === "Completed").length / Math.max(icuTasks.length, 1)) * 100);
  const forecastRows = buildAdmissionForecastRows();

  return (
    <div className="space-y-4">
      <SummaryGrid>
        <StatCard label="Bed utilization" value={occupancy} change="Today %" context="Current occupancy" tone="info" icon={BedDouble} />
        <StatCard label="Medication compliance" value={medCompliance} change="MAR %" context="Administered doses" tone={medCompliance >= 80 ? "success" : "warning"} icon={Pill} />
        <StatCard label="Alert closure" value={alertClosure} change="SLA %" context="Resolved alerts" tone={alertClosure >= 70 ? "success" : "danger"} icon={AlertTriangle} />
        <StatCard label="Task completion" value={taskCompletion} change="Shift %" context="Nursing workload" tone={taskCompletion >= 70 ? "success" : "warning"} icon={ListChecks} />
      </SummaryGrid>
      <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_420px]">
        <CommandSection title="Operational Trend" description="Census, response, workload, and discharge movement across ICU operations.">
          <MetricBar label="ICU occupancy" value={occupancy} tone="info" />
          <MetricBar label="Alert response within SLA" value={74} tone="warning" />
          <MetricBar label="Nurse workload balance" value={68} tone="warning" />
          <MetricBar label="Device availability" value={91} tone="success" />
        </CommandSection>
        <CommandSection title="Admission Forecast" description="Demand forecast for ICU bed planning and expected admissions.">
          {forecastRows.map((row) => (
            <div className="rounded-md border border-border bg-background p-3" key={row.window}>
              <div className="flex items-start justify-between gap-3">
                <div>
                  <p className="text-sm font-semibold text-foreground">{row.window}</p>
                  <p className="mt-1 text-xs text-muted-foreground">{row.source}</p>
                </div>
                <Badge tone={row.tone}>{row.expected} expected</Badge>
              </div>
              <MetricBar label="Bed pressure" value={row.pressure} tone={row.tone} />
            </div>
          ))}
        </CommandSection>
      </div>
      <div className="grid gap-4 xl:grid-cols-2">
        <CommandSection title="Daily Outcomes" description="Priority outcome indicators for ICU operations.">
          <InfoLine label="Pending transfer/discharge" value={`${icuPatients.filter((patient) => patient.currentStatus === "Ready for transfer" || patient.currentStatus === "Discharge ordered").length}`} />
          <InfoLine label="Readmission watch" value="0 flagged today" />
          <InfoLine label="Average handover completion" value="86%" />
          <InfoLine label="Documentation gaps" value={`${icuTasks.filter((task) => task.taskType.toLowerCase().includes("documentation")).length || 2}`} />
        </CommandSection>
      </div>
    </div>
  );
}

type ClinicalAlertRow = {
  id: string;
  alert: typeof icuAlerts[number];
  patient?: IcuPatient;
  patientName: string;
  bedNo: string;
  unit: string;
  category: string;
  trigger: string;
  severity: typeof icuAlerts[number]["severity"];
  source: string;
  owner: string;
  status: typeof icuAlerts[number]["status"];
  createdAt: string;
  ageMinutes: number;
  sla: string;
  action: string;
  tone: DashboardCellTone;
  slaTone: DashboardCellTone;
  statusTone: DashboardCellTone;
  patientTone: DashboardCellTone;
  routeTo: string;
  scenario: string;
};

type ClinicalAlertCellKind = "patient" | "trigger" | "severity" | "source" | "owner" | "sla" | "status" | "route" | "action";
type ClinicalAlertCellAction = { row: ClinicalAlertRow; kind: ClinicalAlertCellKind };

function ClinicalAlertsCommand() {
  const { queryFocus, queryUnit } = useCommandRouteContext();
  const [search, setSearch] = React.useState("");
  const [unit, setUnit] = React.useState(queryUnit || "All ICU units");
  const [severity, setSeverity] = React.useState("All severity");
  const [source, setSource] = React.useState("All sources");
  const [status, setStatus] = React.useState("All status");
  const [activeAction, setActiveAction] = React.useState<ClinicalAlertCellAction | null>(null);
  const [resolvedRows, setResolvedRows] = React.useState<Set<string>>(() => new Set());

  const rows = React.useMemo(() => buildClinicalAlertRows(resolvedRows), [resolvedRows]);
  const unitOptions = React.useMemo(() => ["All ICU units", ...Array.from(new Set(rows.map((row) => row.unit)))], [rows]);
  const sourceOptions = React.useMemo(() => ["All sources", ...Array.from(new Set(rows.map((row) => row.source)))], [rows]);
  React.useEffect(() => {
    if (queryUnit) setUnit(queryUnit);
  }, [queryUnit]);
  const filteredRows = React.useMemo(() => {
    const query = search.trim().toLowerCase();
    return rows.filter((row) => {
      const text = `${row.bedNo} ${row.patientName} ${row.unit} ${row.category} ${row.trigger} ${row.source} ${row.owner} ${row.status} ${row.routeTo}`.toLowerCase();
      return (!query || text.includes(query))
        && (unit === "All ICU units" || row.unit === unit)
        && (severity === "All severity" || row.severity === severity)
        && (source === "All sources" || row.source === source)
        && (status === "All status" || row.status === status);
    }).sort((left, right) => clinicalAlertFocusRank(right, queryFocus) - clinicalAlertFocusRank(left, queryFocus));
  }, [queryFocus, rows, search, severity, source, status, unit]);
  const pagination = useIcuCommandPagination(filteredRows);

  const critical = rows.filter((row) => row.severity === "Critical").length;
  const high = rows.filter((row) => row.severity === "High").length;
  const breached = rows.filter((row) => row.slaTone === "critical" || row.slaTone === "danger").length;
  const acknowledged = rows.filter((row) => row.status === "Acknowledged").length;
  const open = rows.filter((row) => row.status === "Open").length;
  const resolved = rows.filter((row) => row.status === "Resolved").length;

  return (
    <div className="min-w-0 max-w-full space-y-4 overflow-hidden">
      <CollapsibleCommandPanel
        summary={`${unit} | ${severity} | ${status} | ${filteredRows.length} alert(s)`}
        title="Alert metrics & filters"
      >
        <div className="grid grid-cols-2 gap-2 border-b border-slate-200 px-3 py-3 md:flex md:flex-wrap md:items-center">
          <DashboardCommandMetric label="Active alerts" value={rows.length - resolved} tone={open ? "warning" : "success"} />
          <DashboardCommandMetric label="Critical" value={critical} tone={critical ? "critical" : "success"} />
          <DashboardCommandMetric label="High" value={high} tone={high ? "danger" : "success"} />
          <DashboardCommandMetric label="SLA risk" value={breached} tone={breached ? "danger" : "success"} />
          <DashboardCommandMetric label="Open" value={open} tone={open ? "warning" : "success"} />
          <DashboardCommandMetric label="Acknowledged" value={acknowledged} tone="info" />
        </div>

        <div className="grid items-end gap-3 p-3 md:grid-cols-2 xl:grid-cols-[minmax(240px,1.35fr)_repeat(4,minmax(128px,1fr))_minmax(112px,0.7fr)] 2xl:grid-cols-[minmax(280px,1.65fr)_repeat(4,minmax(150px,1fr))_minmax(120px,0.7fr)]">
          <label className="space-y-1 text-sm">
            <span className="block text-xs font-semibold text-slate-700">Search patient / alert / source</span>
            <span className="relative block">
              <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
              <Input className="h-10 pl-9" placeholder="Search alert, patient, owner..." value={search} onChange={(event) => setSearch(event.target.value)} />
            </span>
          </label>
          <IcuOperationsFilterSelect label="ICU unit" value={unit} onChange={setUnit} options={unitOptions} />
          <IcuOperationsFilterSelect label="Severity" value={severity} onChange={setSeverity} options={["All severity", "Critical", "High", "Medium", "Info"]} />
          <IcuOperationsFilterSelect label="Source" value={source} onChange={setSource} options={sourceOptions} />
          <IcuOperationsFilterSelect label="Status" value={status} onChange={setStatus} options={["All status", "Open", "Acknowledged", "Resolved"]} />
          <div className="min-w-[112px] space-y-1">
            <span className="block text-xs font-semibold text-transparent">Reset</span>
            <Button className="h-10 w-full" variant="outline" onClick={() => {
              setSearch("");
              setUnit("All ICU units");
              setSeverity("All severity");
              setSource("All sources");
              setStatus("All status");
            }}>Reset</Button>
          </div>
        </div>
      </CollapsibleCommandPanel>

      <div className="overflow-hidden rounded-sm border border-slate-300 bg-white shadow-sm">
        <div className="flex justify-end border-b border-slate-200 bg-white px-3 py-2">
          <div className="flex flex-wrap items-center justify-end gap-2">
            <IcuLegend />
          </div>
        </div>
        <div className="max-h-[650px] overflow-auto">
          <table className="w-full min-w-[980px] border-collapse bg-white text-sm">
            <thead className="sticky top-0 z-20 bg-white">
              <tr className="border-b border-slate-300 text-[11px] uppercase text-sky-700">
                <th className="sticky left-0 z-40 min-w-[190px] bg-white px-3 py-3 text-left">Patient</th>
                <th className="min-w-[280px] px-3 py-3 text-left">Alert</th>
                <th className="min-w-[130px] px-2 py-3 text-center">Severity</th>
                <th className="min-w-[140px] px-2 py-3 text-center">Source</th>
                <th className="min-w-[130px] px-2 py-3 text-center">Status</th>
                <th className="min-w-[120px] px-2 py-3 text-center">Review</th>
              </tr>
            </thead>
            <tbody>
              {pagination.pageRows.map((row) => (
                <tr className="border-b border-slate-200 last:border-b-0 hover:bg-sky-50/40" key={row.id}>
                  <td className="sticky left-0 z-10 bg-white px-3 py-2 align-middle shadow-[8px_0_14px_-15px_rgba(15,23,42,0.45)]">
                    <button className="block min-h-24 w-full rounded-md px-3 py-2 text-left transition hover:bg-sky-50" type="button" onClick={() => setActiveAction({ row, kind: "patient" })}>
                      <p className={cn("truncate whitespace-nowrap text-sm font-bold", dashboardToneTextClass(row.patientTone))}>{row.patientName}</p>
                      <p className="mt-1 text-xs font-bold text-slate-700">{row.bedNo}</p>
                      <p className="mt-1 truncate whitespace-nowrap text-xs text-slate-500">{row.unit}</p>
                    </button>
                  </td>
                  <td className="px-3 py-2 align-middle">
                    <button className="min-h-20 w-full rounded-md p-2 text-left transition hover:bg-sky-50" type="button" onClick={() => setActiveAction({ row, kind: "trigger" })}>
                      <p className="text-sm font-bold text-slate-950">{row.category}</p>
                      <p className="mt-1 text-xs leading-relaxed text-slate-600">{row.trigger}</p>
                      <p className="mt-1 text-[11px] font-semibold text-slate-500">{row.createdAt}</p>
                    </button>
                  </td>
                  <td className="px-2 py-2 text-center align-middle"><IcuOpsMatrixCell icon={AlertTriangle} title={row.severity} detail={row.scenario} tone={row.tone} showDetail={false} onClick={() => setActiveAction({ row, kind: "severity" })} /></td>
                  <td className="px-2 py-2 text-center align-middle"><IcuOpsMatrixCell icon={FileText} title={row.source} detail="Alert source" tone={clinicalAlertSourceTone(row.source)} showDetail={false} onClick={() => setActiveAction({ row, kind: "source" })} /></td>
                  <td className="px-2 py-2 text-center align-middle"><IcuOpsMatrixCell icon={CheckCircle2} title={row.status} detail="Alert state" tone={row.statusTone} showDetail={false} onClick={() => setActiveAction({ row, kind: "status" })} /></td>
                  <td className="px-2 py-2 text-center align-middle">
                    <button className="group flex w-full flex-col items-center justify-center" type="button" onClick={() => setActiveAction({ row, kind: "action" })}>
                      <span className={cn("inline-flex h-10 w-10 items-center justify-center rounded-full text-white shadow-[0_3px_8px_rgba(0,0,0,0.28)] transition group-hover:brightness-95", dashboardToneSolidClass(row.tone))}>
                        <ClipboardCheck className="h-4 w-4" />
                      </span>
                      <span className="mt-1 text-xs font-bold text-slate-800">Open</span>
                    </button>
                  </td>
                </tr>
              ))}
              {!filteredRows.length ? (
                <tr>
                  <td className="px-4 py-12 text-center text-sm text-slate-500" colSpan={6}>No clinical alert matched the selected filters.</td>
                </tr>
              ) : null}
            </tbody>
          </table>
        </div>
        <IcuCommandPaginationControls {...pagination} />
      </div>
      <ClinicalAlertActionDialog
        action={activeAction}
        onOpenChange={(open) => !open && setActiveAction(null)}
        onComplete={(row, actionLabel) => {
          if (actionLabel === "Mark resolved") setResolvedRows((current) => new Set([...current, row.id]));
          toast.success(`${row.bedNo}: ${actionLabel.toLowerCase()} saved`);
          setActiveAction(null);
        }}
      />
    </div>
  );
}

function buildClinicalAlertRows(resolvedRows: Set<string>): ClinicalAlertRow[] {
  return icuAlerts.map((alert) => {
    const patient = icuPatients.find((row) => row.id === alert.patientId);
    const resolved = resolvedRows.has(alert.id);
    const status = resolved ? "Resolved" : alert.status;
    const ageMinutes = clinicalAlertAgeMinutes(alert.createdAt);
    const severityTone = clinicalAlertSeverityTone(alert.severity);
    const slaTone = clinicalAlertSlaTone(alert.severity, status, ageMinutes);
    return {
      id: alert.id,
      alert: { ...alert, status },
      patient,
      patientName: patient?.patientName ?? patientName(alert.patientId),
      bedNo: alert.bedNo,
      unit: patient?.unit ?? "ICU",
      category: alert.type,
      trigger: alert.message,
      severity: alert.severity,
      source: alert.source,
      owner: alert.owner,
      status,
      createdAt: alert.createdAt,
      ageMinutes,
      sla: clinicalAlertSlaLabel(alert.severity, status, ageMinutes),
      action: status === "Resolved" ? "Closed" : alert.severity === "Critical" ? "Escalate" : status === "Acknowledged" ? "Follow up" : "Acknowledge",
      tone: status === "Resolved" ? "success" : severityTone,
      slaTone,
      statusTone: status === "Resolved" ? "success" : status === "Acknowledged" ? "info" : severityTone,
      patientTone: patient ? patientDashboardTone(patient) : severityTone,
      routeTo: clinicalAlertRoute(alert),
      scenario: clinicalAlertScenario(alert),
    };
  });
}

function clinicalAlertFocusRank(row: ClinicalAlertRow, focus: string) {
  const severityRank = row.severity === "Critical" ? 90 : row.severity === "High" ? 70 : row.severity === "Medium" ? 35 : 10;
  const statusRank = row.status === "Open" ? 40 : row.status === "Acknowledged" ? 20 : 0;
  const slaRank = row.slaTone === "critical" || row.slaTone === "danger" ? 45 : row.slaTone === "warning" ? 25 : 0;
  if (focus === "alerts") return severityRank + statusRank + slaRank;
  return severityRank + slaRank;
}

function ClinicalAlertActionDialog({ action, onOpenChange, onComplete }: { action: ClinicalAlertCellAction | null; onOpenChange: (open: boolean) => void; onComplete: (row: ClinicalAlertRow, action: string) => void }) {
  return (
    <Dialog.Root open={Boolean(action)} onOpenChange={onOpenChange}>
      <Dialog.Portal>
        <Dialog.Overlay className="fixed inset-0 z-50 bg-black/40 backdrop-blur-[1px]" />
        <Dialog.Content className="fixed left-1/2 top-1/2 z-50 flex max-h-[92dvh] w-[min(940px,calc(100vw-24px))] -translate-x-1/2 -translate-y-1/2 flex-col overflow-hidden rounded-xl border border-border bg-surface shadow-soft outline-none">
          {action ? <ClinicalAlertActionDialogContent key={`${action.row.id}-${action.kind}`} action={action} onComplete={onComplete} /> : null}
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

function ClinicalAlertActionDialogContent({ action, onComplete }: { action: ClinicalAlertCellAction; onComplete: (row: ClinicalAlertRow, action: string) => void }) {
  const row = action.row;
  const copy = clinicalAlertModalCopy(action);
  const [selectedAction, setSelectedAction] = React.useState(copy.defaultAction);
  const [owner, setOwner] = React.useState(row.owner);
  const [review, setReview] = React.useState(copy.defaultReview);

  return (
    <>
      <DialogHeader title={copy.title} description={`${row.bedNo} | ${row.patientName} | ${row.category}`} />
      <div className="overflow-y-auto p-4 pb-24">
        <div className={cn("mb-4 rounded-lg border p-3", dashboardToneSurfaceClass(copy.tone))}>
          <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
            <div>
              <p className="text-sm font-black text-slate-950">{row.trigger}</p>
              <p className="mt-1 text-xs font-semibold text-slate-600">{row.source} | {row.createdAt} | {row.scenario}</p>
            </div>
            <span className={cn("w-fit rounded-full border px-2.5 py-1 text-xs font-bold", dashboardTonePillClass(copy.tone))}>{copy.badge}</span>
          </div>
        </div>

        <div className="grid gap-4 xl:grid-cols-[minmax(0,1.25fr)_320px]">
          <div className="space-y-4">
            <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">
              {copy.fields.map((field) => (
                <div className="rounded-md border border-slate-200 bg-slate-50 p-3" key={field.label}>
                  <p className="text-[11px] font-black uppercase text-slate-500">{field.label}</p>
                  <p className="mt-1 text-sm font-bold text-slate-950">{field.value}</p>
                </div>
              ))}
            </div>
            <div className="rounded-md border border-sky-200 bg-sky-50 p-3 text-xs font-semibold leading-relaxed text-sky-800">
              <span className="font-black">Source / rule: </span>{copy.reference}
            </div>
            <div className="rounded-lg border border-border bg-background p-3">
              <p className="text-sm font-semibold text-foreground">{copy.checklistTitle}</p>
              <div className="mt-3 grid gap-2 md:grid-cols-2">
                {copy.checklist.map((item, index) => (
                  <label className="flex items-center gap-2 rounded-md border border-border bg-surface-muted p-2 text-sm" key={item}>
                    <input className="h-4 w-4 rounded border-input" type="checkbox" defaultChecked={index < 2 || row.status === "Resolved"} />
                    {item}
                  </label>
                ))}
              </div>
            </div>
            <div className="grid gap-3 md:grid-cols-2">
              <MiniList title="Clinical next step" rows={copy.nextSteps} />
              <MiniList title="Closure evidence" rows={copy.closureEvidence} />
            </div>
          </div>

          <div className="space-y-4">
            <div className="rounded-lg border border-slate-200 bg-white p-3">
              <p className="text-sm font-bold text-slate-950">Action</p>
              <div className="mt-3 grid gap-3">
                <IcuOperationsFilterSelect label="Alert action" value={selectedAction} onChange={setSelectedAction} options={copy.actionOptions} />
                <IcuOperationsFilterSelect label="Responsible owner" value={owner} onChange={setOwner} options={copy.ownerOptions} />
                <IcuOperationsFilterSelect label="Next review" value={review} onChange={setReview} options={copy.reviewOptions} />
              </div>
            </div>
            <MiniList title="Alert context" rows={[row.patient?.diagnosis ?? row.category, `Status: ${row.status}`, `SLA: ${row.sla}`, `Route: ${row.routeTo}`]} />
            <label className="space-y-1 text-sm">
              <span className="font-medium text-foreground">Action note</span>
              <textarea className="min-h-28 w-full rounded-md border border-input bg-background p-3 text-sm outline-none focus:ring-2 focus:ring-ring/20" defaultValue={`${row.bedNo} ${row.category}. ${selectedAction} by ${owner}. Review ${review}. Trigger: ${row.trigger}.`} />
            </label>
          </div>
        </div>
      </div>
      <div className="flex flex-col-reverse gap-2 border-t border-border bg-surface-muted p-3 sm:flex-row sm:justify-end">
        <Dialog.Close asChild><Button variant="outline">Cancel</Button></Dialog.Close>
        <Button variant="outline" asChild><Link href={icuPatientDetailHref(row.alert.patientId, "events")}>Open patient events</Link></Button>
        <Button variant={selectedAction === "Escalate" || selectedAction.includes("Call") ? "danger" : "default"} onClick={() => onComplete(row, selectedAction)}>{selectedAction}</Button>
      </div>
    </>
  );
}

function clinicalAlertModalCopy(action: ClinicalAlertCellAction) {
  const row = action.row;
  const kindTitle: Record<ClinicalAlertCellKind, string> = {
    patient: "Patient alert context",
    trigger: "Alert trigger review",
    severity: "Severity review",
    source: "Source review",
    owner: "Owner assignment",
    sla: "SLA review",
    status: "Alert status",
    route: "Escalation route",
    action: "Alert action",
  };
  const actionOptions = uniqueTextValues([
    row.action,
    row.severity === "Critical" ? "Call duty doctor" : "Acknowledge",
    "Assign owner",
    "Create follow-up task",
    "Escalate",
    "Mark resolved",
  ]);
  return {
    title: kindTitle[action.kind],
    badge: row.severity,
    tone: row.tone,
    defaultAction: row.action === "Closed" ? "Mark resolved" : row.action,
    defaultReview: row.severity === "Critical" ? "Now" : row.severity === "High" ? "15 min" : row.severity === "Medium" ? "30 min" : "Current shift",
    actionOptions,
    ownerOptions: uniqueTextValues([row.owner, row.routeTo, "Duty Doctor", "Head Nurse Sana", "Ward Nurse", "Biomedical", "Blood Unit", "Transplant Team"]),
    reviewOptions: ["Now", "15 min", "30 min", "Current shift", "After repeat value", "Closed"],
    fields: clinicalAlertFields(action),
    reference: clinicalAlertReference(row),
    checklistTitle: clinicalAlertChecklistTitle(action.kind),
    checklist: clinicalAlertChecklist(row),
    nextSteps: clinicalAlertNextSteps(row),
    closureEvidence: clinicalAlertClosureEvidence(row),
  };
}

function clinicalAlertFields(action: ClinicalAlertCellAction): Array<{ label: string; value: string }> {
  const row = action.row;
  if (action.kind === "source") return [["Source", row.source], ["Category", row.category], ["Created", row.createdAt], ["Patient", `${row.bedNo} - ${row.patientName}`], ["Route", row.routeTo], ["Status", row.status]].map(([label, value]) => ({ label, value }));
  if (action.kind === "owner") return [["Owner", row.owner], ["Route to", row.routeTo], ["SLA", row.sla], ["Status", row.status], ["Severity", row.severity], ["Unit", row.unit]].map(([label, value]) => ({ label, value }));
  if (action.kind === "sla") return [["SLA", row.sla], ["Age", row.createdAt], ["Severity", row.severity], ["Status", row.status], ["Owner", row.owner], ["Action", row.action]].map(([label, value]) => ({ label, value }));
  if (action.kind === "route") return [["Escalation route", row.routeTo], ["Source", row.source], ["Owner", row.owner], ["Scenario", row.scenario], ["SLA", row.sla], ["Status", row.status]].map(([label, value]) => ({ label, value }));
  return [["Patient", `${row.bedNo} - ${row.patientName}`], ["Unit", row.unit], ["Severity", row.severity], ["Source", row.source], ["Owner", row.owner], ["SLA", row.sla]].map(([label, value]) => ({ label, value }));
}

function clinicalAlertChecklistTitle(kind: ClinicalAlertCellKind) {
  if (kind === "source") return "Source validation checklist";
  if (kind === "owner") return "Owner handoff checklist";
  if (kind === "sla") return "SLA checklist";
  if (kind === "route") return "Escalation checklist";
  return "Clinical alert checklist";
}

function clinicalAlertChecklist(row: ClinicalAlertRow) {
  return [
    "Patient identity and bed confirmed",
    "Alert source and trigger reviewed",
    row.severity === "Critical" ? "Duty doctor informed immediately" : "Responsible owner assigned",
    "Patient impact checked",
    "Follow-up task or repeat value planned",
    "Closure evidence documented",
  ];
}

function clinicalAlertNextSteps(row: ClinicalAlertRow) {
  if (row.category.toLowerCase().includes("vital") || row.category.toLowerCase().includes("respiratory")) return ["Repeat vitals/ABG as ordered", "Inform duty doctor", "Update monitoring note", "Escalate if trend worsens"];
  if (row.category.toLowerCase().includes("medication")) return ["Check pharmacy dispense", "Administer after verification", "Document delay reason", "Update eMAR"];
  if (row.category.toLowerCase().includes("blood")) return ["Record transfusion vitals", "Watch reaction", "Inform blood bank if abnormal", "Update transfusion chart"];
  if (row.category.toLowerCase().includes("transfer")) return ["Complete transfer checklist", "Confirm destination", "Assign handover owner", "Close after movement"];
  return ["Assign owner", "Review patient impact", "Document follow-up", "Close with evidence"];
}

function clinicalAlertClosureEvidence(row: ClinicalAlertRow) {
  return ["Action note saved", `Owner: ${row.owner}`, `Source: ${row.source}`, "Repeat value / task outcome attached"];
}

function clinicalAlertReference(row: ClinicalAlertRow) {
  return `${row.source} generated ${row.category} alert. ${row.severity} severity maps to ${row.sla}. Route: ${row.routeTo}.`;
}

function clinicalAlertScenario(alert: typeof icuAlerts[number]) {
  const text = `${alert.type} ${alert.message} ${alert.source}`.toLowerCase();
  if (text.includes("vital") || text.includes("spo2") || text.includes("bp")) return "Vitals risk";
  if (text.includes("respiratory") || text.includes("niv") || text.includes("abg")) return "Respiratory risk";
  if (text.includes("medication") || text.includes("mar") || text.includes("overdue")) return "Medication risk";
  if (text.includes("blood") || text.includes("transfusion")) return "Transfusion watch";
  if (text.includes("transfer")) return "Patient movement";
  if (text.includes("transplant") || text.includes("tacrolimus")) return "Specialty protocol";
  return "Clinical review";
}

function clinicalAlertRoute(alert: typeof icuAlerts[number]) {
  const scenario = clinicalAlertScenario(alert);
  if (scenario === "Vitals risk" || scenario === "Respiratory risk") return "Duty Doctor";
  if (scenario === "Medication risk") return "Ward Nurse + Pharmacy";
  if (scenario === "Transfusion watch") return "Ward Nurse + Blood Unit";
  if (scenario === "Patient movement") return "Unit Nurse";
  if (scenario === "Specialty protocol") return "Transplant Team";
  return alert.owner;
}

function clinicalAlertSeverityTone(severity: typeof icuAlerts[number]["severity"]): DashboardCellTone {
  if (severity === "Critical") return "critical";
  if (severity === "High") return "danger";
  if (severity === "Medium") return "warning";
  return "info";
}

function clinicalAlertSourceTone(source: string): DashboardCellTone {
  const lower = source.toLowerCase();
  if (lower.includes("vital") || lower.includes("monitor")) return "danger";
  if (lower.includes("mar") || lower.includes("transplant")) return "warning";
  if (lower.includes("blood")) return "purple";
  return "info";
}

function clinicalAlertSlaTone(severity: typeof icuAlerts[number]["severity"], status: typeof icuAlerts[number]["status"], ageMinutes: number): DashboardCellTone {
  if (status === "Resolved") return "success";
  if (severity === "Critical") return "critical";
  if (severity === "High" && ageMinutes >= 15) return "danger";
  if (severity === "Medium" && ageMinutes >= 30) return "warning";
  return clinicalAlertSeverityTone(severity);
}

function clinicalAlertSlaLabel(severity: typeof icuAlerts[number]["severity"], status: typeof icuAlerts[number]["status"], ageMinutes: number) {
  if (status === "Resolved") return "Closed";
  if (severity === "Critical") return "Now";
  if (severity === "High") return ageMinutes >= 15 ? "Breached" : "15 min";
  if (severity === "Medium") return ageMinutes >= 30 ? "Due" : "30 min";
  return "Shift";
}

function clinicalAlertAgeMinutes(createdAt: string) {
  if (createdAt.includes("hr")) return Number(createdAt.match(/\d+/)?.[0] ?? 1) * 60;
  return Number(createdAt.match(/\d+/)?.[0] ?? 0);
}

function EscalationCenterCommand() {
  const escalationRows = React.useMemo(() => buildEscalationCenterRows(), []);
  const [search, setSearch] = React.useState("");
  const [unit, setUnit] = React.useState("All ICU units");
  const [severity, setSeverity] = React.useState("All severity");
  const [source, setSource] = React.useState("All sources");
  const [owner, setOwner] = React.useState("All owners");
  const [activeAction, setActiveAction] = React.useState<EscalationCellAction | null>(null);

  const unitOptions = React.useMemo(() => ["All ICU units", ...Array.from(new Set(icuPatients.map((patient) => patient.unit)))], []);
  const sourceOptions = React.useMemo(() => ["All sources", ...Array.from(new Set(escalationRows.map((row) => row.sourceKind)))], [escalationRows]);
  const ownerOptions = React.useMemo(() => ["All owners", ...Array.from(new Set(escalationRows.map((row) => row.owner)))], [escalationRows]);

  const visibleRows = React.useMemo(() => {
    const query = search.trim().toLowerCase();
    return escalationRows.filter((row) => {
      const text = `${row.patient} ${row.bedNo} ${row.unit} ${row.trigger} ${row.category} ${row.owner} ${row.source} ${row.status}`.toLowerCase();
      return (!query || text.includes(query))
        && (unit === "All ICU units" || row.unit === unit)
        && (severity === "All severity" || row.severity === severity)
        && (source === "All sources" || row.sourceKind === source)
        && (owner === "All owners" || row.owner === owner);
    });
  }, [escalationRows, owner, search, severity, source, unit]);

  const criticalRows = visibleRows.filter((row) => row.severity === "Critical");
  const breachedRows = visibleRows.filter((row) => row.slaTone === "critical" || row.status === "Overdue");
  const unassignedRows = visibleRows.filter((row) => /unassigned|pending/i.test(row.owner));
  const ownerLoad = escalationOwnerLoad(visibleRows);
  const patientGroups = React.useMemo(() => buildEscalationPatientGroups(visibleRows), [visibleRows]);
  const pagination = useIcuCommandPagination(patientGroups);

  function resetFilters() {
    setSearch("");
    setUnit("All ICU units");
    setSeverity("All severity");
    setSource("All sources");
    setOwner("All owners");
  }

  function openEscalation(row: EscalationCenterRow, kind: EscalationCellKind) {
    setActiveAction({ row, kind });
  }

  return (
    <>
      <div className="space-y-4">
        <CollapsibleCommandPanel
          summary={`${unit} | ${severity} | ${source} | ${visibleRows.length} escalation(s)`}
          title="Escalation metrics & filters"
        >
          <div className="flex justify-end border-b border-slate-200 px-4 py-3">
            <IcuLegend />
          </div>
          <div className="grid gap-2 border-b border-slate-200 bg-slate-50 px-4 py-3 sm:grid-cols-2 xl:grid-cols-5">
            <DashboardCommandMetric label="Open queue" value={visibleRows.length} tone={visibleRows.length ? "danger" : "success"} />
            <DashboardCommandMetric label="Critical" value={criticalRows.length} tone={criticalRows.length ? "critical" : "success"} />
            <DashboardCommandMetric label="SLA breach" value={breachedRows.length} tone={breachedRows.length ? "warning" : "success"} />
            <DashboardCommandMetric label="Unassigned" value={unassignedRows.length} tone={unassignedRows.length ? "warning" : "success"} />
            <DashboardCommandMetric label="Owners" value={ownerLoad.length} tone="info" />
          </div>
          <div className="grid min-w-0 gap-3 px-4 py-3 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-[minmax(180px,1.25fr)_repeat(4,minmax(115px,0.8fr))_104px] xl:items-end">
            <label className="min-w-0 space-y-1 text-sm">
              <span className="font-medium text-slate-700">Search escalation</span>
              <div className="relative">
                <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
                <Input className="pl-9" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Patient, bed, trigger, owner..." />
              </div>
            </label>
            <NativeSelect label="ICU unit" value={unit} onChange={setUnit} options={unitOptions} />
            <NativeSelect label="Severity" value={severity} onChange={setSeverity} options={["All severity", "Critical", "High", "Medium", "Info"]} />
            <NativeSelect label="Source" value={source} onChange={setSource} options={sourceOptions} />
            <NativeSelect label="Owner" value={owner} onChange={setOwner} options={ownerOptions} />
            <Button className="h-10 w-full min-w-0" variant="outline" onClick={resetFilters}>Reset</Button>
          </div>
        </CollapsibleCommandPanel>

        <div className="overflow-hidden rounded-sm border border-slate-300 bg-white shadow-sm">
          <div className="max-h-[660px] overflow-auto">
            <table className="w-full min-w-[980px] border-collapse bg-white text-sm">
              <thead className="sticky top-0 z-20 bg-white text-[11px] uppercase text-sky-700 shadow-[0_1px_0_rgba(148,163,184,0.45)]">
                <tr>
                  <th className="sticky left-0 z-40 min-w-[210px] bg-white px-3 py-3 text-left">Patient</th>
                  <th className="min-w-[260px] px-3 py-3 text-left">Escalation issue</th>
                  <th className="min-w-[145px] px-3 py-3 text-center">Assigned To</th>
                  <th className="min-w-[125px] px-3 py-3 text-center">Due / SLA</th>
                  <th className="min-w-[130px] px-3 py-3 text-center">Status</th>
                  <th className="min-w-[130px] px-3 py-3 text-center">Action</th>
                </tr>
              </thead>
              <tbody>
                {pagination.pageRows.map((group) => {
                  const row = group.top;
                  const highRiskCount = group.rows.filter((item) => item.severity === "Critical" || item.severity === "High").length;
                  const owners = Array.from(new Set(group.rows.map((item) => item.owner)));
                  const statusSummary = group.rows.some((item) => item.status === "Open" || item.status === "Overdue" || item.status === "Late") ? "Needs action" : row.status;
                  return (
                    <tr className="border-b border-slate-200 last:border-b-0 hover:bg-sky-50/40" key={group.patientId}>
                      <td className="sticky left-0 z-10 bg-white px-3 py-2 align-middle shadow-[8px_0_14px_-15px_rgba(15,23,42,0.45)]">
                        <EscalationPatientCell group={group} />
                      </td>
                      <td className="px-3 py-2 align-middle">
                        <button className="min-h-20 w-full rounded-md p-2 text-left transition hover:bg-sky-50" type="button" onClick={() => openEscalation(row, "trigger")}>
                          <div className="flex flex-wrap items-center gap-2">
                            <span className={cn("text-sm font-bold", dashboardToneTextClass(row.tone))}>{row.category}</span>
                            <Badge tone={remoteConsultBadgeTone(escalationSeverityTone(row.severity))}>{row.severity}</Badge>
                            {highRiskCount > 1 ? <Badge tone="warning">{highRiskCount} high-risk</Badge> : null}
                          </div>
                          <p className="mt-1 text-xs leading-relaxed text-slate-600">{row.trigger}</p>
                          <p className="mt-1 text-[11px] font-semibold text-slate-500">{row.sourceKind} | {row.createdAt}</p>
                        </button>
                      </td>
                      <td className="px-2 py-2 align-middle text-center">
                        <IcuOpsMatrixCell icon={UserRound} title={owners[0] ?? row.owner} detail={owners.length > 1 ? `${owners.length} owners` : row.routeTo} tone={owners.length > 1 ? "warning" : "info"} showDetail={false} onClick={() => openEscalation(row, "owner")} />
                      </td>
                      <td className="px-2 py-2 align-middle text-center">
                        <IcuOpsMatrixCell icon={Clock3} title={row.sla} detail={row.createdAt} tone={row.slaTone} showDetail={false} onClick={() => openEscalation(row, "sla")} />
                      </td>
                      <td className="px-2 py-2 align-middle text-center">
                        <IcuOpsMatrixCell icon={ClipboardCheck} title={statusSummary} detail={row.status} tone={row.statusTone} showDetail={false} onClick={() => openEscalation(row, "status")} />
                      </td>
                      <td className="px-2 py-2 align-middle text-center">
                        <IcuOpsMatrixCell icon={CheckCircle2} title="Review" detail="Open action" tone="info" showDetail={false} onClick={() => openEscalation(row, "review")} />
                      </td>
                    </tr>
                  );
                })}
                {!patientGroups.length ? (
                  <tr>
                    <td className="px-4 py-10 text-center text-sm text-slate-500" colSpan={6}>No escalation matched the selected filters.</td>
                  </tr>
                ) : null}
              </tbody>
            </table>
          </div>
          <IcuCommandPaginationControls {...pagination} />
        </div>
      </div>
      <EscalationActionDialog action={activeAction} onOpenChange={(open) => !open && setActiveAction(null)} />
    </>
  );
}

type EscalationCellKind = "priority" | "trigger" | "owner" | "sla" | "status" | "review";

type EscalationCellAction = {
  row: EscalationCenterRow;
  kind: EscalationCellKind;
};

type EscalationCenterRow = {
  id: string;
  sourceKind: "Clinical alert" | "Nursing task" | "Doctor order" | "Medication";
  patientId: string;
  patient: string;
  bedNo: string;
  unit: string;
  category: string;
  trigger: string;
  severity: "Critical" | "High" | "Medium" | "Info";
  source: string;
  owner: string;
  routeTo: string;
  sla: string;
  status: string;
  createdAt: string;
  tone: DashboardCellTone;
  slaTone: DashboardCellTone;
  statusTone: DashboardCellTone;
  patientTone: DashboardCellTone;
  suggestedAction: string;
};

type EscalationPatientGroup = {
  patientId: string;
  patient: IcuPatient | undefined;
  top: EscalationCenterRow;
  rows: EscalationCenterRow[];
  patientTone: DashboardCellTone;
};

function buildEscalationPatientGroups(rows: EscalationCenterRow[]): EscalationPatientGroup[] {
  const severityOrder: Record<EscalationCenterRow["severity"], number> = { Critical: 0, High: 1, Medium: 2, Info: 3 };
  return Array.from(new Set(rows.map((row) => row.patientId))).map((patientId) => {
    const patientRows = rows
      .filter((row) => row.patientId === patientId)
      .sort((left, right) => severityOrder[left.severity] - severityOrder[right.severity] || left.bedNo.localeCompare(right.bedNo));
    const patient = getEscalationPatient(patientId);
    const top = patientRows[0];
    return {
      patientId,
      patient,
      top,
      rows: patientRows,
      patientTone: patient ? patientDashboardTone(patient) : top.patientTone,
    };
  }).filter((group): group is EscalationPatientGroup => Boolean(group.top))
    .sort((left, right) => severityOrder[left.top.severity] - severityOrder[right.top.severity] || left.top.bedNo.localeCompare(right.top.bedNo));
}

function EscalationPatientCell({ group }: { group: EscalationPatientGroup }) {
  const patient = group.patient;
  const row = group.top;

  return (
    <div className="flex min-h-20 items-center rounded-md border border-transparent bg-white px-3 py-2 text-left transition hover:border-sky-300 hover:shadow-sm">
      <Link className="block w-full text-left" href={icuPatientDetailHref(row.patientId, "overview")}>
        <p className={cn("text-sm font-black", dashboardToneTextClass(group.patientTone))}>{patient?.patientName ?? row.patient}</p>
        <p className="mt-1 text-xs font-semibold text-slate-700">{row.bedNo}</p>
        <p className="mt-1 text-xs text-slate-500">{patient?.mrn ?? "ICU patient"} | {patient?.ageGender ?? row.unit}</p>
      </Link>
    </div>
  );
}

function buildEscalationCenterRows(): EscalationCenterRow[] {
  const alertRows = icuAlerts
    .filter((alert) => alert.status !== "Resolved")
    .map((alert): EscalationCenterRow => {
      const patient = getEscalationPatient(alert.patientId);
      return {
        id: `alert-${alert.id}`,
        sourceKind: "Clinical alert",
        patientId: alert.patientId,
        patient: patient?.patientName ?? patientName(alert.patientId),
        bedNo: alert.bedNo,
        unit: patient?.unit ?? "ICU",
        category: alert.type,
        trigger: alert.message,
        severity: alert.severity,
        source: alert.source,
        owner: alert.owner,
        routeTo: escalationRoute(alert.type, alert.owner, alert.severity),
        sla: escalationSla(alert.severity, alert.status),
        status: alert.status,
        createdAt: alert.createdAt,
        tone: escalationSeverityTone(alert.severity),
        slaTone: escalationSlaTone(alert.severity, alert.status),
        statusTone: escalationStatusTone(alert.status),
        patientTone: patient ? patientDashboardTone(patient) : "info",
        suggestedAction: alert.severity === "Critical" ? "Acknowledge and call duty doctor" : "Assign owner and set follow-up",
      };
    });

  const taskRows = icuTasks
    .filter((task) => task.status === "Overdue" || task.status === "Escalated" || task.priority === "Critical" || task.priority === "High")
    .map((task): EscalationCenterRow => {
      const patient = getEscalationPatient(task.patientId);
      const severity = task.priority === "Routine" ? "Info" : task.priority;
      return {
        id: `task-${task.id}`,
        sourceKind: "Nursing task",
        patientId: task.patientId,
        patient: task.patientName,
        bedNo: task.bedNo,
        unit: patient?.unit ?? "ICU",
        category: task.taskType,
        trigger: `${task.title}. ${task.remarks}`,
        severity,
        source: task.createdBy,
        owner: task.assignedTo,
        routeTo: escalationRoute(task.taskType, task.assignedTo, severity),
        sla: task.status === "Overdue" ? "Breached" : task.dueTime,
        status: task.status,
        createdAt: `Due ${task.dueTime}`,
        tone: escalationSeverityTone(severity),
        slaTone: task.status === "Overdue" ? "critical" : escalationSlaTone(severity, task.status),
        statusTone: escalationStatusTone(task.status),
        patientTone: patient ? patientDashboardTone(patient) : "info",
        suggestedAction: task.status === "Overdue" ? "Escalate overdue task" : "Accept and start task",
      };
    });

  const doctorRows = doctorInstructions
    .filter((instruction) => instruction.status !== "Completed" && (instruction.priority === "Critical" || instruction.priority === "High"))
    .map((instruction): EscalationCenterRow => {
      const patient = getEscalationPatient(instruction.patientId);
      const severity: EscalationCenterRow["severity"] = instruction.priority === "Routine" ? "Info" : instruction.priority;
      return {
        id: `doctor-${instruction.id}`,
        sourceKind: "Doctor order",
        patientId: instruction.patientId,
        patient: patient?.patientName ?? patientName(instruction.patientId),
        bedNo: instruction.bedNo,
        unit: patient?.unit ?? "ICU",
        category: instruction.instructionType,
        trigger: `${instruction.instruction}. ${instruction.remarks}`,
        severity,
        source: instruction.doctor,
        owner: instruction.assignedNurse,
        routeTo: instruction.doctor,
        sla: instruction.dueTime,
        status: instruction.status,
        createdAt: `Due ${instruction.dueTime}`,
        tone: escalationSeverityTone(severity),
        slaTone: escalationSlaTone(severity, instruction.status),
        statusTone: escalationStatusTone(instruction.status),
        patientTone: patient ? patientDashboardTone(patient) : "info",
        suggestedAction: "Confirm order follow-up and document action",
      };
    });

  const medicationRowsForEscalation = medicationRows
    .filter((medication) => medication.status === "Late" || medication.status === "Due")
    .map((medication): EscalationCenterRow => {
      const patient = getEscalationPatient(medication.patientId);
      const severity: EscalationCenterRow["severity"] = medication.status === "Late" ? "High" : "Medium";
      return {
        id: `med-${medication.id}`,
        sourceKind: "Medication",
        patientId: medication.patientId,
        patient: patient?.patientName ?? patientName(medication.patientId),
        bedNo: medication.bedNo,
        unit: patient?.unit ?? "ICU",
        category: "Medication administration",
        trigger: `${medication.medication} ${medication.dose} ${medication.route} is ${medication.status.toLowerCase()}. ${medication.reason}`,
        severity,
        source: "Nurse eMAR",
        owner: medication.administeredBy === "-" ? patient?.assignedWardNurse ?? "Ward Nurse" : medication.administeredBy,
        routeTo: medication.reason.toLowerCase().includes("pharmacy") ? "Pharmacy" : patient?.dutyDoctor ?? "Duty Doctor",
        sla: medication.status === "Late" ? "Breached" : medication.scheduledTime,
        status: medication.status,
        createdAt: `Scheduled ${medication.scheduledTime}`,
        tone: escalationSeverityTone(severity),
        slaTone: medication.status === "Late" ? "critical" : "warning",
        statusTone: escalationStatusTone(medication.status),
        patientTone: patient ? patientDashboardTone(patient) : "info",
        suggestedAction: medication.status === "Late" ? "Notify pharmacy and doctor" : "Prepare and double verify",
      };
    });

  const severityOrder: Record<EscalationCenterRow["severity"], number> = { Critical: 0, High: 1, Medium: 2, Info: 3 };
  return [...alertRows, ...taskRows, ...doctorRows, ...medicationRowsForEscalation]
    .sort((left, right) => severityOrder[left.severity] - severityOrder[right.severity] || left.bedNo.localeCompare(right.bedNo));
}

function getEscalationPatient(patientId: string) {
  return icuPatients.find((patient) => patient.id === patientId);
}

function escalationSeverityTone(severity: EscalationCenterRow["severity"]): DashboardCellTone {
  if (severity === "Critical") return "critical";
  if (severity === "High") return "danger";
  if (severity === "Medium") return "warning";
  return "info";
}

function escalationSla(severity: EscalationCenterRow["severity"], status: string) {
  if (status === "Acknowledged") return "Watching";
  if (severity === "Critical") return "Immediate";
  if (severity === "High") return "15 min";
  if (severity === "Medium") return "30 min";
  return "Today";
}

function escalationSlaTone(severity: EscalationCenterRow["severity"], status: string): DashboardCellTone {
  if (status === "Overdue" || severity === "Critical") return "critical";
  if (severity === "High") return "danger";
  if (severity === "Medium") return "warning";
  return "success";
}

function escalationStatusTone(status: string): DashboardCellTone {
  if (/resolved|completed|administered/i.test(status)) return "success";
  if (/overdue|late|open/i.test(status)) return "danger";
  if (/acknowledged|in progress|assigned|pending/i.test(status)) return "info";
  return "warning";
}

function escalationRoute(category: string, owner: string, severity: EscalationCenterRow["severity"]) {
  const text = `${category} ${owner}`.toLowerCase();
  if (text.includes("medication") || text.includes("mar") || text.includes("pharmacy")) return "Pharmacy + ward nurse";
  if (text.includes("vent") || text.includes("respiratory") || text.includes("abg")) return "Duty doctor + respiratory team";
  if (text.includes("transfer") || text.includes("clearance")) return "Unit nurse + bed desk";
  if (text.includes("blood") || text.includes("transfusion")) return "Blood bank + duty doctor";
  if (severity === "Critical") return "Duty doctor + head nurse";
  return "Assigned owner";
}

function escalationOwnerLoad(rows: EscalationCenterRow[]) {
  return Array.from(new Set(rows.map((row) => row.owner))).map((owner) => {
    const ownerRows = rows.filter((row) => row.owner === owner);
    const critical = ownerRows.filter((row) => row.severity === "Critical" || row.severity === "High").length;
    const tone: DashboardCellTone = critical >= 3 ? "critical" : critical >= 1 ? "warning" : "success";
    return {
      owner,
      count: ownerRows.length,
      critical,
      units: Array.from(new Set(ownerRows.map((row) => row.unit))).slice(0, 3),
      tone,
    };
  }).sort((left, right) => right.count - left.count).slice(0, 6);
}

function escalationChecklist(row: EscalationCenterRow) {
  if (row.sourceKind === "Medication") {
    return ["Patient identity and allergy checked", "Dose route frequency verified", "Pharmacy stock / dispense status confirmed", "Doctor informed if dose remains delayed"];
  }
  if (row.sourceKind === "Doctor order") {
    return ["Order read-back completed", "Assigned nurse accepted action", "Follow-up time documented", "Doctor updated after completion"];
  }
  if (/vent|respiratory|abg/i.test(`${row.category} ${row.trigger}`)) {
    return ["Airway and oxygen support reviewed", "ABG / SpO2 trend checked", "Respiratory therapist informed", "Escalation threshold documented"];
  }
  if (/transfer|clearance/i.test(`${row.category} ${row.trigger}`)) {
    return ["Destination readiness checked", "Bed / device handover prepared", "Medication and documentation clearance checked", "Receiving nurse informed"];
  }
  return ["Patient context reviewed", "Severity confirmed", "Responsible owner assigned", "Action note and next review time recorded"];
}

function escalationSourceHref(row: EscalationCenterRow) {
  if (row.sourceKind === "Clinical alert") return icuPatientDetailHref(row.patientId, "events");
  if (row.sourceKind === "Nursing task") return icuPatientDetailHref(row.patientId, "shift-summary");
  if (row.sourceKind === "Doctor order" || row.sourceKind === "Medication") return icuPatientDetailHref(row.patientId, "orders");
  return icuPatientDetailHref(row.patientId, "overview");
}

function escalationDialogCopy(action: EscalationCellAction) {
  const { kind, row } = action;
  if (kind === "priority") {
    return {
      title: "Priority review",
      description: "Severity rule, patient risk, and response urgency.",
      focus: "Confirm why this case is critical/high and whether it needs immediate escalation.",
      primaryAction: "Confirm priority",
    };
  }
  if (kind === "trigger") {
    return {
      title: "Trigger review",
      description: "Clinical trigger, source event, and immediate bedside action.",
      focus: row.trigger,
      primaryAction: "Save trigger action",
    };
  }
  if (kind === "owner") {
    return {
      title: "Owner and routing",
      description: "Assign the right team and confirm communication path.",
      focus: `Current owner: ${row.owner}. Route: ${row.routeTo}.`,
      primaryAction: "Update owner",
    };
  }
  if (kind === "sla") {
    return {
      title: "SLA and next review",
      description: "Escalation timer, breach risk, and follow-up window.",
      focus: `SLA ${row.sla}, created ${row.createdAt}.`,
      primaryAction: "Save SLA",
    };
  }
  if (kind === "status") {
    return {
      title: "Status update",
      description: "Move escalation from open to in-progress, resolved, or re-escalated.",
      focus: `Current status: ${row.status}.`,
      primaryAction: "Update status",
    };
  }
  return {
    title: "Escalation command action",
    description: "Review patient context, source, checklist, and closure note.",
    focus: row.suggestedAction,
    primaryAction: "Confirm action",
  };
}

function escalationContextFields(action: EscalationCellAction) {
  const { kind, row } = action;
  const base = [
    { label: "Patient", value: `${row.bedNo} - ${row.patient}` },
    { label: "Source", value: row.sourceKind },
  ];
  if (kind === "priority") {
    return [...base, { label: "Severity", value: row.severity }, { label: "Priority basis", value: row.category }, { label: "Suggested response", value: row.suggestedAction }];
  }
  if (kind === "trigger") {
    return [...base, { label: "Trigger type", value: row.category }, { label: "Trigger source", value: row.source }, { label: "Clinical note", value: row.trigger }];
  }
  if (kind === "owner") {
    return [...base, { label: "Current owner", value: row.owner }, { label: "Route to", value: row.routeTo }, { label: "Unit", value: row.unit }];
  }
  if (kind === "sla") {
    return [...base, { label: "SLA", value: row.sla }, { label: "Created / due", value: row.createdAt }, { label: "Breach risk", value: row.slaTone === "critical" ? "High" : "Controlled" }];
  }
  if (kind === "status") {
    return [...base, { label: "Current status", value: row.status }, { label: "Owner", value: row.owner }, { label: "Closure evidence", value: "Action note, responsible owner, and next review time" }];
  }
  return [...base, { label: "Severity", value: row.severity }, { label: "Owner", value: row.owner }, { label: "SLA", value: row.sla }, { label: "Route", value: row.routeTo }];
}

function escalationKindChecklist(action: EscalationCellAction) {
  const { kind, row } = action;
  if (kind === "priority") {
    return ["Patient condition checked against latest vitals", "Critical/high reason documented", "Response owner confirmed", "Immediate review need decided"];
  }
  if (kind === "trigger") {
    return ["Trigger source opened", "Bedside condition verified", "Repeat value/action captured", "Doctor/head nurse informed if needed"];
  }
  if (kind === "owner") {
    return ["Correct team selected", "Backup owner identified", "Notification sent", "Handover note documented"];
  }
  if (kind === "sla") {
    return ["SLA start time confirmed", "Next review time selected", "Breach reason documented if delayed", "Escalation timer communicated"];
  }
  if (kind === "status") {
    return ["Current status verified", "Completion evidence captured", "Pending blocker recorded", "Closure/re-escalation decision saved"];
  }
  return escalationChecklist(row);
}

function EscalationSidePanel({
  title,
  badge,
  tone,
  children,
}: {
  title: string;
  badge: string;
  tone: DashboardCellTone;
  children: React.ReactNode;
}) {
  return (
    <div className="rounded-sm border border-slate-300 bg-white shadow-sm">
      <div className="flex items-center justify-between gap-3 border-b border-slate-200 px-3 py-3">
        <p className="text-sm font-black text-slate-950">{title}</p>
        <span className={cn("rounded-full border px-2.5 py-1 text-xs font-bold", dashboardTonePillClass(tone))}>{badge}</span>
      </div>
      <div className="space-y-2 p-3">{children}</div>
    </div>
  );
}

function EscalationActionDialog({ action, onOpenChange }: { action: EscalationCellAction | null; onOpenChange: (open: boolean) => void }) {
  if (!action) {
    return <Dialog.Root open={false} onOpenChange={onOpenChange} />;
  }

  return <EscalationActionDialogContent key={`${action.row.id}-${action.kind}`} action={action} onOpenChange={onOpenChange} />;
}

function EscalationActionDialogContent({ action, onOpenChange }: { action: EscalationCellAction; onOpenChange: (open: boolean) => void }) {
  const { row } = action;
  const copy = escalationDialogCopy(action);
  const contextFields = escalationContextFields(action);
  const checks = escalationKindChecklist(action);
  const [selectedAction, setSelectedAction] = React.useState(row.status === "Open" || row.status === "Late" || row.status === "Overdue" ? "Acknowledge" : "Update follow-up");
  const [owner, setOwner] = React.useState(row.owner);
  const [sla, setSla] = React.useState(row.sla === "Breached" ? "Immediate" : row.sla);
  const [notify, setNotify] = React.useState(row.routeTo);
  const [note, setNote] = React.useState(copy.focus);
  const [checkedItems, setCheckedItems] = React.useState<string[]>([]);

  const patient = getEscalationPatient(row.patientId);
  const latestVital = [...icuVitals].reverse().find((vital) => vital.patientId === row.patientId);
  const completedChecks = checkedItems.length;

  function toggleCheck(item: string) {
    setCheckedItems((current) => current.includes(item) ? current.filter((value) => value !== item) : [...current, item]);
  }

  function complete(label: string) {
    toast.success(`${label} saved for ${row.bedNo} - ${row.patient}`);
    onOpenChange(false);
  }

  return (
    <Dialog.Root open={Boolean(row)} onOpenChange={onOpenChange}>
      <Dialog.Portal>
        <Dialog.Overlay className="fixed inset-0 z-50 bg-black/45 backdrop-blur-[1px]" />
        <Dialog.Content className="fixed left-1/2 top-1/2 z-50 flex max-h-[92dvh] w-[min(980px,calc(100vw-24px))] -translate-x-1/2 -translate-y-1/2 flex-col overflow-hidden rounded-xl border border-slate-300 bg-white shadow-2xl outline-none">
          <DialogHeader title={copy.title} description={`${copy.description} ${row.bedNo} | ${row.patient} | ${row.unit}`} />
          <div className="min-h-0 flex-1 overflow-y-auto p-4">
            <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_300px]">
              <div className="space-y-4">
                <div className={cn("rounded-md border p-4", dashboardToneSurfaceClass(row.tone))}>
                  <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
                    <div>
                      <p className="text-sm font-black text-slate-950">{row.category}</p>
                      <p className="mt-2 text-sm leading-relaxed text-slate-700">{row.trigger}</p>
                    </div>
                    <div className="flex flex-wrap gap-2">
                      <span className={cn("rounded-full border px-2.5 py-1 text-xs font-bold", dashboardTonePillClass(row.tone))}>{row.severity}</span>
                      <span className={cn("rounded-full border px-2.5 py-1 text-xs font-bold", dashboardTonePillClass(row.statusTone))}>{row.status}</span>
                    </div>
                  </div>
                </div>

                <div className="grid gap-2 rounded-md border border-slate-200 bg-white p-3 sm:grid-cols-2">
                  {contextFields.map((field) => (
                    <InfoLine key={field.label} label={field.label} value={field.value} />
                  ))}
                </div>

                <div className="grid gap-3 md:grid-cols-2">
                  <NativeSelect label="Action" value={selectedAction} onChange={setSelectedAction} options={["Acknowledge", "Assign owner", "Escalate", "Update follow-up", "Resolve"]} />
                  <NativeSelect label="Responsible owner" value={owner} onChange={setOwner} options={["Duty Doctor", "Head Nurse", "Ward Nurse", "Unit Nurse", "Pharmacy", "Biomedical", "Respiratory Team", "Admission Desk", row.owner]} />
                  <NativeSelect label="SLA / next review" value={sla} onChange={setSla} options={["Immediate", "10 min", "15 min", "30 min", "Next round", "Today"]} />
                  <NativeSelect label="Notify / route to" value={notify} onChange={setNotify} options={["Duty doctor + head nurse", "Pharmacy + ward nurse", "Biomedical + respiratory team", "Unit nurse + bed desk", "Blood bank + duty doctor", row.routeTo]} />
                </div>

                <div className="rounded-md border border-slate-200 bg-white p-3">
                  <div className="flex items-center justify-between gap-3">
                    <p className="text-sm font-black text-slate-950">Confirmation checklist</p>
                    <span className={cn("rounded-full border px-2.5 py-1 text-xs font-bold", dashboardTonePillClass(completedChecks === checks.length ? "success" : "info"))}>{completedChecks}/{checks.length}</span>
                  </div>
                  <div className="mt-3 grid gap-2 sm:grid-cols-2">
                    {checks.map((item) => (
                      <label className="flex cursor-pointer items-center gap-2 rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-sm text-slate-700" key={item}>
                        <input checked={checkedItems.includes(item)} className="h-4 w-4 rounded border-slate-300" type="checkbox" onChange={() => toggleCheck(item)} />
                        <span>{item}</span>
                      </label>
                    ))}
                  </div>
                </div>

                <label className="block space-y-1 text-sm">
                  <span className="font-medium text-slate-700">Action note</span>
                  <textarea
                    className="min-h-28 w-full rounded-md border border-slate-300 bg-white px-3 py-2 text-sm outline-none focus:border-sky-400 focus:ring-2 focus:ring-sky-100"
                    value={note}
                    onChange={(event) => setNote(event.target.value)}
                    placeholder="Document clinical action, communication, next review, and closure evidence..."
                  />
                </label>
              </div>

              <div className="space-y-3">
                <div className="rounded-md border border-slate-200 bg-slate-50 p-3">
                  <p className="text-sm font-black text-slate-950">Patient snapshot</p>
                  <div className="mt-3 space-y-2">
                    <InfoLine label="MRN" value={patient?.mrn ?? "-"} />
                    <InfoLine label="Diagnosis" value={patient?.diagnosis ?? "-"} />
                    <InfoLine label="Status" value={patient?.currentStatus ?? "-"} />
                    <InfoLine label="Ventilation" value={patient?.ventilatorStatus ?? "-"} />
                    <InfoLine label="Ward nurse" value={patient?.assignedWardNurse ?? "-"} />
                    <InfoLine label="Latest vitals" value={latestVital ? `SpO2 ${latestVital.spo2}%, BP ${latestVital.bp}` : "-"} />
                  </div>
                </div>
                <div className="rounded-md border border-slate-200 bg-white p-3">
                  <p className="text-sm font-black text-slate-950">Escalation source</p>
                  <div className="mt-3 space-y-2">
                    <InfoLine label="Source" value={row.source} />
                    <InfoLine label="Created" value={row.createdAt} />
                    <InfoLine label="Current SLA" value={row.sla} />
                    <InfoLine label="Route" value={row.routeTo} />
                  </div>
                </div>
                <Link className="inline-flex h-10 w-full items-center justify-center rounded-md border border-sky-300 bg-sky-50 px-3 text-sm font-bold text-sky-700 hover:bg-sky-100" href={escalationSourceHref(row)}>
                  Open source detail
                </Link>
              </div>
            </div>
          </div>
          <div className="flex flex-col-reverse gap-2 border-t border-slate-200 bg-slate-50 p-3 sm:flex-row sm:justify-end">
            <Dialog.Close asChild>
              <Button variant="outline">Cancel</Button>
            </Dialog.Close>
            <Button variant="outline" onClick={() => complete("Follow-up")}>Save follow-up</Button>
            <Button variant="outline" onClick={() => complete("Escalation")}>Escalate</Button>
            <Button onClick={() => complete(selectedAction)}>{copy.primaryAction}</Button>
          </div>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

function PatientOverviewCommand({ patients }: { patients: IcuPatient[] }) {
  const { role } = useRole();

  if (role === "Ward Nurse") {
    return <WardNurseAssignedPatientsCommand patients={patients} />;
  }

  return <PatientOverviewDetailCommand patients={patients} />;
}

function PatientOverviewDetailCommand({ patients }: { patients: IcuPatient[] }) {
  const [patientId, setPatientId] = React.useState(patients[0]?.id ?? icuPatients[0]?.id ?? "");
  const patient = patients.find((item) => item.id === patientId) ?? icuPatients.find((item) => item.id === patientId) ?? icuPatients[0];
  const patientVitals = icuVitals.filter((row) => row.patientId === patient?.id);
  const latestVital = [...patientVitals].reverse()[0];
  const activeMeds = medicationRows.filter((row) => row.patientId === patient?.id);
  const dueMeds = activeMeds.filter((row) => row.status === "Due" || row.status === "Late");
  const activeTasks = icuTasks.filter((row) => row.patientId === patient?.id && row.status !== "Completed");
  const activeAlerts = icuAlerts.filter((row) => row.patientId === patient?.id && row.status !== "Resolved");
  const patientInstructions = doctorInstructions.filter((row) => row.patientId === patient?.id && row.status !== "Completed");
  const deviceRow = getCommandDeviceRows().find((row) => row.bedNo === patient?.bedNo);
  const ioRows = intakeOutputRows.filter((row) => row.patientId === patient?.id);
  const intakeTotal = ioRows.filter((row) => row.kind === "Intake").reduce((sum, row) => sum + row.quantityMl, 0);
  const outputTotal = ioRows.filter((row) => row.kind === "Output").reduce((sum, row) => sum + row.quantityMl, 0);
  const balance = intakeTotal - outputTotal;
  const patientInfusions = infusionRows.filter((row) => row.patientId === patient?.id);
  const patientResults = [
    { id: "lab-abg", type: "Lab", name: "ABG", status: activeAlerts.some((row) => row.type.toLowerCase().includes("lab")) ? "Critical follow-up" : "Reviewed", time: "Today 09:30", tone: activeAlerts.some((row) => row.type.toLowerCase().includes("lab")) ? "danger" as StatusTone : "success" as StatusTone },
    { id: "lab-cbc", type: "Lab", name: "CBC / Electrolytes", status: patient?.criticalityScore && patient.criticalityScore >= 8 ? "Repeat due" : "Stable", time: "Today 08:45", tone: patient?.criticalityScore && patient.criticalityScore >= 8 ? "warning" as StatusTone : "success" as StatusTone },
    { id: "rad-cxr", type: "Radiology", name: patient?.ventilatorStatus === "Room air" ? "Chest review" : "Chest X-ray", status: patient?.ventilatorStatus === "Room air" ? "Not required" : "Report available", time: "Today 07:50", tone: "info" as StatusTone },
  ];
  const timeline = [
    ...patientVitals.slice(-3).map((row) => ({ id: `vital-${row.id}`, type: "Vitals", title: `${row.time} - SpO2 ${row.spo2}%, BP ${row.bp}`, detail: row.note, tone: row.abnormal ? "danger" as StatusTone : "success" as StatusTone })),
    ...activeAlerts.map((row) => ({ id: `alert-${row.id}`, type: "Alert", title: `${row.createdAt} - ${row.type}`, detail: row.message, tone: toneForStatus(row.severity) })),
    ...dueMeds.map((row) => ({ id: `med-${row.id}`, type: "Medication", title: `${row.scheduledTime} - ${row.medication}`, detail: `${row.status}: ${row.reason}`, tone: toneForStatus(row.status) })),
    ...patientInstructions.slice(0, 3).map((row) => ({ id: `order-${row.id}`, type: "Order", title: `${row.dueTime} - ${row.instructionType}`, detail: row.instruction, tone: toneForPriority(row.priority) })),
  ].slice(0, 8);
  const statusTone: StatusTone = patient?.currentStatus === "Critical" ? "danger" : patient?.currentStatus === "Ventilated" ? "warning" : "success";
  const statusDashboardTone: DashboardCellTone = statusTone === "danger" ? "critical" : statusTone === "warning" ? "warning" : "success";
  const matrixItems = [
    {
      key: "status",
      label: "Clinical Status",
      icon: ShieldAlert,
      title: patient?.currentStatus ?? "ICU patient",
      detail: `Score ${patient?.criticalityScore ?? "-"} | ${patient?.diagnosis ?? "-"}`,
      tone: statusDashboardTone,
      href: icuPatientDetailHref(patient.id, "overview"),
    },
    {
      key: "vitals",
      label: "Latest Vitals",
      icon: HeartPulse,
      title: latestVital ? `SpO2 ${latestVital.spo2}%` : "No vitals",
      detail: latestVital ? `BP ${latestVital.bp} | GCS ${latestVital.gcs} | ${latestVital.time}` : "Monitoring pending",
      tone: latestVital?.abnormal || (latestVital && latestVital.spo2 < 94) ? "critical" as DashboardCellTone : "success" as DashboardCellTone,
      href: icuPatientDetailHref(patient.id, "monitoring", "24h-chart"),
    },
    {
      key: "ventilation",
      label: "Ventilation / Device",
      icon: Activity,
      title: patient?.ventilatorStatus ?? "Support",
      detail: `${deviceRow?.monitor ?? "Monitor not mapped"} | ${deviceRow?.signal ?? "Signal pending"}`,
      tone: patient?.ventilatorStatus === "Room air" ? "success" as DashboardCellTone : "purple" as DashboardCellTone,
      href: icuPatientDetailHref(patient.id, "monitoring", "ventilation"),
    },
    {
      key: "intake-output",
      label: "Intake / Output",
      icon: Droplets,
      title: `${balance >= 0 ? "+" : ""}${balance} ml`,
      detail: `${intakeTotal} ml in | ${outputTotal} ml out`,
      tone: Math.abs(balance) > 1000 ? "warning" as DashboardCellTone : "success" as DashboardCellTone,
      href: icuPatientDetailHref(patient.id, "monitoring", "intake-output"),
    },
    {
      key: "medication",
      label: "Medication",
      icon: Pill,
      title: dueMeds.length ? `${dueMeds.length} due` : "On track",
      detail: dueMeds[0] ? `${dueMeds[0].medication} ${dueMeds[0].status}` : `${activeMeds.length} active rows`,
      tone: dueMeds.some((row) => row.status === "Late") ? "critical" as DashboardCellTone : dueMeds.length ? "warning" as DashboardCellTone : "success" as DashboardCellTone,
      href: icuPatientDetailHref(patient.id, "orders"),
    },
    {
      key: "results",
      label: "Labs / Radiology",
      icon: TestTube2,
      title: patientResults.some((row) => row.tone === "danger") ? "Critical" : "Available",
      detail: patientResults.map((row) => `${row.name}: ${row.status}`).slice(0, 2).join(" | "),
      tone: patientResults.some((row) => row.tone === "danger") ? "critical" as DashboardCellTone : patientResults.some((row) => row.tone === "warning") ? "warning" as DashboardCellTone : "info" as DashboardCellTone,
      href: icuPatientDetailHref(patient.id, "results"),
    },
    {
      key: "alerts",
      label: "Alerts / Events",
      icon: AlertTriangle,
      title: activeAlerts.length ? `${activeAlerts.length} alert${activeAlerts.length === 1 ? "" : "s"}` : "No alert",
      detail: activeAlerts[0]?.message ?? "No active event",
      tone: activeAlerts.length ? "critical" as DashboardCellTone : "success" as DashboardCellTone,
      href: icuPatientDetailHref(patient.id, "events", undefined, "eventFocus=open-alerts"),
    },
    {
      key: "tasks",
      label: "Tasks / Orders",
      icon: ClipboardCheck,
      title: `${activeTasks.length + patientInstructions.length} pending`,
      detail: activeTasks[0]?.title ?? patientInstructions[0]?.instruction ?? "No pending item",
      tone: activeTasks.length + patientInstructions.length ? "warning" as DashboardCellTone : "success" as DashboardCellTone,
      href: icuPatientDetailHref(patient.id, "orders", undefined, "ordersTab=pending-work"),
    },
    {
      key: "timeline",
      label: "Notes / Timeline",
      icon: FileText,
      title: `${timeline.length} events`,
      detail: timeline[0]?.title ?? "No recent activity",
      tone: timeline.some((row) => row.tone === "danger") ? "warning" as DashboardCellTone : "info" as DashboardCellTone,
      href: icuPatientDetailHref(patient.id, "events", undefined, "eventFocus=action-needed"),
    },
  ];

  return (
    <div className="space-y-4">
      <div className="rounded-sm border border-slate-300 bg-white shadow-sm">
        <CollapsibleCommandPanel
          summary={`${patient?.bedNo ?? "-"} - ${patient?.patientName ?? "Patient"} | ${patient?.currentStatus ?? "-"} | score ${patient?.criticalityScore ?? "-"}`}
          title="Patient overview metrics & filters"
        >
          <div className="grid gap-3 border-b border-slate-200 p-4 lg:grid-cols-[360px_repeat(5,minmax(0,1fr))] lg:items-end">
            <PatientSelect label="Patient" value={patientId} onChange={setPatientId} patients={patients.length ? patients : icuPatients} />
            <DashboardCommandMetric label="Risk score" value={patient?.criticalityScore ?? "-"} tone={patient && patient.criticalityScore >= 8 ? "critical" : patient && patient.criticalityScore >= 6 ? "warning" : "success"} />
            <DashboardCommandMetric label="Open alerts" value={activeAlerts.length} tone={activeAlerts.length ? "danger" : "success"} />
            <DashboardCommandMetric label="Due meds" value={dueMeds.length} tone={dueMeds.some((row) => row.status === "Late") ? "danger" : dueMeds.length ? "warning" : "success"} />
            <DashboardCommandMetric label="Pending tasks" value={activeTasks.length} tone={activeTasks.length ? "warning" : "success"} />
            <DashboardCommandMetric label="I/O balance" value={`${balance >= 0 ? "+" : ""}${balance} ml`} tone={Math.abs(balance) > 1000 ? "warning" : "success"} />
          </div>
        </CollapsibleCommandPanel>
        <div className="overflow-hidden border-b border-slate-200">
          <div className="overflow-x-auto">
            <table className="w-full min-w-[1180px] border-collapse bg-white text-sm">
              <thead className="bg-slate-50 text-[11px] uppercase text-sky-700">
                <tr>
                  <th className="min-w-[180px] px-3 py-3 text-left">Patient</th>
                  {matrixItems.map((item) => (
                    <th className="min-w-[120px] px-2 py-3 text-center" key={item.key}>{item.label}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                <tr className="border-t border-slate-200">
                  <td className="bg-white px-3 py-3 align-middle">
                    <Link className="block rounded-md border border-slate-200 bg-slate-50 p-3 transition hover:border-sky-300 hover:bg-sky-50" href={icuPatientDetailHref(patient.id, "overview")}>
                      <p className={cn("truncate text-sm font-black", dashboardToneTextClass(patientDashboardTone(patient)))}>{patient.patientName}</p>
                      <p className="mt-1 text-xs font-semibold text-slate-700">{patient.bedNo} | {patient.mrn}</p>
                      <p className="mt-1 text-xs text-slate-500">{patient.ageGender} | {patient.unit}</p>
                    </Link>
                  </td>
                  {matrixItems.map((item) => (
                    <td className="px-2 py-3 align-middle text-center" key={item.key}>
                      <DoctorRoundLinkMatrixCell detail={item.detail} href={item.href} icon={item.icon} title={item.title} tone={item.tone} showDetail={false} />
                    </td>
                  ))}
                </tr>
              </tbody>
            </table>
          </div>
        </div>

        <div className="grid items-start gap-3 p-3 xl:grid-cols-2 2xl:grid-cols-4">
          <CommandSection title="Medication and infusions">
            <div className="space-y-2">
              {activeMeds.slice(0, 3).map((row) => (
                <div className="flex min-h-14 items-center justify-between gap-3 rounded-md border border-slate-200 bg-white px-3 py-2" key={row.id}>
                  <div className="min-w-0">
                    <p className="truncate text-sm font-bold text-slate-950">{row.medication} {row.dose}</p>
                    <p className="truncate text-xs text-slate-500">{row.scheduledTime} | {row.route} | {row.frequency}</p>
                  </div>
                  <StatusPill tone={toneForStatus(row.status)}>{row.status}</StatusPill>
                </div>
              ))}
              {!activeMeds.length ? <p className="rounded-md border border-slate-200 bg-slate-50 p-3 text-sm text-slate-500">No active medication rows.</p> : null}
            </div>
            <MiniList title="Running infusions" rows={patientInfusions.map((row) => `${row.fluidName} ${row.rate} - ${row.status}`)} />
          </CommandSection>

          <CommandSection title="Investigations and results">
            <div className="space-y-2">
              {patientResults.map((row) => (
                <div className="flex min-h-14 items-center justify-between gap-3 rounded-md border border-slate-200 bg-white px-3 py-2" key={row.id}>
                  <div className="min-w-0">
                    <p className="truncate text-sm font-bold text-slate-950">{row.type} - {row.name}</p>
                    <p className="truncate text-xs text-slate-500">{row.time}</p>
                  </div>
                  <StatusPill tone={row.tone}>{row.status}</StatusPill>
                </div>
              ))}
            </div>
          </CommandSection>

          <CommandSection title="Active issues">
            <MiniList title="Alerts" rows={activeAlerts.map((row) => `${row.severity}: ${row.message}`)} />
            <MiniList title="Tasks" rows={activeTasks.map((row) => `${row.dueTime} - ${row.title}`)} />
            <MiniList title="Doctor orders" rows={patientInstructions.map((row) => `${row.dueTime} - ${row.instruction}`)} />
          </CommandSection>

          <CommandSection title="Patient timeline">
            <div className="max-h-[360px] space-y-2 overflow-y-auto pr-1">
              {timeline.map((item) => (
                <div className="rounded-md border border-slate-200 bg-white p-3" key={item.id}>
                  <div className="flex items-center justify-between gap-2">
                    <p className="truncate text-sm font-bold text-slate-950">{item.type}</p>
                    <StatusPill tone={item.tone}>{item.type}</StatusPill>
                  </div>
                  <p className="mt-1 line-clamp-1 text-sm font-semibold text-slate-700">{item.title}</p>
                  <p className="mt-1 line-clamp-2 text-xs leading-relaxed text-slate-500">{item.detail}</p>
                </div>
              ))}
              {!timeline.length ? <p className="rounded-md border border-slate-200 bg-slate-50 p-3 text-sm text-slate-500">No recent patient activity.</p> : null}
            </div>
            <Button variant="outline" asChild><Link href={icuPatientDetailHref(patient.id, "events")}>Open events</Link></Button>
          </CommandSection>
        </div>
      </div>
    </div>
  );
}

type WardNursePatientWorkRow = {
  patient: IcuPatient;
  latestVital?: IcuVital;
  openAlerts: typeof icuAlerts;
  activeTasks: typeof icuTasks;
  dueMeds: typeof medicationRows;
  activeOrders: typeof doctorInstructions;
  pendingIo: typeof intakeOutputRows;
};

function WardNurseAssignedPatientsCommand({ patients }: { patients: IcuPatient[] }) {
  const sourcePatients = patients.length ? patients : icuPatients;
  const activeWardNurse = getActiveWardNurseName();
  const activeWardUnit = getActiveWardNurseUnit();
  const assignedPatients = sourcePatients.filter((patient) => patient.assignedWardNurse === activeWardNurse);
  const seededUnverifiedPatientIds = React.useMemo(() => new Set(assignedPatients.slice(0, 3).map((patient) => patient.id)), [activeWardNurse, assignedPatients.length]);
  const verificationStorageKey = React.useMemo(() => `ward-nurse-session-verification:${activeWardNurse}`, [activeWardNurse]);
  const [verifiedProfileIds, setVerifiedProfileIds] = React.useState<Set<string>>(() => readWardNurseSessionVerifiedIds(verificationStorageKey));
  const [verificationRow, setVerificationRow] = React.useState<WardNursePatientWorkRow | null>(null);
  const [search, setSearch] = React.useState("");
  const rows = assignedPatients
    .map(buildWardNursePatientWorkRow)
    .sort((first, second) => {
      const firstVerified = !seededUnverifiedPatientIds.has(first.patient.id) || verifiedProfileIds.has(first.patient.id);
      const secondVerified = !seededUnverifiedPatientIds.has(second.patient.id) || verifiedProfileIds.has(second.patient.id);
      if (firstVerified !== secondVerified) return firstVerified ? 1 : -1;
      return first.patient.bedNo.localeCompare(second.patient.bedNo);
    });
  const normalizedSearch = search.trim().toLowerCase();
  const filteredRows = normalizedSearch
    ? rows.filter((row) => wardNursePatientSearchText(row, activeWardUnit).includes(normalizedSearch))
    : rows;
  const pageSize = 10;
  const [page, setPage] = React.useState(1);
  const totalPages = Math.max(1, Math.ceil(filteredRows.length / pageSize));
  const pageStart = (page - 1) * pageSize;
  const visibleRows = filteredRows.slice(pageStart, pageStart + pageSize);

  React.useEffect(() => {
    setPage(1);
    setVerifiedProfileIds(readWardNurseSessionVerifiedIds(verificationStorageKey));
    setVerificationRow(null);
  }, [activeWardNurse, assignedPatients.length, verificationStorageKey]);

  React.useEffect(() => {
    setPage(1);
  }, [search]);

  return (
    <div className="space-y-2">
      <div className="overflow-hidden rounded-lg border border-slate-200 bg-white shadow-sm">
        <div className="flex flex-col gap-2 border-b border-slate-200 bg-white px-5 py-4 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h2 className="text-xl font-black tracking-tight text-slate-950">My Assigned Patients</h2>
            <p className="mt-0.5 text-sm font-semibold text-slate-500">{activeWardNurse} | {activeWardUnit}</p>
          </div>
          <div className="flex flex-col gap-2 sm:min-w-[340px] sm:items-end">
            <span className="inline-flex w-fit items-center rounded-full border border-sky-200 bg-sky-50 px-3 py-1.5 text-sm font-black text-sky-700">{filteredRows.length} patient(s)</span>
            <div className="relative w-full sm:max-w-[340px]">
              <Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-slate-400" aria-hidden="true" />
              <Input
                className="h-10 pl-9 text-sm font-semibold"
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search patient, bed, MRN..."
                value={search}
              />
            </div>
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full min-w-[1320px] border-collapse bg-white text-sm">
            <thead className="border-b border-slate-200 bg-slate-50 text-[11px] uppercase tracking-wide text-slate-950">
              <tr>
                <th className="sticky left-0 z-30 w-[220px] bg-slate-50 px-5 py-3.5 text-left shadow-[8px_0_14px_-16px_rgba(15,23,42,0.55)]">Patient / Bed</th>
                <th className="w-[170px] px-3 py-3.5 text-center">Profile Verification</th>
                <th className="w-[190px] px-3 py-3.5 text-center">Assessment / Vitals</th>
                <th className="w-[160px] px-3 py-3.5 text-center">Medication</th>
                <th className="w-[205px] px-3 py-3.5 text-center">Doctor Orders</th>
                <th className="w-[180px] px-3 py-3.5 text-center">Events</th>
                <th className="w-[180px] px-3 py-3.5 text-center">Handover / Issue</th>
                <th className="w-[155px] px-3 py-3.5 text-center">Action</th>
              </tr>
            </thead>
            <tbody>
              {visibleRows.map((row) => {
                const profileVerified = !seededUnverifiedPatientIds.has(row.patient.id) || verifiedProfileIds.has(row.patient.id);
                const assessmentTone: WardNurseCompactTone = row.latestVital?.abnormal ? "danger" : row.latestVital ? "success" : "warning";
                const medicationTone: WardNurseCompactTone = row.dueMeds.some((med) => med.status === "Late") ? "danger" : row.dueMeds.length ? "warning" : "success";
                const orderTone: WardNurseCompactTone = row.activeOrders.length + row.activeTasks.length ? "warning" : "success";
                const eventTone: WardNurseCompactTone = row.openAlerts.length ? "danger" : row.pendingIo.length ? "warning" : "success";
                const handoverTone: WardNurseCompactTone = row.openAlerts.length || row.activeTasks.length ? "warning" : "success";

                return (
                  <tr className="border-b border-slate-200 align-middle last:border-b-0 hover:bg-slate-50/70" key={row.patient.id}>
                    <td className={cn("sticky left-0 z-20 border-r border-slate-200 bg-white px-5 py-4 shadow-[8px_0_14px_-16px_rgba(15,23,42,0.55)]", "border-l-4", wardNurseRowAccentClass(patientDashboardTone(row.patient)))}>
                      <Link className="block rounded-md p-1 transition hover:bg-white hover:shadow-sm" href={icuPatientDetailHref(row.patient.id, "overview")}>
                        <p className={cn("truncate text-base font-black", dashboardToneTextClass(patientDashboardTone(row.patient)))}>{row.patient.patientName}</p>
                        <p className="mt-2 truncate text-sm font-black text-slate-950">{row.patient.bedNo} | {activeWardUnit}</p>
                        <p className="mt-1 truncate text-sm font-semibold text-slate-500">{row.patient.mrn} | {row.patient.ageGender}</p>
                      </Link>
                    </td>
                    <td className="px-3 py-4 text-center">
                      <WardNurseProfileVerificationCell
                        onVerifyNow={() => setVerificationRow(row)}
                        verified={profileVerified}
                      />
                    </td>
                    <td className="px-3 py-4 text-center">
                      <WardNurseQueueCell
                        disabled={!profileVerified}
                        detail={row.latestVital ? `${row.latestVital.time} | SpO2 ${row.latestVital.spo2}% | BP ${row.latestVital.bp}` : "No vitals entered"}
                        href={`/icu-command-center/nursing/nurse-entry?patientId=${row.patient.id}&locked=1`}
                        title={row.latestVital?.abnormal ? "Review vitals" : row.latestVital ? "Updated" : "Enter vitals"}
                        tone={assessmentTone}
                      />
                    </td>
                    <td className="px-3 py-4 text-center">
                      <WardNurseQueueCell
                        disabled={!profileVerified}
                        detail={row.dueMeds[0] ? `${row.dueMeds[0].scheduledTime} | ${row.dueMeds[0].medication}` : "No due medicine"}
                        href={`/icu-command-center/nursing/medication-administration?patientId=${row.patient.id}&focus=medication&locked=1`}
                        title={row.dueMeds.length ? `${row.dueMeds.length} due` : "Clear"}
                        tone={medicationTone}
                      />
                    </td>
                    <td className="px-3 py-4 text-center">
                      <WardNurseQueueCell
                        disabled={!profileVerified}
                        detail={row.activeOrders[0]?.instruction ?? row.activeTasks[0]?.title ?? "No open order"}
                        href={`/icu-command-center/nursing/order?patientId=${row.patient.id}&locked=1`}
                        title={row.activeOrders.length + row.activeTasks.length ? `${row.activeOrders.length + row.activeTasks.length} item(s)` : "Clear"}
                        tone={orderTone}
                      />
                    </td>
                    <td className="px-3 py-4 text-center">
                      <WardNurseQueueCell
                        disabled={!profileVerified}
                        detail={row.openAlerts[0]?.message ?? (row.pendingIo.length ? "I/O needs review" : "No open event")}
                        href={icuPatientDetailHref(row.patient.id, "events", undefined, `${row.openAlerts.length ? "eventFocus=open-alerts" : "eventFocus=action-needed"}&locked=1`)}
                        title={row.openAlerts.length ? `${row.openAlerts.length} alert(s)` : row.pendingIo.length ? "I/O review" : "Clear"}
                        tone={eventTone}
                      />
                    </td>
                    <td className="px-3 py-4 text-center">
                      <WardNurseQueueCell
                        disabled={!profileVerified}
                        detail={row.openAlerts.length || row.activeTasks.length ? "Carry forward if not closed" : "Ready for handover"}
                        href={`/icu-command-center/nursing/shift-handover?patientId=${row.patient.id}&locked=1`}
                        title={row.openAlerts.length || row.activeTasks.length ? "Pending" : "Ready"}
                        tone={handoverTone}
                      />
                    </td>
                    <td className="px-3 py-4 text-center">
                      <div className="flex items-center justify-center gap-3">
                        <WardNurseRoundAction
                          disabled={!profileVerified}
                          href={icuPatientDetailHref(row.patient.id, "overview", undefined, "locked=1")}
                          icon={Eye}
                          label="Open"
                        />
                        <WardNurseRoundAction
                          disabled={!profileVerified}
                          href={icuPatientDetailHref(row.patient.id, "collaborate", undefined, "action=raise-unit-issue&locked=1")}
                          icon={ExternalLink}
                          label="Raise Issue"
                        />
                      </div>
                    </td>
                  </tr>
                );
              })}
              {!filteredRows.length ? (
                <tr>
                  <td className="px-3 py-10 text-center text-sm font-semibold text-slate-500" colSpan={8}>
                    {rows.length ? "No assigned patient matches this search." : `No ICU patient is assigned to ${activeWardNurse}.`}
                  </td>
                </tr>
              ) : null}
            </tbody>
          </table>
        </div>
        {filteredRows.length > pageSize ? (
          <div className="flex flex-col gap-2 border-t border-slate-200 px-3 py-3 text-xs font-semibold text-slate-600 sm:flex-row sm:items-center sm:justify-between">
            <span>
              Showing {pageStart + 1}-{Math.min(pageStart + visibleRows.length, filteredRows.length)} of {filteredRows.length}
            </span>
            <div className="flex items-center gap-2">
              <Button size="sm" variant="outline" disabled={page === 1} onClick={() => setPage((currentPage) => Math.max(1, currentPage - 1))}>
                Previous
              </Button>
              <span className="px-2 text-slate-900">Page {page} / {totalPages}</span>
              <Button size="sm" variant="outline" disabled={page === totalPages} onClick={() => setPage((currentPage) => Math.min(totalPages, currentPage + 1))}>
                Next
              </Button>
            </div>
          </div>
        ) : null}
      </div>
      <WardNursePatientVerificationDialog
        activeWardNurse={activeWardNurse}
        onOpenChange={(open) => {
          if (!open) setVerificationRow(null);
        }}
        onVerify={(patientId) => {
          setVerifiedProfileIds((current) => {
            const next = new Set(current);
            next.add(patientId);
            writeWardNurseSessionVerifiedIds(verificationStorageKey, next);
            return next;
          });
          toast.success("Patient profile verified");
          setVerificationRow(null);
          window.location.href = `/icu-command-center/nursing/nurse-entry?patientId=${patientId}&locked=1`;
        }}
        row={verificationRow}
      />
    </div>
  );
}

