function teleIcuScenarioTitle(mode: TeleIcuScenarioMode) {
  if (mode === "readiness") return "Tele ICU Readiness";
  if (mode === "local-team") return "Tele ICU Local Team";
  if (mode === "remote-md") return "Tele ICU Remote MD";
  return "Tele ICU SLA Monitor";
}

function teleIcuScenarioShortLabel(mode: TeleIcuScenarioMode) {
  if (mode === "readiness") return "Readiness";
  if (mode === "local-team") return "Local Team";
  if (mode === "remote-md") return "Remote MD";
  return "SLA";
}

function teleIcuScenarioDescription(mode: TeleIcuScenarioMode) {
  if (mode === "readiness") return "Use this page when a remote review cell needs a complete readiness check before the remote doctor starts or continues review.";
  if (mode === "local-team") return "Use this page to verify the local duty doctor, ward nurse, and acknowledgement path for every remote ICU case.";
  if (mode === "remote-md") return "Use this page to review remote intensivist ownership, specialty consult context, advice status, and recommendation tracking.";
  return "Use this page to monitor Tele ICU SLA waiting time, breach risk, escalation path, and open patient context.";
}

function RemoteConsultationsCommand() {
  const [rows, setRows] = React.useState<RemoteConsultationRow[]>(() => buildRemoteConsultationRows());
  const [search, setSearch] = React.useState("");
  const [specialty, setSpecialty] = React.useState("All specialties");
  const [status, setStatus] = React.useState("All status");
  const [priority, setPriority] = React.useState("All priority");
  const [doctor, setDoctor] = React.useState("All remote doctors");
  const [readiness, setReadiness] = React.useState("All readiness");
  const [activeAction, setActiveAction] = React.useState<RemoteConsultationActiveAction | null>(null);
  const [activeCell, setActiveCell] = React.useState<RemoteConsultationCellAction | null>(null);

  const specialtyOptions = React.useMemo(() => ["All specialties", ...Array.from(new Set(rows.map((row) => row.specialty)))], [rows]);
  const doctorOptions = React.useMemo(() => ["All remote doctors", ...Array.from(new Set(rows.map((row) => row.remoteDoctor)))], [rows]);
  const visibleRows = React.useMemo(() => {
    const query = search.trim().toLowerCase();
    return rows.filter((row) => {
      const searchText = `${row.patientName} ${row.bedNo} ${row.mrn} ${row.unit} ${row.specialty} ${row.reason} ${row.requestedBy} ${row.remoteDoctor} ${row.documents} ${row.status}`.toLowerCase();
      const readinessMatch = readiness === "All readiness"
        || (readiness === "Ready" && row.readinessScore >= 85)
        || (readiness === "Partial" && row.readinessScore >= 70 && row.readinessScore < 85)
        || (readiness === "Missing documents" && row.readinessScore < 70);
      return (!query || searchText.includes(query))
        && (specialty === "All specialties" || row.specialty === specialty)
        && (status === "All status" || row.status === status)
        && (priority === "All priority" || row.priority === priority)
        && (doctor === "All remote doctors" || row.remoteDoctor === doctor)
        && readinessMatch;
    }).sort(remoteConsultationSort);
  }, [doctor, priority, readiness, rows, search, specialty, status]);

  const resetFilters = () => {
    setSearch("");
    setSpecialty("All specialties");
    setStatus("All status");
    setPriority("All priority");
    setDoctor("All remote doctors");
    setReadiness("All readiness");
  };

  const applyConsultAction = (action: RemoteConsultationActiveAction, note: string) => {
    const nextStatus = remoteConsultStatusAfterAction(action.kind);
    setRows((current) => current.map((row) => (
      row.id === action.row.id
        ? { ...row, status: nextStatus, lastAction: `${remoteConsultActionLabel(action.kind)}: ${note || "Updated"}`, waitingMinutes: Math.max(0, row.waitingMinutes - 5) }
        : row
    )));
    toast.success(`${remoteConsultActionLabel(action.kind)} recorded for ${action.row.bedNo}`);
    setActiveAction(null);
  };

  return (
    <div className="min-w-0 max-w-full space-y-4 overflow-hidden">
      <CollapsibleCommandPanel
        summary={`${specialty} | ${status} | ${priority} | ${visibleRows.length} consult(s)`}
        title="Remote consultation metrics & filters"
      >
        <div className="grid grid-cols-2 gap-2 border-b border-slate-200 px-3 py-3 md:flex md:flex-wrap md:items-center">
          <DashboardCommandMetric label="Consults" value={visibleRows.length} tone="info" />
          <DashboardCommandMetric label="Urgent" value={visibleRows.filter((row) => row.priority === "Critical" || row.priority === "High").length} tone={visibleRows.some((row) => row.priority === "Critical") ? "critical" : "warning"} />
          <DashboardCommandMetric label="In review" value={visibleRows.filter((row) => row.status === "In review").length} tone="info" />
          <DashboardCommandMetric label="Docs pending" value={visibleRows.filter((row) => row.status === "Documents pending").length} tone={visibleRows.some((row) => row.status === "Documents pending") ? "warning" : "success"} />
          <DashboardCommandMetric label="SLA breach" value={visibleRows.filter((row) => remoteConsultSlaBreached(row)).length} tone={visibleRows.some(remoteConsultSlaBreached) ? "danger" : "success"} />
          <DashboardCommandMetric label="Advice sent" value={visibleRows.filter((row) => row.status === "Advice sent").length} tone="success" />
        </div>

        <div className="grid items-end gap-3 p-3 md:grid-cols-2 xl:grid-cols-[minmax(260px,1.4fr)_repeat(5,minmax(135px,1fr))_minmax(112px,0.7fr)]">
          <label className="space-y-1 text-sm">
            <span className="block text-xs font-semibold text-slate-700">Search consultation</span>
            <span className="relative block">
              <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
              <Input className="h-10 pl-9" placeholder="Patient, specialty, doctor, document..." value={search} onChange={(event) => setSearch(event.target.value)} />
            </span>
          </label>
          <NativeSelect label="Specialty" value={specialty} onChange={setSpecialty} options={specialtyOptions} />
          <NativeSelect label="Status" value={status} onChange={setStatus} options={["All status", "Requested", "Accepted", "Documents pending", "Scheduled", "In review", "Advice sent", "Follow-up assigned", "Closed"]} />
          <NativeSelect label="Priority" value={priority} onChange={setPriority} options={["All priority", "Critical", "High", "Medium", "Routine"]} />
          <NativeSelect label="Remote doctor" value={doctor} onChange={setDoctor} options={doctorOptions} />
          <NativeSelect label="Readiness" value={readiness} onChange={setReadiness} options={["All readiness", "Ready", "Partial", "Missing documents"]} />
          <Button className="h-10" variant="outline" onClick={resetFilters}><RefreshCcw className="h-4 w-4" />Reset</Button>
        </div>
      </CollapsibleCommandPanel>

      <RemoteConsultationMatrix rows={visibleRows} onAction={setActiveAction} onCell={setActiveCell} />

      <RemoteConsultationCellDialog cell={activeCell} onOpenChange={(open) => !open && setActiveCell(null)} />
      <RemoteConsultationActionDialog action={activeAction} onConfirm={applyConsultAction} onOpenChange={(open) => !open && setActiveAction(null)} />
    </div>
  );
}

type RemoteConsultationStatus = "Requested" | "Accepted" | "Documents pending" | "Scheduled" | "In review" | "Advice sent" | "Follow-up assigned" | "Closed";
type RemoteConsultationActionKind = "accept" | "start-review" | "request-documents" | "send-advice" | "assign-follow-up";
type RemoteConsultationCellKind = "specialty" | "readiness" | "documents" | "vitals" | "remote-doctor" | "sla" | "status";

type RemoteConsultationRow = {
  id: string;
  patientId: string;
  bedNo: string;
  patientName: string;
  mrn: string;
  ageGender: string;
  unit: string;
  diagnosis: string;
  specialty: string;
  requestedBy: string;
  remoteDoctor: string;
  reason: string;
  documents: string;
  missingDocuments: string[];
  priority: RemoteCommandPriority;
  status: RemoteConsultationStatus;
  readinessScore: number;
  waitingMinutes: number;
  slaMinutes: number;
  followUp: string;
  recommendation: string;
  lastAction: string;
};

type RemoteConsultationActiveAction = {
  row: RemoteConsultationRow;
  kind: RemoteConsultationActionKind;
};

type RemoteConsultationCellAction = {
  row: RemoteConsultationRow;
  kind: RemoteConsultationCellKind;
};

function RemoteConsultationMatrix({
  onAction,
  onCell,
  rows,
}: {
  rows: RemoteConsultationRow[];
  onAction: (action: RemoteConsultationActiveAction) => void;
  onCell: (action: RemoteConsultationCellAction) => void;
}) {
  const pagination = useIcuCommandPagination(rows);
  const columns = ["Specialty", "Readiness", "Documents", "Vitals", "Remote MD", "SLA", "Status", "Action"];
  return (
    <div className="overflow-hidden rounded-sm border border-slate-300 bg-white shadow-sm">
      <div className="flex flex-col gap-2 border-b border-slate-200 bg-white px-3 py-2 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <p className="text-sm font-bold text-slate-950">Remote consultation matrix</p>
        </div>
        <IcuLegend />
      </div>
      <div className="max-h-[660px] overflow-auto">
        <table className="w-full min-w-[1360px] border-collapse bg-white text-sm">
          <thead className="sticky top-0 z-20">
            <tr className="border-b border-slate-300 bg-white text-[11px] uppercase text-sky-700">
              <th className="sticky left-0 z-40 min-w-[220px] bg-white px-3 py-3 text-left">Patient</th>
              <th className="min-w-[220px] px-3 py-3 text-left">Consult reason</th>
              {columns.map((column) => <th className="min-w-[120px] px-3 py-3 text-center" key={column}>{column}</th>)}
            </tr>
          </thead>
          <tbody>
            {pagination.pageRows.map((row) => (
              <tr className="border-b border-slate-200 last:border-b-0 hover:bg-sky-50/40" key={row.id}>
                <td className="sticky left-0 z-10 bg-white px-3 py-2 align-middle shadow-[8px_0_14px_-15px_rgba(15,23,42,0.45)]">
                  <RemoteConsultPatientCell row={row} />
                </td>
                <td className="px-4 py-2 align-middle">
                  <div className="min-h-14">
                    <p className="text-sm font-semibold text-slate-900">{row.reason}</p>
                  </div>
                </td>
                <td className="px-2 py-2 align-middle text-center"><RemoteMatrixCell icon={Stethoscope} title={row.specialty} detail={row.requestedBy} tone={remoteConsultSpecialtyTone(row.specialty)} onClick={() => onCell({ row, kind: "specialty" })} /></td>
                <td className="px-2 py-2 align-middle text-center"><RemoteMatrixCell href={teleIcuScenarioHref("readiness", row.patientId)} icon={ClipboardCheck} title={`${row.readinessScore}%`} detail={remoteConsultReadinessLabel(row)} tone={remoteConsultReadinessTone(row)} /></td>
                <td className="px-2 py-2 align-middle text-center"><RemoteMatrixCell href={icuPatientDetailHref(row.patientId, "results")} icon={FileText} title={row.missingDocuments.length ? `${row.missingDocuments.length} due` : "Ready"} detail={row.documents} tone={row.missingDocuments.length ? "warning" : "success"} /></td>
                <td className="px-2 py-2 align-middle text-center"><RemoteMatrixCell href={icuPatientDetailHref(row.patientId, "monitoring", "24h-chart")} icon={HeartPulse} title={remoteConsultLatestVitals(row.patientId)} detail="Latest vitals" tone={row.priority === "Critical" ? "danger" : "success"} /></td>
                <td className="px-2 py-2 align-middle text-center"><RemoteCircleCell href={teleIcuScenarioHref("remote-md", row.patientId)} icon={UserRound} title={row.remoteDoctor} detail={row.followUp} tone="info" /></td>
                <td className="px-2 py-2 align-middle text-center"><RemoteMatrixCell href={teleIcuScenarioHref("sla", row.patientId)} icon={Clock3} title={remoteConsultSlaLabel(row)} detail={`${row.waitingMinutes} min wait`} tone={remoteConsultSlaTone(row)} /></td>
                <td className="px-2 py-2 align-middle text-center"><RemoteCircleCell icon={CheckCircle2} title={row.status} detail={row.lastAction} tone={remoteConsultStatusTone(row.status)} onClick={() => onCell({ row, kind: "status" })} /></td>
                <td className="min-w-[280px] px-3 py-2 align-middle"><RemoteConsultActionButtons row={row} onAction={onAction} /></td>
              </tr>
            ))}
            {!rows.length ? (
              <tr>
                <td className="px-4 py-10 text-center text-sm text-slate-500" colSpan={columns.length + 2}>No remote consultation matched the selected filters.</td>
              </tr>
            ) : null}
          </tbody>
        </table>
      </div>
      <IcuCommandPaginationControls {...pagination} />
    </div>
  );
}

function RemoteConsultPatientCell({ row }: { row: RemoteConsultationRow }) {
  const tone = remotePriorityTone(row.priority);
  return (
    <Link
      className="block min-h-16 w-full rounded-md border border-transparent bg-white px-3 py-2 text-left transition hover:-translate-y-0.5 hover:border-sky-300 hover:shadow-sm"
      href={icuPatientDetailHref(row.patientId, "overview")}
      title={`Open patient profile for ${row.patientName}`}
    >
      <p className={cn("truncate text-sm font-bold", dashboardToneTextClass(tone))}>{row.patientName}</p>
      <p className="mt-1 truncate text-xs font-semibold text-slate-700">{row.bedNo} | {row.unit}</p>
      <p className="mt-0.5 truncate text-xs text-slate-500">{row.mrn} | {row.ageGender}</p>
    </Link>
  );
}

function RemoteConsultActionButtons({ row, onAction }: { row: RemoteConsultationRow; onAction: (action: RemoteConsultationActiveAction) => void }) {
  const closed = row.status === "Closed";
  return (
    <div className="flex items-center justify-center gap-1.5">
      <Button className="h-8 px-2 text-xs" disabled={closed || row.status !== "Requested"} size="sm" variant="outline" onClick={() => onAction({ row, kind: "accept" })}>Accept</Button>
      <Button className="h-8 px-2 text-xs" disabled={closed || row.status === "In review"} size="sm" variant="outline" onClick={() => onAction({ row, kind: row.missingDocuments.length ? "request-documents" : "start-review" })}>{row.missingDocuments.length ? "Docs" : "Start"}</Button>
      <Button className="h-8 px-2 text-xs" disabled={closed} size="sm" onClick={() => onAction({ row, kind: "send-advice" })}>Advice</Button>
      <Button className="h-8 px-2 text-xs" disabled={closed} size="sm" variant="outline" onClick={() => onAction({ row, kind: "assign-follow-up" })}>Follow-up</Button>
    </div>
  );
}

function RemoteConsultationCellDialog({ cell, onOpenChange }: { cell: RemoteConsultationCellAction | null; onOpenChange: (open: boolean) => void }) {
  return (
    <Dialog.Root open={Boolean(cell)} onOpenChange={onOpenChange}>
      {cell ? <RemoteConsultationCellDialogContent key={`${cell.row.id}-${cell.kind}`} cell={cell} /> : null}
    </Dialog.Root>
  );
}

function RemoteConsultationCellDialogContent({ cell }: { cell: RemoteConsultationCellAction }) {
  const rows = remoteConsultCellRows(cell);
  const checklist = remoteConsultCellChecklist(cell);
  const tone = remoteConsultCellTone(cell);

  return (
    <Dialog.Portal>
      <Dialog.Overlay className="fixed inset-0 z-50 bg-black/45 backdrop-blur-[1px]" />
      <Dialog.Content className="fixed left-1/2 top-1/2 z-50 flex max-h-[90dvh] w-[min(860px,calc(100vw-24px))] -translate-x-1/2 -translate-y-1/2 flex-col overflow-hidden rounded-xl border border-slate-300 bg-white shadow-2xl outline-none">
        <div className={cn("border-b border-slate-200 px-4 py-3 text-white", dashboardToneSolidClass(tone))}>
          <div className="flex items-start justify-between gap-3">
            <div>
              <Dialog.Title className="text-base font-bold">{remoteConsultCellTitle(cell.kind)}</Dialog.Title>
              <Dialog.Description className="mt-1 text-xs text-white/85">{cell.row.bedNo} - {cell.row.patientName} | {cell.row.specialty}</Dialog.Description>
            </div>
            <Dialog.Close asChild>
              <Button className="border-white/30 bg-white/10 text-white hover:bg-white/20" size="sm" variant="outline"><X className="h-4 w-4" />Close</Button>
            </Dialog.Close>
          </div>
        </div>

        <div className="flex-1 space-y-4 overflow-y-auto p-4">
          <div className="grid gap-3 lg:grid-cols-[minmax(0,1fr)_300px]">
            <InfoPanel title={remoteConsultCellInfoTitle(cell.kind)} rows={rows} />
            <div className={cn("rounded-md border p-3", dashboardToneSurfaceClass(tone))}>
              <p className="text-sm font-bold">Current decision</p>
              <p className="mt-2 text-xs leading-relaxed">{remoteConsultCellDecision(cell)}</p>
              <div className="mt-3 flex flex-wrap gap-2">
                <Badge tone={remoteConsultBadgeTone(remotePriorityTone(cell.row.priority))}>{cell.row.priority}</Badge>
                <Badge tone={remoteConsultBadgeTone(remoteConsultStatusTone(cell.row.status))}>{cell.row.status}</Badge>
                <Badge tone={remoteConsultBadgeTone(remoteConsultSlaTone(cell.row))}>{remoteConsultSlaLabel(cell.row)}</Badge>
              </div>
            </div>
          </div>

          <div className="rounded-md border border-slate-200 bg-slate-50 p-3">
            <p className="text-sm font-bold text-slate-950">{remoteConsultCellChecklistTitle(cell.kind)}</p>
            <div className="mt-3 grid gap-2 md:grid-cols-2">
              {checklist.map((item) => (
                <div className="flex items-center gap-2 rounded-md border border-slate-200 bg-white px-3 py-2 text-xs font-semibold text-slate-700" key={item}>
                  <CheckCircle2 className="h-4 w-4 text-emerald-600" />
                  {item}
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className="flex justify-end border-t border-slate-200 bg-slate-50 px-4 py-3">
          <Dialog.Close asChild>
            <Button>Done</Button>
          </Dialog.Close>
        </div>
      </Dialog.Content>
    </Dialog.Portal>
  );
}

function RemoteConsultationActionDialog({
  action,
  onConfirm,
  onOpenChange,
}: {
  action: RemoteConsultationActiveAction | null;
  onConfirm: (action: RemoteConsultationActiveAction, note: string) => void;
  onOpenChange: (open: boolean) => void;
}) {
  return (
    <Dialog.Root open={Boolean(action)} onOpenChange={onOpenChange}>
      {action ? <RemoteConsultationActionDialogContent key={`${action.row.id}-${action.kind}`} action={action} onConfirm={onConfirm} /> : null}
    </Dialog.Root>
  );
}

function RemoteConsultationActionDialogContent({ action, onConfirm }: { action: RemoteConsultationActiveAction; onConfirm: (action: RemoteConsultationActiveAction, note: string) => void }) {
  const [note, setNote] = React.useState(remoteConsultDefaultActionNote(action));
  const [nextStep, setNextStep] = React.useState(action.kind === "request-documents" ? "After document upload" : action.row.followUp);
  const [patientContext, setPatientContext] = React.useState(true);
  const [documentsChecked, setDocumentsChecked] = React.useState(!action.row.missingDocuments.length);
  const [localOwnerMapped, setLocalOwnerMapped] = React.useState(true);
  const canConfirm = patientContext && localOwnerMapped && (documentsChecked || action.kind === "request-documents");

  return (
    <Dialog.Portal>
      <Dialog.Overlay className="fixed inset-0 z-50 bg-black/45 backdrop-blur-[1px]" />
      <Dialog.Content className="fixed left-1/2 top-1/2 z-50 flex max-h-[92dvh] w-[min(900px,calc(100vw-24px))] -translate-x-1/2 -translate-y-1/2 flex-col overflow-hidden rounded-xl border border-slate-300 bg-white shadow-2xl outline-none">
        <div className="border-b border-slate-200 bg-sky-700 px-4 py-3 text-white">
          <div className="flex items-start justify-between gap-3">
            <div>
              <Dialog.Title className="text-base font-bold">{remoteConsultActionLabel(action.kind)}</Dialog.Title>
              <Dialog.Description className="mt-1 text-xs text-sky-50">{action.row.bedNo} - {action.row.patientName} | {action.row.specialty}</Dialog.Description>
            </div>
            <Dialog.Close asChild>
              <Button className="border-white/30 bg-white/10 text-white hover:bg-white/20" size="sm" variant="outline"><X className="h-4 w-4" />Close</Button>
            </Dialog.Close>
          </div>
        </div>

        <div className="flex-1 space-y-4 overflow-y-auto p-4">
          <div className="grid gap-3 lg:grid-cols-2">
            <InfoPanel title="Patient context" rows={[
              ["Patient", `${action.row.patientName} (${action.row.ageGender})`],
              ["Diagnosis", action.row.diagnosis],
              ["Reason", action.row.reason],
              ["Latest vitals", remoteConsultLatestVitals(action.row.patientId)],
              ["Documents", action.row.documents],
            ]} />
            <InfoPanel title="Consult workflow" rows={[
              ["Specialty", action.row.specialty],
              ["Requested by", action.row.requestedBy],
              ["Remote doctor", action.row.remoteDoctor],
              ["Status", action.row.status],
              ["SLA", `${remoteConsultSlaLabel(action.row)} / waiting ${action.row.waitingMinutes} min`],
            ]} />
          </div>

          <div className="rounded-md border border-slate-200 bg-slate-50 p-3">
            <div className="grid gap-3 md:grid-cols-2">
              <NativeSelect label="Next step" value={nextStep} onChange={setNextStep} options={["Next 15 min", "Next 30 min", "After document upload", "After video review", "Next round", "Follow-up task assigned", "Close after acknowledgement"]} />
              <NativeSelect label="Action" value={remoteConsultActionLabel(action.kind)} onChange={() => undefined} options={[remoteConsultActionLabel(action.kind)]} />
            </div>
            <label className="mt-3 block space-y-1 text-sm">
              <span className="font-semibold text-slate-800">Consult note / advice</span>
              <textarea className="min-h-28 w-full rounded-md border border-slate-300 bg-white p-3 text-sm outline-none focus:ring-2 focus:ring-sky-200" value={note} onChange={(event) => setNote(event.target.value)} />
            </label>
          </div>

          <div className="grid gap-2 md:grid-cols-3">
            <label className="flex items-center gap-2 rounded-md border border-slate-200 bg-white px-3 py-2 text-sm">
              <input checked={patientContext} className="h-4 w-4 rounded border-slate-300" type="checkbox" onChange={(event) => setPatientContext(event.target.checked)} />
              <span className="font-semibold text-slate-800">Patient context checked</span>
            </label>
            <label className="flex items-center gap-2 rounded-md border border-slate-200 bg-white px-3 py-2 text-sm">
              <input checked={documentsChecked} className="h-4 w-4 rounded border-slate-300" type="checkbox" onChange={(event) => setDocumentsChecked(event.target.checked)} />
              <span className="font-semibold text-slate-800">Documents checked</span>
            </label>
            <label className="flex items-center gap-2 rounded-md border border-slate-200 bg-white px-3 py-2 text-sm">
              <input checked={localOwnerMapped} className="h-4 w-4 rounded border-slate-300" type="checkbox" onChange={(event) => setLocalOwnerMapped(event.target.checked)} />
              <span className="font-semibold text-slate-800">Local owner mapped</span>
            </label>
          </div>
        </div>

        <div className="flex flex-wrap justify-end gap-2 border-t border-slate-200 bg-slate-50 px-4 py-3">
          <Dialog.Close asChild>
            <Button variant="outline">Cancel</Button>
          </Dialog.Close>
          <Button disabled={!canConfirm} onClick={() => onConfirm(action, `${note} | ${nextStep}`)}>
            <CheckCircle2 className="h-4 w-4" />Confirm action
          </Button>
        </div>
      </Dialog.Content>
    </Dialog.Portal>
  );
}

function buildRemoteConsultationRows(): RemoteConsultationRow[] {
  const configs: Record<string, Pick<RemoteConsultationRow, "specialty" | "reason" | "documents" | "missingDocuments" | "status" | "remoteDoctor" | "followUp" | "waitingMinutes">> = {
    "icu-001": { specialty: "Critical care", reason: "Persistent hypotension and sepsis shock watch", documents: "Vitals, lactate, cultures", missingDocuments: [], status: "In review", remoteDoctor: "Dr. Leena Rao", followUp: "Next 15 min", waitingMinutes: 12 },
    "icu-002": { specialty: "Cardiology", reason: "Post CABG rhythm and ABG review", documents: "ECG, ABG", missingDocuments: [], status: "Accepted", remoteDoctor: "Dr. Vikram Nair", followUp: "Next round", waitingMinutes: 18 },
    "icu-003": { specialty: "Neurology", reason: "Low GCS observation and CT report review", documents: "CT pending", missingDocuments: ["CT report"], status: "Documents pending", remoteDoctor: "Dr. Leena Rao", followUp: "04:00 PM", waitingMinutes: 38 },
    "icu-004": { specialty: "Endocrinology", reason: "DKA electrolyte and insulin transition review", documents: "Electrolytes, glucose chart", missingDocuments: [], status: "Scheduled", remoteDoctor: "Dr. Farah Siddiqui", followUp: "Today 05:00 PM", waitingMinutes: 28 },
    "icu-005": { specialty: "Transplant", reason: "Tacrolimus, renal output, and infection watch", documents: "I/O, creatinine, tacrolimus pending", missingDocuments: ["Tacrolimus level"], status: "Documents pending", remoteDoctor: "Dr. Nitin Suri", followUp: "After report upload", waitingMinutes: 26 },
    "icu-006": { specialty: "Respiratory", reason: "NIV tolerance, CO2 watch, and ABG repeat", documents: "ABG, vitals, NIV chart", missingDocuments: [], status: "Requested", remoteDoctor: "Dr. Vikram Nair", followUp: "Next 15 min", waitingMinutes: 9 },
  };

  return icuPatients.map((patient) => {
    const config = configs[patient.id] ?? { specialty: "Critical care", reason: "Remote ICU consultation", documents: "Vitals attached", missingDocuments: [], status: "Requested" as RemoteConsultationStatus, remoteDoctor: "Dr. Leena Rao", followUp: "Next 30 min", waitingMinutes: 20 };
    const priority = remotePriorityFromPatient(patient, icuAlerts.filter((row) => row.patientId === patient.id && row.status !== "Resolved").length, icuTasks.filter((row) => row.patientId === patient.id && row.status !== "Completed").length);
    const readinessScore = remoteConsultReadinessScore(patient, config.missingDocuments.length, Boolean([...icuVitals].reverse().find((row) => row.patientId === patient.id)));
    return {
      id: `consult-${patient.id}`,
      patientId: patient.id,
      bedNo: patient.bedNo,
      patientName: patient.patientName,
      mrn: patient.mrn,
      ageGender: patient.ageGender,
      unit: patient.unit,
      diagnosis: patient.diagnosis,
      requestedBy: patient.dutyDoctor,
      priority,
      slaMinutes: priority === "Critical" ? 15 : priority === "High" ? 30 : priority === "Medium" ? 60 : 120,
      readinessScore,
      recommendation: remoteConsultRecommendation(patient, config.specialty),
      lastAction: config.status === "In review" ? "Remote review started" : config.status === "Documents pending" ? "Awaiting document upload" : "Awaiting consult action",
      ...config,
    };
  });
}

function remoteConsultationSort(left: RemoteConsultationRow, right: RemoteConsultationRow) {
  return remoteConsultRank(right) - remoteConsultRank(left);
}

function remoteConsultRank(row: RemoteConsultationRow) {
  const priority: Record<RemoteCommandPriority, number> = { Critical: 80, High: 60, Medium: 35, Routine: 15 };
  const status: Record<RemoteConsultationStatus, number> = {
    "Documents pending": 45,
    Requested: 40,
    Accepted: 34,
    "In review": 30,
    Scheduled: 24,
    "Follow-up assigned": 18,
    "Advice sent": 12,
    Closed: 0,
  };
  return priority[row.priority] + status[row.status] + (remoteConsultSlaBreached(row) ? 20 : 0) + (row.missingDocuments.length ? 8 : 0);
}

function remoteConsultReadinessScore(patient: { pendingTasks: number; criticalityScore: number }, missingCount: number, hasVitals: boolean) {
  let score = 96 - missingCount * 18 - patient.pendingTasks * 2 - Math.max(0, patient.criticalityScore - 7) * 2;
  if (!hasVitals) score -= 15;
  return Math.max(45, Math.min(99, score));
}

function remoteConsultLatestVitals(patientId: string) {
  const latest = [...icuVitals].reverse().find((row) => row.patientId === patientId);
  return latest ? `SpO2 ${latest.spo2}%` : "Vitals pending";
}

function remoteConsultReadinessLabel(row: RemoteConsultationRow) {
  if (row.readinessScore >= 85) return "Ready";
  if (row.readinessScore >= 70) return "Partial";
  return "Missing docs";
}

function remoteConsultReadinessTone(row: RemoteConsultationRow): DashboardCellTone {
  if (row.readinessScore >= 85) return "success";
  if (row.readinessScore >= 70) return "warning";
  return "danger";
}

function remoteConsultStatusTone(status: RemoteConsultationStatus): DashboardCellTone {
  if (status === "Documents pending") return "warning";
  if (status === "Requested" || status === "Accepted" || status === "In review" || status === "Scheduled") return "info";
  if (status === "Advice sent" || status === "Follow-up assigned" || status === "Closed") return "success";
  return "muted";
}

function remoteConsultSpecialtyTone(specialty: string): DashboardCellTone {
  const lower = specialty.toLowerCase();
  if (lower.includes("critical")) return "critical";
  if (lower.includes("respiratory")) return "purple";
  if (lower.includes("cardio")) return "danger";
  if (lower.includes("neuro")) return "info";
  if (lower.includes("transplant")) return "warning";
  return "success";
}

function remoteConsultSlaBreached(row: RemoteConsultationRow) {
  return !["Closed", "Advice sent", "Follow-up assigned"].includes(row.status) && row.waitingMinutes > row.slaMinutes;
}

function remoteConsultSlaTone(row: RemoteConsultationRow): DashboardCellTone {
  if (remoteConsultSlaBreached(row)) return "danger";
  const remaining = row.slaMinutes - row.waitingMinutes;
  if (remaining <= 5) return "warning";
  return "success";
}

function remoteConsultSlaLabel(row: RemoteConsultationRow) {
  const remaining = row.slaMinutes - row.waitingMinutes;
  if (remaining < 0) return `${Math.abs(remaining)} min breach`;
  return `${remaining} min left`;
}

function remoteConsultActionLabel(kind: RemoteConsultationActionKind) {
  if (kind === "accept") return "Accept consultation";
  if (kind === "start-review") return "Start review";
  if (kind === "request-documents") return "Request documents";
  if (kind === "send-advice") return "Send advice";
  return "Assign follow-up";
}

function remoteConsultStatusAfterAction(kind: RemoteConsultationActionKind): RemoteConsultationStatus {
  if (kind === "accept") return "Accepted";
  if (kind === "start-review") return "In review";
  if (kind === "request-documents") return "Documents pending";
  if (kind === "send-advice") return "Advice sent";
  return "Follow-up assigned";
}

function remoteConsultDefaultActionNote(action: RemoteConsultationActiveAction) {
  if (action.kind === "request-documents") return `Please upload ${action.row.missingDocuments.join(", ") || "pending reports"} before remote consultant final advice.`;
  if (action.kind === "send-advice") return action.row.recommendation;
  if (action.kind === "assign-follow-up") return `Assign local follow-up for ${action.row.specialty}: ${action.row.followUp}.`;
  if (action.kind === "accept") return `${action.row.specialty} consultation accepted by ${action.row.remoteDoctor}.`;
  return `Review ${action.row.reason}. Check patient context, documents, latest vitals, medication, and local plan.`;
}

function remoteConsultCellTitle(kind: RemoteConsultationCellKind) {
  if (kind === "specialty") return "Specialty consult detail";
  if (kind === "readiness") return "Consult readiness detail";
  if (kind === "documents") return "Clinical documents detail";
  if (kind === "vitals") return "Vitals snapshot";
  if (kind === "remote-doctor") return "Remote doctor ownership";
  if (kind === "sla") return "SLA and timing detail";
  return "Consult status timeline";
}

function remoteConsultCellInfoTitle(kind: RemoteConsultationCellKind) {
  if (kind === "specialty") return "Specialty routing";
  if (kind === "readiness") return "Readiness score";
  if (kind === "documents") return "Document bundle";
  if (kind === "vitals") return "Clinical snapshot";
  if (kind === "remote-doctor") return "Owner mapping";
  if (kind === "sla") return "Timing and escalation";
  return "Status and audit";
}

function remoteConsultCellRows(cell: RemoteConsultationCellAction): Array<[string, string]> {
  const row = cell.row;
  if (cell.kind === "specialty") {
    return [
      ["Specialty", row.specialty],
      ["Consult reason", row.reason],
      ["Requested by", row.requestedBy],
      ["Remote doctor", row.remoteDoctor],
      ["Suggested advice", row.recommendation],
    ];
  }
  if (cell.kind === "readiness") {
    return [
      ["Readiness", `${row.readinessScore}% (${remoteConsultReadinessLabel(row)})`],
      ["Patient context", `${row.bedNo} - ${row.patientName}`],
      ["Vitals", remoteConsultLatestVitals(row.patientId)],
      ["Documents", row.missingDocuments.length ? `Missing: ${row.missingDocuments.join(", ")}` : "All required documents ready"],
      ["Follow-up", row.followUp],
    ];
  }
  if (cell.kind === "documents") {
    return [
      ["Attached", row.documents],
      ["Missing", row.missingDocuments.length ? row.missingDocuments.join(", ") : "None"],
      ["Required for", row.specialty],
      ["Current status", row.status],
      ["Requested by", row.requestedBy],
    ];
  }
  if (cell.kind === "vitals") {
    const latest = [...icuVitals].reverse().find((item) => item.patientId === row.patientId);
    return [
      ["Latest vitals", latest ? `SpO2 ${latest.spo2}%, BP ${latest.bp}, Pulse ${latest.pulse}` : "Vitals pending"],
      ["Respiratory", latest ? `${latest.respiratoryRate}/min, ${latest.oxygenFlow}` : "Not available"],
      ["Neuro / pain", latest ? `GCS ${latest.gcs}, Pain ${latest.painScore}/10` : "Not available"],
      ["Urine output", latest ? `${latest.urineOutput} ml/hr` : "Not available"],
      ["Note", latest?.note ?? row.reason],
    ];
  }
  if (cell.kind === "remote-doctor") {
    return [
      ["Remote doctor", row.remoteDoctor],
      ["Local doctor", row.requestedBy],
      ["Patient unit", row.unit],
      ["Next follow-up", row.followUp],
      ["Current action", row.lastAction],
    ];
  }
  if (cell.kind === "sla") {
    return [
      ["SLA", remoteConsultSlaLabel(row)],
      ["Waiting", `${row.waitingMinutes} min`],
      ["Allowed time", `${row.slaMinutes} min`],
      ["Priority", row.priority],
      ["Escalation", remoteConsultSlaBreached(row) ? "SLA breached - escalate" : "Within SLA"],
    ];
  }
  return [
    ["Status", row.status],
    ["Last action", row.lastAction],
    ["Follow-up", row.followUp],
    ["Remote doctor", row.remoteDoctor],
    ["Documents", row.documents],
  ];
}

function remoteConsultCellChecklistTitle(kind: RemoteConsultationCellKind) {
  if (kind === "specialty") return "Before specialty review";
  if (kind === "readiness") return "Readiness checklist";
  if (kind === "documents") return "Document checklist";
  if (kind === "vitals") return "Vitals review checklist";
  if (kind === "remote-doctor") return "Ownership checklist";
  if (kind === "sla") return "SLA checklist";
  return "Status checklist";
}

function remoteConsultCellChecklist(cell: RemoteConsultationCellAction) {
  if (cell.kind === "specialty") return ["Correct specialty selected", "Patient diagnosis matches consult reason", "Remote doctor mapped", "Local doctor available", "Expected advice category clear"];
  if (cell.kind === "readiness") return ["Patient context complete", "Latest vitals available", "Documents attached", "Video/local team readiness checked", "Missing items assigned"];
  if (cell.kind === "documents") return ["Vitals sheet attached", "Lab/radiology reports checked", "Medication chart available", "Doctor note available", "Missing document owner assigned"];
  if (cell.kind === "vitals") return ["Abnormal values highlighted", "Trend compared with previous entry", "Oxygen/ventilator support reviewed", "Urine output reviewed", "Escalation criteria checked"];
  if (cell.kind === "remote-doctor") return ["Remote doctor assigned", "Local doctor owner visible", "Ward nurse contact visible", "Next review time agreed", "Advice acknowledgement path clear"];
  if (cell.kind === "sla") return ["Priority-based SLA checked", "Waiting time reviewed", "Breach reason documented", "Escalation owner assigned", "Next action time visible"];
  return ["Current status verified", "Last action reviewed", "Pending document/action checked", "Follow-up owner mapped", "Closure criteria clear"];
}

function remoteConsultCellDecision(cell: RemoteConsultationCellAction) {
  const row = cell.row;
  if (cell.kind === "specialty") return `${row.specialty} review is for ${row.reason}. Keep ${row.remoteDoctor} and ${row.requestedBy} mapped before advice is sent.`;
  if (cell.kind === "readiness") return row.readinessScore >= 85 ? "Consult is ready for remote review." : "Consult needs missing context before final advice.";
  if (cell.kind === "documents") return row.missingDocuments.length ? `Request ${row.missingDocuments.join(", ")} before closure.` : "Document bundle is ready for consultant review.";
  if (cell.kind === "vitals") return `Latest clinical trend should be reviewed before ${row.specialty} advice is finalized.`;
  if (cell.kind === "remote-doctor") return `${row.remoteDoctor} owns the remote recommendation; ${row.requestedBy} remains local clinical owner.`;
  if (cell.kind === "sla") return remoteConsultSlaBreached(row) ? "This consult has crossed SLA and should be escalated or reviewed immediately." : "This consult is currently within SLA.";
  return `Current workflow status is ${row.status}. Last action: ${row.lastAction}.`;
}

function remoteConsultCellTone(cell: RemoteConsultationCellAction): DashboardCellTone {
  if (cell.kind === "specialty") return remoteConsultSpecialtyTone(cell.row.specialty);
  if (cell.kind === "readiness") return remoteConsultReadinessTone(cell.row);
  if (cell.kind === "documents") return cell.row.missingDocuments.length ? "warning" : "success";
  if (cell.kind === "vitals") return cell.row.priority === "Critical" ? "danger" : "success";
  if (cell.kind === "sla") return remoteConsultSlaTone(cell.row);
  if (cell.kind === "status") return remoteConsultStatusTone(cell.row.status);
  return "info";
}

function remoteConsultBadgeTone(tone: DashboardCellTone): StatusTone {
  if (tone === "purple") return "info";
  return tone;
}

function remoteConsultRecommendation(patient: { unit: string; ventilatorStatus: string; currentStatus: string }, specialty: string) {
  if (specialty === "Respiratory") return "Review ABG, NIV tolerance, target SpO2, suction need, and escalation trigger.";
  if (specialty === "Transplant") return "Review tacrolimus level, strict I/O, creatinine trend, infection prevention, and renal dosing.";
  if (specialty === "Neurology") return "Continue GCS/pupil charting, aspiration precautions, CT/report follow-up, and seizure watch.";
  if (specialty === "Cardiology") return "Review rhythm, BP, ABG, fluids, inotropes, and post-procedure monitoring plan.";
  if (patient.ventilatorStatus !== "Room air") return "Review oxygen/ventilator support, ABG, sedation, and weaning readiness.";
  if (patient.currentStatus === "Ready for transfer") return "Confirm transfer readiness, medication, documents, and follow-up plan.";
  return "Continue ICU monitoring and document remote consultant advice.";
}

function EscalatedCasesCommand() {
  const [rows, setRows] = React.useState<EscalatedCaseRow[]>(() => buildEscalatedCaseRows());
  const [search, setSearch] = React.useState("");
  const [source, setSource] = React.useState("All sources");
  const [severity, setSeverity] = React.useState("All severity");
  const [owner, setOwner] = React.useState("All owners");
  const [status, setStatus] = React.useState("All status");
  const [sla, setSla] = React.useState("All SLA");
  const [activeCell, setActiveCell] = React.useState<EscalatedCaseCellAction | null>(null);
  const [activeAction, setActiveAction] = React.useState<EscalatedCaseAction | null>(null);

  const sourceOptions = React.useMemo(() => ["All sources", ...Array.from(new Set(rows.map((row) => row.source)))], [rows]);
  const ownerOptions = React.useMemo(() => ["All owners", ...Array.from(new Set(rows.flatMap((row) => [row.primaryOwner, ...row.ownerChain])))], [rows]);
  const visibleRows = React.useMemo(() => {
    const query = search.trim().toLowerCase();
    return rows.filter((row) => {
      const text = `${row.bedNo} ${row.patientName} ${row.mrn} ${row.unit} ${row.trigger} ${row.source} ${row.primaryOwner} ${row.ownerChain.join(" ")} ${row.currentAction} ${row.outcome}`.toLowerCase();
      const slaMatch = sla === "All SLA"
        || (sla === "Breached" && escalatedCaseSlaBreached(row))
        || (sla === "Near breach" && !escalatedCaseSlaBreached(row) && row.slaMinutes - row.waitingMinutes <= 5)
        || (sla === "Within SLA" && !escalatedCaseSlaBreached(row));
      return (!query || text.includes(query))
        && (source === "All sources" || row.source === source)
        && (severity === "All severity" || row.severity === severity)
        && (owner === "All owners" || row.primaryOwner === owner || row.ownerChain.includes(owner))
        && (status === "All status" || row.status === status)
        && slaMatch;
    }).sort(escalatedCaseSort);
  }, [owner, rows, search, severity, sla, source, status]);

  const resetFilters = () => {
    setSearch("");
    setSource("All sources");
    setSeverity("All severity");
    setOwner("All owners");
    setStatus("All status");
    setSla("All SLA");
  };

  const applyAction = (action: EscalatedCaseAction, note: string) => {
    const nextStatus = escalatedCaseStatusAfterAction(action.kind);
    setRows((current) => current.map((row) => (
      row.id === action.row.id
        ? {
            ...row,
            status: nextStatus,
            currentAction: escalatedCaseCurrentActionAfterAction(action, note),
            outcome: action.kind === "close" ? note || "Escalation closed after outcome verification" : row.outcome,
            lastUpdate: "Just now",
            waitingMinutes: Math.max(0, row.waitingMinutes - 4),
          }
        : row
    )));
    toast.success(`${escalatedCaseActionLabel(action.kind)} recorded for ${action.row.bedNo}`);
    setActiveAction(null);
  };

  return (
    <div className="min-w-0 max-w-full space-y-4 overflow-hidden">
      <CollapsibleCommandPanel
        summary={`${source} | ${severity} | ${status} | ${visibleRows.length} case(s)`}
        title="Escalated case metrics & filters"
      >
        <div className="grid grid-cols-2 gap-2 border-b border-slate-200 px-3 py-3 md:flex md:flex-wrap md:items-center">
          <DashboardCommandMetric label="Visible" value={visibleRows.length} tone="info" />
          <DashboardCommandMetric label="Critical" value={visibleRows.filter((row) => row.severity === "Critical").length} tone={visibleRows.some((row) => row.severity === "Critical") ? "critical" : "success"} />
          <DashboardCommandMetric label="Breached" value={visibleRows.filter(escalatedCaseSlaBreached).length} tone={visibleRows.some(escalatedCaseSlaBreached) ? "danger" : "success"} />
          <DashboardCommandMetric label="In action" value={visibleRows.filter((row) => row.status === "In action").length} tone="info" />
          <DashboardCommandMetric label="Device" value={visibleRows.filter((row) => row.source === "Device / connectivity").length} tone="warning" />
          <DashboardCommandMetric label="Closed" value={visibleRows.filter((row) => row.status === "Closed").length} tone="success" />
        </div>

        <div className="grid items-end gap-3 p-3 md:grid-cols-2 xl:grid-cols-[minmax(260px,1.4fr)_repeat(5,minmax(135px,1fr))_minmax(112px,0.7fr)]">
          <label className="space-y-1 text-sm">
            <span className="block text-xs font-semibold text-slate-700">Search escalation</span>
            <span className="relative block">
              <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
              <Input className="h-10 pl-9" placeholder="Patient, trigger, owner, source..." value={search} onChange={(event) => setSearch(event.target.value)} />
            </span>
          </label>
          <NativeSelect label="Source" value={source} onChange={setSource} options={sourceOptions} />
          <NativeSelect label="Severity" value={severity} onChange={setSeverity} options={["All severity", "Critical", "High", "Medium"]} />
          <NativeSelect label="Owner" value={owner} onChange={setOwner} options={ownerOptions} />
          <NativeSelect label="Status" value={status} onChange={setStatus} options={["All status", "New", "Acknowledged", "Assigned", "In action", "Escalated further", "Resolved", "Closed"]} />
          <NativeSelect label="SLA" value={sla} onChange={setSla} options={["All SLA", "Breached", "Near breach", "Within SLA"]} />
          <Button className="h-10" variant="outline" onClick={resetFilters}><RefreshCcw className="h-4 w-4" />Reset</Button>
        </div>
      </CollapsibleCommandPanel>

      <EscalatedCasesMatrix rows={visibleRows} onAction={setActiveAction} onCell={setActiveCell} />

      <EscalatedCaseCellDialog cell={activeCell} onOpenChange={(open) => !open && setActiveCell(null)} />
      <EscalatedCaseActionDialog action={activeAction} onConfirm={applyAction} onOpenChange={(open) => !open && setActiveAction(null)} />
    </div>
  );
}

type EscalatedCaseStatus = "New" | "Acknowledged" | "Assigned" | "In action" | "Escalated further" | "Resolved" | "Closed";
type EscalatedCaseSeverity = "Critical" | "High" | "Medium";
type EscalatedCaseActionKind = "acknowledge" | "assign" | "start" | "update" | "escalate" | "close";
type EscalatedCaseCellKind = "trigger" | "severity" | "source" | "owner" | "sla" | "action" | "outcome";

type EscalatedCaseRow = {
  id: string;
  patientId?: string;
  bedNo: string;
  patientName: string;
  mrn: string;
  ageGender: string;
  unit: string;
  trigger: string;
  source: string;
  severity: EscalatedCaseSeverity;
  status: EscalatedCaseStatus;
  primaryOwner: string;
  ownerChain: string[];
  escalatedTo: string;
  currentAction: string;
  nextStep: string;
  outcome: string;
  waitingMinutes: number;
  slaMinutes: number;
  openedAt: string;
  lastUpdate: string;
};

type EscalatedCaseAction = {
  row: EscalatedCaseRow;
  kind: EscalatedCaseActionKind;
};

type EscalatedCaseCellAction = {
  row: EscalatedCaseRow;
  kind: EscalatedCaseCellKind;
};

function EscalatedCasesMatrix({
  onAction,
  onCell,
  rows,
}: {
  rows: EscalatedCaseRow[];
  onAction: (action: EscalatedCaseAction) => void;
  onCell: (action: EscalatedCaseCellAction) => void;
}) {
  const pagination = useIcuCommandPagination(rows);
  const columns = ["Trigger", "Severity", "Source", "Owner Chain", "SLA", "Current Action", "Outcome", "Action"];
  return (
    <div className="overflow-hidden rounded-sm border border-slate-300 bg-white shadow-sm">
      <div className="flex flex-col gap-2 border-b border-slate-200 bg-white px-3 py-2 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <p className="text-sm font-bold text-slate-950">Escalated cases matrix</p>
        </div>
        <IcuLegend />
      </div>
      <div className="max-h-[660px] overflow-auto">
        <table className="w-full min-w-[1420px] border-collapse bg-white text-sm">
          <thead className="sticky top-0 z-20">
            <tr className="border-b border-slate-300 bg-white text-[11px] uppercase text-sky-700">
              <th className="sticky left-0 z-40 min-w-[220px] bg-white px-3 py-3 text-left">Patient / case</th>
              {columns.map((column) => <th className="min-w-[135px] px-3 py-3 text-center" key={column}>{column}</th>)}
            </tr>
          </thead>
          <tbody>
            {pagination.pageRows.map((row) => (
              <tr className="border-b border-slate-200 last:border-b-0 hover:bg-sky-50/40" key={row.id}>
                <td className="sticky left-0 z-10 bg-white px-3 py-2 align-middle shadow-[8px_0_14px_-15px_rgba(15,23,42,0.45)]">
                  <EscalatedCasePatientCell row={row} />
                </td>
                <td className="px-2 py-2 align-middle text-center"><RemoteMatrixCell href={escalatedCaseScenarioHref("trigger", row.id)} icon={AlertTriangle} title={row.trigger.split(" ").slice(0, 3).join(" ")} detail={row.trigger} tone={escalatedCaseSeverityTone(row.severity)} /></td>
                <td className="px-2 py-2 align-middle text-center"><RemoteMatrixCell href={escalatedCaseScenarioHref("severity", row.id)} icon={ShieldAlert} title={row.severity} detail={row.status} tone={escalatedCaseSeverityTone(row.severity)} /></td>
                <td className="px-2 py-2 align-middle text-center"><RemoteMatrixCell href={escalatedCaseScenarioHref("source", row.id)} icon={escalatedCaseSourceIcon(row.source)} title={row.source} detail={row.openedAt} tone={escalatedCaseSourceTone(row.source)} /></td>
                <td className="px-2 py-2 align-middle text-center"><RemoteMatrixCell href={escalatedCaseScenarioHref("owner-chain", row.id)} icon={UserRound} title={row.primaryOwner} detail={row.escalatedTo} tone="info" /></td>
                <td className="px-2 py-2 align-middle text-center"><RemoteMatrixCell href={escalatedCaseScenarioHref("sla", row.id)} icon={Clock3} title={escalatedCaseSlaLabel(row)} detail={`${row.waitingMinutes} min wait`} tone={escalatedCaseSlaTone(row)} /></td>
                <td className="px-2 py-2 align-middle text-center"><RemoteMatrixCell href={escalatedCaseScenarioHref("current-action", row.id)} icon={ClipboardCheck} title={row.status} detail={row.currentAction} tone={escalatedCaseStatusTone(row.status)} /></td>
                <td className="px-2 py-2 align-middle text-center"><RemoteMatrixCell href={escalatedCaseScenarioHref("outcome", row.id)} icon={CheckCircle2} title={row.outcome.includes("Pending") ? "Pending" : "Updated"} detail={row.outcome} tone={row.status === "Closed" || row.status === "Resolved" ? "success" : "warning"} /></td>
                <td className="min-w-[360px] px-3 py-2 align-middle"><EscalatedCaseActionButtons row={row} onAction={onAction} /></td>
              </tr>
            ))}
            {!rows.length ? (
              <tr>
                <td className="px-4 py-10 text-center text-sm text-slate-500" colSpan={columns.length + 1}>No escalated case matched the selected filters.</td>
              </tr>
            ) : null}
          </tbody>
        </table>
      </div>
      <IcuCommandPaginationControls {...pagination} />
    </div>
  );
}

function EscalatedCasePatientCell({ row }: { row: EscalatedCaseRow }) {
  const tone = escalatedCaseSeverityTone(row.severity);
  const content = (
    <span className="block min-h-16 w-full rounded-md border border-transparent bg-white px-3 py-2 text-left transition hover:-translate-y-0.5 hover:border-sky-300 hover:shadow-sm">
      <span className={cn("block truncate text-sm font-bold", dashboardToneTextClass(tone))}>{row.patientName}</span>
      <span className="mt-1 block truncate text-xs font-semibold text-slate-700">{row.bedNo} | {row.unit}</span>
      <span className="mt-0.5 block truncate text-xs text-slate-500">{row.mrn} | {row.ageGender}</span>
    </span>
  );

  if (!row.patientId) return content;
  return (
    <Link href={icuPatientDetailHref(row.patientId, "overview")} title={`Open patient profile for ${row.patientName}`}>
      {content}
    </Link>
  );
}

function EscalatedCaseActionButtons({ row, onAction }: { row: EscalatedCaseRow; onAction: (action: EscalatedCaseAction) => void }) {
  const closed = row.status === "Closed";
  return (
    <div className="flex items-center justify-center gap-1.5">
      <Button className="h-8 px-2 text-xs" disabled={closed || row.status !== "New"} size="sm" variant="outline" onClick={() => onAction({ row, kind: "acknowledge" })}>Ack</Button>
      <Button className="h-8 px-2 text-xs" disabled={closed || row.status === "Assigned"} size="sm" variant="outline" onClick={() => onAction({ row, kind: "assign" })}>Assign</Button>
      <Button className="h-8 px-2 text-xs" disabled={closed || row.status === "In action"} size="sm" variant="outline" onClick={() => onAction({ row, kind: "start" })}>Start</Button>
      <Button className="h-8 px-2 text-xs" disabled={closed} size="sm" onClick={() => onAction({ row, kind: "update" })}>Update</Button>
      <Button className="h-8 px-2 text-xs" disabled={closed || row.status === "Escalated further"} size="sm" variant="danger" onClick={() => onAction({ row, kind: "escalate" })}>Esc</Button>
      <Button className="h-8 px-2 text-xs" disabled={closed} size="sm" variant="outline" onClick={() => onAction({ row, kind: "close" })}>Close</Button>
    </div>
  );
}

function EscalatedCaseCellDialog({ cell, onOpenChange }: { cell: EscalatedCaseCellAction | null; onOpenChange: (open: boolean) => void }) {
  return (
    <Dialog.Root open={Boolean(cell)} onOpenChange={onOpenChange}>
      {cell ? <EscalatedCaseCellDialogContent key={`${cell.row.id}-${cell.kind}`} cell={cell} /> : null}
    </Dialog.Root>
  );
}

function EscalatedCaseCellDialogContent({ cell }: { cell: EscalatedCaseCellAction }) {
  const tone = escalatedCaseCellTone(cell);
  return (
    <Dialog.Portal>
      <Dialog.Overlay className="fixed inset-0 z-50 bg-black/45 backdrop-blur-[1px]" />
      <Dialog.Content className="fixed left-1/2 top-1/2 z-50 flex max-h-[90dvh] w-[min(860px,calc(100vw-24px))] -translate-x-1/2 -translate-y-1/2 flex-col overflow-hidden rounded-xl border border-slate-300 bg-white shadow-2xl outline-none">
        <div className={cn("border-b border-slate-200 px-4 py-3 text-white", dashboardToneSolidClass(tone))}>
          <div className="flex items-start justify-between gap-3">
            <div>
              <Dialog.Title className="text-base font-bold">{escalatedCaseCellTitle(cell.kind)}</Dialog.Title>
              <Dialog.Description className="mt-1 text-xs text-white/85">{cell.row.bedNo} - {cell.row.patientName} | {cell.row.source}</Dialog.Description>
            </div>
            <Dialog.Close asChild>
              <Button className="border-white/30 bg-white/10 text-white hover:bg-white/20" size="sm" variant="outline"><X className="h-4 w-4" />Close</Button>
            </Dialog.Close>
          </div>
        </div>

        <div className="flex-1 space-y-4 overflow-y-auto p-4">
          <div className="grid gap-3 lg:grid-cols-[minmax(0,1fr)_300px]">
            <InfoPanel title={escalatedCaseCellInfoTitle(cell.kind)} rows={escalatedCaseCellRows(cell)} />
            <div className={cn("rounded-md border p-3", dashboardToneSurfaceClass(tone))}>
              <p className="text-sm font-bold">Decision cue</p>
              <p className="mt-2 text-xs leading-relaxed">{escalatedCaseCellDecision(cell)}</p>
              <div className="mt-3 flex flex-wrap gap-2">
                <Badge tone={remoteConsultBadgeTone(escalatedCaseSeverityTone(cell.row.severity))}>{cell.row.severity}</Badge>
                <Badge tone={remoteConsultBadgeTone(escalatedCaseStatusTone(cell.row.status))}>{cell.row.status}</Badge>
                <Badge tone={remoteConsultBadgeTone(escalatedCaseSlaTone(cell.row))}>{escalatedCaseSlaLabel(cell.row)}</Badge>
              </div>
            </div>
          </div>

          <div className="rounded-md border border-slate-200 bg-slate-50 p-3">
            <p className="text-sm font-bold text-slate-950">{escalatedCaseCellChecklistTitle(cell.kind)}</p>
            <div className="mt-3 grid gap-2 md:grid-cols-2">
              {escalatedCaseCellChecklist(cell).map((item) => (
                <div className="flex items-center gap-2 rounded-md border border-slate-200 bg-white px-3 py-2 text-xs font-semibold text-slate-700" key={item}>
                  <CheckCircle2 className="h-4 w-4 text-emerald-600" />
                  {item}
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className="flex justify-end border-t border-slate-200 bg-slate-50 px-4 py-3">
          <Dialog.Close asChild>
            <Button>Done</Button>
          </Dialog.Close>
        </div>
      </Dialog.Content>
    </Dialog.Portal>
  );
}

function EscalatedCaseActionDialog({
  action,
  onConfirm,
  onOpenChange,
}: {
  action: EscalatedCaseAction | null;
  onConfirm: (action: EscalatedCaseAction, note: string) => void;
  onOpenChange: (open: boolean) => void;
}) {
  return (
    <Dialog.Root open={Boolean(action)} onOpenChange={onOpenChange}>
      {action ? <EscalatedCaseActionDialogContent key={`${action.row.id}-${action.kind}`} action={action} onConfirm={onConfirm} /> : null}
    </Dialog.Root>
  );
}

function EscalatedCaseActionDialogContent({ action, onConfirm }: { action: EscalatedCaseAction; onConfirm: (action: EscalatedCaseAction, note: string) => void }) {
  const [note, setNote] = React.useState(escalatedCaseDefaultActionNote(action));
  const [owner, setOwner] = React.useState(action.row.primaryOwner);
  const [nextReview, setNextReview] = React.useState(action.kind === "close" ? "Close after verification" : action.row.nextStep);
  const [contextChecked, setContextChecked] = React.useState(true);
  const [ownerInformed, setOwnerInformed] = React.useState(action.kind !== "assign");
  const [outcomeDocumented, setOutcomeDocumented] = React.useState(action.kind === "update" || action.kind === "close");
  const canConfirm = contextChecked && (ownerInformed || action.kind === "assign") && (outcomeDocumented || !["close", "update"].includes(action.kind));

  return (
    <Dialog.Portal>
      <Dialog.Overlay className="fixed inset-0 z-50 bg-black/45 backdrop-blur-[1px]" />
      <Dialog.Content className="fixed left-1/2 top-1/2 z-50 flex max-h-[92dvh] w-[min(900px,calc(100vw-24px))] -translate-x-1/2 -translate-y-1/2 flex-col overflow-hidden rounded-xl border border-slate-300 bg-white shadow-2xl outline-none">
        <div className="border-b border-slate-200 bg-sky-700 px-4 py-3 text-white">
          <div className="flex items-start justify-between gap-3">
            <div>
              <Dialog.Title className="text-base font-bold">{escalatedCaseActionLabel(action.kind)}</Dialog.Title>
              <Dialog.Description className="mt-1 text-xs text-sky-50">{action.row.bedNo} - {action.row.patientName} | {action.row.trigger}</Dialog.Description>
            </div>
            <Dialog.Close asChild>
              <Button className="border-white/30 bg-white/10 text-white hover:bg-white/20" size="sm" variant="outline"><X className="h-4 w-4" />Close</Button>
            </Dialog.Close>
          </div>
        </div>

        <div className="flex-1 space-y-4 overflow-y-auto p-4">
          <div className="grid gap-3 lg:grid-cols-2">
            <InfoPanel title="Case context" rows={[
              ["Patient / case", `${action.row.bedNo} - ${action.row.patientName}`],
              ["Trigger", action.row.trigger],
              ["Source", action.row.source],
              ["Severity", action.row.severity],
              ["SLA", `${escalatedCaseSlaLabel(action.row)} / waiting ${action.row.waitingMinutes} min`],
            ]} />
            <InfoPanel title="Owner and outcome" rows={[
              ["Primary owner", action.row.primaryOwner],
              ["Escalated to", action.row.escalatedTo],
              ["Current action", action.row.currentAction],
              ["Next step", action.row.nextStep],
              ["Outcome", action.row.outcome],
            ]} />
          </div>

          <div className="rounded-md border border-slate-200 bg-slate-50 p-3">
            <div className="grid gap-3 md:grid-cols-2">
              <NativeSelect label="Responsible owner" value={owner} onChange={setOwner} options={Array.from(new Set([action.row.primaryOwner, ...action.row.ownerChain, "Duty Doctor", "Remote Intensivist", "Head Nurse Sana", "Biomedical Raj", "Pharmacy", "Lab / Radiology"]))} />
              <NativeSelect label="Next review" value={nextReview} onChange={setNextReview} options={["Immediate", "Next 10 min", "Next 15 min", "Next 30 min", "After report/result", "After biomedical fix", "Close after verification"]} />
            </div>
            <label className="mt-3 block space-y-1 text-sm">
              <span className="font-semibold text-slate-800">Action / outcome note</span>
              <textarea className="min-h-28 w-full rounded-md border border-slate-300 bg-white p-3 text-sm outline-none focus:ring-2 focus:ring-sky-200" value={note} onChange={(event) => setNote(event.target.value)} />
            </label>
          </div>

          <div className="grid gap-2 md:grid-cols-3">
            <label className="flex items-center gap-2 rounded-md border border-slate-200 bg-white px-3 py-2 text-sm">
              <input checked={contextChecked} className="h-4 w-4 rounded border-slate-300" type="checkbox" onChange={(event) => setContextChecked(event.target.checked)} />
              <span className="font-semibold text-slate-800">Context reviewed</span>
            </label>
            <label className="flex items-center gap-2 rounded-md border border-slate-200 bg-white px-3 py-2 text-sm">
              <input checked={ownerInformed} className="h-4 w-4 rounded border-slate-300" type="checkbox" onChange={(event) => setOwnerInformed(event.target.checked)} />
              <span className="font-semibold text-slate-800">Owner informed</span>
            </label>
            <label className="flex items-center gap-2 rounded-md border border-slate-200 bg-white px-3 py-2 text-sm">
              <input checked={outcomeDocumented} className="h-4 w-4 rounded border-slate-300" type="checkbox" onChange={(event) => setOutcomeDocumented(event.target.checked)} />
              <span className="font-semibold text-slate-800">Outcome documented</span>
            </label>
          </div>
        </div>

        <div className="flex flex-wrap justify-end gap-2 border-t border-slate-200 bg-slate-50 px-4 py-3">
          <Dialog.Close asChild>
            <Button variant="outline">Cancel</Button>
          </Dialog.Close>
          <Button disabled={!canConfirm} onClick={() => onConfirm(action, `${note} | Owner: ${owner} | ${nextReview}`)}>
            <CheckCircle2 className="h-4 w-4" />Confirm action
          </Button>
        </div>
      </Dialog.Content>
    </Dialog.Portal>
  );
}

function EscalatedCaseScenarioCommand({ caseId, mode }: { caseId?: string; mode: EscalatedCaseScenarioMode }) {
  const allRows = React.useMemo(() => buildEscalatedCaseRows(), []);
  const selectedCase = caseId ? allRows.find((row) => row.id === caseId) : undefined;
  const rows = selectedCase ? [selectedCase] : allRows;
  const pagination = useIcuCommandPagination(rows);
  const criticalRows = rows.filter((row) => row.severity === "Critical");
  const breachedRows = rows.filter(escalatedCaseSlaBreached);
  const activeRows = rows.filter((row) => row.status === "In action" || row.status === "Escalated further");
  const ownerCount = new Set(rows.flatMap((row) => [row.primaryOwner, ...row.ownerChain])).size;

  return (
    <div className="min-w-0 max-w-full space-y-4 overflow-hidden">
      <div className="overflow-hidden rounded-md border border-slate-200 bg-white shadow-sm">
        <div className="flex flex-col gap-3 border-b border-slate-200 bg-slate-50 px-4 py-3 lg:flex-row lg:items-start lg:justify-between">
          <div>
            <p className="text-base font-black text-slate-950">{escalatedCaseScenarioTitle(mode)}</p>
            <p className="mt-1 max-w-4xl text-xs leading-5 text-slate-500">{escalatedCaseScenarioDescription(mode)}</p>
            {selectedCase ? (
              <p className="mt-2 inline-flex rounded-full border border-sky-300 bg-sky-50 px-3 py-1 text-xs font-bold text-sky-800">
                Filtered: {selectedCase.bedNo} - {selectedCase.trigger}
              </p>
            ) : null}
          </div>
          <div className="flex flex-wrap gap-2">
            <Link className="inline-flex h-9 items-center justify-center rounded-md border border-slate-300 bg-white px-3 text-sm font-semibold text-slate-700 hover:bg-slate-50" href="/icu-command-center/tele-icu/escalated-cases">Escalated Cases</Link>
            {selectedCase ? <Link className="inline-flex h-9 items-center justify-center rounded-md border border-slate-300 bg-white px-3 text-sm font-semibold text-slate-700 hover:bg-slate-50" href={escalatedCaseScenarioHref(mode)}>All cases</Link> : null}
          </div>
        </div>

        <div className="grid grid-cols-2 gap-2 px-3 py-3 md:flex md:flex-wrap md:items-center">
          <DashboardCommandMetric label="Cases" value={rows.length} tone="info" />
          <DashboardCommandMetric label="Critical" value={criticalRows.length} tone={criticalRows.length ? "critical" : "success"} />
          <DashboardCommandMetric label="SLA breach" value={breachedRows.length} tone={breachedRows.length ? "danger" : "success"} />
          <DashboardCommandMetric label="Active" value={activeRows.length} tone={activeRows.length ? "warning" : "success"} />
          <DashboardCommandMetric label="Owners" value={ownerCount} tone="info" />
          <DashboardCommandMetric label="Sources" value={new Set(rows.map((row) => row.source)).size} tone="info" />
        </div>
      </div>

      <div className="grid grid-cols-2 gap-2 md:flex md:flex-wrap">
        {(["trigger", "severity", "source", "owner-chain", "sla", "current-action", "outcome"] as EscalatedCaseScenarioMode[]).map((item) => (
          <Link
            className={cn(
              "inline-flex h-10 items-center justify-center rounded-md border px-3 text-sm font-bold transition hover:-translate-y-0.5 hover:shadow-sm",
              item === mode ? "border-sky-500 bg-sky-50 text-sky-800" : "border-slate-300 bg-white text-slate-700 hover:bg-slate-50",
            )}
            href={escalatedCaseScenarioHref(item, selectedCase?.id)}
            key={item}
          >
            {escalatedCaseScenarioShortLabel(item)}
          </Link>
        ))}
      </div>

      <TeleIcuTableShell description={escalatedCaseScenarioTableDescription(mode)} title={`${escalatedCaseScenarioShortLabel(mode)} view`}>
        <table className="w-full min-w-[1480px] border-collapse bg-white text-sm">
          <thead className="sticky top-0 z-20 bg-white text-[11px] uppercase text-sky-700">
            <tr className="border-b border-slate-300">
              {["Case", "Trigger", "Severity", "Source trace", "Owner chain", "SLA", "Current action", "Outcome", "Open"].map((column) => (
                <th className="px-3 py-3 text-left" key={column}>{column}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {pagination.pageRows.map((row) => (
              <tr className="border-b border-slate-200 last:border-b-0 hover:bg-sky-50/40" key={row.id}>
                <td className="px-3 py-3"><EscalatedCaseInlineCase row={row} /></td>
                <td className={cn("px-3 py-3 text-xs text-slate-700", mode === "trigger" && "bg-sky-50")}>
                  <p className="font-bold text-slate-950">{row.trigger}</p>
                  <p className="mt-1">{row.openedAt} | {row.lastUpdate}</p>
                </td>
                <td className={cn("px-3 py-3", mode === "severity" && "bg-sky-50")}>
                  <span className={cn("rounded-full border px-2.5 py-1 text-xs font-bold", dashboardTonePillClass(escalatedCaseSeverityTone(row.severity)))}>{row.severity}</span>
                  <p className="mt-2 text-xs text-slate-500">{row.status}</p>
                </td>
                <td className={cn("px-3 py-3", mode === "source" && "bg-sky-50")}>
                  <TeleIcuPlainLink href={escalatedCaseSourceHref(row)} label={row.source} detail="Open source module" />
                </td>
                <td className={cn("px-3 py-3 text-xs text-slate-700", mode === "owner-chain" && "bg-sky-50")}>
                  <p className="font-bold text-slate-950">{row.primaryOwner}</p>
                  <p className="mt-1">{row.ownerChain.join(" -> ")}</p>
                  <p className="mt-1 text-slate-500">Escalated to: {row.escalatedTo}</p>
                </td>
                <td className={cn("px-3 py-3", mode === "sla" && "bg-sky-50")}>
                  <TeleIcuScorePill detail={`${row.waitingMinutes}/${row.slaMinutes} min`} tone={escalatedCaseSlaTone(row)} value={escalatedCaseSlaLabel(row)} />
                </td>
                <td className={cn("px-3 py-3 text-xs text-slate-700", mode === "current-action" && "bg-sky-50")}>
                  <p className="font-bold text-slate-950">{row.status}</p>
                  <p className="mt-1">{row.currentAction}</p>
                  <p className="mt-1 text-slate-500">Next: {row.nextStep}</p>
                </td>
                <td className={cn("px-3 py-3 text-xs text-slate-700", mode === "outcome" && "bg-sky-50")}>
                  <p className="font-bold text-slate-950">{row.outcome}</p>
                  <p className="mt-1 text-slate-500">{row.status === "Closed" || row.status === "Resolved" ? "Closure evidence available" : "Closure evidence pending"}</p>
                </td>
                <td className="px-3 py-3"><EscalatedCaseOpenLinks row={row} /></td>
              </tr>
            ))}
            {!rows.length ? (
              <tr>
                <td className="px-4 py-10 text-center text-sm text-slate-500" colSpan={9}>No escalated case matched this view.</td>
              </tr>
            ) : null}
          </tbody>
        </table>
        <IcuCommandPaginationControls {...pagination} />
      </TeleIcuTableShell>
    </div>
  );
}

function EscalatedCaseInlineCase({ row }: { row: EscalatedCaseRow }) {
  const content = (
    <span className="block rounded-md border border-transparent p-1 transition hover:border-sky-300 hover:bg-sky-50">
      <span className="block text-xs font-bold text-slate-950">{row.bedNo}</span>
      <span className="mt-1 block text-sm font-bold text-slate-950">{row.patientName}</span>
      <span className="mt-1 block text-xs text-slate-500">{row.mrn} | {row.unit}</span>
    </span>
  );
  return row.patientId ? <Link href={icuPatientDetailHref(row.patientId, "overview")}>{content}</Link> : content;
}

function EscalatedCaseOpenLinks({ row }: { row: EscalatedCaseRow }) {
  return (
    <div className="flex flex-wrap gap-2">
      {row.patientId ? <Link className="rounded-md border border-slate-300 bg-white px-2.5 py-1 text-xs font-bold text-slate-700 hover:bg-slate-50" href={icuPatientDetailHref(row.patientId, "overview")}>Patient</Link> : null}
      <Link className="rounded-md border border-slate-300 bg-white px-2.5 py-1 text-xs font-bold text-slate-700 hover:bg-slate-50" href={escalatedCaseSourceHref(row)}>Source</Link>
      <Link className="rounded-md border border-slate-300 bg-white px-2.5 py-1 text-xs font-bold text-slate-700 hover:bg-slate-50" href={escalatedCaseScenarioHref("sla", row.id)}>SLA</Link>
      <Link className="rounded-md border border-slate-300 bg-white px-2.5 py-1 text-xs font-bold text-slate-700 hover:bg-slate-50" href={escalatedCaseScenarioHref("outcome", row.id)}>Outcome</Link>
    </div>
  );
}

function escalatedCaseSourceHref(row: EscalatedCaseRow) {
  const lower = row.source.toLowerCase();
  if (lower.includes("device")) return "/icu-command-center/critical-care/device-monitoring";
  if (!row.patientId) return "/icu-command-center/tele-icu/escalated-cases";
  if (lower.includes("diagnostic") || lower.includes("lab")) return icuPatientDetailHref(row.patientId, "results");
  if (lower.includes("pharmacy") || lower.includes("medication")) return icuPatientDetailHref(row.patientId, "orders", undefined, "ordersTab=medicine-chart");
  if (lower.includes("ventilator") || lower.includes("respiratory")) return icuPatientDetailHref(row.patientId, "monitoring", "ventilation");
  if (lower.includes("clinical")) return icuPatientDetailHref(row.patientId, "monitoring", "24h-chart");
  return icuPatientDetailHref(row.patientId, "events");
}

function escalatedCaseScenarioTitle(mode: EscalatedCaseScenarioMode) {
  if (mode === "trigger") return "Escalation Trigger";
  if (mode === "severity") return "Escalation Severity";
  if (mode === "source") return "Escalation Source Trace";
  if (mode === "owner-chain") return "Escalation Owner Chain";
  if (mode === "sla") return "Escalation SLA";
  if (mode === "current-action") return "Escalation Current Action";
  return "Escalation Outcome";
}

function escalatedCaseScenarioShortLabel(mode: EscalatedCaseScenarioMode) {
  if (mode === "trigger") return "Trigger";
  if (mode === "severity") return "Severity";
  if (mode === "source") return "Source";
  if (mode === "owner-chain") return "Owner Chain";
  if (mode === "sla") return "SLA";
  if (mode === "current-action") return "Current Action";
  return "Outcome";
}

function escalatedCaseScenarioDescription(mode: EscalatedCaseScenarioMode) {
  if (mode === "trigger") return "Use this view to open an escalation from the exact trigger and see patient/device context before action.";
  if (mode === "severity") return "Use this view to review criticality, patient impact, SLA pressure, and owner response based on severity.";
  if (mode === "source") return "Use this view to trace the original module: vitals, diagnostics, ventilator, pharmacy, or device connectivity.";
  if (mode === "owner-chain") return "Use this view to verify primary owner, backup owner, escalated-to team, and handoff accountability.";
  if (mode === "sla") return "Use this view to monitor waiting time, allowed time, breach status, and response governance.";
  if (mode === "current-action") return "Use this view to track the active work item, next step, owner, and update timing.";
  return "Use this view to document closure evidence, owner confirmation, and final patient/device impact review.";
}

function escalatedCaseScenarioTableDescription(mode: EscalatedCaseScenarioMode) {
  if (mode === "source") return "Source links open the existing clinical/device page wherever available.";
  if (mode === "sla") return "Breach rows should be escalated further or updated with outcome immediately.";
  if (mode === "owner-chain") return "Owner chain shows primary owner, backup path, and escalation target in one row.";
  return "Selected column is highlighted while the full escalation context remains visible.";
}

