function PatientRiskDeviceDetail({ deviceRow, row }: { deviceRow?: ReturnType<typeof getCommandDeviceRows>[number]; row: PatientRiskRow }) {
  if (!deviceRow) {
    return <div className="rounded-md border border-slate-200 border-l-amber-500 bg-white p-4 text-sm font-semibold text-slate-700 shadow-sm">No device mapping found. Risk adds +1 because bedside device signal is not mapped.</div>;
  }
  const deviceRisk = deviceRow.signal !== "Good" || deviceRow.connectivity !== "Online";
  return (
    <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_320px]">
      <TeleIcuTableShell description="Device signal and connectivity source behind Patient Risk Center." title="Device detail">
        <table className="w-full min-w-[860px] border-collapse bg-white text-sm">
          <thead className="sticky top-0 z-20 bg-white text-[11px] uppercase text-sky-700">
            <tr className="border-b border-slate-300">
              {["Device", "Value", "Status", "Risk rule"].map((column) => <th className="px-3 py-3 text-left" key={column}>{column}</th>)}
            </tr>
          </thead>
          <tbody>
            {[
              ["Monitor", deviceRow.monitor, deviceRow.connectivity, "Connectivity should be Online."],
              ["Ventilator", deviceRow.ventilator, row.ventilatorStatus, "Ventilator/O2 status is cross-checked with respiratory risk."],
              ["Pump", deviceRow.infusionPump, deviceRow.connectivity, "Pump should remain connected for infusion visibility."],
              ["Gateway", deviceRow.gateway, deviceRow.signal, "Signal should be Good. Weak/no signal adds device risk."],
              ["Last data", deviceRow.lastData, `${deviceRow.uptime}% uptime`, "Delayed data requires bedside validation."],
            ].map(([label, value, status, rule]) => (
              <tr className="border-b border-slate-200 last:border-b-0 hover:bg-sky-50/40" key={label}>
                <td className="px-3 py-3 font-bold text-slate-950">{label}</td>
                <td className="px-3 py-3 text-xs font-semibold text-slate-700">{value}</td>
                <td className="px-3 py-3 text-xs text-slate-600">{status}</td>
                <td className="px-3 py-3 text-xs leading-5 text-slate-600">{rule}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </TeleIcuTableShell>
      <InfoPanel title="Device risk summary" rows={[
        ["Signal", deviceRow.signal],
        ["Connectivity", deviceRow.connectivity],
        ["Issue", deviceRow.issue],
        ["Owner", deviceRow.owner],
        ["Risk contribution", deviceRisk ? "+1" : "+0"],
      ]} />
    </div>
  );
}

