function patientRiskDrilldownHref(row: PatientRiskRow, focus: PatientRiskDrilldownFocus) {
  return `/icu-command-center/clinical-intelligence/patient-risk-center/drilldown?patientId=${encodeURIComponent(row.patientId)}&focus=${encodeURIComponent(focus)}`;
}

function normalizePatientRiskDrilldownFocus(focus?: string): PatientRiskDrilldownFocus {
  return patientRiskDrilldownFocuses.includes(focus as PatientRiskDrilldownFocus) ? focus as PatientRiskDrilldownFocus : "score";
}

function patientRiskDrilldownLabel(focus: PatientRiskDrilldownFocus) {
  const labels: Record<PatientRiskDrilldownFocus, string> = {
    score: "Score",
    vitals: "Vitals",
    ventilation: "Ventilation",
    infection: "Infection / qSOFA",
    medication: "Medication",
    device: "Device",
    tasks: "Tasks / alerts",
  };
  return labels[focus];
}

function patientRiskDrilldownItems(row: PatientRiskRow): Array<{
  detail: string;
  focus: PatientRiskDrilldownFocus;
  label: string;
  rule: string;
  tone: DashboardCellTone;
  value: string;
  why: string;
}> {
  return [
    {
      detail: row.riskLevel,
      focus: "score",
      label: "Risk score",
      rule: "criticality + open alerts + medication risk + vitals risk + device risk + task load + urine risk",
      tone: riskLevelTone(row.riskLevel),
      value: `${row.score}`,
      why: "Composite operational score used to decide which patient needs command attention first.",
    },
    {
      detail: row.latestVitals,
      focus: "vitals",
      label: "Vitals",
      rule: "Abnormal vital flag adds +2; urine output below 30 ml/hr adds +1.",
      tone: row.abnormalVital ? "danger" : "success",
      value: row.abnormalVital ? "Abnormal" : "Stable",
      why: "Latest vitals can drive immediate review even when other modules are stable.",
    },
    {
      detail: row.ventilatorStatus,
      focus: "ventilation",
      label: "Ventilation",
      rule: "Room air = 1, NIV/O2 = 6, invasive ventilation = 9.",
      tone: row.ventilationScore >= 7 ? "purple" : row.ventilationScore >= 6 ? "warning" : "success",
      value: `${row.ventilationScore}`,
      why: "Respiratory support increases bedside acuity and monitoring intensity.",
    },
    {
      detail: row.infectionSuspected ? "Sepsis screen" : "Infection screen",
      focus: "infection",
      label: "Infection / qSOFA",
      rule: "qSOFA: RR >= 22, SBP <= 100, GCS < 15. Score 2 or more needs clinician review.",
      tone: row.qsofaScore >= 2 ? "danger" : row.infectionScore >= 7 ? "warning" : "success",
      value: `${row.qsofaScore}/3`,
      why: "Infection context and qSOFA criteria explain why sepsis screening is highlighted.",
    },
    {
      detail: row.medicationRisk ? "Risk rows present" : "No due risk",
      focus: "medication",
      label: "Medication",
      rule: "Late medication or double verification required counts as medication risk.",
      tone: row.medicationRisk ? "warning" : "success",
      value: `${row.medicationRisk}`,
      why: "Medication delays and high-alert checks can directly affect patient safety.",
    },
    {
      detail: row.deviceIssue,
      focus: "device",
      label: "Device",
      rule: "Signal should be Good and device should be mapped. Not mapped/weak/no signal adds risk.",
      tone: row.deviceSignal === "Good" ? "success" : "warning",
      value: row.deviceSignal,
      why: "Device signal quality controls how reliable the live monitoring data is.",
    },
    {
      detail: `${row.alerts} alert(s)`,
      focus: "tasks",
      label: "Tasks / alerts",
      rule: "Open alerts add directly to score; 5 or more pending tasks adds +1.",
      tone: row.pendingTasks >= 5 || row.alerts >= 2 ? "warning" : "success",
      value: `${row.pendingTasks}`,
      why: "Unclosed tasks and alerts show operational backlog around the patient.",
    },
  ];
}

function patientRiskScoreBreakdown(row: PatientRiskRow, patient?: IcuPatient): Array<{ label: string; points: number; reason: string; tone: DashboardCellTone; value: string }> {
  const baseCriticality = patient?.criticalityScore ?? 0;
  const abnormalVitalPoints = row.abnormalVital ? 2 : 0;
  const devicePoints = row.deviceSignal !== "Good" ? 1 : 0;
  const taskPoints = row.pendingTasks >= 5 ? 1 : 0;
  const urinePoints = row.latestUrineOutput > 0 && row.latestUrineOutput < 30 ? 1 : 0;
  return [
    { label: "Base clinical criticality", points: baseCriticality, reason: "Patient baseline criticality from ICU patient record.", tone: baseCriticality >= 8 ? "critical" : baseCriticality >= 6 ? "warning" : "success", value: patient ? `${patient.currentStatus} | criticality ${baseCriticality}` : `criticality ${baseCriticality}` },
    { label: "Open alerts", points: row.alerts, reason: "Each unresolved ICU alert adds risk until acknowledged/resolved.", tone: row.alerts ? "danger" : "success", value: `${row.alerts} open alert(s)` },
    { label: "Medication risk", points: row.medicationRisk, reason: "Late medicine or double verification required counts as medication risk.", tone: row.medicationRisk ? "warning" : "success", value: `${row.medicationRisk} risk item(s)` },
    { label: "Abnormal vitals", points: abnormalVitalPoints, reason: "Latest vital row is marked abnormal.", tone: abnormalVitalPoints ? "danger" : "success", value: row.latestVitals },
    { label: "Device signal", points: devicePoints, reason: "Weak/no/not-mapped signal adds device reliability risk.", tone: devicePoints ? "warning" : "success", value: `${row.deviceSignal} | ${row.deviceIssue}` },
    { label: "Task load", points: taskPoints, reason: "Five or more pending tasks adds operational risk.", tone: taskPoints ? "warning" : "success", value: `${row.pendingTasks} pending task(s)` },
    { label: "Urine output", points: urinePoints, reason: "Urine output below 30 ml/hr adds perfusion/renal watch risk.", tone: urinePoints ? "warning" : "success", value: `${row.latestUrineOutput} ml/hr` },
  ];
}

function patientRiskVitalRules(vital?: IcuVital): Array<{ label: string; met: boolean; rule: string; tone: DashboardCellTone; value: string }> {
  const systolic = parseSystolicBp(vital?.bp ?? "");
  const spo2Met = (vital?.spo2 ?? 100) < 94;
  const rrMet = (vital?.respiratoryRate ?? 0) >= 22;
  const bpMet = systolic !== null && systolic <= 100;
  const gcsMet = (vital?.gcs ?? 15) < 15;
  const urineMet = (vital?.urineOutput ?? 999) < 30;
  const pulseMet = (vital?.pulse ?? 0) >= 120;
  return [
    { label: "SpO2", met: spo2Met, rule: "Flag if SpO2 < 94%", tone: spo2Met ? "danger" : "success", value: vital ? `${vital.spo2}%` : "No value" },
    { label: "Respiratory rate", met: rrMet, rule: "qSOFA point if RR >= 22/min", tone: rrMet ? "warning" : "success", value: vital ? `${vital.respiratoryRate}/min` : "No value" },
    { label: "Systolic BP", met: bpMet, rule: "qSOFA point if SBP <= 100 mmHg", tone: bpMet ? "warning" : "success", value: systolic !== null ? `${systolic} mmHg` : "No BP" },
    { label: "Mentation / GCS", met: gcsMet, rule: "qSOFA point if GCS < 15", tone: gcsMet ? "warning" : "success", value: vital ? `GCS ${vital.gcs}` : "No GCS" },
    { label: "Pulse", met: pulseMet, rule: "Flag if pulse >= 120/min", tone: pulseMet ? "warning" : "success", value: vital ? `${vital.pulse}/min` : "No value" },
    { label: "Urine output", met: urineMet, rule: "Risk point if urine output < 30 ml/hr", tone: urineMet ? "warning" : "success", value: vital ? `${vital.urineOutput} ml/hr` : "No value" },
  ];
}

function patientRiskMedicationTone(row: IcuMedication): DashboardCellTone {
  if (row.status === "Late") return "danger";
  if (row.status === "Due" || row.doubleVerification === "Required") return "warning";
  if (row.status === "Administered") return "success";
  return "muted";
}

function patientRiskTaskTone(status: (typeof icuTasks)[number]["status"]): DashboardCellTone {
  if (status === "Overdue" || status === "Escalated") return "danger";
  if (status === "Pending" || status === "Assigned" || status === "In progress") return "warning";
  if (status === "Completed") return "success";
  return "info";
}

function RiskWorkflowActionDialog({
  action,
  onComplete,
  onOpenChange,
}: {
  action: RiskWorkflowAction | null;
  onComplete: (action: RiskWorkflowAction, note: string) => void;
  onOpenChange: (open: boolean) => void;
}) {
  return (
    <Dialog.Root open={Boolean(action)} onOpenChange={onOpenChange}>
      {action ? <RiskWorkflowActionDialogContent action={action} key={`${action.mode}-${action.row.id}-${action.kind}`} onComplete={onComplete} /> : null}
    </Dialog.Root>
  );
}

function RiskWorkflowActionDialogContent({ action, onComplete }: { action: RiskWorkflowAction; onComplete: (action: RiskWorkflowAction, note: string) => void }) {
  const copy = riskActionCopy(action);
  const [selectedAction, setSelectedAction] = React.useState(copy.defaultAction);
  const [owner, setOwner] = React.useState(action.row.owner);
  const [reviewWindow, setReviewWindow] = React.useState(copy.defaultReview);
  const [note, setNote] = React.useState(copy.note);

  return (
    <Dialog.Portal>
      <Dialog.Overlay className="fixed inset-0 z-50 bg-black/45 backdrop-blur-[1px]" />
      <Dialog.Content className="fixed left-1/2 top-1/2 z-50 flex max-h-[92dvh] w-[min(920px,calc(100vw-24px))] -translate-x-1/2 -translate-y-1/2 flex-col overflow-hidden rounded-xl border border-slate-300 bg-white shadow-2xl outline-none">
        <div className={cn("border-b border-slate-200 px-4 py-3 text-white", dashboardToneSolidClass(copy.tone))}>
          <div className="flex items-start justify-between gap-3">
            <div>
              <Dialog.Title className="text-base font-bold">{copy.title}</Dialog.Title>
              <Dialog.Description className="mt-1 text-xs text-white/85">{action.row.bedNo} - {action.row.patient} | {copy.description}</Dialog.Description>
            </div>
            <Dialog.Close asChild>
              <Button className="border-white/30 bg-white/10 text-white hover:bg-white/20" size="sm" variant="outline"><X className="h-4 w-4" />Close</Button>
            </Dialog.Close>
          </div>
        </div>
        <div className="flex-1 space-y-4 overflow-y-auto p-4">
          <div className="grid gap-3 lg:grid-cols-2">
            <InfoPanel title={copy.contextTitle} rows={copy.contextRows as [string, string][]} />
            <InfoPanel title={copy.signalTitle} rows={copy.signalRows as [string, string][]} />
          </div>

          {copy.showSepsis ? <SepsisReferenceCard row={action.row} /> : null}

          <div className="rounded-md border border-slate-200 bg-slate-50 p-3">
            <div className="grid gap-3 md:grid-cols-3">
              <IcuOperationsFilterSelect label={copy.actionLabel} value={selectedAction} onChange={setSelectedAction} options={copy.actionOptions} />
              <IcuOperationsFilterSelect label="Responsible owner" value={owner} onChange={setOwner} options={copy.ownerOptions} />
              <IcuOperationsFilterSelect label="Next review" value={reviewWindow} onChange={setReviewWindow} options={copy.reviewOptions} />
            </div>
            <label className="mt-3 block space-y-1 text-sm">
              <span className="font-semibold text-slate-800">Action / review note</span>
              <textarea className="min-h-28 w-full rounded-md border border-slate-300 bg-white p-3 text-sm outline-none focus:ring-2 focus:ring-sky-200" value={note} onChange={(event) => setNote(event.target.value)} />
            </label>
          </div>

          <div className="rounded-md border border-slate-200 bg-white p-3">
            <p className="text-sm font-bold text-slate-950">{copy.checklistTitle}</p>
            <div className="mt-3 grid gap-2 md:grid-cols-2">
              {copy.checklist.map((item, index) => (
                <label className="flex items-center gap-2 rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-sm" key={item}>
                  <input className="h-4 w-4 rounded border-slate-300" type="checkbox" defaultChecked={index < 2} />
                  <span className="font-semibold text-slate-700">{item}</span>
                </label>
              ))}
            </div>
          </div>
        </div>
        <div className="flex flex-wrap justify-end gap-2 border-t border-slate-200 bg-slate-50 px-4 py-3">
          <Dialog.Close asChild><Button variant="outline">Cancel</Button></Dialog.Close>
          <Button variant="outline" asChild><Link href={icuPatientDetailHref(action.row.patientId, "graph")}>Open vital graph</Link></Button>
          <Button variant={selectedAction.includes("Escalate") ? "danger" : "default"} onClick={() => onComplete(action, `${note} | ${selectedAction} | Owner: ${owner} | ${reviewWindow}`)}>
            <CheckCircle2 className="h-4 w-4" />Save action
          </Button>
        </div>
      </Dialog.Content>
    </Dialog.Portal>
  );
}

function riskCommandMetrics(mode: RiskCommandMode, rows: PatientRiskRow[]): Array<{ label: string; value: React.ReactNode; tone: DashboardCellTone }> {
  if (mode === "ews") {
    return [
      { label: "EWS tracked", value: rows.length, tone: "info" },
      { label: "Immediate", value: rows.filter((row) => row.score >= 10).length, tone: rows.some((row) => row.score >= 10) ? "critical" : "success" },
      { label: "30 min watch", value: rows.filter((row) => row.score >= 7 && row.score < 10).length, tone: "warning" },
      { label: "Abnormal vitals", value: rows.filter((row) => row.abnormalVital).length, tone: rows.some((row) => row.abnormalVital) ? "danger" : "success" },
      { label: "2 hourly", value: rows.filter((row) => row.score >= 5 && row.score < 7).length, tone: "info" },
    ];
  }
  return [
    { label: "Patients", value: rows.length, tone: "info" },
    { label: "Critical", value: rows.filter((row) => row.riskLevel === "Critical").length, tone: rows.some((row) => row.riskLevel === "Critical") ? "critical" : "success" },
    { label: "High risk", value: rows.filter((row) => row.riskLevel === "High").length, tone: "danger" },
    { label: "Med risk", value: rows.filter((row) => row.medicationRisk > 0).length, tone: "warning" },
    { label: "Open alerts", value: rows.reduce((sum, row) => sum + row.alerts, 0), tone: "warning" },
  ];
}

function riskActionLabel(kind: RiskActionKind) {
  if (kind === "review") return "Risk review";
  if (kind === "escalate") return "Escalation";
  if (kind === "care-plan") return "Care plan update";
  if (kind === "observe") return "Observation plan";
  if (kind === "chart") return "Chart review";
  return "Acknowledge";
}

function riskActionCopy(action: RiskWorkflowAction) {
  const row = action.row;
  const ownerOptions = uniqueTextValues([row.owner, row.assignedWardNurse, row.assignedUnitNurse, "Head Nurse Sana", "Duty Doctor", "Remote Intensivist", "Respiratory Therapist"]);
  const reviewOptions = uniqueTextValues([observationFrequency(row.score), "Immediate", "Next 15 min", "Next 30 min", "Next 2 hours", "After result", "After round"]);
  const tone = action.kind === "escalate" ? "danger" : action.mode === "ews" ? ewsTone(row.score) : riskLevelTone(row.riskLevel);
  if (action.mode === "ews") {
    const base = {
      ownerOptions,
      reviewOptions,
      showSepsis: false,
      tone,
    };

    if (action.kind === "review") {
      return {
        ...base,
        title: "EWS score detail",
        description: `${ewsBucket(row.score)} bucket | score threshold and reason`,
        actionLabel: "Score action",
        defaultAction: "Confirm EWS score",
        defaultReview: observationFrequency(row.score),
        actionOptions: ["Confirm EWS score", "Repeat full vitals", "Increase observation frequency", "Escalate to duty doctor"],
        contextTitle: "Score and threshold",
        contextRows: [
          ["EWS score", `${row.score}`],
          ["Bucket", ewsBucket(row.score)],
          ["Observation frequency", observationFrequency(row.score)],
          ["Escalation trigger", escalationTrigger(row.score)],
          ["Reason", row.trendReason],
        ],
        signalTitle: "Score contributors",
        signalRows: [
          ["Latest vitals", row.latestVitals],
          ["Respiratory support", row.ventilatorStatus],
          ["Open alerts", `${row.alerts}`],
          ["Medication risk", `${row.medicationRisk}`],
          ["Low urine output", row.latestUrineOutput < 30 ? `${row.latestUrineOutput} ml/hr` : "No"],
        ],
        checklistTitle: "Score verification checklist",
        checklist: ["Latest full vital set checked", "Score bucket matched threshold", "Trend compared with previous entry", "Observation frequency selected", "Doctor escalation checked if score high", "Next review time documented"],
        note: `${row.bedNo} EWS score ${row.score} (${ewsBucket(row.score)}). Reason: ${row.trendReason}.`,
      };
    }

    if (action.kind === "chart") {
      return {
        ...base,
        title: "Latest vitals detail",
        description: "Only vital values and abnormal-vital rule for this patient",
        actionLabel: "Vitals action",
        defaultAction: "Repeat full vitals",
        defaultReview: "Next 15 min",
        actionOptions: ["Repeat full vitals", "Open vital graph", "Inform duty doctor", "Continue monitoring"],
        contextTitle: "Latest vital set",
        contextRows: [
          ["Blood pressure", row.latestBp],
          ["SpO2", `${row.latestSpo2}%`],
          ["Pulse", `${row.latestPulse}/min`],
          ["Respiratory rate", `${row.latestRespiratoryRate}/min`],
          ["GCS", `${row.latestGcs}`],
        ],
        signalTitle: "Vitals rule",
        signalRows: [
          ["Abnormal flag", row.abnormalVital ? "Triggered" : "Within range"],
          ["Urine output", `${row.latestUrineOutput} ml/hr`],
          ["Pain score", `${row.latestPainScore}/10`],
          ["Last charted", row.lastVitalsTime],
          ["Trend reason", row.trendReason],
        ],
        checklistTitle: "Vitals review checklist",
        checklist: ["BP/SpO2/pulse/RR checked", "GCS and pain reviewed", "Urine output checked", "Repeat reading planned if abnormal", "Vital graph opened if trend unclear", "Doctor informed if deterioration persists"],
        note: `${row.bedNo} latest vitals reviewed: ${row.latestVitals}.`,
      };
    }

    if (action.kind === "observe") {
      return {
        ...base,
        title: "Observation frequency",
        description: "Next observation timing based on EWS bucket",
        actionLabel: "Observation action",
        defaultAction: "Schedule next observation",
        defaultReview: observationFrequency(row.score),
        actionOptions: ["Schedule next observation", "Assign nurse follow-up", "Repeat full vitals", "Escalate if next reading worsens"],
        contextTitle: "Observation plan",
        contextRows: [
          ["Next frequency", observationFrequency(row.score)],
          ["EWS bucket", ewsBucket(row.score)],
          ["Current score", `${row.score}`],
          ["Assigned nurse", row.assignedWardNurse],
          ["Unit nurse", row.assignedUnitNurse],
        ],
        signalTitle: "Follow-up focus",
        signalRows: [
          ["Watch reason", row.trendReason],
          ["Latest vitals", row.latestVitals],
          ["Escalation trigger", escalationTrigger(row.score)],
          ["Owner", row.owner],
          ["Last vitals time", row.lastVitalsTime],
        ],
        checklistTitle: "Observation scheduling checklist",
        checklist: ["Observation time selected", "Ward nurse assigned", "Next vital set includes BP/SpO2/RR/GCS", "Escalation rule communicated", "Manual entry fallback available", "Handover note updated"],
        note: `${row.bedNo} next EWS observation scheduled: ${observationFrequency(row.score)}.`,
      };
    }

    if (action.kind === "escalate") {
      return {
        ...base,
        title: "Escalation trigger",
        description: "Only trigger reason, owner, and immediate action",
        actionLabel: "Escalation action",
        defaultAction: "Escalate to duty doctor",
        defaultReview: row.score >= 10 ? "Immediate" : "Next 30 min",
        actionOptions: ["Escalate to duty doctor", "Call head nurse", "Repeat full vitals now", "Prepare critical review"],
        contextTitle: "Trigger detail",
        contextRows: [
          ["Trigger", escalationTrigger(row.score)],
          ["EWS score", `${row.score}`],
          ["Bucket", ewsBucket(row.score)],
          ["Reason", row.trendReason],
          ["Diagnosis", row.diagnosis],
        ],
        signalTitle: "Escalation ownership",
        signalRows: [
          ["Duty doctor", row.owner],
          ["Ward nurse", row.assignedWardNurse],
          ["Latest vitals", row.latestVitals],
          ["Respiratory support", row.ventilatorStatus],
          ["Open alerts", `${row.alerts}`],
        ],
        checklistTitle: "Escalation checklist",
        checklist: ["Duty doctor informed", "Repeat full vitals started", "High-risk medication/oxygen checked", "Head nurse aware if critical", "Action time documented", "Response reviewed after escalation"],
        note: `${row.bedNo} EWS escalation: ${escalationTrigger(row.score)}. ${row.trendReason}.`,
      };
    }

    return {
      ...base,
      title: "EWS acknowledgement",
      description: "Only owner acknowledgement and responsibility trail",
      actionLabel: "Acknowledgement action",
      defaultAction: "Acknowledge EWS plan",
      defaultReview: observationFrequency(row.score),
      actionOptions: ["Acknowledge EWS plan", "Reassign owner", "Assign nurse follow-up", "Mark reviewed"],
      contextTitle: "Owner trail",
      contextRows: [
        ["Duty doctor", row.owner],
        ["Ward nurse", row.assignedWardNurse],
        ["Unit nurse", row.assignedUnitNurse],
        ["Patient", `${row.bedNo} - ${row.patient}`],
        ["Unit", row.unit],
      ],
      signalTitle: "Acknowledgement scope",
      signalRows: [
        ["EWS score", `${row.score}`],
        ["Observation frequency", observationFrequency(row.score)],
        ["Trigger", escalationTrigger(row.score)],
        ["Last vitals", row.lastVitalsTime],
        ["Action needed", row.score >= 7 ? "Active follow-up" : "Routine watch"],
      ],
      checklistTitle: "Acknowledgement checklist",
      checklist: ["Owner accepted responsibility", "Ward nurse aware", "Next observation time visible", "Escalation trigger understood", "Handover note updated", "Status marked acknowledged"],
      note: `${row.bedNo} EWS plan acknowledged by ${row.assignedWardNurse}. Next review: ${observationFrequency(row.score)}.`,
    };
  }
  return {
    title: riskActionLabel(action.kind),
    description: "Patient risk center workflow",
    actionLabel: "Risk action",
    defaultAction: action.kind === "escalate" ? "Escalate high risk" : action.kind === "care-plan" ? "Update care plan" : "Review risk factors",
    defaultReview: row.riskLevel === "Critical" ? "Immediate" : row.riskLevel === "High" ? "Next 30 min" : "After round",
    actionOptions: ["Review risk factors", "Escalate high risk", "Update care plan", "Assign nurse follow-up", "Mark reviewed"],
    ownerOptions,
    reviewOptions,
    contextTitle: "Patient risk context",
    contextRows: [
      ["Patient", `${row.bedNo} - ${row.patient}`],
      ["Diagnosis", row.diagnosis],
      ["Risk score", `${row.score} / ${row.riskLevel}`],
      ["Latest vitals", row.latestVitals],
      ["Trend reason", row.trendReason],
    ],
    signalTitle: "Ownership and signals",
    signalRows: [
      ["Duty doctor", row.owner],
      ["Ward nurse", row.assignedWardNurse],
      ["Ventilation", row.ventilatorStatus],
      ["Medication risk", `${row.medicationRisk}`],
      ["Device signal", `${row.deviceSignal} / ${row.deviceIssue}`],
    ],
    showSepsis: true,
    checklistTitle: "Risk review checklist",
    checklist: ["Vitals trend reviewed", "Medication/device risk reviewed", "Open alerts and tasks checked", "Doctor/nurse owner confirmed", "Care plan updated if risk changed", "Follow-up time documented"],
    note: `${row.bedNo} risk ${row.score} (${row.riskLevel}). Factors: ${row.trendReason}.`,
    tone,
  };
}

function riskLevelTone(level: string): DashboardCellTone {
  if (level === "Critical") return "critical";
  if (level === "High") return "danger";
  if (level === "Watch") return "warning";
  return "success";
}

function ewsTone(score: number): DashboardCellTone {
  if (score >= 10) return "critical";
  if (score >= 7) return "danger";
  if (score >= 5) return "warning";
  return "success";
}

function ewsBucket(score: number) {
  if (score >= 10) return "Immediate";
  if (score >= 7) return "30 min watch";
  if (score >= 5) return "2 hourly";
  return "Stable";
}

function observationFrequency(score: number) {
  if (score >= 10) return "15 min";
  if (score >= 7) return "30 min";
  if (score >= 5) return "2 hourly";
  return "4 hourly";
}

function escalationTrigger(score: number) {
  if (score >= 10) return "Duty doctor now";
  if (score >= 7) return "Head nurse review";
  if (score >= 5) return "Increase observation";
  return "Continue monitoring";
}

function SepsisReferenceCard({ row }: { row: PatientRiskRow }) {
  return (
    <div className="rounded-md border border-slate-200 border-l-amber-500 bg-white p-3 shadow-sm">
      <div className="flex flex-col gap-2 sm:flex-row sm:items-start sm:justify-between">
        <div>
          <p className="text-sm font-black text-slate-950">Sepsis screening reference</p>
          <p className="mt-1 text-xs text-slate-700">
            qSOFA bedside screen based on Sepsis-3 criteria. Score 2 or more suggests higher risk and needs clinician review/full assessment.
          </p>
        </div>
        <Badge tone={row.qsofaScore >= 2 ? "danger" : "success"}>qSOFA {row.qsofaScore}/3</Badge>
      </div>
      <div className="mt-3 grid gap-2 md:grid-cols-3">
        {row.qsofaCriteria.map((criterion) => (
          <div className={cn("rounded-md border p-3", criterion.met ? "border-red-200 bg-white text-red-900" : "border-emerald-200 bg-white text-emerald-900")} key={criterion.label}>
            <p className="text-xs font-bold uppercase text-slate-500">{criterion.label}</p>
            <p className="mt-1 text-sm font-black">{criterion.value}</p>
            <p className="mt-1 text-xs text-slate-600">{criterion.rule}</p>
          </div>
        ))}
      </div>
      <div className="mt-3 rounded-md border border-amber-200 bg-white p-3 text-xs leading-relaxed text-slate-700">
        <p><span className="font-bold text-slate-950">Clinical note:</span> This is a screening/reference aid, not a final diagnosis. Confirm sepsis/septic shock using clinical judgement, infection evidence, organ dysfunction/SOFA, lactate, cultures, hemodynamics, and consultant review.</p>
        <p className="mt-2 font-semibold text-slate-800">References: Sepsis-3 consensus definition; Surviving Sepsis Campaign adult sepsis guidelines.</p>
      </div>
    </div>
  );
}

function buildQsofaScreen(vital?: IcuVital) {
  const systolic = parseSystolicBp(vital?.bp ?? "");
  const respiratoryMet = (vital?.respiratoryRate ?? 0) >= 22;
  const bpMet = systolic !== null && systolic <= 100;
  const mentationMet = (vital?.gcs ?? 15) < 15;
  const criteria = [
    { label: "Respiratory rate", value: vital ? `${vital.respiratoryRate}/min` : "No vitals", rule: "qSOFA point if RR >= 22/min", met: respiratoryMet },
    { label: "Systolic BP", value: systolic !== null ? `${systolic} mmHg` : "No BP", rule: "qSOFA point if SBP <= 100 mmHg", met: bpMet },
    { label: "Mentation / GCS", value: vital ? `GCS ${vital.gcs}` : "No GCS", rule: "qSOFA point if altered mentation / GCS < 15", met: mentationMet },
  ];
  return {
    score: criteria.filter((criterion) => criterion.met).length,
    criteria,
  };
}

function parseSystolicBp(bp: string) {
  const match = bp.match(/\d+/);
  return match ? Number(match[0]) : null;
}

