function buildRiskRows() {
  return icuPatients.map((patient) => {
    const latestVital = [...icuVitals].reverse().find((row) => row.patientId === patient.id);
    const diagnosisText = patient.diagnosis.toLowerCase();
    const infectionSuspected = diagnosisText.includes("septic") || diagnosisText.includes("sepsis") || diagnosisText.includes("infection") || diagnosisText.includes("pneumonia");
    const qsofa = buildQsofaScreen(latestVital);
    const openAlerts = icuAlerts.filter((row) => row.patientId === patient.id && row.status !== "Resolved").length;
    const medicationRisk = medicationRows.filter((row) => row.patientId === patient.id && (row.status === "Late" || row.doubleVerification === "Required")).length;
    const pendingTasks = icuTasks.filter((task) => task.patientId === patient.id && task.status !== "Completed").length;
    const abnormalVital = latestVital?.abnormal ? 2 : 0;
    const deviceRow = getCommandDeviceRows().find((row) => row.bedNo === patient.bedNo);
    const deviceRisk = deviceRow?.signal !== "Good" ? 1 : 0;
    const ventilationScore = patient.ventilatorStatus === "Room air" ? 1 : patient.ventilatorStatus.includes("Invasive") ? 9 : 6;
    const infectionScore = infectionSuspected ? Math.max(7, qsofa.score >= 2 ? 9 : 7) : qsofa.score >= 2 ? 6 : 2;
    const organSupportScore = patient.ventilatorStatus !== "Room air" || medicationRows.some((row) => row.patientId === patient.id && row.medication.toLowerCase().includes("noradrenaline")) ? 8 : patient.criticalityScore >= 6 ? 5 : 2;
    const taskRisk = pendingTasks >= 5 ? 1 : 0;
    const urineRisk = latestVital && latestVital.urineOutput < 30 ? 1 : 0;
    const score = patient.criticalityScore + openAlerts + medicationRisk + abnormalVital + deviceRisk + taskRisk + urineRisk;
    const riskLevel = score >= 11 ? "Critical" : score >= 8 ? "High" : score >= 5 ? "Watch" : "Stable";
    const trendReason = [
      latestVital?.abnormal ? "abnormal vitals" : "",
      openAlerts ? `${openAlerts} open alert(s)` : "",
      medicationRisk ? `${medicationRisk} medication risk` : "",
      qsofa.score >= 2 ? `qSOFA ${qsofa.score}/3` : "",
      deviceRisk ? "device signal issue" : "",
      taskRisk ? "high pending task load" : "",
      urineRisk ? "low urine output" : "",
      ventilationScore >= 6 ? "respiratory support" : "",
    ].filter(Boolean).join(", ") || "stable trend";
    return {
      id: patient.id,
      patientId: patient.id,
      bedNo: patient.bedNo,
      patient: patient.patientName,
      mrn: patient.mrn,
      ageGender: patient.ageGender,
      diagnosis: patient.diagnosis,
      unit: patient.unit,
      currentStatus: patient.currentStatus,
      ventilatorStatus: patient.ventilatorStatus,
      lastVitalsTime: patient.lastVitalsTime,
      assignedUnitNurse: patient.assignedUnitNurse,
      assignedWardNurse: patient.assignedWardNurse,
      score,
      riskLevel,
      latestVitals: latestVital ? `${latestVital.bp}, SpO2 ${latestVital.spo2}%, GCS ${latestVital.gcs}` : "No vitals",
      latestBp: latestVital?.bp ?? "-",
      latestSpo2: latestVital?.spo2 ?? 0,
      latestPulse: latestVital?.pulse ?? 0,
      latestRespiratoryRate: latestVital?.respiratoryRate ?? 0,
      latestGcs: latestVital?.gcs ?? 0,
      latestUrineOutput: latestVital?.urineOutput ?? 0,
      latestPainScore: latestVital?.painScore ?? 0,
      abnormalVital: Boolean(latestVital?.abnormal),
      alerts: openAlerts,
      medicationRisk,
      infectionSuspected,
      qsofaScore: qsofa.score,
      qsofaCriteria: qsofa.criteria,
      pendingTasks,
      ventilationScore,
      infectionScore,
      organSupportScore,
      deviceSignal: deviceRow?.signal ?? "Not mapped",
      deviceIssue: deviceRow?.issue ?? "Not mapped",
      trendReason,
      owner: patient.dutyDoctor,
    };
  });
}

