function patientName(patientId: string) {
  const patient = icuPatients.find((item) => item.id === patientId);
  return patient ? `${patient.bedNo} - ${patient.patientName}` : patientId;
}

function icuPatientDetailHref(patientId: string, tab: IcuPatientDetailTab, subtab?: IcuMonitoringSubTab, extraQuery = "") {
  const subtabQuery = tab === "monitoring" && subtab ? `&subtab=${subtab}` : "";
  const normalizedExtra = extraQuery ? `&${extraQuery.replace(/^\?/, "").replace(/^&/, "")}` : "";
  return `/icu-command-center/patients/${patientId}?tab=${tab}${subtabQuery}${normalizedExtra}`;
}

function icuPatientDailyChartHref(patientId: string) {
  return `/icu-command-center/patients/${patientId}/daily-chart`;
}

function normalizeIcuPatientDetailTab(tab?: string): IcuPatientDetailTab {
  if (tab === "monitoring" || tab === "results" || tab === "graph" || tab === "orders" || tab === "events" || tab === "shift-summary" || tab === "collaborate") return tab;
  return "overview";
}

function normalizeIcuMonitoringSubTab(subtab?: string): IcuMonitoringSubTab {
  if (subtab === "24h-chart" || subtab === "ventilation" || subtab === "intake-output" || subtab === "device-snapshot") return subtab;
  return "monitoring-overview";
}

type DashboardCellTone = "critical" | "danger" | "warning" | "success" | "info" | "purple" | "muted";
type MedicationOrdersSubTab = "pending-work" | "medicine-chart";
type IcuEventFocus = "all" | "open-alerts" | "action-needed";
type IcuShiftFocus = "all" | "pending" | "critical" | "completed";
type TeleIcuScenarioMode = "readiness" | "local-team" | "remote-md" | "sla";
type EscalatedCaseScenarioMode = "trigger" | "severity" | "source" | "owner-chain" | "sla" | "current-action" | "outcome";

function normalizeMedicationOrdersSubTab(tab?: string): MedicationOrdersSubTab {
  if (tab === "pending-work" || tab === "medicine-chart") return tab;
  return "medicine-chart";
}

function normalizeIcuEventFocus(focus?: string): IcuEventFocus {
  if (focus === "open-alerts" || focus === "action-needed") return focus;
  return "all";
}

function normalizeIcuShiftFocus(focus?: string): IcuShiftFocus {
  if (focus === "pending" || focus === "critical" || focus === "completed") return focus;
  return "all";
}

function teleIcuScenarioHref(mode: TeleIcuScenarioMode, patientId?: string) {
  const routeByMode: Record<TeleIcuScenarioMode, string> = {
    readiness: "/icu-command-center/tele-icu/readiness",
    "local-team": "/icu-command-center/tele-icu/local-team",
    "remote-md": "/icu-command-center/tele-icu/remote-md",
    sla: "/icu-command-center/tele-icu/sla",
  };
  return patientId ? `${routeByMode[mode]}?patientId=${patientId}` : routeByMode[mode];
}

function escalatedCaseScenarioHref(mode: EscalatedCaseScenarioMode, caseId?: string) {
  const routeByMode: Record<EscalatedCaseScenarioMode, string> = {
    trigger: "/icu-command-center/tele-icu/escalated-cases/trigger",
    severity: "/icu-command-center/tele-icu/escalated-cases/severity",
    source: "/icu-command-center/tele-icu/escalated-cases/source",
    "owner-chain": "/icu-command-center/tele-icu/escalated-cases/owner-chain",
    sla: "/icu-command-center/tele-icu/escalated-cases/sla",
    "current-action": "/icu-command-center/tele-icu/escalated-cases/current-action",
    outcome: "/icu-command-center/tele-icu/escalated-cases/outcome",
  };
  return caseId ? `${routeByMode[mode]}?caseId=${encodeURIComponent(caseId)}` : routeByMode[mode];
}

