// eslint-disable-next-line @typescript-eslint/no-unused-vars
function _buildIcuRapidReviewPatient(patient: IcuPatient, vitals: IcuVital[], ioRows: IcuIntakeOutput[]): RapidReviewPatient {
  const observations = buildIcuRapidObservations(patient, vitals, ioRows);
  const latestObservation = observations[observations.length - 1];
  const latestVital = vitals[vitals.length - 1];
  const latestZone = latestObservation?.dominantZone ?? "Safe";
  const latestResponse = latestObservation?.responseLevel ?? "Routine";

  return {
    id: patient.id,
    patientName: patient.patientName,
    uhid: patient.mrn,
    visitNo: `ICU-${patient.id.toUpperCase()}`,
    ageGender: patient.ageGender.replace("/", " / "),
    ward: patient.unit,
    bed: patient.bedNo,
    source: patient.admissionSource === "Emergency" ? "Emergency" : "IPD",
    consultant: patient.admittingDoctor,
    owner: patient.assignedWardNurse,
    lastObservationAt: latestObservation ? latestObservation.recordedAt : patient.lastVitalsTime,
    waitMinutes: Math.max(5, patient.criticalityScore * 4),
    responseLevel: latestResponse,
    queueStatus: latestResponse === "MER Call" || latestResponse === "MDT Review" ? "Escalated" : "Acknowledged",
    trigger: patient.alerts[0] ?? patient.diagnosis,
    urineOutput: latestObservation?.urineOutput ?? (latestVital ? `${latestVital.urineOutput} ml/hr` : "Not recorded"),
    reviewDue: latestResponse === "Routine" ? "Next round" : "Now",
    observationHistory: observations,
    metrics: buildIcuRapidMetrics(latestVital, latestObservation, latestZone),
    recommendedActions: [
      "Review 24-hour vital trend",
      "Check intake/output balance before next round",
      "Escalate abnormal trend to duty doctor",
      "Document action in monitoring notes",
    ],
  };
}

function buildIcuRapidObservations(patient: IcuPatient, vitals: IcuVital[], ioRows: IcuIntakeOutput[]): RapidObservationSet[] {
  const sortedVitals = [...vitals].sort((left, right) => left.time.localeCompare(right.time));
  const fallbackVital: IcuVital = sortedVitals[sortedVitals.length - 1] ?? {
    id: `${patient.id}-fallback-vital`,
    patientId: patient.id,
    bedNo: patient.bedNo,
    time: "00:00",
    temperature: patient.criticalityScore >= 8 ? "38.0" : "37.0",
    pulse: patient.criticalityScore >= 8 ? 118 : 88,
    bp: patient.criticalityScore >= 8 ? "96/62" : "124/78",
    respiratoryRate: patient.criticalityScore >= 8 ? 28 : 18,
    spo2: patient.criticalityScore >= 8 ? 93 : 98,
    oxygenFlow: patient.ventilatorStatus,
    gcs: patient.currentStatus === "Critical" ? 12 : 15,
    urineOutput: patient.criticalityScore >= 8 ? 30 : 55,
    painScore: patient.criticalityScore >= 8 ? 5 : 2,
    nurse: patient.assignedWardNurse,
    abnormal: patient.criticalityScore >= 7,
    note: patient.diagnosis,
  };
  const latestDate = latestIcuIoDate(ioRows) ?? "2026-06-06";

  return Array.from({ length: 24 }, (_, hour) => {
    const time = `${String(hour).padStart(2, "0")}:00`;
    const exactVital = sortedVitals.find((vital) => vital.time.slice(0, 2) === time.slice(0, 2));
    const anchor = exactVital ?? sortedVitals[hour % Math.max(1, sortedVitals.length)] ?? fallbackVital;
    const wave = (hour % 6) - 2;
    const respiratoryRate = exactVital ? anchor.respiratoryRate : clampIcuNumber(anchor.respiratoryRate + Math.round(wave / 2), 10, 42);
    const pulse = exactVital ? anchor.pulse : clampIcuNumber(anchor.pulse + wave * 2, 45, 160);
    const spo2 = exactVital ? anchor.spo2 : clampIcuNumber(anchor.spo2 - (patient.criticalityScore >= 8 && hour >= 14 ? 1 : 0) + (hour % 4 === 0 ? 0 : 1), 84, 100);
    const bp = exactVital ? anchor.bp : adjustedIcuBp(anchor.bp, wave, patient.criticalityScore);
    const temperature = exactVital ? anchor.temperature : clampIcuNumber(Number(anchor.temperature) + wave * 0.05, 35, 41).toFixed(1);
    const hourlyIntake = sumIcuIoForHour(ioRows, hour, "Intake");
    const hourlyOutput = sumIcuIoForHour(ioRows, hour, "Output");
    const urineOutput = hourlyOutput || anchor.urineOutput;
    const risk = deriveIcuRapidRisk({
      abnormal: anchor.abnormal,
      bp,
      gcs: anchor.gcs,
      pulse,
      respiratoryRate,
      spo2,
      urineOutput,
    });

    return {
      id: `${patient.id}-rapid-${time}`,
      observationDate: latestDate,
      recordedAt: time,
      recordedBy: exactVital?.nurse ?? anchor.nurse ?? patient.assignedWardNurse,
      shift: icuRapidShiftForHour(hour),
      respiratoryRate: `${respiratoryRate}`,
      spo2: `${spo2}%`,
      oxygenFlow: anchor.oxygenFlow,
      fio2: icuFio2Text(anchor.oxygenFlow),
      deliveryMethod: icuDeliveryMethod(anchor.oxygenFlow),
      bloodPressure: bp,
      pulse: `${pulse}`,
      monitorHeartRate: `${clampIcuNumber(pulse + (hour % 3), 45, 165)}`,
      pulseRhythm: pulse >= 125 ? "Irregular" : pulse >= 105 ? "Regularly irregular" : "Regular",
      temperature,
      consciousness: `${anchor.gcs}`,
      painScore: `${anchor.painScore}`,
      fluidIntake: `${hourlyIntake || estimateIcuHourlyIntake(patient, hour)} ml/hr`,
      urineOutput: `${urineOutput} ml/hr`,
      dominantZone: risk.zone,
      responseLevel: risk.responseLevel,
      reviewStatus: risk.responseLevel === "Routine" ? "Reviewed" : "Pending doctor review",
      note: exactVital?.note ?? `${patient.currentStatus} trend review - ${patient.diagnosis}`,
    };
  });
}

function buildIcuRapidMetrics(latestVital: IcuVital | undefined, latestObservation: RapidObservationSet | undefined, zone: RapidZone): RapidObservationMetric[] {
  return [
    { id: "rr", label: "Respiratory rate", value: latestObservation?.respiratoryRate ?? "-", unit: "/min", zone, trend: "Stable", note: "Latest respiratory chart value." },
    { id: "spo2", label: "O2 saturation", value: latestObservation?.spo2?.replace("%", "") ?? "-", unit: "%", zone, trend: latestVital?.abnormal ? "Worsening" : "Stable", note: "Latest oxygen saturation trend." },
    { id: "bp", label: "Blood pressure", value: latestObservation?.bloodPressure ?? "-", unit: "mmHg", zone, trend: "Stable", note: "Latest systolic/diastolic reading." },
    { id: "pulse", label: "Pulse rate", value: latestObservation?.pulse ?? "-", unit: "/min", zone, trend: "Stable", note: "Latest pulse rate." },
    { id: "temp", label: "Temperature", value: latestObservation?.temperature ?? "-", unit: "C", zone, trend: "Stable", note: "Latest temperature value." },
    { id: "io", label: "Urine output", value: latestObservation?.urineOutput?.replace(" ml/hr", "") ?? "-", unit: "ml/hr", zone, trend: "Stable", note: "Hourly output shown with fluid intake trend." },
  ];
}

function deriveIcuRapidRisk({
  abnormal,
  bp,
  gcs,
  pulse,
  respiratoryRate,
  spo2,
  urineOutput,
}: {
  abnormal: boolean;
  bp: string;
  gcs: number;
  pulse: number;
  respiratoryRate: number;
  spo2: number;
  urineOutput: number;
}): { zone: RapidZone; responseLevel: RapidResponseLevel } {
  const systolic = Number(bp.split("/")[0] ?? 0);
  if (spo2 < 90 || systolic < 85 || gcs <= 8 || respiratoryRate >= 34) return { zone: "Purple", responseLevel: "MER Call" };
  if (spo2 < 94 || systolic < 95 || pulse >= 120 || respiratoryRate >= 28 || urineOutput < 30 || abnormal) return { zone: "Red", responseLevel: "MDT Review" };
  if (spo2 < 97 || pulse >= 100 || respiratoryRate >= 22 || urineOutput < 40) return { zone: "Yellow", responseLevel: "RN Review" };
  return { zone: "Safe", responseLevel: "Routine" };
}

function sumIcuIoForHour(rows: IcuIntakeOutput[], hour: number, kind: IcuIntakeOutput["kind"]) {
  const hourPrefix = `${String(hour).padStart(2, "0")}:`;
  return rows
    .filter((row) => row.kind === kind && row.time.startsWith(hourPrefix))
    .reduce((sum, row) => sum + row.quantityMl, 0);
}

function latestIcuIoDate(rows: IcuIntakeOutput[]) {
  return rows.map((row) => row.date).sort((left, right) => right.localeCompare(left))[0];
}

function icuRapidShiftForHour(hour: number): RapidObservationSet["shift"] {
  if (hour >= 6 && hour <= 13) return "Morning";
  if (hour >= 14 && hour <= 21) return "Evening";
  return "Night";
}

function adjustedIcuBp(value: string, wave: number, criticalityScore: number) {
  const [sysRaw, diaRaw] = value.split("/");
  const systolic = Number(sysRaw) || 120;
  const diastolic = Number(diaRaw) || 80;
  const pressureDrift = criticalityScore >= 8 ? -2 : criticalityScore <= 3 ? 2 : 0;
  return `${clampIcuNumber(systolic + wave + pressureDrift, 70, 190)}/${clampIcuNumber(diastolic + Math.round(wave / 2) + pressureDrift, 40, 120)}`;
}

function icuDeliveryMethod(oxygenFlow: string): RapidObservationSet["deliveryMethod"] {
  const lower = oxygenFlow.toLowerCase();
  if (lower.includes("ventilator") || lower.includes("invasive")) return "Ventilator";
  if (lower.includes("niv") || lower.includes("cpap") || lower.includes("bipap")) return "CPAP";
  if (lower.includes("nrbm")) return "NRBM";
  if (lower.includes("nasal")) return "Nasal cannula";
  if (lower.includes("air") || lower.includes("room")) return "Room air";
  return "Simple mask";
}

function icuFio2Text(oxygenFlow: string) {
  const fio2Match = oxygenFlow.match(/fio2\s*(\d+)/i);
  if (fio2Match?.[1]) return `${fio2Match[1]}%`;
  const lower = oxygenFlow.toLowerCase();
  if (lower.includes("room air") || lower === "air") return "21%";
  if (lower.includes("ventilator")) return "40%";
  if (lower.includes("niv") || lower.includes("nrbm")) return "60%";
  const flowMatch = oxygenFlow.match(/(\d+)\s*l/i);
  if (flowMatch?.[1]) return `${Math.min(100, 24 + Number(flowMatch[1]) * 4)}%`;
  return "28%";
}

function estimateIcuHourlyIntake(patient: IcuPatient, hour: number) {
  if (patient.criticalityScore >= 8) return 60 + (hour % 4) * 15;
  if (patient.criticalityScore >= 5) return 45 + (hour % 3) * 10;
  return 35 + (hour % 2) * 10;
}

function clampIcuNumber(value: number, min: number, max: number) {
  return Math.round(Math.min(max, Math.max(min, value)));
}

function IcuPatientDetailMetric({ icon: Icon, label, value, detail, tone }: { icon: typeof Activity; label: string; value: React.ReactNode; detail: string; tone: DashboardCellTone }) {
  return (
    <div className={cn("min-h-[132px] rounded-2xl border border-slate-200 bg-white p-4 shadow-[0_14px_32px_rgba(15,23,42,0.05)] transition duration-150 hover:-translate-y-0.5 hover:shadow-[0_18px_40px_rgba(15,23,42,0.07)]", patientDetailAccentClass(tone))}>
      <div className="flex items-start justify-between gap-3">
        <div>
          <p className="text-xs font-semibold uppercase tracking-[0.08em] text-slate-500">{label}</p>
          <p className="mt-3 text-2xl font-semibold leading-tight tracking-tight text-slate-950">{value}</p>
        </div>
        <span className={cn("inline-flex h-10 w-10 items-center justify-center rounded-xl border bg-white", patientDetailIconClass(tone))}>
          <Icon className="h-5 w-5" />
        </span>
      </div>
      <p className="mt-3 truncate text-xs font-medium text-slate-500">{detail}</p>
    </div>
  );
}

function patientDetailAccentClass(tone: DashboardCellTone) {
  if (tone === "critical" || tone === "danger") return "border-l-4 border-l-red-500";
  if (tone === "warning") return "border-l-4 border-l-orange-500";
  if (tone === "purple" || tone === "info") return "border-l-4 border-l-blue-500";
  if (tone === "success") return "border-l-4 border-l-emerald-500";
  if (tone === "muted") return "border-l-4 border-l-slate-300";
  return "border-l-4 border-l-blue-500";
}

function patientDetailIconClass(tone: DashboardCellTone) {
  if (tone === "critical" || tone === "danger") return "border-red-100 bg-red-50 text-red-600";
  if (tone === "warning") return "border-orange-100 bg-orange-50 text-orange-600";
  if (tone === "purple" || tone === "info") return "border-blue-100 bg-blue-50 text-blue-600";
  if (tone === "success") return "border-emerald-100 bg-emerald-50 text-emerald-600";
  if (tone === "muted") return "border-slate-200 text-slate-500";
  return "border-blue-100 bg-blue-50 text-blue-600";
}

