function IcuPatientEntryTable({
  title,
  rows,
  empty,
}: {
  title: string;
  rows: Array<{ id: string; time: string; title: string; detail: string; tone: DashboardCellTone }>;
  empty: string;
}) {
  return (
    <div className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-[0_14px_32px_rgba(15,23,42,0.05)]">
      <div className="flex items-center justify-between gap-3 border-b border-slate-100 px-4 py-3">
        <p className="text-sm font-semibold text-slate-950">{title}</p>
        <span className="rounded-full border border-slate-200 bg-slate-50 px-2.5 py-1 text-xs font-semibold text-slate-600">{rows.length}</span>
      </div>
      <div className="divide-y divide-slate-100">
        {rows.map((row) => (
          <div className="grid gap-2 px-4 py-3 transition hover:bg-sky-50/60 md:grid-cols-[120px_minmax(0,1fr)_120px] md:items-center" key={row.id}>
            <span className="text-xs font-bold text-slate-500">{row.time}</span>
            <div>
              <p className="text-sm font-bold text-slate-950">{row.title}</p>
              <p className="mt-1 text-xs text-slate-500">{row.detail}</p>
            </div>
            <span className={cn("rounded-full border px-2.5 py-1 text-center text-xs font-bold", dashboardTonePillClass(row.tone))}>{row.tone}</span>
          </div>
        ))}
        {!rows.length ? <div className="p-5 text-center text-sm font-semibold text-slate-500">{empty}</div> : null}
      </div>
    </div>
  );
}

type IcuPatientResultStatus = "Available" | "Critical" | "Pending" | "Reviewed";

type IcuPatientResultRow = {
  id: string;
  patientId: string;
  category: "Pathology" | "Radiology" | "ABG" | "Microbiology" | "Cardiology";
  reportName: string;
  status: IcuPatientResultStatus;
  orderedAt: string;
  reportedAt: string;
  source: string;
  summary: string;
  reviewedBy: string;
  values: Array<[string, string]>;
  attachmentLabel: string;
};

function IcuPatientResultsWorkspace({
  initialType,
  patient,
  rows,
  onPreview,
  onDownload,
}: {
  initialType?: string;
  patient: IcuPatient;
  rows: IcuPatientResultRow[];
  onPreview: (resultId: string) => void;
  onDownload: (result: IcuPatientResultRow) => void;
}) {
  const [query, setQuery] = React.useState("");
  const initialCategory = normalizeIcuPatientResultCategory(initialType);
  const [categoryFilter, setCategoryFilter] = React.useState(initialCategory);
  const [statusFilter, setStatusFilter] = React.useState("All status");
  const categoryOptions = ["All categories", ...Array.from(new Set(rows.map((row) => row.category)))];
  const statusOptions = ["All status", "Available", "Critical", "Pending", "Reviewed"];
  const filteredRows = rows.filter((row) => {
    const text = `${row.reportName} ${row.category} ${row.status} ${row.source} ${row.summary}`.toLowerCase();
    return text.includes(query.toLowerCase())
      && (categoryFilter === "All categories" || row.category === categoryFilter)
      && (statusFilter === "All status" || row.status === statusFilter);
  });
  const critical = filteredRows.filter((row) => row.status === "Critical").length;
  const pending = filteredRows.filter((row) => row.status === "Pending").length;
  const available = filteredRows.filter((row) => row.status !== "Pending").length;
  const unreviewed = filteredRows.filter((row) => row.status === "Available" || row.status === "Critical").length;
  const pagination = useIcuCommandPagination(filteredRows);

  return (
    <div className="space-y-4">
      <CollapsibleCommandPanel
        summary={`${filteredRows.length} result(s) | ${critical} critical | ${pending} pending | ${unreviewed} review pending`}
        title="Result filters"
      >
        <div className="space-y-3 p-3">
          <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
            <IcuPatientDetailMetric icon={TestTube2} label="Available reports" value={available} detail="Ready for review" tone={available ? "info" : "muted"} />
            <IcuPatientDetailMetric icon={AlertTriangle} label="Critical results" value={critical} detail="Needs attention" tone={critical ? "critical" : "success"} />
            <IcuPatientDetailMetric icon={Clock3} label="Pending reports" value={pending} detail="Awaiting result" tone={pending ? "warning" : "success"} />
            <IcuPatientDetailMetric icon={ClipboardCheck} label="Review pending" value={unreviewed} detail="Sign-off queue" tone={unreviewed ? "warning" : "success"} />
          </div>

          <div className="grid gap-3 rounded-2xl border border-slate-200 bg-white p-4 lg:grid-cols-[minmax(220px,1fr)_220px_180px_auto] lg:items-end">
            <label className="space-y-1 text-sm">
              <span className="font-semibold text-slate-800">Search report</span>
              <Input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search report, source, summary..." />
            </label>
            <NativeSelect label="Category" value={categoryFilter} onChange={setCategoryFilter} options={categoryOptions} />
            <NativeSelect label="Status" value={statusFilter} onChange={setStatusFilter} options={statusOptions} />
            <Button variant="outline" onClick={() => {
              setQuery("");
              setCategoryFilter("All categories");
              setStatusFilter("All status");
            }}>Reset</Button>
          </div>
        </div>
      </CollapsibleCommandPanel>

      <div className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-[0_14px_32px_rgba(15,23,42,0.05)]">
        <div className="overflow-x-auto">
          <table className="w-full min-w-[900px] border-separate border-spacing-0 text-left text-sm">
            <thead className="sticky top-0 z-10 border-b border-slate-200 bg-slate-50 text-xs uppercase tracking-wide text-slate-500">
              <tr>
                <th className="px-4 py-3">Report</th>
                <th className="px-4 py-3">Type</th>
                <th className="px-4 py-3">Status</th>
                <th className="px-4 py-3">Time</th>
                <th className="px-4 py-3">Summary</th>
                <th className="px-4 py-3 text-right">Action</th>
              </tr>
            </thead>
            <tbody>
              {pagination.pageRows.map((row) => {
                const downloadDisabled = row.status === "Pending";
                return (
                  <tr className="bg-white transition even:bg-slate-50/45 hover:bg-sky-50/70 [&:last-child>td]:border-0" key={row.id}>
                    <td className="border-b border-slate-100 px-4 py-3">
                      <p className="font-bold text-slate-950">{row.reportName}</p>
                      <p className="mt-1 text-xs text-slate-500">{row.source}</p>
                    </td>
                    <td className="border-b border-slate-100 px-4 py-3">
                      <span className="rounded-full border border-slate-300 bg-white px-2.5 py-1 text-xs font-bold text-slate-700">{row.category}</span>
                    </td>
                    <td className="border-b border-slate-100 px-4 py-3">
                      <span className={cn("rounded-full border px-2.5 py-1 text-xs font-bold", dashboardTonePillClass(toneForPatientResult(row.status)))}>{row.status}</span>
                    </td>
                    <td className="border-b border-slate-100 px-4 py-3 text-xs text-slate-600">
                      <p><span className="font-bold">Ordered:</span> {row.orderedAt}</p>
                      <p className="mt-1"><span className="font-bold">Reported:</span> {row.reportedAt}</p>
                    </td>
                    <td className="max-w-[340px] border-b border-slate-100 px-4 py-3 text-xs leading-relaxed text-slate-600">{row.summary}</td>
                    <td className="border-b border-slate-100 px-4 py-3">
                      <div className="flex justify-end gap-2">
                        <Button className="h-9 px-3 text-xs" size="sm" variant="outline" onClick={() => onPreview(row.id)}>
                          <FileText className="h-4 w-4" />Preview
                        </Button>
                        <Button className="h-9 px-3 text-xs" disabled={downloadDisabled} size="sm" title={downloadDisabled ? "Report is pending" : "Download report"} onClick={() => onDownload(row)}>
                          <Download className="h-4 w-4" />Download
                        </Button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
        <IcuCommandPaginationControls {...pagination} />
        {!filteredRows.length ? <div className="p-6 text-center text-sm font-semibold text-slate-500">No diagnostic result matched the selected filters.</div> : null}
      </div>
    </div>
  );
}

function normalizeIcuPatientResultCategory(value?: string) {
  const lower = value?.toLowerCase();
  if (lower === "radiology") return "Radiology";
  if (lower === "pathology" || lower === "lab" || lower === "labs") return "Pathology";
  if (lower === "abg") return "ABG";
  if (lower === "microbiology") return "Microbiology";
  if (lower === "cardiology") return "Cardiology";
  return "All categories";
}

function IcuPatientResultPreviewDialog({
  result,
  onClose,
  onDownload,
}: {
  result: IcuPatientResultRow | null;
  onClose: () => void;
  onDownload: (result: IcuPatientResultRow) => void;
}) {
  return (
    <Dialog.Root open={Boolean(result)} onOpenChange={(open) => {
      if (!open) onClose();
    }}>
      <Dialog.Portal>
        <Dialog.Overlay className="fixed inset-0 z-50 bg-black/40 backdrop-blur-[1px]" />
        <Dialog.Content className="fixed left-1/2 top-1/2 z-50 flex max-h-[90dvh] w-[min(860px,calc(100vw-24px))] -translate-x-1/2 -translate-y-1/2 flex-col overflow-hidden rounded-xl border border-slate-200 bg-white shadow-soft outline-none">
          {result ? (
            <>
              <div className="border-b border-slate-200 bg-sky-700 px-4 py-3 text-white">
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <Dialog.Title className="text-base font-bold">{result.reportName}</Dialog.Title>
                    <Dialog.Description className="mt-1 text-xs text-sky-100">{result.category} | {result.source} | {result.attachmentLabel}</Dialog.Description>
                  </div>
                  <button className="rounded-md border border-white/30 px-2 py-1 text-xs font-bold hover:bg-white/10" type="button" onClick={onClose}>Close</button>
                </div>
              </div>
              <div className="overflow-y-auto p-4">
                <div className="grid gap-3 sm:grid-cols-3">
                  <InfoLine label="Status" value={<span className={cn("rounded-full border px-2.5 py-1 text-xs font-bold", dashboardTonePillClass(toneForPatientResult(result.status)))}>{result.status}</span>} />
                  <InfoLine label="Ordered at" value={result.orderedAt} />
                  <InfoLine label="Reported at" value={result.reportedAt} />
                </div>
                <div className="mt-4 rounded-md border border-slate-200 bg-slate-50 p-3">
                  <p className="text-xs font-bold uppercase text-slate-500">Report summary</p>
                  <p className="mt-2 text-sm font-medium text-slate-900">{result.summary}</p>
                  <p className="mt-2 text-xs text-slate-500">Reviewed by: {result.reviewedBy}</p>
                </div>
                <div className="mt-4 rounded-md border border-slate-200 bg-white">
                  <div className="border-b border-slate-200 px-3 py-2">
                    <p className="text-sm font-bold text-slate-950">Result values</p>
                  </div>
                  <div className="divide-y divide-slate-200">
                    {result.values.map(([label, value]) => (
                      <div className="grid grid-cols-[180px_minmax(0,1fr)] gap-3 px-3 py-2 text-sm" key={label}>
                        <span className="font-semibold text-slate-600">{label}</span>
                        <span className="text-slate-950">{value}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
              <div className="flex justify-end gap-2 border-t border-slate-200 bg-slate-50 p-3">
                <Button variant="outline" onClick={onClose}>Close</Button>
                <Button onClick={() => onDownload(result)}>Download report</Button>
              </div>
            </>
          ) : null}
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

type IcuPatientEventRow = {
  id: string;
  type: "Vitals" | "Alert" | "Medication" | "Task" | "Result" | "I/O" | "Doctor" | "Handover";
  time: string;
  classification: string;
  severity: "Critical" | "High" | "Medium" | "Normal" | "Info";
  status: string;
  title: string;
  detail: string;
  owner: string;
  action: string;
  tone: DashboardCellTone;
};

function IcuPatientEventsWorkspace({ initialFocus, patient, results }: { initialFocus: IcuEventFocus; patient: IcuPatient; results: IcuPatientResultRow[] }) {
  const patientSelection = useWardNursePatientContext(patient);
  const activePatient = patientSelection.patient;
  const activeResults = activePatient.id === patient.id ? results : buildIcuPatientResultRows(activePatient);
  const events = React.useMemo(() => buildIcuPatientEvents(activePatient, activeResults), [activePatient, activeResults]);
  const [typeFilter, setTypeFilter] = React.useState(() => initialFocus === "open-alerts" ? "Alert" : "All events");
  const typeOptions = ["All events", "Vitals", "I/O", "Result", "Medication", "Alert"];
  const filteredEvents = events.filter((event) => typeFilter === "All events" || event.type === typeFilter);

  return (
    <div className="space-y-4">
      {patientSelection.selectable ? (
        <WardNursePatientContextSelector
          label="Patient"
          onChange={patientSelection.setPatientId}
          patients={patientSelection.assignedPatients}
          value={activePatient.id}
        />
      ) : null}

      <div className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-[0_14px_32px_rgba(15,23,42,0.05)]">
        <div className="grid gap-3 border-b border-slate-100 bg-white p-4 md:grid-cols-[minmax(220px,1fr)_auto] md:items-end">
          <NativeSelect label="Event type" value={typeFilter} onChange={setTypeFilter} options={typeOptions} />
          <Button variant="outline" onClick={() => {
            setTypeFilter("All events");
          }}>Reset</Button>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full min-w-[1180px] border-separate border-spacing-0 text-left text-sm">
            <thead className="sticky top-0 z-10 border-b border-slate-200 bg-slate-50 text-xs uppercase tracking-wide text-slate-500">
              <tr>
                <th className="px-3 py-3">Time</th>
                <th className="px-3 py-3">Event Type</th>
                <th className="px-3 py-3">Classification</th>
                <th className="px-3 py-3">Severity</th>
                <th className="px-3 py-3">Event</th>
                <th className="px-3 py-3">Details</th>
                <th className="px-3 py-3">Owner</th>
                <th className="px-3 py-3">Next Action</th>
              </tr>
            </thead>
            <tbody>
              {filteredEvents.map((event) => (
                <tr className="align-top even:bg-slate-50/45 hover:bg-sky-50/70 [&:last-child>td]:border-0" key={event.id}>
                  <td className="whitespace-nowrap border-b border-slate-100 px-3 py-3 text-sm font-bold text-slate-800">{event.time}</td>
                  <td className="border-b border-slate-100 px-3 py-3">
                    <span className={cn("inline-flex rounded-full border px-2.5 py-1 text-xs font-bold", dashboardTonePillClass(event.tone))}>{event.type}</span>
                  </td>
                  <td className="border-b border-slate-100 px-3 py-3 text-sm font-semibold text-slate-800">{event.classification}</td>
                  <td className="border-b border-slate-100 px-3 py-3">
                    <span className={cn("inline-flex rounded-full border px-2.5 py-1 text-xs font-bold", dashboardTonePillClass(icuPatientEventSeverityTone(event.severity)))}>{event.severity}</span>
                  </td>
                  <td className="border-b border-slate-100 px-3 py-3 text-sm font-bold text-slate-950">{event.title}</td>
                  <td className="border-b border-slate-100 px-3 py-3 text-xs leading-5 text-slate-500">{event.detail}</td>
                  <td className="border-b border-slate-100 px-3 py-3 text-xs font-semibold text-slate-600">{event.owner}</td>
                  <td className="border-b border-slate-100 px-3 py-3 text-xs font-bold text-slate-800">{event.action}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        {!filteredEvents.length ? <div className="p-6 text-center text-sm font-semibold text-slate-500">No patient event matched selected filters.</div> : null}
      </div>
    </div>
  );
}

function icuPatientEventSeverityTone(severity: IcuPatientEventRow["severity"]): DashboardCellTone {
  if (severity === "Critical") return "critical";
  if (severity === "High") return "danger";
  if (severity === "Medium") return "warning";
  if (severity === "Normal") return "success";
  return "info";
}

function icuPatientEventSeverityFromPriority(priority: string): IcuPatientEventRow["severity"] {
  if (priority === "Critical") return "Critical";
  if (priority === "High") return "High";
  if (priority === "Medium") return "Medium";
  if (priority === "Routine" || priority === "Low") return "Normal";
  return "Info";
}

type IcuShiftHandoverRow = {
  id: string;
  type: "Alert" | "Medication" | "Task" | "Doctor order" | "Report" | "I/O" | "Vitals" | "Completed";
  item: string;
  time: string;
  assignedTo: string;
  status: string;
  source: string;
  nextAction: string;
  tone: DashboardCellTone;
  focus: Exclude<IcuShiftFocus, "all">;
};

function IcuPatientShiftSummaryWorkspace({ initialFocus, patient }: { initialFocus: IcuShiftFocus; patient: IcuPatient }) {
  const shiftOptions = React.useMemo(() => icuShiftSummaryScenarios(), []);
  const [shift, setShift] = React.useState(shiftOptions[0]?.label ?? "Morning shift (07:00-15:00)");
  const [focus, setFocus] = React.useState<IcuShiftFocus>(initialFocus === "all" ? "pending" : initialFocus);
  const activeShift = shiftOptions.find((option) => option.label === shift) ?? shiftOptions[0];
  const patientHistoryDates = React.useMemo(() => {
    const dates = intakeOutputRows.filter((row) => row.patientId === patient.id).map((row) => row.date);
    return Array.from(new Set([...dates, TODAY_DATE])).sort().reverse();
  }, [patient.id]);
  const [historyDate, setHistoryDate] = React.useState(patientHistoryDates[0] ?? TODAY_DATE);
  const [outgoingNurse, setOutgoingNurse] = React.useState(patient.assignedWardNurse);
  const [incomingNurse, setIncomingNurse] = React.useState(activeShift?.incoming ?? patient.assignedWardNurse);
  const [unitReviewer, setUnitReviewer] = React.useState(patient.assignedUnitNurse);
  const summary = React.useMemo(() => buildWholeShiftSummary(patient, outgoingNurse, shift), [outgoingNurse, patient, shift]);
  const historyRows = React.useMemo(() => buildIcuShiftHistoryRows(patient, historyDate, shiftOptions), [historyDate, patient, shiftOptions]);
  const handoverRows = React.useMemo(() => buildIcuShiftHandoverRows(patient), [patient]);
  const actionableRows = handoverRows.filter((row) => row.focus !== "completed");
  const visibleRows = focus === "all" ? actionableRows : handoverRows.filter((row) => row.focus === focus);
  const criticalRows = handoverRows.filter((row) => row.focus === "critical");
  const pendingRows = handoverRows.filter((row) => row.focus === "pending");
  const wardNurseOptions = Array.from(new Set([patient.assignedWardNurse, activeShift?.outgoing, activeShift?.incoming, "Ward Nurse Kavita", "Ward Nurse Arjun", "Night Nurse Leena", "Ward Nurse Neha"].filter(Boolean)));
  const unitNurseOptions = Array.from(new Set([patient.assignedUnitNurse, "Unit Nurse Priya", "Unit Nurse Meera", "Head Nurse Sana"].filter(Boolean)));
  const updateShift = (nextShift: string) => {
    setShift(nextShift);
    const next = shiftOptions.find((option) => option.label === nextShift);
    if (next) {
      setOutgoingNurse(next.outgoing);
      setIncomingNurse(next.incoming);
      setUnitReviewer(next.reviewer);
    }
  };

  return (
    <div className="space-y-4">
      <CollapsibleCommandPanel
        title="Shift pending controls"
        summary={`${formatIcuShiftHistoryDate(historyDate)} | ${activeShift?.time ?? shift} | ${focus === "all" ? "All pending work" : focus}`}
      >
        <div className="grid gap-3 p-3 md:grid-cols-2 xl:grid-cols-5">
          <label className="space-y-1 text-sm">
            <span className="font-semibold text-slate-800">History date</span>
            <Input
              max={patientHistoryDates[0] ?? TODAY_DATE}
              min={patientHistoryDates.at(-1) ?? TODAY_DATE}
              type="date"
              value={historyDate}
              onChange={(event) => setHistoryDate(event.target.value)}
            />
          </label>
          <NativeSelect label="Shift window" value={shift} onChange={updateShift} options={shiftOptions.map((option) => option.label)} />
          <NativeSelect label="Outgoing ward nurse" value={outgoingNurse} onChange={setOutgoingNurse} options={wardNurseOptions} />
          <NativeSelect label="Incoming ward nurse" value={incomingNurse} onChange={setIncomingNurse} options={wardNurseOptions} />
          <NativeSelect label="Unit nurse reviewer" value={unitReviewer} onChange={setUnitReviewer} options={unitNurseOptions} />
          <NativeSelect label="Focus" value={focus} onChange={(value) => setFocus(normalizeIcuShiftFocus(value))} options={["all", "pending", "critical", "completed"]} />
        </div>
      </CollapsibleCommandPanel>

      <div className="grid gap-3 lg:grid-cols-[minmax(0,1fr)_44px_minmax(0,1fr)_minmax(0,1fr)] lg:items-stretch">
        <IcuShiftNurseRoleCard
          label="Outgoing ward nurse"
          name={outgoingNurse}
          tone="muted"
        />
        <div className="hidden items-center justify-center lg:flex">
          <ArrowRightLeft className="h-5 w-5 text-slate-400" />
        </div>
        <IcuShiftNurseRoleCard
          label="Incoming ward nurse"
          name={incomingNurse}
          tone="info"
        />
        <IcuShiftNurseRoleCard
          label="Unit nurse reviewer"
          name={unitReviewer}
          tone="muted"
        />
      </div>

      <div className="overflow-hidden rounded-md border border-slate-200 bg-white shadow-sm">
        <div className="flex flex-col gap-2 border-b border-slate-200 bg-white px-3 py-3 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <p className="text-sm font-black text-slate-950">Shift Pending Summary</p>
            <p className="mt-0.5 text-xs font-semibold text-slate-500">{patient.bedNo} | {patient.patientName} | {activeShift?.time ?? shift}</p>
          </div>
          <div className="flex flex-wrap gap-2">
            {(["all", "critical", "pending"] as IcuShiftFocus[]).map((option) => (
              <button
                className={cn(
                  "rounded-full border px-3 py-1 text-xs font-bold transition",
                  focus === option ? "border-sky-400 bg-sky-50 text-sky-900 shadow-sm" : "border-slate-200 bg-white text-slate-700 hover:border-slate-300 hover:bg-slate-50",
                )}
                key={option}
                type="button"
                onClick={() => setFocus(option)}
              >
                {option === "all" ? `All ${actionableRows.length}` : option === "critical" ? `Critical ${criticalRows.length}` : `Pending ${pendingRows.length}`}
              </button>
            ))}
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full min-w-[1120px] border-collapse text-left text-sm">
            <thead className="border-b border-slate-200 bg-slate-50 text-xs uppercase text-slate-500">
              <tr>
                <th className="px-3 py-3">Category</th>
                <th className="px-3 py-3">Pending Work</th>
                <th className="px-3 py-3">Due / Time</th>
                <th className="px-3 py-3">Assigned To</th>
                <th className="px-3 py-3">Status</th>
                <th className="px-3 py-3">Next Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200">
              {visibleRows.map((row) => (
                <tr className="align-middle hover:bg-slate-50" key={row.id}>
                  <td className="px-3 py-3">
                    <span className="inline-flex rounded-full border border-slate-200 bg-slate-50 px-2.5 py-1 text-xs font-bold text-slate-700">{row.type}</span>
                  </td>
                  <td className="px-3 py-3">
                    <p className="font-semibold leading-5 text-slate-700">{row.item}</p>
                  </td>
                  <td className="px-3 py-3 font-bold text-slate-800">{row.time}</td>
                  <td className="px-3 py-3 font-semibold text-slate-700">{row.assignedTo}</td>
                  <td className="px-3 py-3"><StatusPill tone={smartBedStatusToneFromDashboard(row.tone)}>{row.status}</StatusPill></td>
                  <td className="px-3 py-3 text-xs font-bold text-slate-800">{row.nextAction}</td>
                </tr>
              ))}
              {!visibleRows.length ? (
                <tr>
                  <td className="px-3 py-8 text-center text-sm font-semibold text-slate-500" colSpan={6}>No pending item for selected focus.</td>
                </tr>
              ) : null}
            </tbody>
          </table>
        </div>
      </div>

      <div className="grid gap-3 rounded-md border border-slate-200 bg-white p-3 lg:grid-cols-2">
        <InfoLine label="Active issues" value={summary.suggested.issues} />
        <InfoLine label="Pending medication" value={summary.suggested.pendingMeds} />
        <InfoLine label="Pending tests" value={summary.suggested.pendingTests} />
        <InfoLine label="Escalation risks" value={summary.suggested.risks} />
      </div>

      <div className="rounded-md border border-slate-200 bg-white">
        <div className="flex flex-col gap-2 border-b border-slate-200 px-3 py-3 sm:flex-row sm:items-start sm:justify-between">
          <p className="text-sm font-bold text-slate-950">Past shift history</p>
          <span className="rounded-full border border-sky-300 bg-sky-50 px-2.5 py-1 text-xs font-bold text-sky-700">{historyRows.length} shifts</span>
        </div>
        <div className="grid gap-3 p-3 lg:grid-cols-3">
          {historyRows.map((row) => (
            <div className={cn("rounded-md border border-slate-200 bg-white p-3 shadow-sm", patientDetailAccentClass(row.tone))} key={row.id}>
              <div className="flex items-start justify-between gap-2">
                <div>
                  <p className="text-sm font-bold text-slate-950">{row.shift}</p>
                  <p className="mt-1 text-xs text-slate-500">{row.time}</p>
                </div>
                <span className={cn("rounded-full border bg-white px-2.5 py-1 text-xs font-bold", patientDetailIconClass(row.tone))}>{row.status}</span>
              </div>
              <div className="mt-3 grid gap-2 text-xs">
                <InfoLine label="Outgoing" value={row.outgoing} />
                <InfoLine label="Incoming" value={row.incoming} />
                <InfoLine label="Reviewer" value={row.reviewer} />
                <InfoLine label="Recorded work" value={`${row.vitals} vitals, ${row.ioRows} I/O, ${row.meds} med rows`} />
                <InfoLine label="Watch" value={row.watch} />
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

function buildIcuShiftHandoverRows(patient: IcuPatient): IcuShiftHandoverRow[] {
  const alerts = icuAlerts
    .filter((row) => row.patientId === patient.id && row.status !== "Resolved")
    .map((row): IcuShiftHandoverRow => {
      const critical = row.severity === "Critical" || row.severity === "High";
      return {
        id: `shift-alert-${row.id}`,
        type: "Alert",
        item: `${row.type}: ${row.message}`,
        time: row.createdAt,
        assignedTo: row.owner,
        status: row.status,
        source: row.source,
        nextAction: row.status === "Open" ? "Acknowledge and close clinical response" : "Track closure",
        tone: critical ? "danger" : "warning",
        focus: critical ? "critical" : "pending",
      };
    });

  const meds = medicationRows
    .filter((row) => row.patientId === patient.id && (row.status === "Due" || row.status === "Late"))
    .map((row): IcuShiftHandoverRow => ({
      id: `shift-med-${row.id}`,
      type: "Medication",
      item: `${row.medication} ${row.dose}`,
      time: row.scheduledTime,
      assignedTo: row.administeredBy === "-" ? patient.assignedWardNurse : row.administeredBy,
      status: row.status,
      source: "MAR",
      nextAction: row.status === "Late" ? "Administer now or document hold reason" : "Administer due dose",
      tone: row.status === "Late" ? "danger" : "warning",
      focus: row.status === "Late" ? "critical" : "pending",
    }));

  const tasks = icuTasks
    .filter((row) => row.patientId === patient.id && row.status !== "Completed")
    .map((row): IcuShiftHandoverRow => {
      const critical = row.status === "Overdue" || row.status === "Escalated" || row.priority === "Critical";
      return {
        id: `shift-task-${row.id}`,
        type: "Task",
        item: row.title,
        time: row.dueTime,
        assignedTo: row.assignedTo,
        status: row.status,
        source: row.createdBy,
        nextAction: critical ? "Escalate or complete before handover" : "Complete in next shift",
        tone: critical ? "danger" : "warning",
        focus: critical ? "critical" : "pending",
      };
    });

  const instructions = doctorInstructions
    .filter((row) => row.patientId === patient.id && row.status !== "Completed")
    .map((row): IcuShiftHandoverRow => {
      const critical = row.priority === "Critical" || row.priority === "High";
      return {
        id: `shift-order-${row.id}`,
        type: "Doctor order",
        item: row.instruction,
        time: row.dueTime,
        assignedTo: row.assignedNurse,
        status: row.status,
        source: row.doctor,
        nextAction: "Acknowledge and document execution",
        tone: critical ? "danger" : "info",
        focus: critical ? "critical" : "pending",
      };
    });

  const reports = buildIcuPatientResultRows(patient)
    .filter((row) => row.status === "Pending" || row.status === "Critical" || row.reviewedBy.toLowerCase().includes("not reviewed"))
    .map((row): IcuShiftHandoverRow => {
      const critical = row.status === "Critical";
      return {
        id: `shift-report-${row.id}`,
        type: "Report",
        item: `${row.category}: ${row.reportName}`,
        time: row.reportedAt === "Awaited" ? `Ordered ${row.orderedAt}` : row.reportedAt,
        assignedTo: critical ? patient.dutyDoctor : patient.assignedWardNurse,
        status: row.status === "Pending" ? "Awaited" : row.reviewedBy.toLowerCase().includes("not reviewed") ? "Review pending" : row.status,
        source: row.source,
        nextAction: row.status === "Pending" ? "Collect/report follow-up" : critical ? "Inform doctor and document review" : "Get doctor sign-off",
        tone: critical ? "danger" : "warning",
        focus: critical ? "critical" : "pending",
      };
    });

  const fluidRows = intakeOutputRows
    .filter((row) => row.patientId === patient.id && (row.status === "Pending review" || (row.kind === "Output" && row.quantityMl < 30)))
    .slice(-6)
    .map((row): IcuShiftHandoverRow => {
      const lowOutput = row.kind === "Output" && row.quantityMl < 30;
      return {
        id: `shift-io-${row.id}`,
        type: "I/O",
        item: `${row.component} ${row.quantityMl} ml`,
        time: row.time,
        assignedTo: row.nurse,
        status: row.status,
        source: row.source,
        nextAction: lowOutput ? "Review urine/fluid plan" : "Verify I/O entry",
        tone: lowOutput ? "danger" : "warning",
        focus: lowOutput ? "critical" : "pending",
      };
    });

  const abnormalVitals = icuVitals
    .filter((row) => row.patientId === patient.id && row.abnormal)
    .slice(-2)
    .map((row): IcuShiftHandoverRow => ({
      id: `shift-vital-${row.id}`,
      type: "Vitals",
      item: `SpO2 ${row.spo2}%, BP ${row.bp}, RR ${row.respiratoryRate}/min`,
      time: row.time,
      assignedTo: row.nurse,
      status: "Abnormal",
      source: "Vitals chart",
      nextAction: "Repeat vitals and keep doctor informed",
      tone: "danger",
      focus: "critical",
    }));

  const completed = [
    ...medicationRows
      .filter((row) => row.patientId === patient.id && row.status === "Administered")
      .slice(-2)
      .map((row): IcuShiftHandoverRow => ({
        id: `shift-done-med-${row.id}`,
        type: "Completed",
        item: `${row.medication} ${row.dose} administered`,
        time: row.actualTime,
        assignedTo: row.administeredBy,
        status: "Completed",
        source: "MAR",
        nextAction: "No action",
        tone: "success",
        focus: "completed",
      })),
    ...intakeOutputRows
      .filter((row) => row.patientId === patient.id && (row.status === "Signed" || row.status === "Auto synced"))
      .slice(-2)
      .map((row): IcuShiftHandoverRow => ({
        id: `shift-done-io-${row.id}`,
        type: "Completed",
        item: `${row.kind}: ${row.component} ${row.quantityMl} ml`,
        time: row.time,
        assignedTo: row.nurse,
        status: row.status,
        source: row.source,
        nextAction: "No action",
        tone: "success",
        focus: "completed",
      })),
  ];

  const rows = [...alerts, ...meds, ...tasks, ...instructions, ...reports, ...fluidRows, ...abnormalVitals, ...completed];
  const priority: Record<IcuShiftHandoverRow["focus"], number> = { critical: 0, pending: 1, completed: 2 };
  return rows.sort((left, right) => priority[left.focus] - priority[right.focus] || left.time.localeCompare(right.time));
}

