function buildIcuShiftHistoryRows(patient: IcuPatient, date: string, shifts: ReturnType<typeof icuShiftSummaryScenarios>) {
  const latestIoDate = intakeOutputRows.filter((row) => row.patientId === patient.id).map((row) => row.date).sort().at(-1) ?? TODAY_DATE;
  return shifts.map((shift) => {
    const ioRows = intakeOutputRows.filter((row) => row.patientId === patient.id && row.date === date && isTimeInIcuShiftWindow(row.time, shift.label));
    const vitals = date === latestIoDate
      ? icuVitals.filter((row) => row.patientId === patient.id && isTimeInIcuShiftWindow(row.time, shift.label))
      : [];
    const meds = date === latestIoDate
      ? medicationRows.filter((row) => row.patientId === patient.id && isTimeInIcuShiftWindow(row.scheduledTime, shift.label))
      : [];
    const alerts = date === latestIoDate ? icuAlerts.filter((row) => row.patientId === patient.id && row.status !== "Resolved") : [];
    const lowOutput = ioRows.filter((row) => row.kind === "Output" && row.quantityMl < 30).length;
    const abnormalVitals = vitals.filter((row) => row.abnormal).length;
    const pendingIo = ioRows.filter((row) => row.status === "Pending review").length;
    const dueMeds = meds.filter((row) => row.status === "Due" || row.status === "Late").length;
    const actionCount = lowOutput + abnormalVitals + pendingIo + dueMeds + alerts.length;
    const tone: DashboardCellTone = actionCount >= 3 ? "danger" : actionCount ? "warning" : ioRows.length || vitals.length || meds.length ? "success" : "muted";
    const watch = [
      abnormalVitals ? `${abnormalVitals} abnormal vital(s)` : "",
      lowOutput ? `${lowOutput} low output row(s)` : "",
      pendingIo ? `${pendingIo} I/O pending review` : "",
      dueMeds ? `${dueMeds} medication due/late` : "",
      alerts.length ? `${alerts.length} open alert(s)` : "",
    ].filter(Boolean).join(", ");

    return {
      id: `${date}-${shift.label}`,
      shift: shift.label,
      time: shift.time,
      outgoing: shift.outgoing,
      incoming: shift.incoming,
      reviewer: shift.reviewer,
      vitals: vitals.length,
      ioRows: ioRows.length,
      meds: meds.length,
      status: actionCount ? "Needs watch" : ioRows.length || vitals.length || meds.length ? "Reviewed" : "No entries",
      tone,
      watch: watch || "No active issue captured for this shift date.",
    };
  });
}

function isTimeInIcuShiftWindow(time: string, shiftLabel: string) {
  const [hourValue = "0"] = time.split(":");
  const hour = Number.parseInt(hourValue, 10);
  if (!Number.isFinite(hour)) return false;
  if (shiftLabel.startsWith("Morning")) return hour >= 7 && hour < 15;
  if (shiftLabel.startsWith("Evening")) return hour >= 15 && hour < 23;
  if (shiftLabel.startsWith("Night")) return hour >= 23 || hour < 7;
  return true;
}

function formatIcuShiftHistoryDate(date: string) {
  const [, year = "", month = "", day = ""] = date.match(/^(\d{4})-(\d{2})-(\d{2})$/) ?? [];
  if (!year || !month || !day) return date;
  return `${day}/${month}/${year}`;
}

