function toneForPatientResult(status: IcuPatientResultStatus): DashboardCellTone {
  if (status === "Critical") return "critical";
  if (status === "Pending") return "warning";
  if (status === "Reviewed") return "success";
  return "info";
}

function downloadIcuPatientResult(result: IcuPatientResultRow) {
  if (result.status === "Pending") {
    toast.info("Report is pending, download will be available after result release.");
    return;
  }

  const content = [
    "Plasmit Hospital - ICU Diagnostic Result",
    `Report: ${result.reportName}`,
    `Type: ${result.category}`,
    `Status: ${result.status}`,
    `Source: ${result.source}`,
    `Ordered at: ${result.orderedAt}`,
    `Reported at: ${result.reportedAt}`,
    `Reviewed by: ${result.reviewedBy}`,
    "",
    "Summary:",
    result.summary,
    "",
    "Values:",
    ...result.values.map(([label, value]) => `${label}: ${value}`),
  ].join("\n");
  const blob = new Blob([content], { type: "text/plain;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = `${result.attachmentLabel.replace(/\.pdf$/i, "")}.txt`;
  link.click();
  URL.revokeObjectURL(url);
  toast.success(`${result.reportName} downloaded`);
}

