function IcuRound2Table({ children, columns, title }: { children: React.ReactNode; columns: string[]; title: string }) {
  return (
    <section className="overflow-hidden rounded-md border border-slate-200 bg-white">
      <div className="border-b border-slate-200 px-3 py-2">
        <h3 className="text-sm font-bold text-slate-950">{title}</h3>
      </div>
      <div className="overflow-auto">
        <table className="w-full min-w-[620px] border-collapse text-sm">
          <thead className="bg-slate-50">
            <tr className="border-b border-slate-200 text-[11px] uppercase text-slate-500">
              {columns.map((column) => <th className="px-3 py-2 text-left" key={column}>{column}</th>)}
            </tr>
          </thead>
          <tbody>{children}</tbody>
        </table>
      </div>
    </section>
  );
}

function DoctorRounds() {
  const [mode, setMode] = React.useState<DoctorRoundMode>("Daily Round");
  const [patientId, setPatientId] = React.useState(icuPatients[0]?.id ?? "");
  const selectedPatient = icuPatients.find((patient) => patient.id === patientId) ?? icuPatients[0];
  const [draft, setDraft] = React.useState<DoctorRoundDraft>(() => createDefaultDoctorRoundDraft(selectedPatient, "Daily Round"));
  const [savedRounds, setSavedRounds] = React.useState<DoctorRoundSavedRound[]>([]);
  const [roundFocus, setRoundFocus] = React.useState<DoctorRoundFocusFilter>("All focus");
  const [activeReview, setActiveReview] = React.useState<DoctorRoundReviewContext | null>(null);
  const [activePanel, setActivePanel] = React.useState<DoctorRoundPanelKind | null>(null);
  const doctorOptions = React.useMemo(() => getDoctorRoundDoctorOptions(mode), [mode]);
  const activeDoctor = doctorOptions.includes(draft.doctor) ? draft.doctor : (doctorOptions[0] ?? draft.doctor);
  const doctorPatients = React.useMemo(() => filterDoctorRoundPatients(mode, activeDoctor), [activeDoctor, mode]);

  const latestVital = [...icuVitals].reverse().find((vital) => vital.patientId === selectedPatient?.id);
  const patientAlerts = icuAlerts.filter((alert) => alert.patientId === selectedPatient?.id);
  const patientMeds = medicationRows.filter((row) => row.patientId === selectedPatient?.id);
  const patientInfusions = infusionRows.filter((row) => row.patientId === selectedPatient?.id);
  const patientTasks = icuTasks.filter((task) => task.patientId === selectedPatient?.id);
  const fluidBalance = intakeOutputRows.filter((row) => row.patientId === selectedPatient?.id).reduce((sum, row) => sum + row.balanceMl, 0);
  const roundScenarios = buildDoctorRoundScenarios({ mode, patient: selectedPatient, draft, latestVital, alerts: patientAlerts, meds: patientMeds, infusions: patientInfusions, tasks: patientTasks, fluidBalance });
  const blockingCount = roundScenarios.filter((scenario) => scenario.blocking).length;
  const generatedGoals = buildDoctorRoundGoals(draft, selectedPatient);
  const selectedPatientVisible = doctorPatients.some((patient) => patient.id === patientId);
  const roundCriticalCount = doctorPatients.filter((patient) => patient.criticalityScore >= 8 || patient.currentStatus === "Critical").length;
  const roundOpenAlerts = doctorPatients.reduce((sum, patient) => sum + icuAlerts.filter((alert) => alert.patientId === patient.id && alert.status !== "Resolved").length, 0);
  const roundDueMeds = doctorPatients.reduce((sum, patient) => sum + medicationRows.filter((row) => row.patientId === patient.id && ["Due", "Late"].includes(row.status)).length, 0);
  const roundPendingSign = doctorPatients.filter((patient) => !savedRounds.some((round) => doctorRoundSavedForPatient(round, patient))).length;
  const roundSignedCount = doctorPatients.filter((patient) => savedRounds.some((round) => doctorRoundSavedForPatient(round, patient))).length;

  const updateDraft = (key: keyof DoctorRoundDraft, value: string) => {
    setDraft((current) => ({ ...current, [key]: value }));
  };

  const selectPatient = (nextPatientId: string) => {
    const nextPatient = icuPatients.find((patient) => patient.id === nextPatientId) ?? selectedPatient;
    setPatientId(nextPatientId);
    setDraft(createDefaultDoctorRoundDraft(nextPatient, mode));
  };

  const selectDoctor = (doctor: string) => {
    const nextPatients = filterDoctorRoundPatients(mode, doctor);
    const nextPatient = nextPatients.find((patient) => patient.id === patientId) ?? nextPatients[0] ?? selectedPatient;
    if (nextPatient) {
      setPatientId(nextPatient.id);
    }
    setDraft({ ...createDefaultDoctorRoundDraft(nextPatient, mode), doctor });
  };

  const selectMode = (nextMode: DoctorRoundMode) => {
    const nextDoctor = getDoctorForRoundMode(selectedPatient, nextMode);
    const nextPatients = filterDoctorRoundPatients(nextMode, nextDoctor);
    const nextPatient = nextPatients.find((patient) => patient.id === patientId) ?? nextPatients[0] ?? selectedPatient;
    setMode(nextMode);
    if (nextPatient) {
      setPatientId(nextPatient.id);
    }
    setDraft({ ...createDefaultDoctorRoundDraft(nextPatient, nextMode), doctor: nextDoctor });
  };

  const saveRound = () => {
    if (!selectedPatient) return;
    if (blockingCount) {
      toast.error("Resolve mandatory round checks before signing.");
      return;
    }
    const investigationSummary = draft.investigationOrders.trim() ? `Tests: ${draft.investigationOrders.trim()}` : "Tests: not specified";
    const summary = mode === "Admitting Doctor"
      ? `${draft.provisionalDiagnosis}. ${draft.initialOrders}. ${investigationSummary}`
      : `${draft.problemList}. Decision: ${draft.decision}. ${investigationSummary}`;
    setSavedRounds((rows) => [
      { id: `round-${Date.now()}`, mode, patient: `${selectedPatient.bedNo} - ${selectedPatient.patientName}`, decision: draft.decision, summary, time: "Now" },
      ...rows,
    ]);
    toast.success(`${mode} signed for ${selectedPatient.patientName}`);
  };

  const createNurseInstruction = () => {
    toast.success(`Nurse instruction generated for ${selectedPatient?.bedNo}`);
  };

  const openRoundPanel = (nextPatientId: string, panel: DoctorRoundPanelKind) => {
    selectPatient(nextPatientId);
    setActivePanel(panel);
  };

  return (
    <div className="min-w-0 max-w-full space-y-4 overflow-hidden">
      <CollapsibleCommandPanel
        summary={`${mode} | ${activeDoctor} | ${selectedPatient?.bedNo ?? "-"} - ${selectedPatient?.patientName ?? "Patient"}`}
        title="Round mode & patient selection"
      >
        <div className="border-l-4 border-sky-600 bg-sky-50 px-4 py-3">
          <div className="space-y-3">
            <div className="flex flex-wrap items-center justify-between gap-2">
              <div className="flex flex-wrap items-center gap-2">
                <span className="text-[11px] font-black uppercase tracking-wide text-slate-600">Mode</span>
                {(["Admitting Doctor", "Daily Round"] as const).map((item) => (
                  <button
                    className={cn(
                      "inline-flex h-8 items-center justify-center gap-1.5 rounded-full border px-3 text-[11px] font-black transition",
                      mode === item ? "border-sky-700 bg-sky-600 text-white shadow-sm" : "border-slate-300 bg-white text-slate-700 hover:border-sky-400 hover:bg-sky-50",
                    )}
                    key={item}
                    type="button"
                    onClick={() => selectMode(item)}
                  >
                    {item === "Admitting Doctor" ? <Stethoscope className="h-3.5 w-3.5" /> : <ClipboardCheck className="h-3.5 w-3.5" />}
                    {item}
                  </button>
                ))}
              </div>
              <HospitalColourLegend />
            </div>

            <div className="grid gap-3 md:grid-cols-2">
              <label className="space-y-1 text-sm">
                <span className="font-semibold text-slate-800">{mode === "Admitting Doctor" ? "Admitting doctor" : "Round doctor"}</span>
                <select className="h-11 w-full rounded-md border border-slate-300 bg-white px-3 text-sm font-medium text-slate-900 outline-none focus:ring-2 focus:ring-sky-200" value={activeDoctor} onChange={(event) => selectDoctor(event.target.value)}>
                  {doctorOptions.map((doctor) => <option key={doctor}>{doctor}</option>)}
                </select>
              </label>

              <label className="space-y-1 text-sm">
                <span className="font-semibold text-slate-800">ICU patient ({doctorPatients.length})</span>
                <select className="h-11 w-full rounded-md border border-slate-300 bg-white px-3 text-sm font-medium text-slate-900 outline-none focus:ring-2 focus:ring-sky-200" value={selectedPatientVisible ? patientId : ""} onChange={(event) => selectPatient(event.target.value)} disabled={!doctorPatients.length}>
                  {!doctorPatients.length ? <option value="">No patient assigned</option> : null}
                  {doctorPatients.map((patient) => <option key={patient.id} value={patient.id}>{patient.bedNo} - {patient.patientName} | {patient.unit}</option>)}
                </select>
              </label>
            </div>
          </div>
        </div>
        {selectedPatient ? (
          <div className="flex flex-col gap-2 border-t border-slate-100 px-4 py-3 sm:flex-row sm:items-center sm:justify-end">
            <Button onClick={() => openRoundPanel(selectedPatient.id, "workspace")}>
              <Stethoscope className="h-4 w-4" />
              Round Entry
            </Button>
            <Link className="inline-flex h-9 items-center justify-center rounded-md border border-sky-300 bg-sky-50 px-3 text-sm font-bold text-sky-700 hover:bg-sky-100" href={icuPatientDailyChartHref(selectedPatient.id)}>
              Open ICU Daily Chart
            </Link>
          </div>
        ) : null}
      </CollapsibleCommandPanel>

      <DoctorRoundQueuePanel activePatientId={patientId} focus={roundFocus} mode={mode} patients={doctorPatients} savedRounds={savedRounds} selectedDoctor={activeDoctor} onFocusChange={setRoundFocus} onOpenPanel={openRoundPanel} onOpenReview={setActiveReview} onSelectDoctor={selectDoctor} onSelectPatient={selectPatient} />

      <DoctorRoundPanelDialog
        alerts={patientAlerts}
        draft={draft}
        fluidBalance={fluidBalance}
        generatedGoals={generatedGoals}
        latestVital={latestVital}
        meds={patientMeds}
        mode={mode}
        panel={activePanel}
        patient={selectedPatient}
        savedRounds={savedRounds}
        scenarios={roundScenarios}
        tasks={patientTasks}
        updateDraft={updateDraft}
        onCreateInstruction={createNurseInstruction}
        onOpenChange={(open) => !open && setActivePanel(null)}
        onSignRound={saveRound}
      />

      <DoctorRoundReviewDialog
        review={activeReview}
        onCreateInstruction={createNurseInstruction}
        onOpenChange={(open) => !open && setActiveReview(null)}
        onSignRound={saveRound}
      />
    </div>
  );
}

function DoctorRoundFocusMetric({
  active,
  label,
  value,
  tone,
  onClick,
}: {
  active: boolean;
  label: string;
  value: React.ReactNode;
  tone: DashboardCellTone;
  onClick: () => void;
}) {
  return (
    <button
      aria-pressed={active}
      className={cn(
        "inline-flex min-w-32 shrink-0 items-center justify-between gap-3 rounded-full border px-3 py-1.5 text-left shadow-sm transition hover:-translate-y-0.5 hover:shadow-md",
        dashboardTonePillClass(tone),
        active ? "ring-2 ring-sky-300 ring-offset-1" : "",
      )}
      type="button"
      onClick={onClick}
    >
      <span className="text-[11px] font-bold uppercase">{label}</span>
      <span className="text-sm font-black">{value}</span>
    </button>
  );
}

function DoctorRoundPanelDialog({
  alerts,
  draft,
  fluidBalance,
  generatedGoals,
  latestVital,
  meds,
  mode,
  panel,
  patient,
  savedRounds,
  scenarios,
  tasks,
  updateDraft,
  onCreateInstruction,
  onOpenChange,
  onSignRound,
}: {
  alerts: typeof icuAlerts;
  draft: DoctorRoundDraft;
  fluidBalance: number;
  generatedGoals: Array<{ title: string; detail: string }>;
  latestVital?: (typeof icuVitals)[number];
  meds: typeof medicationRows;
  mode: DoctorRoundMode;
  panel: DoctorRoundPanelKind | null;
  patient?: IcuPatient;
  savedRounds: DoctorRoundSavedRound[];
  scenarios: DoctorRoundScenario[];
  tasks: typeof icuTasks;
  updateDraft: (key: keyof DoctorRoundDraft, value: string) => void;
  onCreateInstruction: () => void;
  onOpenChange: (open: boolean) => void;
  onSignRound: () => void;
}) {
  const copy = panel ? doctorRoundPanelCopy(panel, mode) : null;

  return (
    <Dialog.Root open={Boolean(panel)} onOpenChange={onOpenChange}>
      <Dialog.Portal>
        <Dialog.Overlay className="fixed inset-0 z-50 bg-black/40 backdrop-blur-[1px]" />
        <Dialog.Content className="fixed left-1/2 top-1/2 z-50 flex max-h-[92dvh] w-[min(1040px,calc(100vw-24px))] -translate-x-1/2 -translate-y-1/2 flex-col overflow-hidden rounded-xl border border-border bg-surface shadow-soft outline-none">
          {panel && copy ? (
            <>
              <DialogHeader title={copy.title} description={patient ? `${patient.bedNo} | ${patient.patientName} | ${patient.unit}` : "Doctor round review"} />
              <div className="overflow-y-auto p-4">
                {panel === "previous" ? <DoctorRoundPreviousSummaryPanel alerts={alerts} meds={meds} patient={patient} savedRounds={savedRounds} tasks={tasks} /> : null}
                {panel === "current" ? <DoctorRoundThisReviewPanel draft={draft} fluidBalance={fluidBalance} latestVital={latestVital} mode={mode} patient={patient} /> : null}
                {panel === "workspace" ? (
                  mode === "Admitting Doctor"
                    ? <AdmittingDoctorWorkspace draft={draft} selectedPatient={patient} updateDraft={updateDraft} />
                    : <DailyRoundWorkspace draft={draft} selectedPatient={patient} updateDraft={updateDraft} />
                ) : null}
                {panel === "outputs" ? <DoctorRoundOutputsPanel blockingCount={scenarios.filter((scenario) => scenario.blocking).length} generatedGoals={generatedGoals} onCreateInstruction={onCreateInstruction} onSignRound={onSignRound} /> : null}
                {panel === "safety" ? <DoctorRoundScenarioPanel scenarios={scenarios} /> : null}
                {panel === "snapshot" ? <DoctorRoundClinicalPanel latestVital={latestVital} meds={meds} infusions={patient ? infusionRows.filter((row) => row.patientId === patient.id) : []} fluidBalance={fluidBalance} tasks={tasks} /> : null}
                {panel === "signed" ? <DoctorRoundSignedPanel patient={patient} savedRounds={savedRounds} /> : null}
              </div>
              <div className="flex flex-col-reverse gap-2 border-t border-border bg-surface-muted p-3 sm:flex-row sm:justify-end">
                <Dialog.Close asChild><Button variant="outline">Close</Button></Dialog.Close>
                <Button variant="outline" onClick={onCreateInstruction}><FileText className="h-4 w-4" />Create instruction</Button>
                <Button disabled={scenarios.some((scenario) => scenario.blocking)} onClick={onSignRound}><ClipboardCheck className="h-4 w-4" />Sign round</Button>
              </div>
            </>
          ) : null}
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

function doctorRoundPanelCopy(panel: DoctorRoundPanelKind, mode: DoctorRoundMode) {
  const workspaceTitle = mode === "Admitting Doctor" ? "Admit assessment" : "Daily plan";
  const map: Record<DoctorRoundPanelKind, { title: string }> = {
    previous: { title: "Previous summary" },
    current: { title: "This round review" },
    workspace: { title: workspaceTitle },
    outputs: { title: "Round outputs" },
    safety: { title: "Safety checks" },
    snapshot: { title: "Clinical snapshot" },
    signed: { title: "Signed rounds" },
  };
  return map[panel];
}

function DoctorRoundPreviousSummaryPanel({
  alerts,
  meds,
  patient,
  savedRounds,
  tasks,
}: {
  alerts: typeof icuAlerts;
  meds: typeof medicationRows;
  patient?: IcuPatient;
  savedRounds: DoctorRoundSavedRound[];
  tasks: typeof icuTasks;
}) {
  if (!patient) return <EmptyWorkflowState title="No patient selected" detail="Select patient from command matrix." />;
  const previousRound = savedRounds.find((round) => round.patient.includes(patient.bedNo) || round.patient.includes(patient.patientName));
  const previousSummary = previousRound?.summary ?? doctorRoundPreviousSummary(patient);
  const dueMeds = meds.filter((medication) => medication.status === "Due" || medication.status === "Late");
  const openAlerts = alerts.filter((alert) => alert.status !== "Resolved");
  const openTasks = tasks.filter((task) => task.status !== "Completed");

  return (
    <div className="rounded-md border border-slate-200 bg-white p-4 shadow-sm">
      <div className="flex items-start justify-between gap-3">
        <div>
          <p className="text-sm font-bold text-slate-950">Previous round summary</p>
          <p className="mt-1 text-xs text-slate-500">{patient.bedNo} - {patient.patientName}</p>
        </div>
        <Badge tone={previousRound ? "success" : "info"}>{previousRound ? previousRound.time : "No prior round"}</Badge>
      </div>
      <div className="mt-4 rounded-md border border-slate-200 bg-slate-50 p-3">
        <p className="text-sm font-semibold text-slate-900">{previousSummary}</p>
        <div className="mt-3 grid gap-2 text-xs text-slate-600 sm:grid-cols-2">
          <InfoPair label="Last decision" value={previousRound?.decision ?? doctorRoundDisposition(patient)} tone={doctorRoundDispositionInfoTone(patient)} />
          <InfoPair label="Unresolved alerts" value={`${openAlerts.length}`} tone={openAlerts.length ? "danger" : "success"} />
          <InfoPair label="Pending meds" value={`${dueMeds.length}`} tone={dueMeds.length ? "warning" : "success"} />
          <InfoPair label="Follow-up tasks" value={`${openTasks.length}`} tone={openTasks.length ? "warning" : "success"} />
        </div>
      </div>
    </div>
  );
}

function DoctorRoundThisReviewPanel({
  draft,
  fluidBalance,
  latestVital,
  mode,
  patient,
}: {
  draft: DoctorRoundDraft;
  fluidBalance: number;
  latestVital?: (typeof icuVitals)[number];
  mode: DoctorRoundMode;
  patient?: IcuPatient;
}) {
  if (!patient) return <EmptyWorkflowState title="No patient selected" detail="Select patient from command matrix." />;
  return (
    <div className="rounded-md border border-sky-200 bg-white p-4 shadow-sm">
      <div className="flex items-start justify-between gap-3">
        <div>
          <p className="text-sm font-bold text-slate-950">This round review</p>
          <p className="mt-1 text-xs text-slate-500">Doctor reviews current condition before signing.</p>
        </div>
        <Badge tone={mode === "Admitting Doctor" ? "info" : "warning"}>{mode}</Badge>
      </div>
      <div className="mt-4 grid gap-2 md:grid-cols-2">
        <InfoPair label="Latest vitals" value={latestVital ? `SpO2 ${latestVital.spo2}%, BP ${latestVital.bp}, Pulse ${latestVital.pulse}` : "No latest vitals"} tone={latestVital?.abnormal ? "danger" : "success"} />
        <InfoPair label="Fluid balance" value={`${fluidBalance} ml`} tone={fluidBalance > 400 ? "warning" : "success"} />
        <InfoPair label="Current decision" value={draft.decision} tone={doctorRoundDispositionInfoTone(patient)} />
        <InfoPair label="Test orders" value={draft.investigationOrders.trim() ? "Prepared" : "Pending"} tone={draft.investigationOrders.trim() ? "success" : "warning"} />
        <InfoPair label="Nursing instruction" value={draft.nursingInstructions ? "Prepared" : "Pending"} tone={draft.nursingInstructions ? "success" : "warning"} />
      </div>
      <div className="mt-3 rounded-md border border-sky-100 bg-sky-50 p-3">
        <p className="text-xs font-bold uppercase text-sky-700">Current assessment</p>
        <p className="mt-1 text-sm text-slate-900">{mode === "Admitting Doctor" ? draft.admissionAssessment : draft.problemList}</p>
      </div>
    </div>
  );
}

function DoctorRoundOutputsPanel({
  blockingCount,
  generatedGoals,
  onCreateInstruction,
  onSignRound,
}: {
  blockingCount: number;
  generatedGoals: Array<{ title: string; detail: string }>;
  onCreateInstruction: () => void;
  onSignRound: () => void;
}) {
  return (
    <div className="rounded-md border border-sky-200 bg-white p-4 shadow-sm">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <p className="text-sm font-bold text-slate-900">Round outputs</p>
          <p className="mt-1 text-xs text-slate-500">Goals, orders, nursing instructions, medication changes, and disposition.</p>
        </div>
        <div className="flex flex-wrap gap-2">
          <Button variant="outline" onClick={onCreateInstruction}><FileText className="h-4 w-4" />Create instruction</Button>
          <Button disabled={Boolean(blockingCount)} onClick={onSignRound}><ClipboardCheck className="h-4 w-4" />Sign round</Button>
        </div>
      </div>
      <div className="mt-4 grid gap-2 md:grid-cols-2">
        {generatedGoals.map((goal) => (
          <div className="rounded-md border border-slate-200 bg-slate-50 p-3" key={goal.title}>
            <p className="text-xs font-bold uppercase text-slate-500">{goal.title}</p>
            <p className="mt-1 text-sm text-slate-900">{goal.detail}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

function DoctorRoundSignedPanel({ patient, savedRounds }: { patient?: IcuPatient; savedRounds: DoctorRoundSavedRound[] }) {
  const rows = patient ? savedRounds.filter((round) => doctorRoundSavedForPatient(round, patient)) : savedRounds;
  return (
    <div className="rounded-md border border-slate-200 bg-white p-4 shadow-sm">
      <div className="flex items-center justify-between gap-3">
        <div>
          <p className="text-sm font-bold text-slate-900">Signed rounds</p>
          <p className="mt-1 text-xs text-slate-500">{patient ? `${patient.bedNo} - ${patient.patientName}` : "Session notes created from this screen."}</p>
        </div>
        <Badge tone="info">{rows.length}</Badge>
      </div>
      <div className="mt-3 space-y-2">
        {rows.map((round) => (
          <div className="rounded-md border border-slate-200 border-l-sky-500 bg-white p-3 shadow-sm" key={round.id}>
            <div className="flex items-start justify-between gap-2">
              <p className="text-sm font-bold text-slate-950">{round.patient}</p>
              <span className="rounded-full border border-sky-300 bg-white px-2 py-0.5 text-xs font-bold text-sky-700">{round.time}</span>
            </div>
            <p className="mt-1 text-xs text-slate-500">{round.mode} | {round.decision}</p>
            <p className="mt-2 text-xs text-slate-700">{round.summary}</p>
          </div>
        ))}
        {!rows.length ? <EmptyWorkflowState title="No signed round yet" detail="Complete mandatory checks and sign the round." /> : null}
      </div>
    </div>
  );
}

function AdmittingDoctorWorkspace({ draft, selectedPatient, updateDraft }: { draft: DoctorRoundDraft; selectedPatient?: IcuPatient; updateDraft: (key: keyof DoctorRoundDraft, value: string) => void }) {
  return (
    <div className="rounded-md border border-sky-200 bg-white p-4 shadow-sm">
      <div className="flex flex-wrap items-start justify-between gap-3 border-b border-sky-100 pb-4">
        <div>
          <p className="text-base font-bold text-slate-950">Admitting doctor assessment</p>
          <p className="mt-1 text-sm text-slate-500">{selectedPatient?.admissionSource} admission | {selectedPatient?.admissionTime}</p>
        </div>
        <span className={cn("rounded-full border px-3 py-1 text-xs font-bold", clinicalTonePillClass(toneForStatus(selectedPatient?.currentStatus ?? "Info")))}>{selectedPatient?.currentStatus ?? "Review"}</span>
      </div>
      <div className="mt-4 grid gap-3 md:grid-cols-2">
        <RoundTextField label="Round type" value={draft.roundType} onChange={(value) => updateDraft("roundType", value)} tone="info" />
        <RoundTextField label="Code status" value={draft.codeStatus} onChange={(value) => updateDraft("codeStatus", value)} tone="critical" />
        <RoundTextArea label="Provisional diagnosis" value={draft.provisionalDiagnosis} suggestions={getDoctorRoundAdviceOptions("provisionalDiagnosis")} onChange={(value) => updateDraft("provisionalDiagnosis", value)} tone="info" />
        <RoundTextArea label="Initial condition / assessment" value={draft.admissionAssessment} suggestions={getDoctorRoundAdviceOptions("admissionAssessment")} onChange={(value) => updateDraft("admissionAssessment", value)} tone="warning" />
        <RoundTextArea label="Medication reconciliation" value={draft.medicationReconciliation} suggestions={getDoctorRoundAdviceOptions("medicationReconciliation")} onChange={(value) => updateDraft("medicationReconciliation", value)} tone="danger" />
        <RoundTextArea label="Device / bed plan" value={draft.devicePlan} suggestions={getDoctorRoundAdviceOptions("devicePlan")} onChange={(value) => updateDraft("devicePlan", value)} tone="purple" />
        <RoundTextArea label="Initial orders" value={draft.initialOrders} suggestions={getDoctorRoundAdviceOptions("initialOrders")} onChange={(value) => updateDraft("initialOrders", value)} tone="info" />
        <RoundTextArea label="Investigation / test orders" value={draft.investigationOrders} suggestions={getDoctorRoundAdviceOptions("investigationOrders")} onChange={(value) => updateDraft("investigationOrders", value)} tone="warning" />
        <RoundTextArea label="Consults / family counselling" value={draft.consultPlan} suggestions={getDoctorRoundAdviceOptions("consultPlan")} onChange={(value) => updateDraft("consultPlan", value)} tone="success" />
      </div>
    </div>
  );
}

function DailyRoundWorkspace({ draft, selectedPatient, updateDraft }: { draft: DoctorRoundDraft; selectedPatient?: IcuPatient; updateDraft: (key: keyof DoctorRoundDraft, value: string) => void }) {
  return (
    <div className="rounded-md border border-sky-200 bg-white p-4 shadow-sm">
      <div className="flex flex-wrap items-start justify-between gap-3 border-b border-sky-100 pb-4">
        <div>
          <p className="text-base font-bold text-slate-950">Daily ICU round workspace</p>
          <p className="mt-1 text-sm text-slate-500">{selectedPatient?.bedNo} | ICU day review, system-wise plan, and decision.</p>
        </div>
        <label className="min-w-[230px] space-y-1 text-sm">
          <span className="font-semibold text-slate-800">Disposition decision</span>
          <select className="h-11 w-full rounded-md border border-slate-300 bg-white px-3 text-sm font-medium text-slate-900 outline-none focus:ring-2 focus:ring-sky-200" value={draft.decision} onChange={(event) => updateDraft("decision", event.target.value)}>
            {["Continue ICU care", "Transfer to ward", "Surgery review", "Discharge planning", "Goals-of-care discussion"].map((option) => <option key={option}>{option}</option>)}
          </select>
        </label>
      </div>
      <div className="mt-4 grid gap-3 md:grid-cols-2">
        <RoundTextArea label="Problem list / assessment" value={draft.problemList} suggestions={getDoctorRoundAdviceOptions("problemList", draft.decision)} onChange={(value) => updateDraft("problemList", value)} tone="info" />
        <RoundTextArea label="Respiratory / ventilator plan" value={draft.respiratoryPlan} suggestions={getDoctorRoundAdviceOptions("respiratoryPlan", draft.decision)} onChange={(value) => updateDraft("respiratoryPlan", value)} tone="purple" />
        <RoundTextArea label="Infection / antibiotic plan" value={draft.infectionPlan} suggestions={getDoctorRoundAdviceOptions("infectionPlan", draft.decision)} onChange={(value) => updateDraft("infectionPlan", value)} tone="warning" />
        <RoundTextArea label="Hemodynamic plan" value={draft.hemodynamicPlan} suggestions={getDoctorRoundAdviceOptions("hemodynamicPlan", draft.decision)} onChange={(value) => updateDraft("hemodynamicPlan", value)} tone="critical" />
        <RoundTextArea label="Renal / fluid plan" value={draft.renalFluidPlan} suggestions={getDoctorRoundAdviceOptions("renalFluidPlan", draft.decision)} onChange={(value) => updateDraft("renalFluidPlan", value)} tone="info" />
        <RoundTextArea label="Nutrition plan" value={draft.nutritionPlan} suggestions={getDoctorRoundAdviceOptions("nutritionPlan", draft.decision)} onChange={(value) => updateDraft("nutritionPlan", value)} tone="success" />
        <RoundTextArea label="Neuro / pain / sedation" value={draft.neuroPainPlan} suggestions={getDoctorRoundAdviceOptions("neuroPainPlan", draft.decision)} onChange={(value) => updateDraft("neuroPainPlan", value)} tone="purple" />
        <RoundTextArea label="Medication review" value={draft.medicationPlan} suggestions={getDoctorRoundAdviceOptions("medicationPlan", draft.decision)} onChange={(value) => updateDraft("medicationPlan", value)} tone="danger" />
        <RoundTextArea label="Investigation / test orders" value={draft.investigationOrders} suggestions={getDoctorRoundAdviceOptions("investigationOrders", draft.decision)} onChange={(value) => updateDraft("investigationOrders", value)} tone="warning" />
        <RoundTextArea label="Lines / devices" value={draft.linesDevicePlan} suggestions={getDoctorRoundAdviceOptions("linesDevicePlan", draft.decision)} onChange={(value) => updateDraft("linesDevicePlan", value)} tone="warning" />
        <RoundTextArea label="Nursing instructions" value={draft.nursingInstructions} suggestions={getDoctorRoundAdviceOptions("nursingInstructions", draft.decision)} onChange={(value) => updateDraft("nursingInstructions", value)} tone="info" />
        <RoundTextArea label="Pending follow-up" value={draft.pendingFollowUp} suggestions={getDoctorRoundAdviceOptions("pendingFollowUp", draft.decision)} onChange={(value) => updateDraft("pendingFollowUp", value)} tone="warning" />
        <RoundTextArea label="Family update" value={draft.familyUpdate} suggestions={getDoctorRoundAdviceOptions("familyUpdate", draft.decision)} onChange={(value) => updateDraft("familyUpdate", value)} tone="success" />
      </div>
    </div>
  );
}

function createDefaultDoctorRoundDraft(patient?: IcuPatient, mode: DoctorRoundMode = "Daily Round"): DoctorRoundDraft {
  const ventilated = patient?.ventilatorStatus !== "Room air";
  const critical = (patient?.criticalityScore ?? 0) >= 8;
  return {
    doctor: getDoctorForRoundMode(patient, mode),
    roundType: "Daily ICU consultant round",
    provisionalDiagnosis: patient?.diagnosis ?? "ICU diagnosis under review",
    admissionAssessment: `${patient?.currentStatus ?? "ICU"} patient admitted from ${patient?.admissionSource ?? "source"}. Confirm airway, breathing, circulation, disability, exposure, allergy, and medication history.`,
    medicationReconciliation: "Home/current medicines reviewed. Allergy and high-risk medicine checks pending final confirmation.",
    devicePlan: ventilated ? `Continue ${patient?.ventilatorStatus}. Verify monitor, oxygen/ventilator, infusion pump, Foley/lines, and removal need.` : "Monitor mapped. Oxygen/line/device need to be reviewed and de-escalated if possible.",
    initialOrders: critical ? "Vitals 15 min until stable, ABG/labs review, sepsis/critical care bundle, strict I/O, medication reconciliation." : "Vitals as per ICU protocol, labs review, medication reconciliation, nursing observation, discharge/transfer readiness review.",
    investigationOrders: critical || ventilated ? "ABG, CBC, electrolytes, RFT, LFT, lactate, culture if febrile, and chest X-ray/CT only as clinically indicated." : "Review routine ICU labs and pending reports; order repeat tests only if they change today's plan.",
    consultPlan: "Consulting doctor and duty doctor informed. Family counselling and consent status to be documented.",
    codeStatus: "Full code",
    problemList: patient?.diagnosis ?? "Active ICU problems",
    respiratoryPlan: ventilated ? `Review ${patient?.ventilatorStatus}, ABG, weaning readiness, sedation target, suction, and VAP bundle.` : "Maintain oxygen target, review respiratory rate/SpO2 trend, and de-escalate oxygen if stable.",
    infectionPlan: patient?.diagnosis.toLowerCase().includes("septic") ? "Review culture status, antibiotic day count, fever trend, source control, and de-escalation plan." : "Review fever trend, culture/lab status, antibiotic need, and infection prevention.",
    hemodynamicPlan: critical ? "MAP target > 65, fluid responsiveness, vasopressor need, lactate/urine output follow-up." : "Maintain BP target, review rhythm, perfusion, and escalation triggers.",
    renalFluidPlan: "Strict intake/output, urine output target, electrolyte/creatinine review, renal dose adjustment if needed.",
    nutritionPlan: "Review NPO/NG/oral status, feed tolerance, aspiration risk, and dietician input.",
    neuroPainPlan: "GCS/pupil trend, pain score, sedation goal, delirium prevention, and seizure precautions if indicated.",
    medicationPlan: "Continue/hold/stop medicines, check duplicate/high-risk medicines, renal dose, allergy, and pharmacy availability.",
    linesDevicePlan: "Review central line/Foley/ventilator/drains daily and remove unnecessary devices.",
    nursingInstructions: "Vitals as per risk, strict I/O, medication timing, escalation for SpO2/BP/GCS/urine output worsening.",
    pendingFollowUp: "Pending labs/radiology, consultant review, medication changes, family update, and transfer/discharge readiness.",
    familyUpdate: "Family updated about current condition, risks, and plan. Consent/review pending if condition changes.",
    decision: patient?.currentStatus === "Ready for transfer" ? "Transfer to ward" : "Continue ICU care",
  };
}

function getDoctorForRoundMode(patient?: IcuPatient, mode: DoctorRoundMode = "Daily Round") {
  if (!patient) return "Dr. Sameer Mehta";
  return mode === "Admitting Doctor" ? patient.admittingDoctor : patient.dutyDoctor;
}

function getDoctorRoundDoctorOptions(mode: DoctorRoundMode) {
  return Array.from(new Set(icuPatients.map((patient) => getDoctorForRoundMode(patient, mode)))).sort();
}

function filterDoctorRoundPatients(mode: DoctorRoundMode, doctor: string) {
  return icuPatients.filter((patient) => getDoctorForRoundMode(patient, mode) === doctor);
}

function buildDoctorRoundScenarios({
  mode,
  patient,
  draft,
  latestVital,
  alerts,
  meds,
  infusions,
  tasks,
  fluidBalance,
}: {
  mode: DoctorRoundMode;
  patient?: IcuPatient;
  draft: DoctorRoundDraft;
  latestVital?: (typeof icuVitals)[number];
  alerts: typeof icuAlerts;
  meds: typeof medicationRows;
  infusions: typeof infusionRows;
  tasks: typeof icuTasks;
  fluidBalance: number;
}): DoctorRoundScenario[] {
  const scenarios: DoctorRoundScenario[] = [];
  const openCriticalAlerts = alerts.filter((alert) => alert.status !== "Resolved" && alert.severity === "Critical");
  const dueMeds = meds.filter((med) => med.status === "Due" || med.status === "Late");
  const overdueTasks = tasks.filter((task) => task.status === "Overdue");
  const ventilated = patient?.ventilatorStatus !== "Room air";

  scenarios.push({
    id: "identity-context",
    title: patient ? `${patient.bedNo} patient selected` : "Patient missing",
    detail: patient ? `${patient.patientName}, ${patient.ageGender}, ${patient.diagnosis}.` : "Select a patient before signing a round.",
    tone: patient ? "info" : "danger",
    blocking: !patient,
  });

  if (mode === "Admitting Doctor") {
    scenarios.push({
      id: "admission-checklist",
      title: "Admission checklist",
      detail: "Diagnosis, allergy, medication reconciliation, initial orders, device mapping, code status, and family counselling must be captured.",
      tone: draft.medicationReconciliation && draft.initialOrders && draft.familyUpdate ? "success" : "warning",
      blocking: !draft.medicationReconciliation || !draft.initialOrders,
    });
  }

  if ((patient?.criticalityScore ?? 0) >= 8 || openCriticalAlerts.length) {
    scenarios.push({
      id: "critical-deterioration",
      title: "Critical deterioration watch",
      detail: `${openCriticalAlerts.length} critical alerts. Review vitals trend, sepsis/shock plan, escalation trigger, and duty doctor communication.`,
      tone: "critical",
    });
  }

  if (latestVital?.abnormal || (latestVital?.spo2 ?? 100) < 94 || (latestVital?.pulse ?? 0) > 120 || (latestVital?.urineOutput ?? 99) < 30) {
    scenarios.push({
      id: "vitals-risk",
      title: "Abnormal latest vitals",
      detail: latestVital ? `SpO2 ${latestVital.spo2}%, pulse ${latestVital.pulse}, BP ${latestVital.bp}, urine ${latestVital.urineOutput} ml/hr.` : "No latest vitals available.",
      tone: "danger",
    });
  }

  if (ventilated) {
    scenarios.push({
      id: "ventilator-bundle",
      title: "Ventilator / oxygen bundle",
      detail: "Review ABG, sedation goal, weaning readiness, suction, oral care, head elevation, and VAP prevention.",
      tone: "warning",
    });
  }

  if (patient?.diagnosis.toLowerCase().includes("septic") || draft.infectionPlan.toLowerCase().includes("antibiotic")) {
    scenarios.push({
      id: "infection-sepsis",
      title: "Sepsis / infection review",
      detail: "Capture culture status, antibiotic day count, fever trend, source control, and de-escalation date.",
      tone: "warning",
    });
  }

  if (!draft.investigationOrders.trim()) {
    scenarios.push({
      id: "investigation-orders",
      title: "Investigation / test orders pending",
      detail: "Add doctor-ordered labs/radiology or document that no new investigation is required for this round.",
      tone: "warning",
    });
  }

  if (dueMeds.length) {
    scenarios.push({
      id: "medication-review",
      title: "Medication action pending",
      detail: `${dueMeds.length} due/late medication rows. Review continue, hold, stop, duplicate, high-risk, renal dose, and pharmacy availability.`,
      tone: "danger",
    });
  }

  if (infusions.some((infusion) => infusion.status === "Running")) {
    scenarios.push({
      id: "infusion-review",
      title: "Running infusion review",
      detail: `${infusions.filter((infusion) => infusion.status === "Running").length} infusion(s) running. Confirm pump, rate, balance, and stop/titration target.`,
      tone: "warning",
    });
  }

  if (fluidBalance > 400 || (latestVital?.urineOutput ?? 99) < 30) {
    scenarios.push({
      id: "renal-fluid",
      title: "Renal / fluid balance risk",
      detail: `Current visible balance ${fluidBalance} ml. Review urine target, creatinine, diuretic/fluids, and renal dose adjustment.`,
      tone: "warning",
    });
  }

  if (overdueTasks.length) {
    scenarios.push({
      id: "nursing-followup",
      title: "Nursing follow-up overdue",
      detail: `${overdueTasks.length} overdue task(s). Generate clear nursing instructions before sign-off.`,
      tone: "danger",
    });
  }

  if (patient?.currentStatus === "Ready for transfer" && draft.decision !== "Transfer to ward") {
    scenarios.push({
      id: "transfer-readiness",
      title: "Transfer readiness mismatch",
      detail: "Patient is marked ready for transfer. Confirm ICU need or place transfer-to-ward decision.",
      tone: "warning",
    });
  }

  if (!draft.familyUpdate.trim()) {
    scenarios.push({
      id: "family-update",
      title: "Family update pending",
      detail: "Daily round should record family counselling, consent status, and goals-of-care discussion if needed.",
      tone: "warning",
    });
  }

  return scenarios;
}

function buildDoctorRoundGoals(draft: DoctorRoundDraft, patient?: IcuPatient) {
  return [
    { title: "Today's goals", detail: draft.problemList },
    { title: "Doctor orders", detail: draft.initialOrders || draft.medicationPlan },
    { title: "Test / investigation orders", detail: draft.investigationOrders || "No new investigation order" },
    { title: "Nursing instructions", detail: draft.nursingInstructions },
    { title: "Medication changes", detail: draft.medicationPlan },
    { title: "Pending follow-up", detail: draft.pendingFollowUp },
    { title: "Disposition", detail: `${draft.decision}${patient ? ` for ${patient.bedNo}` : ""}` },
  ];
}

function HospitalColourLegend() {
  const items = [
    ["Critical", "bg-red-600"],
    ["Warning", "bg-amber-500"],
    ["Orders", "bg-sky-600"],
    ["Stable", "bg-emerald-600"],
    ["Ventilator", "bg-violet-600"],
  ];
  return (
    <div className="hidden flex-wrap gap-2 lg:flex">
      {items.map(([label, color]) => (
        <span className="inline-flex items-center gap-1.5 text-[11px] font-semibold text-slate-600" key={label}>
          <span className={cn("h-2.5 w-2.5 rounded-full", color)} />
          {label}
        </span>
      ))}
    </div>
  );
}

function DoctorRoundQueuePanel({
  activePatientId,
  focus,
  mode,
  patients,
  savedRounds,
  selectedDoctor,
  onFocusChange,
  onOpenPanel,
  onOpenReview,
  onSelectDoctor,
  onSelectPatient,
}: {
  activePatientId: string;
  focus: DoctorRoundFocusFilter;
  mode: DoctorRoundMode;
  patients: IcuPatient[];
  savedRounds: DoctorRoundSavedRound[];
  selectedDoctor: string;
  onFocusChange: (focus: DoctorRoundFocusFilter) => void;
  onOpenPanel: (patientId: string, panel: DoctorRoundPanelKind) => void;
  onOpenReview: (review: DoctorRoundReviewContext) => void;
  onSelectDoctor: (doctor: string) => void;
  onSelectPatient: (patientId: string) => void;
}) {
  const [query, setQuery] = React.useState("");
  const [unit, setUnit] = React.useState("All ICU units");
  const [status, setStatus] = React.useState("All round status");
  const roundQueue = buildDoctorRoundQueue(mode, patients);
  const unitOptions = React.useMemo(() => ["All ICU units", ...Array.from(new Set(patients.map((patient) => patient.unit))).sort()], [patients]);
  const statusOptions = React.useMemo(() => ["All round status", ...Array.from(new Set(roundQueue.map((row) => doctorRoundRowStatus(row))))], [roundQueue]);
  const focusCounts = React.useMemo(() => doctorRoundFocusCounts(roundQueue, savedRounds), [roundQueue, savedRounds]);
  const roster = Array.from(new Set(icuPatients.map((patient) => mode === "Admitting Doctor" ? patient.admittingDoctor : patient.dutyDoctor))).map((doctor) => {
    const patients = icuPatients.filter((patient) => (mode === "Admitting Doctor" ? patient.admittingDoctor : patient.dutyDoctor) === doctor);
    const alertCount = patients.reduce((sum, patient) => sum + icuAlerts.filter((alert) => alert.patientId === patient.id && alert.status !== "Resolved").length, 0);
    return { doctor, patients, alertCount };
  });

  React.useEffect(() => {
    if (!unitOptions.includes(unit)) setUnit("All ICU units");
  }, [unit, unitOptions]);

  React.useEffect(() => {
    if (!statusOptions.includes(status)) setStatus("All round status");
  }, [status, statusOptions]);

  const visibleRows = roundQueue.filter((row) => {
    const patient = row.patient;
    const rowStatus = doctorRoundRowStatus(row);
    const searchText = `${patient.bedNo} ${patient.patientName} ${patient.mrn} ${patient.diagnosis} ${patient.unit} ${patient.dutyDoctor} ${patient.admittingDoctor} ${row.overnightEvent} ${row.pendingLabs} ${row.pendingOrders}`.toLowerCase();
    const matchesQuery = !query.trim() || searchText.includes(query.trim().toLowerCase());
    const matchesUnit = unit === "All ICU units" || patient.unit === unit;
    const matchesStatus = status === "All round status" || rowStatus === status;
    const matchesFocus = doctorRoundMatchesFocus(row, focus, savedRounds);
    return matchesQuery && matchesUnit && matchesStatus && matchesFocus;
  });
  const pagination = useIcuCommandPagination(visibleRows);

  return (
    <section className="overflow-hidden rounded-sm border border-slate-300 bg-white shadow-sm">
      <div className="border-b border-slate-200 bg-white p-3">
        <CollapsibleCommandPanel
          summary={`${selectedDoctor} | ${focus} | ${visibleRows.length}/${roundQueue.length} patient(s)`}
          title="Round controls"
        >
          <div className="space-y-3 p-3">
            <div className="grid items-end gap-3 md:grid-cols-2 xl:grid-cols-[minmax(260px,1.4fr)_repeat(4,minmax(150px,1fr))_auto]">
              <label className="space-y-1 text-sm">
                <span className="block text-xs font-semibold text-slate-700">Search patient / bed / diagnosis</span>
                <span className="relative block">
                  <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
                  <Input className="h-10 pl-9" placeholder="Search patient, MRN, bed, diagnosis..." value={query} onChange={(event) => setQuery(event.target.value)} />
                </span>
              </label>
              <IcuOperationsFilterSelect label={mode === "Admitting Doctor" ? "Admitting doctor" : "Round doctor"} value={selectedDoctor} onChange={onSelectDoctor} options={roster.map((row) => row.doctor)} />
              <IcuOperationsFilterSelect label="ICU unit" value={unit} onChange={setUnit} options={unitOptions} />
              <IcuOperationsFilterSelect label="Round focus" value={focus} onChange={(value) => onFocusChange(value as DoctorRoundFocusFilter)} options={DOCTOR_ROUND_FOCUS_FILTERS} />
              <IcuOperationsFilterSelect label="Round status" value={status} onChange={setStatus} options={statusOptions} />
              <Button className="h-10" variant="outline" onClick={() => {
                setQuery("");
                setUnit("All ICU units");
                setStatus("All round status");
                onFocusChange("All focus");
              }}>Reset</Button>
            </div>
          </div>
        </CollapsibleCommandPanel>
      </div>

      <div className="flex justify-end border-b border-slate-200 bg-white px-3 py-2">
        <IcuLegend />
      </div>

      <div className="max-h-[650px] overflow-auto">
        <table className="w-full min-w-[2350px] border-collapse bg-white text-sm">
          <thead className="sticky top-0 z-20 bg-white">
            <tr className="border-b border-slate-300 text-[11px] uppercase text-sky-700">
              <th className="sticky left-0 z-40 min-w-[230px] bg-white px-3 py-3 text-left">Patient / Bed</th>
              <th className="min-w-[120px] px-2 py-3 text-center">Risk</th>
              <th className="min-w-[150px] px-2 py-3 text-center">Latest vitals</th>
              <th className="min-w-[150px] px-2 py-3 text-center">Ventilation</th>
              <th className="min-w-[120px] px-2 py-3 text-center">Alerts</th>
              <th className="min-w-[120px] px-2 py-3 text-center">Due meds</th>
              <th className="min-w-[140px] px-2 py-3 text-center">Pending labs</th>
              <th className="min-w-[160px] px-2 py-3 text-center">Disposition</th>
              <th className="min-w-[150px] px-2 py-3 text-center">Round status</th>
              <th className="min-w-[120px] px-2 py-3 text-center">Previous</th>
              <th className="min-w-[120px] px-2 py-3 text-center">This round</th>
              <th className="min-w-[125px] px-2 py-3 text-center">{mode === "Admitting Doctor" ? "Admit assess" : "Daily plan"}</th>
              <th className="min-w-[120px] px-2 py-3 text-center">Output</th>
              <th className="min-w-[120px] px-2 py-3 text-center">Safety</th>
              <th className="min-w-[120px] px-2 py-3 text-center">Snapshot</th>
              <th className="min-w-[120px] px-2 py-3 text-center">Signed</th>
              <th className="min-w-[130px] px-2 py-3 text-center">Action</th>
            </tr>
          </thead>
          <tbody>
          {pagination.pageRows.map((row) => {
            const patient = row.patient;
            const openAlertCount = row.alertCount;
            const latestVital = [...icuVitals].reverse().find((vital) => vital.patientId === patient.id);
            const dueMeds = medicationRows.filter((medication) => medication.patientId === patient.id && ["Due", "Late"].includes(medication.status));
            const rowFluidBalance = intakeOutputRows.filter((entry) => entry.patientId === patient.id).reduce((sum, entry) => sum + entry.balanceMl, 0);
            const rowTasks = icuTasks.filter((task) => task.patientId === patient.id && task.status !== "Completed").length;
            const signedCount = savedRounds.filter((round) => doctorRoundSavedForPatient(round, patient)).length;
            const safetyCount = [
              patient.criticalityScore >= 8,
              openAlertCount > 0,
              dueMeds.length > 0,
              row.pendingLabs !== "None",
              rowFluidBalance > 400,
            ].filter(Boolean).length;
            const rowStatus = doctorRoundRowStatus(row);
            const rowTone = doctorRoundRowTone(row);
            const statusTone = doctorRoundStatusTone(rowStatus);
            const openReview = (kind: DoctorRoundMatrixKind) => {
              onSelectPatient(patient.id);
              onOpenReview(doctorRoundReviewContextFromRow(row, mode, kind));
            };
            const openPanel = (panel: DoctorRoundPanelKind) => {
              onOpenPanel(patient.id, panel);
            };
            return (
              <tr className={cn("border-b border-slate-200 last:border-b-0 hover:bg-sky-50/40", patient.id === activePatientId ? "bg-sky-50/70" : "")} key={row.id}>
                <td className="sticky left-0 z-10 bg-white px-3 py-2 align-middle shadow-[8px_0_14px_-15px_rgba(15,23,42,0.45)]">
                  <Link className="flex min-h-20 w-full flex-col justify-center rounded-md px-3 py-2 text-left transition hover:bg-sky-50" href={icuPatientDetailHref(patient.id, "overview")}>
                    <p className={cn("text-sm font-bold", dashboardToneTextClass(rowTone))}>{patient.patientName}</p>
                    <p className="mt-1 text-xs font-semibold text-slate-700">{row.roundNo}. {patient.bedNo}</p>
                    <p className="mt-1 truncate whitespace-nowrap text-xs text-slate-500">{patient.mrn} | {patient.unit}</p>
                  </Link>
                </td>
                <td className="px-2 py-2 text-center align-middle">
                  <IcuOpsMatrixCell icon={ShieldAlert} title={`Score ${patient.criticalityScore}`} detail={patient.criticalityScore >= 8 ? "Critical first" : patient.criticalityScore >= 6 ? "Watch" : "Stable"} tone={rowTone} showDetail={false} onClick={() => openReview("risk")} />
                </td>
                <td className="px-2 py-2 text-center align-middle">
                  <DoctorRoundLinkMatrixCell href={icuPatientDetailHref(patient.id, "monitoring", "24h-chart")} icon={HeartPulse} title={latestVital ? `SpO2 ${latestVital.spo2}%` : "No vitals"} detail={latestVital ? `BP ${latestVital.bp}` : "Chart pending"} tone={latestVital?.abnormal ? "danger" : "success"} showDetail={false} />
                </td>
                <td className="px-2 py-2 text-center align-middle">
                  <DoctorRoundLinkMatrixCell href={icuPatientDetailHref(patient.id, "monitoring", "ventilation")} icon={Activity} title={patient.ventilatorStatus} detail={patient.ventilatorStatus === "Room air" ? "No support" : "Ventilation chart"} tone={patient.ventilatorStatus === "Room air" ? "success" : "purple"} showDetail={false} />
                </td>
                <td className="px-2 py-2 text-center align-middle">
                  <DoctorRoundLinkMatrixCell href={icuPatientDetailHref(patient.id, "events")} icon={AlertTriangle} title={`${openAlertCount}`} detail={openAlertCount ? "Open alert" : "Clear"} tone={openAlertCount ? "danger" : "success"} showDetail={false} />
                </td>
                <td className="px-2 py-2 text-center align-middle">
                  <DoctorRoundLinkMatrixCell href={icuPatientDetailHref(patient.id, "orders")} icon={Pill} title={`${dueMeds.length}`} detail={dueMeds.some((medication) => medication.status === "Late") ? "Late dose" : dueMeds.length ? "Due now" : "No due"} tone={dueMeds.some((medication) => medication.status === "Late") ? "danger" : dueMeds.length ? "warning" : "success"} showDetail={false} />
                </td>
                <td className="px-2 py-2 text-center align-middle">
                  <DoctorRoundLinkMatrixCell href={icuPatientDetailHref(patient.id, "results")} icon={FileText} title={row.pendingLabs} detail={row.overnightEvent} tone={row.pendingLabs === "None" ? "success" : "warning"} showDetail={false} />
                </td>
                <td className="px-2 py-2 text-center align-middle">
                  <IcuOpsMatrixCell icon={ArrowRightLeft} title={doctorRoundDisposition(patient)} detail={row.pendingOrders} tone={doctorRoundDispositionTone(patient)} showDetail={false} onClick={() => openReview("disposition")} />
                </td>
                <td className="px-2 py-2 text-center align-middle">
                  <IcuOpsMatrixCell icon={ClipboardCheck} title={rowStatus} detail={mode} tone={statusTone} showDetail={false} onClick={() => openReview("status")} />
                </td>
                <td className="px-2 py-2 text-center align-middle">
                  <DoctorRoundPanelMatrixCell icon={Clock3} title="Previous" detail={signedCount ? "Saved" : "Last"} tone={signedCount ? "success" : "info"} showDetail={false} onClick={() => openPanel("previous")} />
                </td>
                <td className="px-2 py-2 text-center align-middle">
                  <DoctorRoundPanelMatrixCell icon={HeartPulse} title="This" detail={rowStatus} tone={statusTone} showDetail={false} onClick={() => openPanel("current")} />
                </td>
                <td className="px-2 py-2 text-center align-middle">
                  <DoctorRoundPanelMatrixCell icon={Stethoscope} title={mode === "Admitting Doctor" ? "Admit" : "Plan"} detail={mode === "Admitting Doctor" ? "Assess" : "Daily"} tone="info" showDetail={false} onClick={() => openPanel("workspace")} />
                </td>
                <td className="px-2 py-2 text-center align-middle">
                  <DoctorRoundPanelMatrixCell icon={ClipboardCheck} title="Output" detail={`${dueMeds.length} meds`} tone={dueMeds.length ? "warning" : "success"} showDetail={false} onClick={() => openPanel("outputs")} />
                </td>
                <td className="px-2 py-2 text-center align-middle">
                  <DoctorRoundPanelMatrixCell icon={ShieldAlert} title="Safety" detail={`${safetyCount} checks`} tone={safetyCount > 1 ? "danger" : safetyCount ? "warning" : "success"} showDetail={false} onClick={() => openPanel("safety")} />
                </td>
                <td className="px-2 py-2 text-center align-middle">
                  <DoctorRoundPanelMatrixCell icon={Activity} title="Snapshot" detail={`${rowTasks} tasks`} tone={latestVital?.abnormal || rowFluidBalance > 400 ? "warning" : "success"} showDetail={false} onClick={() => openPanel("snapshot")} />
                </td>
                <td className="px-2 py-2 text-center align-middle">
                  <DoctorRoundPanelMatrixCell icon={CheckCircle2} title="Signed" detail={`${signedCount}`} tone={signedCount ? "success" : "muted"} showDetail={false} onClick={() => openPanel("signed")} />
                </td>
                <td className="px-2 py-2 text-center align-middle">
                  <div className="flex min-h-20 items-center justify-center">
                    <button className="group flex min-h-20 w-full flex-col items-center justify-center" type="button" onClick={() => openPanel("workspace")}>
                      <span className={cn("inline-flex h-9 min-w-24 items-center justify-center gap-1 rounded-full px-3 text-xs font-black text-white shadow-[0_3px_8px_rgba(0,0,0,0.28)] transition group-hover:brightness-95", dashboardToneSolidClass(statusTone))}>
                        <Stethoscope className="h-4 w-4" />
                        <span className="max-w-20 truncate whitespace-nowrap">Entry</span>
                      </span>
                      <span className="invisible mt-1 block max-w-32 truncate whitespace-nowrap text-center text-[11px] font-semibold leading-tight text-slate-600" aria-hidden="true">Round Entry</span>
                    </button>
                  </div>
                </td>
              </tr>
            );
          })}
          {!visibleRows.length ? (
            <tr>
              <td className="px-4 py-12 text-center text-sm text-slate-500" colSpan={17}>No round patient matched the selected filters.</td>
            </tr>
          ) : null}
          </tbody>
        </table>
      </div>
      <IcuCommandPaginationControls {...pagination} />
    </section>
  );
}

