type DoctorRoundQueueRow = ReturnType<typeof buildDoctorRoundQueue>[number];

function doctorRoundFocusCounts(rows: DoctorRoundQueueRow[], savedRounds: DoctorRoundSavedRound[]): Record<DoctorRoundFocusFilter, number> {
  return DOCTOR_ROUND_FOCUS_FILTERS.reduce((counts, focus) => {
    counts[focus] = focus === "All focus" ? rows.length : rows.filter((row) => doctorRoundMatchesFocus(row, focus, savedRounds)).length;
    return counts;
  }, {} as Record<DoctorRoundFocusFilter, number>);
}

function doctorRoundMatchesFocus(row: DoctorRoundQueueRow, focus: DoctorRoundFocusFilter, savedRounds: DoctorRoundSavedRound[]) {
  if (focus === "All focus") return true;
  const patient = row.patient;
  const latestVital = [...icuVitals].reverse().find((vital) => vital.patientId === patient.id);
  const dueMeds = medicationRows.filter((medication) => medication.patientId === patient.id && ["Due", "Late"].includes(medication.status));
  const signedCount = savedRounds.filter((round) => doctorRoundSavedForPatient(round, patient)).length;
  if (focus === "Critical risk") return patient.criticalityScore >= 8 || patient.currentStatus === "Critical" || row.alertCount > 1;
  if (focus === "Abnormal vitals") return Boolean(latestVital?.abnormal || (latestVital && latestVital.spo2 < 94));
  if (focus === "Ventilator / device") return patient.ventilatorStatus !== "Room air";
  if (focus === "Open alerts") return row.alertCount > 0;
  if (focus === "Due meds") return dueMeds.length > 0;
  if (focus === "Pending labs") return row.pendingLabs !== "None";
  if (focus === "Pending sign") return signedCount === 0;
  if (focus === "Signed") return signedCount > 0;
  return true;
}

function doctorRoundFocusTone(focus: DoctorRoundFocusFilter): DashboardCellTone {
  if (focus === "Critical risk") return "critical";
  if (focus === "Abnormal vitals" || focus === "Due meds" || focus === "Pending labs" || focus === "Pending sign") return "warning";
  if (focus === "Ventilator / device") return "purple";
  if (focus === "Open alerts") return "danger";
  if (focus === "Signed") return "success";
  return "info";
}

function doctorRoundFocusHint(focus: DoctorRoundFocusFilter) {
  if (focus === "Critical risk") return "Score high / critical patient";
  if (focus === "Abnormal vitals") return "Vitals trend abnormal";
  if (focus === "Ventilator / device") return "Respiratory device support";
  if (focus === "Open alerts") return "Unresolved clinical alerts";
  if (focus === "Due meds") return "Due or late medicine";
  if (focus === "Pending labs") return "Result follow-up pending";
  if (focus === "Pending sign") return "Round not signed";
  if (focus === "Signed") return "Round completed";
  return "All round patients";
}

function doctorRoundReviewContextFromRow(row: DoctorRoundQueueRow, mode: DoctorRoundMode, kind: DoctorRoundMatrixKind): DoctorRoundReviewContext {
  return {
    patient: row.patient,
    kind,
    mode,
    roundNo: row.roundNo,
    alertCount: row.alertCount,
    overnightEvent: row.overnightEvent,
    pendingLabs: row.pendingLabs,
    pendingOrders: row.pendingOrders,
    rowStatus: doctorRoundRowStatus(row),
  };
}

