function DoctorRoundReviewDialogContent({
  review,
  onCreateInstruction,
  onSignRound,
}: {
  review: DoctorRoundReviewContext;
  onCreateInstruction: () => void;
  onSignRound: () => void;
}) {
  const copy = doctorRoundReviewCopy(review);
  const patient = review.patient;
  const latestVital = [...icuVitals].reverse().find((vital) => vital.patientId === patient.id);
  const alerts = icuAlerts.filter((alert) => alert.patientId === patient.id && alert.status !== "Resolved");
  const dueMeds = medicationRows.filter((medication) => medication.patientId === patient.id && ["Due", "Late"].includes(medication.status));
  const openTasks = icuTasks.filter((task) => task.patientId === patient.id && task.status !== "Completed");

  return (
    <>
      <DialogHeader title={copy.title} description={`${patient.bedNo} | ${patient.patientName} | ${patient.unit} | ${review.mode}`} />
      <div className="grid gap-4 overflow-y-auto p-4 lg:grid-cols-[290px_1fr]">
        <div className="space-y-3">
          <div className={cn("rounded-md border p-3", dashboardToneSurfaceClass(copy.tone))}>
            <div className="flex items-start justify-between gap-3">
              <div>
                <p className="text-sm font-bold text-slate-950">{patient.patientName}</p>
                <p className="mt-1 text-xs text-slate-600">{patient.mrn} | {patient.ageGender}</p>
              </div>
              <span className={cn("rounded-full border px-2 py-0.5 text-[11px] font-bold", dashboardTonePillClass(copy.tone))}>{copy.badge}</span>
            </div>
            <p className="mt-3 text-xs font-semibold text-slate-700">{copy.focus}</p>
          </div>
          <InfoPair label="Latest vitals" value={latestVital ? `SpO2 ${latestVital.spo2}%, BP ${latestVital.bp}` : "No vitals"} tone={latestVital?.abnormal ? "danger" : "success"} />
          <InfoPair label="Open alerts" value={`${alerts.length}`} tone={alerts.length ? "danger" : "success"} />
          <InfoPair label="Due / late meds" value={`${dueMeds.length}`} tone={dueMeds.length ? "warning" : "success"} />
          <InfoPair label="Open tasks" value={`${openTasks.length}`} tone={openTasks.length ? "warning" : "success"} />
        </div>

        <div className="space-y-4">
          <div className="rounded-lg border border-border bg-background p-3">
            <p className="text-sm font-semibold text-foreground">{copy.sectionTitle}</p>
            <div className="mt-3 grid gap-2 md:grid-cols-2">
              {copy.checklist.map((item, index) => (
                <label className="flex items-center gap-2 rounded-md border border-border bg-surface-muted p-2 text-sm" key={item}>
                  <input className="h-4 w-4 rounded border-input" type="checkbox" defaultChecked={index < 2} />
                  {item}
                </label>
              ))}
            </div>
          </div>

          <label className="space-y-1 text-sm">
            <span className="font-medium text-foreground">Doctor review note</span>
            <textarea className="min-h-28 w-full rounded-md border border-input bg-background p-3 text-sm outline-none focus:ring-2 focus:ring-ring/20" defaultValue={copy.note} />
          </label>
        </div>
      </div>
      <div className="flex flex-col-reverse gap-2 border-t border-border bg-surface-muted p-3 sm:flex-row sm:justify-end">
        <Dialog.Close asChild><Button variant="outline">Close</Button></Dialog.Close>
        <Button variant="outline" onClick={onCreateInstruction}><FileText className="h-4 w-4" />Create instruction</Button>
        <Button onClick={onSignRound}><ClipboardCheck className="h-4 w-4" />Sign round</Button>
      </div>
    </>
  );
}

function doctorRoundReviewCopy(review: DoctorRoundReviewContext): {
  title: string;
  badge: string;
  focus: string;
  sectionTitle: string;
  checklist: string[];
  note: string;
  tone: DashboardCellTone;
} {
  const patient = review.patient;
  const common = {
    note: `${patient.bedNo} ${patient.patientName}. ${review.rowStatus}. Overnight: ${review.overnightEvent}. Pending labs: ${review.pendingLabs}. Pending orders: ${review.pendingOrders}.`,
  };
  if (review.kind === "vitals") return {
    ...common,
    title: "Vitals review",
    badge: "Vitals",
    focus: "Doctor reviews latest vitals trend, abnormal values, escalation triggers, and monitoring frequency.",
    sectionTitle: "Vitals checklist",
    checklist: ["Latest vitals reviewed", "Abnormal trend compared with previous round", "Monitoring frequency updated", "Escalation trigger documented", "Nurse instruction created", "Follow-up time added"],
    tone: "danger",
  };
  if (review.kind === "ventilation") return {
    ...common,
    title: "Ventilation review",
    badge: "Ventilator",
    focus: `Current respiratory support: ${patient.ventilatorStatus}.`,
    sectionTitle: "Respiratory checklist",
    checklist: ["Oxygen/ventilator mode reviewed", "ABG/chest finding reviewed", "Weaning readiness checked", "Suction/VAP bundle reviewed", "Escalation plan documented", "Respiratory instruction created"],
    tone: patient.ventilatorStatus === "Room air" ? "success" : "purple",
  };
  if (review.kind === "alerts") return {
    ...common,
    title: "Alert review",
    badge: "Alerts",
    focus: `${review.alertCount} open alert(s) need doctor acknowledgement and action plan.`,
    sectionTitle: "Alert checklist",
    checklist: ["Critical alerts acknowledged", "Owner assigned", "Action note documented", "Repeat alert risk reviewed", "Nurse follow-up added", "Close only after clinical response"],
    tone: review.alertCount ? "danger" : "success",
  };
  if (review.kind === "medication") return {
    ...common,
    title: "Medication review",
    badge: "Medication",
    focus: "Doctor reviews due/late medication, renal dose, high-risk medicine, hold/continue/stop decision.",
    sectionTitle: "Medication checklist",
    checklist: ["Due/late dose reviewed", "Allergy and duplicate checked", "Renal/hepatic dose reviewed", "High-risk medicine verified", "Hold/stop/continue decision documented", "Pharmacy issue escalated if needed"],
    tone: "warning",
  };
  if (review.kind === "labs") return {
    ...common,
    title: "Lab / result review",
    badge: "Results",
    focus: `Pending labs/result focus: ${review.pendingLabs}.`,
    sectionTitle: "Result checklist",
    checklist: ["Pending labs reviewed", "Critical values checked", "Radiology/report follow-up added", "Repeat test need decided", "Treatment plan updated", "Next review time documented"],
    tone: review.pendingLabs === "None" ? "success" : "warning",
  };
  if (review.kind === "disposition") return {
    ...common,
    title: "Disposition review",
    badge: "Disposition",
    focus: `Current disposition suggestion: ${doctorRoundDisposition(patient)}.`,
    sectionTitle: "Disposition checklist",
    checklist: ["ICU need reviewed", "Transfer/discharge readiness checked", "Destination and handover plan reviewed", "Family update documented", "Pending blockers listed", "Decision added to this round"],
    tone: doctorRoundDispositionTone(patient),
  };
  if (review.kind === "risk") return {
    ...common,
    title: "Risk review",
    badge: `Score ${patient.criticalityScore}`,
    focus: "Doctor reviews criticality score, organ support, alerts, and today's risk priority.",
    sectionTitle: "Risk checklist",
    checklist: ["Risk score reviewed", "Clinical deterioration triggers checked", "Organ support plan updated", "Critical patient placed first", "Escalation owner confirmed", "Next senior review time documented"],
    tone: doctorRoundRowTone({ patient, alertCount: review.alertCount, pendingLabs: review.pendingLabs, pendingOrders: review.pendingOrders } as DoctorRoundQueueRow),
  };
  return {
    ...common,
    title: review.kind === "action" ? "Round action workspace" : "Patient round review",
    badge: review.rowStatus,
    focus: "Doctor reviews previous summary, current status, system plan, outputs, and then signs the round.",
    sectionTitle: "Round action checklist",
    checklist: ["Previous round summary reviewed", "Current assessment updated", "Orders/nursing instructions checked", "Disposition decision captured", "Family update reviewed", "Round ready to sign"],
    tone: doctorRoundStatusTone(review.rowStatus),
  };
}

function doctorRoundSavedForPatient(round: DoctorRoundSavedRound, patient: IcuPatient) {
  return round.patient.includes(patient.bedNo) || round.patient.includes(patient.patientName);
}

function doctorRoundPreviousSummary(patient: IcuPatient) {
  if (patient.currentStatus === "Critical") return "Previous round: patient remained critical; continue ICU care, strict monitoring, medication review, and family update required.";
  if (patient.ventilatorStatus !== "Room air") return "Previous round: respiratory support continued; ABG, ventilator bundle, sedation target, and weaning readiness to be reviewed.";
  if (patient.currentStatus === "Ready for transfer") return "Previous round: patient improving and transfer readiness to be confirmed after nursing, medication, and destination handover checks.";
  return "Previous round: stable ICU care continued with routine monitoring, medication review, pending results follow-up, and family update.";
}

function doctorRoundRowStatus(row: DoctorRoundQueueRow) {
  if (row.patient.criticalityScore >= 8 || row.alertCount > 1 || row.patient.currentStatus === "Critical") return "Critical review";
  if (row.patient.currentStatus === "Ready for transfer" || row.patient.currentStatus === "Discharge ordered") return "Disposition review";
  if (row.patient.pendingTasks || row.pendingLabs !== "None" || row.pendingOrders !== "None") return "Needs round";
  if (row.patient.currentStatus === "Stable ICU care") return "Ready to sign";
  return "Routine";
}

function doctorRoundRowTone(row: DoctorRoundQueueRow): DashboardCellTone {
  if (row.patient.criticalityScore >= 8 || row.alertCount > 1 || row.patient.currentStatus === "Critical") return "critical";
  if (row.patient.ventilatorStatus !== "Room air" || row.patient.currentStatus === "Ventilated") return "purple";
  if (row.patient.currentStatus === "Ready for transfer") return "success";
  if (row.patient.pendingTasks || row.pendingLabs !== "None") return "warning";
  return "info";
}

function doctorRoundStatusTone(status: string): DashboardCellTone {
  if (status === "Critical review") return "critical";
  if (status === "Disposition review" || status === "Ready to sign") return "success";
  if (status === "Needs round") return "warning";
  return "info";
}

function doctorRoundDisposition(patient: IcuPatient) {
  if (patient.currentStatus === "Ready for transfer") return "Transfer";
  if (patient.currentStatus === "Discharge ordered") return "Discharge";
  if (patient.currentStatus === "Death workflow") return "Goals care";
  if (patient.criticalityScore >= 8 || patient.ventilatorStatus !== "Room air") return "Continue ICU";
  return "Review";
}

function doctorRoundDispositionTone(patient: IcuPatient): DashboardCellTone {
  if (patient.currentStatus === "Death workflow") return "danger";
  if (patient.currentStatus === "Ready for transfer" || patient.currentStatus === "Discharge ordered") return "success";
  if (patient.criticalityScore >= 8) return "critical";
  if (patient.ventilatorStatus !== "Room air") return "purple";
  return "info";
}

function doctorRoundDispositionInfoTone(patient: IcuPatient): StatusTone {
  const tone = doctorRoundDispositionTone(patient);
  return tone === "purple" ? "warning" : tone;
}

function buildDoctorRoundQueue(mode: DoctorRoundMode, queuePatients: IcuPatient[]) {
  const overnightEvents = ["SpO2 dip", "ABG follow-up", "No major event", "Transfer stable", "Urine low", "Fever spike"];
  const pendingLabs = ["Lactate", "ABG", "CBC", "Culture", "Electrolytes", "None"];
  const pendingOrders = ["Medication review", "Ventilator order", "Fluid plan", "Transfer order", "Nursing task", "None"];
  return queuePatients.map((patient, index) => {
    const alertCount = icuAlerts.filter((alert) => alert.patientId === patient.id && alert.status !== "Resolved").length;
    const patientDueMedication = medicationRows.filter((row) => row.patientId === patient.id && ["Due", "Late"].includes(row.status)).length;
    const patientOpenTasks = icuTasks.filter((task) => task.patientId === patient.id && task.status !== "Completed").length;
    return {
      id: `${mode}-${patient.id}`,
      roundNo: index + 1,
      patient,
      alertCount,
      overnightEvent: overnightEvents[index % overnightEvents.length],
      pendingLabs: patient.criticalityScore >= 8 || patient.ventilatorStatus !== "Room air" ? pendingLabs[index % (pendingLabs.length - 1)] : "None",
      pendingOrders: patient.currentStatus === "Ready for transfer" || patient.currentStatus === "Discharge ordered"
        ? "Transfer order"
        : patientDueMedication
          ? "Medication review"
          : patientOpenTasks
            ? "Nursing task"
            : "None",
    };
  }).sort((first, second) => {
    const firstScore = first.patient.criticalityScore + first.alertCount * 2 + first.patient.pendingTasks / 2;
    const secondScore = second.patient.criticalityScore + second.alertCount * 2 + second.patient.pendingTasks / 2;
    return secondScore - firstScore;
  }).map((row, index) => ({ ...row, roundNo: index + 1 }));
}

