type IcuDischargeDestination =
  | "Ward"
  | "Step-down / HDU"
  | "Other ICU"
  | "OT / Procedure"
  | "Other hospital"
  | "Home discharge"
  | "LAMA / DAMA"
  | "Palliative / Hospice"
  | "Death workflow"
  | "Continue ICU";

type IcuDischargeStatus = "Not ready" | "Ordered" | "In progress" | "Ready" | "Blocked" | "Escalated";
type IcuDischargeDialogTab = "workflow" | "summary";
type IcuDischargeClearance = "Done" | "Pending" | "Blocked" | "Not needed";
type IcuDischargeClearanceKey = "Doctor" | "Nurse" | "Pharmacy" | "Lab/Radiology" | "Billing/Admin" | "Destination bed" | "Transport" | "Family";

type IcuDischargeWorkflowRow = {
  id: string;
  patient: IcuPatient;
  orderType: string;
  destinationType: IcuDischargeDestination;
  destination: string;
  receivingTeam: string;
  status: IcuDischargeStatus;
  priority: "Critical" | "High" | "Routine";
  eta: string;
  owner: string;
  transport: string;
  documentStatus: string;
  bedRelease: string;
  blockers: string[];
  clearances: Record<IcuDischargeClearanceKey, IcuDischargeClearance>;
  handover: string[];
};

const dischargeDestinationOptions: IcuDischargeDestination[] = [
  "Ward",
  "Step-down / HDU",
  "Other ICU",
  "OT / Procedure",
  "Other hospital",
  "Home discharge",
  "LAMA / DAMA",
  "Palliative / Hospice",
  "Death workflow",
  "Continue ICU",
];

const dischargeStatusOptions: IcuDischargeStatus[] = ["Not ready", "Ordered", "In progress", "Ready", "Blocked", "Escalated"];

function dischargePatient(id: string) {
  const patient = icuPatients.find((item) => item.id === id);
  if (!patient) throw new Error(`Missing ICU patient ${id}`);
  return patient;
}

