function TransferDischarge() {
  const { queryFocus, queryUnit } = useCommandRouteContext();
  const [search, setSearch] = React.useState("");
  const [unit, setUnit] = React.useState(queryUnit || "All ICU units");
  const [destination, setDestination] = React.useState("All destinations");
  const [status, setStatus] = React.useState("All status");
  const [activeWorkflow, setActiveWorkflow] = React.useState<{ row: IcuDischargeWorkflowRow; initialTab: IcuDischargeDialogTab } | null>(null);

  const unitOptions = React.useMemo(() => ["All ICU units", ...Array.from(new Set(icuDischargeRows.map((row) => row.patient.unit)))], []);
  React.useEffect(() => {
    if (queryUnit) setUnit(queryUnit);
  }, [queryUnit]);
  const filteredRows = React.useMemo(() => {
    const query = search.trim().toLowerCase();
    return icuDischargeRows.filter((row) => {
      const searchMatch = !query
        || row.patient.patientName.toLowerCase().includes(query)
        || row.patient.mrn.toLowerCase().includes(query)
        || row.patient.bedNo.toLowerCase().includes(query)
        || row.patient.diagnosis.toLowerCase().includes(query)
        || row.destination.toLowerCase().includes(query);
      const unitMatch = unit === "All ICU units" || row.patient.unit === unit;
      const destinationMatch = destination === "All destinations" || row.destinationType === destination;
      const statusMatch = status === "All status" || row.status === status;
      return searchMatch && unitMatch && destinationMatch && statusMatch;
    }).sort((left, right) => dischargeFocusRank(right, queryFocus) - dischargeFocusRank(left, queryFocus));
  }, [destination, queryFocus, search, status, unit]);
  const pagination = useIcuCommandPagination(filteredRows);

  const readyCount = icuDischargeRows.filter((row) => row.status === "Ready" || row.status === "Ordered").length;
  const inProgressCount = icuDischargeRows.filter((row) => row.status === "In progress").length;
  const blockedCount = icuDischargeRows.filter((row) => row.status === "Blocked" || row.status === "Escalated").length;
  const bedReleaseCount = icuDischargeRows.filter((row) => dischargeReadiness(row) >= 70).length;
  const externalCount = icuDischargeRows.filter((row) => row.destinationType === "Other hospital" || row.destinationType === "Other ICU").length;

  return (
    <div className="min-w-0 max-w-full space-y-4 overflow-hidden">
      <CollapsibleCommandPanel
        summary={`${unit} | ${destination} | ${status} | ${filteredRows.length} workflow(s)`}
        title="Transfer metrics & filters"
      >
        <div className="grid grid-cols-2 gap-2 border-b border-slate-200 px-3 py-3 sm:flex sm:flex-wrap sm:items-center">
          <DashboardCommandMetric label="Workflows" value={icuDischargeRows.length} tone="info" />
          <DashboardCommandMetric label="Visible" value={filteredRows.length} tone={filteredRows.length ? "info" : "muted"} />
          <DashboardCommandMetric label="Ready / ordered" value={readyCount} tone={readyCount ? "success" : "muted"} />
          <DashboardCommandMetric label="In progress" value={inProgressCount} tone={inProgressCount ? "warning" : "muted"} />
          <DashboardCommandMetric label="Blocked" value={blockedCount} tone={blockedCount ? "danger" : "success"} />
          <DashboardCommandMetric label="External" value={externalCount} tone={externalCount ? "critical" : "muted"} />
          <DashboardCommandMetric label="Bed release" value={bedReleaseCount} tone={bedReleaseCount ? "success" : "warning"} />
        </div>

        <div className="grid gap-2 p-3 md:grid-cols-2 xl:grid-cols-[minmax(260px,1.6fr)_repeat(3,minmax(160px,1fr))_auto]">
          <div className="relative">
            <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
            <Input className="h-10 pl-9" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search ICU patient, MRN, bed, destination..." />
          </div>
          <select className="h-10 rounded-md border border-slate-300 bg-white px-3 text-sm" value={unit} onChange={(event) => setUnit(event.target.value)}>
            {unitOptions.map((option) => <option key={option}>{option}</option>)}
          </select>
          <select className="h-10 rounded-md border border-slate-300 bg-white px-3 text-sm" value={destination} onChange={(event) => setDestination(event.target.value)}>
            {["All destinations", ...dischargeDestinationOptions].map((option) => <option key={option}>{option}</option>)}
          </select>
          <select className="h-10 rounded-md border border-slate-300 bg-white px-3 text-sm" value={status} onChange={(event) => setStatus(event.target.value)}>
            {["All status", ...dischargeStatusOptions].map((option) => <option key={option}>{option}</option>)}
          </select>
          <Button
            variant="outline"
            onClick={() => {
              setSearch("");
              setUnit("All ICU units");
              setDestination("All destinations");
              setStatus("All status");
            }}
          >
            Reset
          </Button>
        </div>
      </CollapsibleCommandPanel>

      <div className="overflow-hidden rounded-sm border border-slate-300 bg-white shadow-sm">
        <div className="max-h-[650px] overflow-auto">
          <table className="w-full min-w-[1420px] border-collapse bg-white text-sm">
            <thead className="sticky top-0 z-20 bg-white">
              <tr className="border-b border-slate-300 text-[11px] uppercase text-sky-700">
                <th className="sticky left-0 z-40 min-w-[190px] bg-white px-3 py-3 text-left">Patient</th>
                <th className="min-w-[240px] px-3 py-3 text-left">ICU context</th>
                <th className="min-w-[150px] px-2 py-3 text-center">Destination</th>
                <th className="min-w-[130px] px-2 py-3 text-center">Readiness</th>
                <th className="min-w-[120px] px-2 py-3 text-center">Blockers</th>
                <th className="min-w-[130px] px-2 py-3 text-center">Clearance</th>
                <th className="min-w-[130px] px-2 py-3 text-center">Handover</th>
                <th className="min-w-[130px] px-2 py-3 text-center">Transport</th>
                <th className="min-w-[130px] px-2 py-3 text-center">Bed release</th>
                <th className="min-w-[170px] px-2 py-3 text-center">Workflow / Summary</th>
              </tr>
            </thead>
            <tbody>
              {pagination.pageRows.map((row) => (
                <IcuDischargeBoardRow
                  key={row.id}
                  row={row}
                  onOpen={() => setActiveWorkflow({ row, initialTab: "workflow" })}
                />
              ))}
              {!filteredRows.length ? (
                <tr>
                  <td className="px-4 py-12 text-center text-sm text-slate-500" colSpan={10}>No ICU discharge workflow matched the selected filters.</td>
                </tr>
              ) : null}
            </tbody>
          </table>
        </div>
        <IcuCommandPaginationControls {...pagination} />
      </div>

      <IcuDischargeWorkflowDialog
        initialTab={activeWorkflow?.initialTab ?? "workflow"}
        row={activeWorkflow?.row ?? null}
        onOpenChange={(open) => !open && setActiveWorkflow(null)}
        onComplete={(row) => {
          toast.success(`Discharge workflow saved for ${row.patient.patientName}`);
          setActiveWorkflow(null);
        }}
      />
    </div>
  );
}

export function IcuDischargeSummaryPage({ workflowId }: { workflowId: string }) {
  const row = icuDischargeRows.find((workflow) => workflow.id === workflowId);

  if (!row) {
    return (
      <div className="min-w-0 max-w-full space-y-4 pb-8">
        <div className="rounded-md border border-slate-200 bg-white p-4 shadow-sm">
          <p className="text-base font-bold text-slate-950">Discharge summary not found</p>
          <p className="mt-1 text-sm text-slate-500">The selected ICU discharge workflow is not available for the current patient record.</p>
          <Button className="mt-4" variant="outline" asChild>
            <Link href="/icu-command-center/patients/discharges">Back to discharge dashboard</Link>
          </Button>
        </div>
      </div>
    );
  }

  const completion = dischargeReadiness(row);
  const admissionMeds = medicationRows.filter((medication) => medication.patientId === row.patient.id);
  const dischargeMeds = icuDischargeMedicationRows(row, row.destinationType, admissionMeds);
  const clinicalFindings = icuDischargeClinicalFindings(row, row.destinationType);
  const labRows = icuDischargeLabRows(row);
  const procedureRows = icuDischargeProcedureRows(row);
  const pendingRows = icuDischargePendingRows(row);

  return (
    <div className="min-w-0 max-w-full space-y-4 pb-8">
      <div className="rounded-md border border-slate-200 bg-white p-4 shadow-sm">
        <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
          <div className="min-w-0">
            <div className="flex flex-wrap items-center gap-2">
              <Badge tone="info">ICU discharge summary</Badge>
              <Badge tone={completion >= 80 ? "success" : completion >= 50 ? "warning" : "danger"}>{completion}% ready</Badge>
              <Badge tone={row.destinationType === "Death workflow" ? "danger" : "success"}>{row.destinationType === "Death workflow" ? "Death workflow" : "Alive"}</Badge>
            </div>
            <h1 className="mt-2 truncate text-xl font-bold text-slate-950">{row.patient.patientName} summary page</h1>
            <p className="mt-1 text-sm text-slate-500">
              {row.patient.bedNo} | {row.patient.mrn} | {row.patient.unit} | {row.destinationType} to {row.destination}
            </p>
          </div>
          <div className="flex flex-wrap gap-2">
            <Button variant="outline" asChild>
              <Link href="/icu-command-center/patients/discharges">Back to discharges</Link>
            </Button>
            <Button
              variant="outline"
              onClick={() => downloadIcuDischargeSummaryPdf(row, row.destinationType, completion, clinicalFindings, labRows, procedureRows, admissionMeds, dischargeMeds, pendingRows)}
            >
              <Download className="h-4 w-4" />
              Download PDF
            </Button>
            <Button asChild>
              <Link href={icuPatientDetailHref(row.patient.id, "overview")}>Open patient</Link>
            </Button>
          </div>
        </div>
      </div>

      <IcuDischargeSummaryTab row={row} destination={row.destinationType} completion={completion} />
    </div>
  );
}

function IcuDischargeBoardRow({
  row,
  onOpen,
}: {
  row: IcuDischargeWorkflowRow;
  onOpen: () => void;
}) {
  const readiness = dischargeReadiness(row);
  const clearanceDone = Object.values(row.clearances).filter((value) => value === "Done").length;
  const clearancePending = Object.values(row.clearances).filter((value) => value === "Pending" || value === "Blocked").length;

  return (
    <tr className="border-b border-slate-200 last:border-b-0 hover:bg-sky-50/40">
      <td className="sticky left-0 z-10 bg-white px-3 py-2 align-middle shadow-[8px_0_14px_-15px_rgba(15,23,42,0.45)]">
        <Link
          className="block min-h-16 rounded-md px-3 py-2 transition hover:bg-sky-50"
          href={icuPatientDetailHref(row.patient.id, "overview")}
          title={`Open ${row.patient.patientName} ICU detail`}
        >
          <p className={cn("truncate text-sm font-bold", dashboardToneTextClass(dischargePatientTone(row)))}>{row.patient.patientName}</p>
          <p className="mt-1 truncate text-xs font-semibold text-slate-700">{row.patient.bedNo} | {row.patient.unit}</p>
          <p className="mt-0.5 truncate text-xs text-slate-500">{row.patient.mrn} | {row.patient.ageGender}</p>
        </Link>
      </td>
      <td className="px-4 py-2 align-middle">
        <div className="min-h-16">
          <p className="text-sm font-bold text-slate-950">{row.orderType}</p>
          <p className="mt-1 text-xs text-slate-500">{row.patient.unit} | {row.patient.assignedWardNurse}</p>
        </div>
      </td>
      <td className="px-2 py-2 text-center align-middle">
        <IcuDischargeTrafficCell icon={ArrowRightLeft} title={row.destinationType} detail={row.destination} tone={dischargeDestinationTone(row)} showDetail={false} onClick={onOpen} />
      </td>
      <td className="px-2 py-2 text-center align-middle">
        <IcuDischargeTrafficCell icon={CheckCircle2} title={`${readiness}%`} detail={row.status} tone={dischargeReadinessTone(readiness)} showDetail={false} onClick={onOpen} />
      </td>
      <td className="px-2 py-2 text-center align-middle">
        <IcuDischargeActionCell icon={AlertTriangle} title={row.blockers.length ? `${row.blockers.length} open` : "Clear"} detail={row.blockers[0] ?? "No active blocker"} tone={dischargeBlockerTone(row)} showDetail={false} onClick={onOpen} />
      </td>
      <td className="px-2 py-2 text-center align-middle">
        <IcuDischargeTrafficCell icon={ClipboardCheck} title={`${clearanceDone} done`} detail={`${clearancePending} pending`} tone={clearancePending ? "warning" : "success"} showDetail={false} onClick={onOpen} />
      </td>
      <td className="px-2 py-2 text-center align-middle">
        <IcuDischargeActionCell icon={FileText} title={`${row.handover.length} points`} detail={row.handover[0] ?? row.receivingTeam} tone={row.handover.length >= 3 ? "info" : "warning"} showDetail={false} onClick={onOpen} />
      </td>
      <td className="px-2 py-2 text-center align-middle">
        <IcuDischargeActionCell icon={ArrowRightLeft} title={row.eta} detail={row.transport} tone={dischargeTransportTone(row)} showDetail={false} onClick={onOpen} />
      </td>
      <td className="px-2 py-2 text-center align-middle">
        <IcuDischargeTrafficCell icon={BedDouble} title={dischargeBedReleaseTitle(row)} detail={row.bedRelease} tone={dischargeBedReleaseTone(row)} showDetail={false} />
      </td>
      <td className="px-2 py-2 text-center align-middle">
        <div className="flex min-h-20 items-center justify-center gap-2">
          <button className="group flex flex-col items-center justify-center" type="button" onClick={onOpen} title={`Open workflow for ${row.patient.patientName}`}>
            <span className={cn("inline-flex h-10 w-10 items-center justify-center rounded-full text-white shadow-[0_3px_8px_rgba(0,0,0,0.28)] transition group-hover:brightness-95", dashboardToneSolidClass("info"))}>
              <ListChecks className="h-4 w-4" />
            </span>
            <span className="mt-1 text-xs font-bold text-slate-800">Workflow</span>
          </button>
          <Link className="group flex flex-col items-center justify-center" href={`/icu-command-center/patients/discharges/${row.id}/summary`} title={`Open discharge summary for ${row.patient.patientName}`}>
            <span className={cn("inline-flex h-10 w-10 items-center justify-center rounded-full text-white shadow-[0_3px_8px_rgba(0,0,0,0.28)] transition group-hover:brightness-95", dashboardToneSolidClass("success"))}>
              <FileText className="h-4 w-4" />
            </span>
            <span className="mt-1 text-xs font-bold text-slate-800">Summary</span>
          </Link>
        </div>
      </td>
    </tr>
  );
}

function IcuDischargeTrafficCell({
  icon: Icon,
  title,
  detail,
  tone,
  showDetail = true,
  onClick,
}: {
  icon: typeof Activity;
  title: string;
  detail: string;
  tone: DashboardCellTone;
  showDetail?: boolean;
  onClick?: () => void;
}) {
  const content = (
    <span className={cn("flex w-full min-w-24 flex-col items-center justify-center", showDetail ? "min-h-20" : "min-h-14")}>
      <span className={cn("inline-flex min-h-9 min-w-24 items-center justify-center gap-1 rounded-full px-3 text-xs font-black text-white shadow-[0_3px_8px_rgba(0,0,0,0.28)] transition", dashboardToneSolidClass(tone))}>
        <Icon className="h-4 w-4" />
        <span className="max-w-24 truncate">{title}</span>
      </span>
      {showDetail ? <span className="mt-1 block max-w-32 text-center text-[11px] font-semibold leading-tight text-slate-600">{detail}</span> : null}
    </span>
  );

  if (!onClick) return content;

  return (
    <button className="inline-flex w-full justify-center rounded-md outline-none transition hover:brightness-95 focus-visible:ring-2 focus-visible:ring-ring/30" type="button" onClick={onClick} title={`${title} - ${detail}`}>
      {content}
    </button>
  );
}

function IcuDischargeActionCell({
  icon: Icon,
  title,
  detail,
  tone,
  showDetail = true,
  onClick,
}: {
  icon: typeof Activity;
  title: string;
  detail: string;
  tone: DashboardCellTone;
  showDetail?: boolean;
  onClick?: () => void;
}) {
  const content = (
    <span className={cn("flex w-full min-w-24 flex-col items-center justify-center", showDetail ? "min-h-20" : "min-h-14")}>
      <span className={cn("inline-flex h-10 w-10 items-center justify-center rounded-full text-white shadow-[0_3px_8px_rgba(0,0,0,0.28)] transition", dashboardToneSolidClass(tone))}>
        <Icon className="h-4 w-4" />
      </span>
      <span className="mt-1 block text-center text-xs font-bold leading-tight text-slate-800">{title}</span>
      {showDetail ? <span className="mt-0.5 block max-w-32 truncate text-center text-[11px] leading-tight text-slate-500">{detail}</span> : null}
    </span>
  );

  if (!onClick) return content;

  return (
    <button className="inline-flex w-full justify-center" type="button" onClick={onClick} title={`${title} - ${detail}`}>
      {content}
    </button>
  );
}

function IcuDischargeWorkflowDialog({
  row,
  initialTab,
  onOpenChange,
  onComplete,
}: {
  row: IcuDischargeWorkflowRow | null;
  initialTab: IcuDischargeDialogTab;
  onOpenChange: (open: boolean) => void;
  onComplete: (row: IcuDischargeWorkflowRow) => void;
}) {
  return (
    <Dialog.Root open={Boolean(row)} onOpenChange={onOpenChange}>
      <Dialog.Portal>
        <Dialog.Overlay className="fixed inset-0 z-50 bg-black/40 backdrop-blur-[1px]" />
        <Dialog.Content className="fixed left-1/2 top-1/2 z-50 flex max-h-[92dvh] w-[min(1040px,calc(100vw-24px))] -translate-x-1/2 -translate-y-1/2 flex-col overflow-hidden rounded-xl border border-border bg-surface shadow-soft outline-none">
          {row ? <IcuDischargeWorkflowContent initialTab={initialTab} key={`${row.id}-${initialTab}`} row={row} onComplete={onComplete} onOpenChange={onOpenChange} /> : null}
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

function IcuDischargeWorkflowContent({
  row,
  initialTab,
  onOpenChange,
  onComplete,
}: {
  row: IcuDischargeWorkflowRow;
  initialTab: IcuDischargeDialogTab;
  onOpenChange: (open: boolean) => void;
  onComplete: (row: IcuDischargeWorkflowRow) => void;
}) {
  const [activeTab, setActiveTab] = React.useState<IcuDischargeDialogTab>(initialTab);
  const [destination, setDestination] = React.useState<IcuDischargeDestination>(row.destinationType);
  const [status, setStatus] = React.useState<IcuDischargeStatus>(row.status);
  const [checkedItems, setCheckedItems] = React.useState<Record<string, boolean>>(() => {
    const checklist = dischargeChecklistForDestination(row.destinationType, row);
    return Object.fromEntries(checklist.map((item) => [item.label, item.status === "Done"]));
  });

  const checklist = React.useMemo(() => dischargeChecklistForDestination(destination, row), [destination, row]);
  const completed = checklist.filter((item) => checkedItems[item.label]).length;
  const completion = checklist.length ? Math.round((completed / checklist.length) * 100) : 0;

  return (
    <>
      <DialogHeader title={`${row.patient.patientName} ICU discharge workflow`} description={`${row.patient.bedNo} | ${row.patient.mrn} | ${row.patient.unit} | ${row.orderType}`} />
      <div className="grid gap-4 overflow-y-auto p-4 lg:grid-cols-[300px_1fr]">
        <div className="space-y-3">
          <PatientMiniCard patient={row.patient} />
          <div className="rounded-md border border-border bg-background p-3">
            <div className="flex items-center justify-between gap-3">
              <div>
                <p className="text-sm font-semibold text-foreground">Workflow readiness</p>
                <p className="text-xs text-muted-foreground">Checklist completion for selected scenario.</p>
              </div>
              <Badge tone={completion >= 80 ? "success" : completion >= 50 ? "warning" : "danger"}>{completion}%</Badge>
            </div>
            <div className="mt-3 h-2 overflow-hidden rounded-full bg-surface-muted">
              <div className={cn("h-full rounded-full", dischargeReadinessBarClass(completion))} style={{ width: `${completion}%` }} />
            </div>
          </div>
          <MiniList title="Active blockers" rows={row.blockers} empty="No blocker for selected patient" />
          <MiniList title="SBAR handover points" rows={row.handover} />
        </div>

        <div className="space-y-4">
          <div className="flex flex-wrap gap-2 rounded-lg border border-border bg-surface-muted p-2">
            {[
              { id: "workflow", label: "Workflow" },
              { id: "summary", label: "Discharge Summary" },
            ].map((tab) => (
              <button
                className={cn(
                  "inline-flex h-9 items-center rounded-md px-4 text-sm font-semibold transition",
                  activeTab === tab.id ? "bg-primary text-primary-foreground shadow-sm" : "bg-background text-muted-foreground hover:text-foreground",
                )}
                key={tab.id}
                type="button"
                onClick={() => setActiveTab(tab.id as "workflow" | "summary")}
              >
                {tab.label}
              </button>
            ))}
          </div>

          {activeTab === "workflow" ? (
            <>
              <div className="grid gap-3 md:grid-cols-2">
                <NativeSelect label="Workflow scenario" value={destination} onChange={(value) => setDestination(value as IcuDischargeDestination)} options={dischargeDestinationOptions} />
                <NativeSelect label="Workflow status" value={status} onChange={(value) => setStatus(value as IcuDischargeStatus)} options={dischargeStatusOptions} />
                <WorkflowField label="Destination / location" value={destination === row.destinationType ? row.destination : dischargeDefaultDestination(destination)} />
                <WorkflowField label="Receiving team" value={destination === row.destinationType ? row.receivingTeam : dischargeDefaultReceivingTeam(destination)} />
                <WorkflowField label="Transport plan" value={destination === row.destinationType ? row.transport : dischargeDefaultTransport(destination)} />
                <WorkflowField label="Bed release plan" value={destination === row.destinationType ? row.bedRelease : dischargeDefaultBedRelease(destination)} />
              </div>

              <div className="rounded-lg border border-border bg-background">
                <div className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
                  <div>
                    <p className="text-sm font-semibold text-foreground">Scenario checklist</p>
                    <p className="text-xs text-muted-foreground">Doctor, nurse, destination, transport, documentation, and family readiness.</p>
                  </div>
                  <Badge tone={completion === 100 ? "success" : "warning"}>{completed}/{checklist.length} complete</Badge>
                </div>
                <div className="grid gap-2 p-3 md:grid-cols-2">
                  {checklist.map((item) => {
                    const checked = Boolean(checkedItems[item.label]);
                    return (
                      <label className={cn("flex gap-3 rounded-md border p-3 text-sm", checked ? "border-success/30 bg-success/10" : "border-border bg-surface-muted")} key={item.label}>
                        <input
                          className="mt-1 h-4 w-4 rounded border-input"
                          type="checkbox"
                          checked={checked}
                          onChange={(event) => setCheckedItems((current) => ({ ...current, [item.label]: event.target.checked }))}
                        />
                        <span>
                          <span className="flex items-center gap-2 font-medium text-foreground">
                            {checked ? <CheckCircle2 className="h-4 w-4 text-success" /> : <Clock3 className="h-4 w-4 text-muted-foreground" />}
                            {item.label}
                          </span>
                          <span className="mt-1 block text-xs text-muted-foreground">{item.owner} | {item.note}</span>
                        </span>
                      </label>
                    );
                  })}
                </div>
              </div>
            </>
          ) : (
            <IcuDischargeSummaryTab row={row} destination={destination} completion={completion} />
          )}
        </div>
      </div>
      <DialogFooter
        onCancel={() => onOpenChange(false)}
        primaryLabel={activeTab === "summary" ? "Save summary" : status === "Ready" ? "Confirm movement" : "Save workflow"}
        primaryVariant={destination === "Death workflow" ? "danger" : "default"}
        onPrimary={() => onComplete(row)}
      />
    </>
  );
}

function IcuDischargeSummaryTab({ row, destination, completion }: { row: IcuDischargeWorkflowRow; destination: IcuDischargeDestination; completion: number }) {
  const [previewOpen, setPreviewOpen] = React.useState(false);
  const [clinicalFindings, setClinicalFindings] = React.useState(() => icuDischargeClinicalFindings(row, destination));
  const summaryTitle = icuDischargeSummaryTitle(destination);
  const latestVital = [...icuVitals].reverse().find((vital) => vital.patientId === row.patient.id);
  const admissionMeds = medicationRows.filter((medication) => medication.patientId === row.patient.id);
  const dischargeMeds = icuDischargeMedicationRows(row, destination, admissionMeds);
  const labRows = icuDischargeLabRows(row);
  const procedureRows = icuDischargeProcedureRows(row);
  const pendingRows = icuDischargePendingRows(row);
  const summaryStatus = destination === "Death workflow" ? "Ready for death documentation" : destination === "Continue ICU" ? "Not applicable until transfer" : "Draft";
  const finalStatus = destination === "Death workflow" ? "Death" : "Alive";

  return (
    <div className="space-y-4">
      <div className="overflow-hidden rounded-lg border border-primary/20 bg-background">
        <div className="border-b border-border bg-gradient-to-r from-primary/10 via-surface to-success/10 px-4 py-4">
          <div className="flex flex-col gap-4 xl:flex-row xl:items-center xl:justify-between">
            <div className="min-w-0">
              <div className="flex flex-wrap items-center gap-2">
                <Badge tone="info">{summaryTitle}</Badge>
                <Badge tone={summaryStatus === "Draft" ? "warning" : "info"}>{summaryStatus}</Badge>
                <Badge tone={pendingRows.length ? "warning" : "success"}>{pendingRows.length ? `${pendingRows.length} pending` : "No pending blocker"}</Badge>
              </div>
              <h2 className="mt-2 truncate text-xl font-semibold text-foreground">{row.patient.patientName} discharge document</h2>
              <p className="mt-1 text-sm text-muted-foreground">
                {icuDischargeSummaryNo(row)} | {row.patient.mrn} | {row.patient.bedNo} | {row.patient.admittingDoctor}
              </p>
            </div>
            <div className="grid gap-2 sm:grid-cols-3 xl:min-w-[460px]">
              <IcuSummaryHeroMetric label="Completion" value={`${completion}%`} />
              <IcuSummaryHeroMetric label="Movement type" value={icuDischargeTypeLabel(destination)} />
              <IcuSummaryHeroMetric label="Status" value={finalStatus} />
            </div>
          </div>
        </div>
        <div className="grid gap-3 p-4 lg:grid-cols-[1fr_auto] lg:items-center">
          <div className="text-sm text-muted-foreground">
            ICU transfer/discharge summary follows the same discharge module format, with ICU destination, support devices, pending reports, medication, handover, and bed release context.
          </div>
          <div className="flex flex-wrap gap-2">
            <Button size="sm" variant="outline" onClick={() => toast.success("ICU discharge summary draft saved")}>
              <ClipboardCheck className="h-4 w-4" />
              Save Draft
            </Button>
            <Button size="sm" variant="outline" onClick={() => setPreviewOpen(true)}>
              <FileText className="h-4 w-4" />
              Preview PDF
            </Button>
            <Button size="sm" variant="outline" onClick={() => downloadIcuDischargeSummaryPdf(row, destination, completion, clinicalFindings, labRows, procedureRows, admissionMeds, dischargeMeds, pendingRows)}>
              <Download className="h-4 w-4" />
              Download PDF
            </Button>
          </div>
        </div>
      </div>

      <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5">
        <IcuSummaryStatusTile label="Summary No." value={icuDischargeSummaryNo(row)} tone="info" />
        <IcuSummaryStatusTile label="Document status" value={summaryStatus} tone={summaryStatus === "Draft" ? "warning" : "info"} />
        <IcuSummaryStatusTile label="Version" value="v1.0 draft" tone="muted" />
        <IcuSummaryStatusTile label="Lock state" value="Editable" tone="warning" />
        <label className="rounded-lg border border-border bg-background p-3 text-xs">
          <span className="font-medium text-muted-foreground">Discharge status</span>
          <select className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm outline-none focus:ring-2 focus:ring-ring/20" defaultValue={finalStatus}>
            <option>Alive</option>
            <option>Death</option>
          </select>
        </label>
      </div>

      <div className="grid gap-4 2xl:grid-cols-[minmax(0,1fr)_300px]">
        <div className="min-w-0 space-y-4">
          <div className="rounded-lg border border-border bg-background">
            <div className="border-b border-border px-4 py-3">
              <p className="text-sm font-semibold text-foreground">Structured clinical editor</p>
              <p className="text-xs text-muted-foreground">Mapped to ICU vitals, MAR, lab/radiology, handover, bed release, and destination scenario.</p>
            </div>
            <div className="space-y-4 p-4">
              <details className="rounded-lg border border-border bg-surface-muted p-3" open>
                <summary className="cursor-pointer text-sm font-semibold text-foreground">Diagnosis and clinical summary</summary>
                <div className="mt-3 grid gap-3 xl:grid-cols-2">
                  <IcuSummaryField label="Type of discharge" value={icuDischargeTypeLabel(destination)} />
                  <IcuSummaryField label="Discharge status" value={finalStatus} />
                  <IcuSummaryField label="Primary diagnosis" value={row.patient.diagnosis} />
                  <IcuSummaryField label="Secondary diagnoses / comorbidities" value={icuDischargeComorbidities(row)} />
                  <IcuSummaryTextArea label="Chief complaints" value={icuDischargeChiefComplaints(row)} />
                  <IcuSummaryTextArea label="History of present illness" value={icuDischargeHistory(row)} />
                  <IcuSummaryTextArea label="Brief clinical history leading to admission" value={`${row.patient.admissionSource} admission to ${row.patient.unit}. Current ICU status: ${row.patient.currentStatus}.`} />
                  <IcuSummaryTextArea label="Past and medical history" value={icuDischargePastHistory(row)} />
                  <IcuSummaryTextArea label="Social history" value="Family/attendant available for counselling. Social and home support to be re-confirmed by receiving team." />
                  <IcuSummaryTextArea label="Allergic history" value={icuDischargeAllergyHistory(row)} />
                  <div className="xl:col-span-2">
                    <IcuClinicalFindingsEditor findings={clinicalFindings} onChange={setClinicalFindings} />
                  </div>
                  <IcuSummaryTextArea label="Treatment provided during hospital course" value={icuDischargeTreatmentProvided(row, destination)} />
                </div>
              </details>

              <details className="rounded-lg border border-border bg-surface-muted p-3">
                <summary className="cursor-pointer text-sm font-semibold text-foreground">Vitals, investigations and procedures</summary>
                <div className="mt-3 space-y-3">
                  <div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-5">
                    <IcuSummaryVital label="Temperature" value={latestVital ? `${latestVital.temperature} C` : "-"} />
                    <IcuSummaryVital label="Pulse" value={latestVital ? `${latestVital.pulse}/min` : "-"} />
                    <IcuSummaryVital label="Blood pressure" value={latestVital?.bp ?? "-"} />
                    <IcuSummaryVital label="SpO2" value={latestVital ? `${latestVital.spo2}%` : "-"} />
                    <IcuSummaryVital label="Recorded" value={latestVital?.time ?? row.patient.lastVitalsTime} />
                  </div>
                  <div className="grid gap-2 md:grid-cols-3">
                    {icuDischargeConditionRows(row, destination).map((condition) => (
                      <div className="rounded-md border border-success/30 bg-success/10 p-2 text-xs font-semibold text-success" key={condition}>
                        {condition}
                      </div>
                    ))}
                  </div>
                  <IcuSummaryMiniTable headers={["Test", "Date/time", "Value", "Flag"]} rows={labRows.map((item) => [item.test, item.at, item.value, item.flag])} />
                  <IcuSummaryMiniTable headers={["Procedure", "Date", "Consultant", "Finding"]} rows={procedureRows.map((item) => [item.name, item.at, item.doctor, item.finding])} />
                </div>
              </details>

              <details className="rounded-lg border border-border bg-surface-muted p-3">
                <summary className="cursor-pointer text-sm font-semibold text-foreground">Medication, advice and follow-up</summary>
                <div className="mt-3 space-y-3">
                  <IcuSummaryMiniTable
                    headers={["Medication", "Dose", "Route", "Frequency", "Status"]}
                    rows={admissionMeds.length ? admissionMeds.map((item) => [item.medication, item.dose, item.route, item.frequency, item.status]) : [["No active MAR medicine", "-", "-", "-", "-"]]}
                  />
                  <IcuSummaryMiniTable
                    headers={["Medication at discharge/transfer", "Dose", "Route", "Frequency", "Duration", "Advice"]}
                    rows={dischargeMeds.map((item) => [item.medication, item.dose, item.route, item.frequency, item.duration, item.advice])}
                  />
                  <div className="grid gap-3 xl:grid-cols-2">
                    <IcuSummaryTextArea label="Patient instructions" value={icuDischargePatientInstructions(row, destination)} />
                    <IcuSummaryTextArea label="Red flag symptoms" value={icuDischargeWarningSigns(row, destination)} />
                    <IcuSummaryTextArea label="Diet advice" value={icuDischargeDietAdvice(row)} />
                    <IcuSummaryTextArea label="Activity advice" value={icuDischargeActivityAdvice(destination)} />
                    <IcuSummaryTextArea label="Wound / device care" value={icuDischargeDeviceAdvice(row, destination)} />
                    <IcuSummaryTextArea label="Lifestyle modifications" value={icuDischargeLifestyleAdvice(row)} />
                  </div>
                </div>
              </details>
            </div>
          </div>

          <details className="rounded-lg border border-border bg-background">
            <summary className="flex cursor-pointer flex-col gap-3 border-b border-border px-4 py-3 lg:flex-row lg:items-center lg:justify-between">
              <div>
                <p className="text-sm font-semibold text-foreground">A4 PDF preview</p>
                <p className="text-xs text-muted-foreground">Same discharge-summary layout, adapted for ICU transfer/discharge.</p>
              </div>
              <Button size="sm" variant="outline" onClick={(event) => { event.preventDefault(); setPreviewOpen(true); }}>
                <FileText className="h-4 w-4" />
                Preview PDF
              </Button>
            </summary>
            <div className="space-y-4 bg-surface-muted p-4">
              <IcuDischargeSummaryA4
                row={row}
                destination={destination}
                completion={completion}
                clinicalFindings={clinicalFindings}
                labRows={labRows}
                procedureRows={procedureRows}
                admissionMeds={admissionMeds}
                dischargeMeds={dischargeMeds}
                pendingRows={pendingRows}
              />
            </div>
          </details>
        </div>

        <div className="h-fit rounded-lg border border-border bg-background p-3 2xl:sticky 2xl:top-[88px]">
          <div className="flex items-center justify-between gap-3">
            <div>
              <p className="text-sm font-semibold text-foreground">Patient and legal panel</p>
              <p className="text-xs text-muted-foreground">Approval context</p>
            </div>
            <StatusPill tone={row.status === "Blocked" || row.status === "Escalated" ? "danger" : "info"}>{row.status}</StatusPill>
          </div>
          <div className="mt-3 rounded-lg border border-border bg-surface-muted p-3">
            <div className="font-semibold text-foreground">{row.patient.patientName}</div>
            <div className="mt-1 text-xs text-muted-foreground">{row.patient.mrn} | {row.patient.ageGender}</div>
            <div className="mt-1 text-xs text-muted-foreground">{row.patient.bedNo}, {row.patient.unit}</div>
            <div className="mt-1 text-xs text-muted-foreground">Admit: {row.patient.admissionTime}</div>
            <div className="mt-1 text-xs text-muted-foreground">Destination: {row.destination}</div>
            <div className="mt-1 text-xs text-muted-foreground">{row.patient.admittingDoctor}</div>
          </div>
          <div className="mt-3 space-y-2">
            <InfoLine label="Doctor" value={row.clearances.Doctor} />
            <InfoLine label="Nursing" value={row.clearances.Nurse} />
            <InfoLine label="Pharmacy" value={row.clearances.Pharmacy} />
            <InfoLine label="Destination bed" value={row.clearances["Destination bed"]} />
            <InfoLine label="Checklist" value={`${completion}% complete`} />
          </div>
          <div className="mt-3 rounded-lg border border-warning/30 bg-warning/10 p-3 text-xs text-warning">
            Final summaries should be locked after sign-off. Corrections must use amendment workflow with reason, approver, timestamp, and version history.
          </div>
        </div>
      </div>

      <IcuDischargeSummaryPreviewDialog
        open={previewOpen}
        onClose={() => setPreviewOpen(false)}
        row={row}
        destination={destination}
        completion={completion}
        clinicalFindings={clinicalFindings}
        labRows={labRows}
        procedureRows={procedureRows}
        admissionMeds={admissionMeds}
        dischargeMeds={dischargeMeds}
        pendingRows={pendingRows}
      />
    </div>
  );
}

function IcuSummaryHeroMetric({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-lg border border-border bg-background/85 p-3">
      <div className="text-[11px] font-medium uppercase text-muted-foreground">{label}</div>
      <div className="mt-1 truncate text-sm font-semibold text-foreground">{value}</div>
    </div>
  );
}

function IcuSummaryStatusTile({ label, value, tone }: { label: string; value: string; tone: StatusTone }) {
  return (
    <div className={cn("rounded-lg border p-3 text-xs", tone === "warning" ? "border-warning/30 bg-warning/10" : tone === "info" ? "border-info/30 bg-info/10" : "border-border bg-background")}>
      <div className="font-medium text-muted-foreground">{label}</div>
      <div className="mt-2 truncate text-sm font-semibold text-foreground">{value}</div>
    </div>
  );
}

function IcuSummaryField({ label, value }: { label: string; value: string }) {
  return (
    <label className="space-y-1 text-sm">
      <span className="font-medium text-foreground">{label}</span>
      <Input defaultValue={value} />
    </label>
  );
}

function IcuSummaryTextArea({ label, value }: { label: string; value: string }) {
  return (
    <label className="space-y-1 text-sm">
      <span className="font-medium text-foreground">{label}</span>
      <textarea className="min-h-24 w-full rounded-md border border-input bg-background p-3 text-sm outline-none focus:ring-2 focus:ring-ring/20" defaultValue={value} />
    </label>
  );
}

function IcuClinicalFindingsEditor({ findings, onChange }: { findings: string[]; onChange: (findings: string[]) => void }) {
  return (
    <div className="rounded-lg border border-border bg-background p-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div>
          <p className="text-sm font-semibold text-foreground">Clinical findings</p>
          <p className="text-xs text-muted-foreground">Numbered findings are carried into the summary and PDF.</p>
        </div>
        <Button size="sm" variant="outline" onClick={() => onChange([...findings, ""])}>
          <Plus className="h-4 w-4" />
          Add finding
        </Button>
      </div>
      <div className="mt-3 space-y-2">
        {findings.map((finding, index) => (
          <div className="grid gap-2 sm:grid-cols-[32px_1fr_auto]" key={`finding-${index}`}>
            <div className="grid h-10 place-items-center rounded-md border border-border bg-surface-muted text-sm font-semibold text-muted-foreground">{index + 1}</div>
            <Input
              value={finding}
              onChange={(event) => {
                const next = [...findings];
                next[index] = event.target.value;
                onChange(next);
              }}
              placeholder={`Clinical finding ${index + 1}`}
            />
            <Button
              size="sm"
              variant="outline"
              onClick={() => onChange(findings.filter((_, itemIndex) => itemIndex !== index))}
              disabled={findings.length <= 1}
            >
              Remove
            </Button>
          </div>
        ))}
      </div>
    </div>
  );
}

function IcuSummaryVital({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-md border border-border bg-background p-2">
      <div className="text-[10px] uppercase text-muted-foreground">{label}</div>
      <div className="mt-1 text-sm font-semibold text-foreground">{value}</div>
    </div>
  );
}

function IcuSummaryMiniTable({ headers, rows }: { headers: string[]; rows: string[][] }) {
  return (
    <div className="overflow-x-auto rounded-lg border border-border bg-background">
      <table className="w-full min-w-[620px] text-xs">
        <thead className="bg-surface-muted text-muted-foreground">
          <tr>{headers.map((header) => <th className="px-3 py-2 text-left font-semibold" key={header}>{header}</th>)}</tr>
        </thead>
        <tbody>
          {rows.map((row, index) => (
            <tr className="border-t border-border" key={`${row.join("-")}-${index}`}>
              {row.map((cell, cellIndex) => <td className="px-3 py-2" key={`${cell}-${cellIndex}`}>{cell}</td>)}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function IcuDischargeSummaryPreviewDialog({
  open,
  onClose,
  row,
  destination,
  completion,
  clinicalFindings,
  labRows,
  procedureRows,
  admissionMeds,
  dischargeMeds,
  pendingRows,
}: {
  open: boolean;
  onClose: () => void;
  row: IcuDischargeWorkflowRow;
  destination: IcuDischargeDestination;
  completion: number;
  clinicalFindings: string[];
  labRows: ReturnType<typeof icuDischargeLabRows>;
  procedureRows: ReturnType<typeof icuDischargeProcedureRows>;
  admissionMeds: typeof medicationRows;
  dischargeMeds: ReturnType<typeof icuDischargeMedicationRows>;
  pendingRows: ReturnType<typeof icuDischargePendingRows>;
}) {
  return (
    <Dialog.Root open={open} onOpenChange={(nextOpen) => !nextOpen && onClose()}>
      <Dialog.Portal>
        <Dialog.Overlay className="fixed inset-0 z-[70] bg-black/50 backdrop-blur-[1px]" />
        <Dialog.Content className="fixed left-1/2 top-1/2 z-[71] flex max-h-[94dvh] w-[min(920px,calc(100vw-24px))] -translate-x-1/2 -translate-y-1/2 flex-col overflow-hidden rounded-xl border border-border bg-surface shadow-soft outline-none">
          <div className="flex items-center justify-between gap-3 border-b border-border bg-surface-muted px-4 py-3">
            <div>
              <Dialog.Title className="text-sm font-semibold text-foreground">ICU Discharge Summary Preview</Dialog.Title>
              <Dialog.Description className="text-xs text-muted-foreground">{row.patient.patientName} | {row.patient.mrn}</Dialog.Description>
            </div>
            <div className="flex gap-2">
              <Button size="sm" variant="outline" onClick={() => downloadIcuDischargeSummaryPdf(row, destination, completion, clinicalFindings, labRows, procedureRows, admissionMeds, dischargeMeds, pendingRows)}>
                <Download className="h-4 w-4" />
                Download PDF
              </Button>
              <Dialog.Close asChild>
                <Button size="sm" variant="outline" onClick={onClose}>Close</Button>
              </Dialog.Close>
            </div>
          </div>
          <div className="overflow-y-auto bg-surface-muted p-4">
            <IcuDischargeSummaryA4
              row={row}
              destination={destination}
              completion={completion}
              clinicalFindings={clinicalFindings}
              labRows={labRows}
              procedureRows={procedureRows}
              admissionMeds={admissionMeds}
              dischargeMeds={dischargeMeds}
              pendingRows={pendingRows}
            />
          </div>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

async function downloadIcuDischargeSummaryPdf(
  row: IcuDischargeWorkflowRow,
  destination: IcuDischargeDestination,
  completion: number,
  clinicalFindings: string[],
  labRows: ReturnType<typeof icuDischargeLabRows>,
  procedureRows: ReturnType<typeof icuDischargeProcedureRows>,
  admissionMeds: typeof medicationRows,
  dischargeMeds: ReturnType<typeof icuDischargeMedicationRows>,
  pendingRows: ReturnType<typeof icuDischargePendingRows>,
) {
  const toastId = toast.loading("Preparing ICU discharge summary PDF...");
  let container: HTMLDivElement | null = null;
  let root: ReturnType<typeof createRoot> | null = null;

  try {
    const [{ default: html2canvas }, { jsPDF }] = await Promise.all([
      import("html2canvas"),
      import("jspdf"),
    ]);

    container = document.createElement("div");
    container.style.position = "fixed";
    container.style.left = "-12000px";
    container.style.top = "0";
    container.style.width = "826px";
    container.style.background = "#f1f5f9";
    container.style.pointerEvents = "none";
    container.style.zIndex = "-1";
    document.body.appendChild(container);

    root = createRoot(container);
    flushSync(() => {
      root?.render(
        <div className="bg-slate-100 p-4">
          <IcuDischargeSummaryA4
            row={row}
            destination={destination}
            completion={completion}
            clinicalFindings={clinicalFindings}
            labRows={labRows}
            procedureRows={procedureRows}
            admissionMeds={admissionMeds}
            dischargeMeds={dischargeMeds}
            pendingRows={pendingRows}
          />
        </div>,
      );
    });

    await waitForIcuDischargePdfPaint();
    const pageElements = Array.from(container.querySelectorAll<HTMLElement>("[data-icu-discharge-pdf-page='true']"));
    if (!pageElements.length) throw new Error("ICU discharge PDF page is not available.");

    const pdf = new jsPDF({ orientation: "portrait", unit: "mm", format: "a4", compress: true });
    const pdfWidth = pdf.internal.pageSize.getWidth();
    const pdfHeight = pdf.internal.pageSize.getHeight();

    for (const [index, pageElement] of pageElements.entries()) {
      const canvas = await html2canvas(pageElement, {
        backgroundColor: "#ffffff",
        logging: false,
        scale: 2,
        useCORS: true,
        windowWidth: pageElement.scrollWidth,
        windowHeight: pageElement.scrollHeight,
      });
      const imageData = canvas.toDataURL("image/png");
      const ratio = Math.min(pdfWidth / canvas.width, pdfHeight / canvas.height);
      const renderWidth = canvas.width * ratio;
      const renderHeight = canvas.height * ratio;
      const x = (pdfWidth - renderWidth) / 2;

      if (index > 0) pdf.addPage();
      pdf.addImage(imageData, "PNG", x, 0, renderWidth, renderHeight, undefined, "FAST");
    }

    pdf.save(`${icuDischargeSummaryNo(row)}.pdf`);
    toast.success("ICU discharge summary PDF downloaded", { id: toastId });
  } catch (error) {
    console.error(error);
    toast.error("PDF download failed. Please use Preview PDF and print for now.", { id: toastId });
  } finally {
    root?.unmount();
    container?.remove();
  }
}

async function waitForIcuDischargePdfPaint() {
  if ("fonts" in document) {
    await document.fonts.ready;
  }
  await new Promise<void>((resolve) => {
    requestAnimationFrame(() => requestAnimationFrame(() => resolve()));
  });
}

