function IcuPdfSection({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <section className="mt-4">
      <div className="border-b border-slate-200 pb-1 text-sm font-bold uppercase tracking-wide text-slate-800">{title}</div>
      <div className="mt-2">{children}</div>
    </section>
  );
}

function IcuPdfLine({ label, value }: { label: string; value: string }) {
  return (
    <div className="grid grid-cols-[135px_1fr] gap-2 rounded border border-slate-200 px-2 py-1">
      <span className="font-semibold text-slate-500">{label}</span>
      <span>{value}</span>
    </div>
  );
}

function IcuPdfMetric({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded border border-slate-200 bg-slate-50 p-2">
      <div className="text-[10px] uppercase text-slate-500">{label}</div>
      <div className="mt-1 font-semibold">{value}</div>
    </div>
  );
}

function IcuPdfParagraph({ title, value }: { title: string; value: string }) {
  return (
    <div className="mt-2 text-xs leading-5">
      <span className="font-semibold">{title}: </span>
      <span className="text-slate-700">{value}</span>
    </div>
  );
}

function IcuPdfTable({ headers, rows }: { headers: string[]; rows: string[][] }) {
  return (
    <table className="mt-3 w-full border-collapse text-[10px]">
      <thead>
        <tr>{headers.map((header) => <th className="border border-slate-300 bg-slate-100 px-2 py-1 text-left" key={header}>{header}</th>)}</tr>
      </thead>
      <tbody>
        {rows.map((row, index) => (
          <tr key={`${row.join("-")}-${index}`}>
            {row.map((cell, cellIndex) => <td className="border border-slate-200 px-2 py-1" key={`${cell}-${cellIndex}`}>{cell}</td>)}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

function icuDischargeSummaryNo(row: IcuDischargeWorkflowRow) {
  return `ICU-DS-${row.patient.mrn.replace(/[^A-Z0-9]/gi, "")}-${row.id.slice(-3).toUpperCase()}`;
}

function icuDischargeSummaryTitle(destination: IcuDischargeDestination) {
  if (destination === "Home discharge" || destination === "LAMA / DAMA") return "Discharge Summary";
  if (destination === "Death workflow") return "Death Summary";
  if (destination === "Continue ICU") return "ICU Continuation Summary";
  return "ICU Discharge / Transfer Summary";
}

function icuDischargeTypeLabel(destination: IcuDischargeDestination) {
  const labels: Record<IcuDischargeDestination, string> = {
    Ward: "ICU to ward transfer",
    "Step-down / HDU": "ICU to step-down / HDU transfer",
    "Other ICU": "Inter-ICU transfer",
    "OT / Procedure": "Procedure / OT transfer",
    "Other hospital": "Referred / external hospital transfer",
    "Home discharge": "Normal",
    "LAMA / DAMA": "LAMA / Against Medical Advice",
    "Palliative / Hospice": "Palliative / hospice transfer",
    "Death workflow": "Death",
    "Continue ICU": "Continue ICU care",
  };
  return labels[destination];
}

function icuDischargeClinicalFindings(row: IcuDischargeWorkflowRow, destination: IcuDischargeDestination) {
  const findings = [
    `${row.patient.currentStatus} in ${row.patient.unit} with criticality score ${row.patient.criticalityScore}.`,
    `Respiratory support at review: ${row.patient.ventilatorStatus}.`,
    `Destination decision: ${icuDischargeTypeLabel(destination)} to ${row.destination}.`,
  ];
  if (row.blockers.length) findings.push(`Pending blockers: ${row.blockers.join(", ")}.`);
  return findings;
}

function icuDischargeChiefComplaints(row: IcuDischargeWorkflowRow) {
  if (row.patient.diagnosis.toLowerCase().includes("copd")) return "Breathlessness, wheeze, high CO2 watch, and oxygen/NIV requirement.";
  if (row.patient.diagnosis.toLowerCase().includes("stroke")) return "Low GCS observation, neuro monitoring requirement, and aspiration risk.";
  if (row.patient.diagnosis.toLowerCase().includes("cabg")) return "Post-operative cardiothoracic ICU monitoring after CABG.";
  if (row.patient.diagnosis.toLowerCase().includes("dka")) return "DKA with electrolyte imbalance requiring insulin, fluid, and electrolyte monitoring.";
  if (row.patient.diagnosis.toLowerCase().includes("transplant")) return "Post-transplant immunosuppression and renal output monitoring.";
  return "Critical illness requiring ICU monitoring and active treatment.";
}

function icuDischargeHistory(row: IcuDischargeWorkflowRow) {
  return `${row.patient.patientName} was admitted from ${row.patient.admissionSource} to ${row.patient.unit} for ${row.patient.diagnosis}. ICU course included close monitoring, medication administration, device/support review, and repeated nursing handover.`;
}

function icuDischargePastHistory(row: IcuDischargeWorkflowRow) {
  if (row.patient.diagnosis.toLowerCase().includes("cabg")) return "Known cardiac disease with recent surgical intervention.";
  if (row.patient.diagnosis.toLowerCase().includes("copd")) return "Chronic respiratory disease history to be continued in receiving care plan.";
  if (row.patient.diagnosis.toLowerCase().includes("dka")) return "Diabetes-related acute metabolic decompensation.";
  if (row.patient.diagnosis.toLowerCase().includes("transplant")) return "Renal transplant history with immunosuppression monitoring.";
  return "Relevant past history to be verified from EMR and receiving team handover.";
}

function icuDischargeComorbidities(row: IcuDischargeWorkflowRow) {
  if (row.patient.diagnosis.toLowerCase().includes("dka")) return "Diabetes mellitus, electrolyte imbalance.";
  if (row.patient.diagnosis.toLowerCase().includes("cabg")) return "Coronary artery disease, post-operative status.";
  if (row.patient.diagnosis.toLowerCase().includes("copd")) return "COPD, acute respiratory failure risk.";
  if (row.patient.diagnosis.toLowerCase().includes("transplant")) return "Post renal transplant, immunosuppression.";
  if (row.patient.diagnosis.toLowerCase().includes("septic")) return "Sepsis risk, respiratory distress.";
  return "To be updated by admitting consultant.";
}

function icuDischargeAllergyHistory(row: IcuDischargeWorkflowRow) {
  const antibiotic = medicationRows.find((medication) => medication.patientId === row.patient.id && medication.medication.toLowerCase().includes("meropenem"));
  if (antibiotic) return "No documented beta-lactam allergy in current ICU record; verify before next antibiotic dose.";
  return "No allergy recorded in the current ICU record; receiving team must verify from EMR.";
}

function icuDischargeTreatmentProvided(row: IcuDischargeWorkflowRow, destination: IcuDischargeDestination) {
  const meds = medicationRows.filter((medication) => medication.patientId === row.patient.id).map((medication) => medication.medication).join(", ") || "ICU protocol medicines";
  const infusions = infusionRows.filter((infusion) => infusion.patientId === row.patient.id).map((infusion) => infusion.fluidName).join(", ");
  const transferPlan = destination === "Continue ICU" ? "continue ICU treatment and reassess next round" : `prepare ${icuDischargeTypeLabel(destination).toLowerCase()}`;
  return `Treatment included ICU monitoring, ${meds}${infusions ? `, ${infusions}` : ""}, nursing care plan, vitals review, and doctor instructions. Current plan is to ${transferPlan}.`;
}

function icuDischargeConditionRows(row: IcuDischargeWorkflowRow, destination: IcuDischargeDestination) {
  if (destination === "Death workflow") return ["Death declared workflow", "Family informed", "Mortuary handover pending"];
  if (destination === "Continue ICU") return ["Requires ICU care", "Monitoring active", "Reassessment planned"];
  if (row.patient.ventilatorStatus !== "Room air") return ["Monitored transfer", row.patient.ventilatorStatus, "Escalation criteria documented"];
  return ["Hemodynamically stable", "Afebrile/stable symptoms", "Transfer ready"];
}

function icuDischargeMedicationRows(row: IcuDischargeWorkflowRow, destination: IcuDischargeDestination, admissionMeds: typeof medicationRows) {
  const rows = admissionMeds.map((medication) => ({
    medication: medication.medication,
    dose: medication.dose,
    route: medication.route,
    frequency: medication.frequency,
    duration: destination === "Ward" || destination === "Step-down / HDU" ? "Continue as per receiving team" : "Review at destination",
    advice: medication.status === "Held" ? "Review hold reason before restart" : medication.reason || "Continue with monitoring",
  }));

  if (rows.length) return rows;

  return [{
    medication: "Pantoprazole",
    dose: "40 mg",
    route: "IV/Oral",
    frequency: "OD",
    duration: "As advised",
    advice: "Stress ulcer prophylaxis if clinically indicated.",
  }];
}

function icuDischargeLabRows(row: IcuDischargeWorkflowRow) {
  const latestVital = [...icuVitals].reverse().find((vital) => vital.patientId === row.patient.id);
  const alert = icuAlerts.find((item) => item.patientId === row.patient.id && item.type.toLowerCase().includes("lab"));
  const base = [
    { test: "Latest vitals review", at: latestVital?.time ?? row.patient.lastVitalsTime, value: latestVital ? `${latestVital.bp}, SpO2 ${latestVital.spo2}%` : row.patient.lastVitalsTime, flag: latestVital?.abnormal ? "Abnormal" : "Reviewed" },
    { test: "Medication review", at: "Current shift", value: `${medicationRows.filter((medication) => medication.patientId === row.patient.id).length} active`, flag: "Reviewed" },
  ];
  if (alert) base.push({ test: alert.type, at: alert.createdAt, value: alert.message, flag: alert.severity });
  return base;
}

function icuDischargeProcedureRows(row: IcuDischargeWorkflowRow) {
  const rows: Array<{ name: string; at: string; doctor: string; finding: string }> = [
    { name: "ICU monitoring and stabilization", at: row.patient.admissionTime, doctor: row.patient.admittingDoctor, finding: row.patient.currentStatus },
  ];
  const infusion = infusionRows.find((item) => item.patientId === row.patient.id);
  if (infusion) rows.push({ name: "Infusion / fluid support", at: infusion.startTime, doctor: row.patient.dutyDoctor, finding: `${infusion.fluidName} ${infusion.status}` });
  const transfusion = transfusionRows.find((item) => item.patientId === row.patient.id);
  if (transfusion) rows.push({ name: "Blood transfusion support", at: transfusion.startTime, doctor: transfusion.doctor, finding: `${transfusion.componentType} ${transfusion.status}` });
  return rows;
}

function icuDischargePendingRows(row: IcuDischargeWorkflowRow) {
  const blockers = row.blockers.map((blocker) => ({ item: blocker, owner: row.owner, status: "Pending" }));
  if (blockers.length) return blockers;
  return [{ item: "No pending critical report", owner: row.owner, status: "Clear" }];
}

function icuDischargePatientInstructions(row: IcuDischargeWorkflowRow, destination: IcuDischargeDestination) {
  if (destination === "Death workflow") return "Family support, documentation, belongings, and mortuary handover to be coordinated by nursing/admin team.";
  if (destination === "LAMA / DAMA") return "Risks explained. Patient/family advised to seek urgent medical care if condition worsens.";
  if (destination === "Continue ICU") return "Continue ICU care as per active orders. Family to be updated after next consultant review.";
  return `Receiving team to continue ${row.patient.diagnosis} care plan, medication timings, monitoring frequency, and escalation criteria.`;
}

function icuDischargeWarningSigns(row: IcuDischargeWorkflowRow, destination: IcuDischargeDestination) {
  if (destination === "Death workflow") return "Not applicable after death declaration workflow.";
  const signs = ["fall in SpO2", "hypotension", "altered sensorium", "low urine output", "new fever", "uncontrolled pain"];
  if (row.patient.ventilatorStatus !== "Room air") signs.push("increasing oxygen or ventilator requirement");
  return signs.join(", ");
}

function icuDischargeDietAdvice(row: IcuDischargeWorkflowRow) {
  if (row.patient.diagnosis.toLowerCase().includes("stroke")) return "Aspiration precautions; swallowing assessment before oral feed if indicated.";
  if (row.patient.diagnosis.toLowerCase().includes("dka")) return "Diabetic diet plan after endocrine/medical review.";
  if (row.patient.diagnosis.toLowerCase().includes("transplant")) return "Renal/transplant diet with fluid and infection-control advice.";
  return "Diet as per receiving team and aspiration risk assessment.";
}

function icuDischargeActivityAdvice(destination: IcuDischargeDestination) {
  if (destination === "Home discharge") return "Gradual mobilization as advised, with follow-up review.";
  if (destination === "OT / Procedure") return "Procedure transport only; activity plan after procedure review.";
  if (destination === "Continue ICU") return "Bedside activity and physiotherapy as per ICU orders.";
  return "Mobilization level to be continued by receiving nurse/physiotherapy team.";
}

function icuDischargeDeviceAdvice(row: IcuDischargeWorkflowRow, destination: IcuDischargeDestination) {
  if (destination === "Death workflow") return "Remove/stop devices only after declaration and policy-based documentation.";
  if (row.patient.ventilatorStatus !== "Room air") return `${row.patient.ventilatorStatus} plan and oxygen escalation criteria must be handed over.`;
  return "Lines, drains, catheter, oxygen, and monitor needs reviewed before movement.";
}

function icuDischargeLifestyleAdvice(row: IcuDischargeWorkflowRow) {
  if (row.patient.diagnosis.toLowerCase().includes("copd")) return "Avoid smoke exposure; continue respiratory follow-up and inhaler technique counselling.";
  if (row.patient.diagnosis.toLowerCase().includes("dka")) return "Diabetes education, glucose monitoring, insulin adherence, and sick-day rule counselling.";
  return "Follow disease-specific counselling by receiving consultant.";
}

function dischargeReadiness(row: IcuDischargeWorkflowRow) {
  const applicable = Object.values(row.clearances).filter((value) => value !== "Not needed");
  if (!applicable.length) return 0;
  const done = applicable.filter((value) => value === "Done").length;
  return Math.round((done / applicable.length) * 100);
}

function dischargeFocusRank(row: IcuDischargeWorkflowRow, focus: string) {
  const statusRank = row.status === "Ready" || row.status === "Ordered"
    ? 80
    : row.status === "Blocked" || row.status === "Escalated"
      ? 70
      : row.status === "In progress"
        ? 55
        : 10;
  const destinationRank = row.destinationType === "Ward" || row.destinationType === "Step-down / HDU" || row.destinationType === "Other ICU" ? 30 : 0;
  const readinessRank = dischargeReadiness(row);
  if (focus === "transfer") return statusRank + destinationRank + readinessRank;
  return statusRank + readinessRank;
}

function dischargeReadinessBarClass(value: number) {
  if (value >= 80) return "bg-success";
  if (value >= 50) return "bg-warning";
  return "bg-danger";
}

function dischargePatientTone(row: IcuDischargeWorkflowRow): DashboardCellTone {
  if (row.status === "Escalated" || row.priority === "Critical") return "critical";
  if (row.status === "Blocked") return "danger";
  if (row.patient.ventilatorStatus !== "Room air") return "purple";
  if (row.status === "Ready" || row.status === "Ordered") return "success";
  return "info";
}

function dischargeStatusDashboardTone(status: IcuDischargeStatus): DashboardCellTone {
  if (status === "Ready" || status === "Ordered") return "success";
  if (status === "In progress") return "warning";
  if (status === "Blocked") return "danger";
  if (status === "Escalated") return "critical";
  return "muted";
}

function dischargeReadinessTone(value: number): DashboardCellTone {
  if (value >= 80) return "success";
  if (value >= 50) return "warning";
  return "danger";
}

function dischargeDestinationTone(row: IcuDischargeWorkflowRow): DashboardCellTone {
  if (row.destinationType === "Death workflow" || row.destinationType === "LAMA / DAMA") return "critical";
  if (row.destinationType === "Other hospital") return "danger";
  if (row.destinationType === "Other ICU" || row.destinationType === "OT / Procedure") return "warning";
  if (row.destinationType === "Continue ICU") return "muted";
  if (row.destinationType === "Step-down / HDU") return "info";
  return "success";
}

function dischargeBlockerTone(row: IcuDischargeWorkflowRow): DashboardCellTone {
  if (!row.blockers.length) return "success";
  if (row.status === "Escalated" || row.priority === "Critical") return "critical";
  if (row.status === "Blocked" || row.blockers.length >= 3) return "danger";
  return "warning";
}

function dischargeTransportTone(row: IcuDischargeWorkflowRow): DashboardCellTone {
  if (row.transport === "Not applicable" || row.transport === "No transport") return "muted";
  if (row.clearances.Transport === "Blocked") return "danger";
  if (row.clearances.Transport === "Pending") return row.priority === "Critical" ? "critical" : "warning";
  return "info";
}

function dischargeBedReleaseTone(row: IcuDischargeWorkflowRow): DashboardCellTone {
  if (row.bedRelease.includes("Not") || row.bedRelease.includes("Blocked")) return "danger";
  if (row.bedRelease.includes("Hold")) return "warning";
  if (dischargeReadiness(row) >= 70) return "success";
  return "info";
}

function dischargeBedReleaseTitle(row: IcuDischargeWorkflowRow) {
  if (row.bedRelease.includes("Not")) return "Not releasable";
  if (row.bedRelease.includes("Hold")) return "Hold bed";
  if (row.bedRelease.includes("Blocked")) return "Blocked";
  return "Cleaning";
}

function dischargeChecklistForDestination(destination: IcuDischargeDestination, row: IcuDischargeWorkflowRow) {
  const base = [
    { label: "Latest vitals and ICU status reviewed", owner: row.owner, status: row.clearances.Doctor, note: row.patient.currentStatus },
    { label: "Nurse-to-nurse SBAR handover ready", owner: row.patient.assignedWardNurse, status: row.clearances.Nurse, note: "Diagnosis, active problems, meds, devices, and escalation criteria" },
    { label: "Medication reconciliation complete", owner: "Pharmacy", status: row.clearances.Pharmacy, note: "Continue, hold, stop, and next due dose documented" },
    { label: "Pending lab/radiology follow-up handed over", owner: "Diagnostics", status: row.clearances["Lab/Radiology"], note: row.documentStatus },
    { label: "Family / attendant informed", owner: row.patient.assignedUnitNurse, status: row.clearances.Family, note: "Destination and expected monitoring explained" },
  ];

  const scenario: Record<IcuDischargeDestination, Array<{ label: string; owner: string; status: IcuDischargeClearance; note: string }>> = {
    Ward: [
      { label: "Receiving ward bed confirmed", owner: "Bed manager", status: row.clearances["Destination bed"], note: "Ward bed, nurse, and doctor team accepted" },
      { label: "Ward monitoring plan written", owner: row.patient.admittingDoctor, status: row.clearances.Doctor, note: "Frequency, warning signs, and escalation path" },
      { label: "ICU bed release and cleaning request prepared", owner: "ICU coordinator", status: row.clearances.Transport, note: row.bedRelease },
    ],
    "Step-down / HDU": [
      { label: "Step-down monitoring frequency approved", owner: row.patient.consultingDoctor, status: row.clearances.Doctor, note: "Vitals, neuro/respiratory checks, and escalation thresholds" },
      { label: "Oxygen / device plan accepted by HDU", owner: "Receiving HDU nurse", status: row.clearances["Destination bed"], note: row.patient.ventilatorStatus },
      { label: "Safe transport with oxygen arranged", owner: "Transport team", status: row.clearances.Transport, note: row.transport },
    ],
    "Other ICU": [
      { label: "Accepting ICU consultant confirmed", owner: "ICU command center", status: row.clearances.Doctor, note: "Inter-ICU clinical responsibility handoff" },
      { label: "Ventilator/device compatibility checked", owner: "Biomedical", status: row.clearances.Transport, note: "Monitor, pump, oxygen, and ventilator needs" },
      { label: "Critical transfer documentation printed", owner: row.patient.assignedUnitNurse, status: row.clearances.Nurse, note: "Transfer note, latest vitals, orders, and results" },
    ],
    "OT / Procedure": [
      { label: "Procedure consent and pre-op checklist complete", owner: row.patient.admittingDoctor, status: row.clearances.Doctor, note: "Consent, NPO, blood, antibiotic, and anesthesia review" },
      { label: "Procedure transport slot confirmed", owner: "OT coordinator", status: row.clearances.Transport, note: "Monitor and oxygen support during movement" },
      { label: "Return ICU bed held or release decision captured", owner: "ICU coordinator", status: row.clearances["Destination bed"], note: "Temporary movement versus permanent transfer" },
    ],
    "Other hospital": [
      { label: "Receiving hospital acceptance documented", owner: "Referral desk", status: row.clearances["Destination bed"], note: row.destination },
      { label: "ALS ambulance and equipment confirmed", owner: "Transport team", status: row.clearances.Transport, note: row.transport },
      { label: "Referral bundle prepared", owner: row.patient.dutyDoctor, status: row.clearances["Lab/Radiology"], note: "Summary, latest vitals, labs, radiology, and medication list" },
    ],
    "Home discharge": [
      { label: "Final consultant discharge approval", owner: row.patient.admittingDoctor, status: row.clearances.Doctor, note: "Hospital discharge from ICU/hospital" },
      { label: "Discharge medicines and follow-up explained", owner: "Pharmacy + nurse", status: row.clearances.Pharmacy, note: "Warning signs and next appointment" },
      { label: "Billing/admin closure complete", owner: "Billing/Admin", status: row.clearances["Billing/Admin"], note: "Final clearance before leaving hospital" },
    ],
    "LAMA / DAMA": [
      { label: "Risk counselling documented", owner: row.patient.admittingDoctor, status: row.clearances.Doctor, note: "Patient/family understands risk of leaving against advice" },
      { label: "Consent/witness form completed", owner: "Nursing in-charge", status: row.clearances.Nurse, note: "Signature, witness, and time captured" },
      { label: "Medicines, reports, and financial closure offered", owner: "Pharmacy/Admin", status: row.clearances.Pharmacy, note: "Safe exit even when against advice" },
    ],
    "Palliative / Hospice": [
      { label: "Goals-of-care discussion documented", owner: row.patient.admittingDoctor, status: row.clearances.Doctor, note: "Treatment limitation and comfort plan" },
      { label: "Comfort medication and nursing plan ready", owner: row.patient.assignedWardNurse, status: row.clearances.Nurse, note: "Pain, oxygen, family presence, and dignity care" },
      { label: "Hospice/palliative destination accepted", owner: "Palliative coordinator", status: row.clearances["Destination bed"], note: "Transfer or in-hospital palliative care" },
    ],
    "Death workflow": [
      { label: "Death declaration completed by doctor", owner: "Duty doctor", status: row.clearances.Doctor, note: "Time, cause context, and documentation" },
      { label: "Family informed and body handover prepared", owner: "Nursing in-charge", status: row.clearances.Family, note: "Belongings, consent, and viewing workflow" },
      { label: "Mortuary, pharmacy return, billing closure queued", owner: "Admin + pharmacy", status: row.clearances["Billing/Admin"], note: "Bed cleaning after body movement" },
    ],
    "Continue ICU": [
      { label: "Transfer/discharge blocked with reason", owner: row.patient.admittingDoctor, status: row.clearances.Doctor, note: row.blockers.join(", ") },
      { label: "Next reassessment time documented", owner: row.patient.dutyDoctor, status: row.clearances.Nurse, note: row.eta },
      { label: "Family updated that ICU care continues", owner: row.patient.assignedUnitNurse, status: row.clearances.Family, note: "Reason and next review shared" },
    ],
  };

  return [...base, ...scenario[destination]];
}

